# ------------------------------------------------------------------ настройки

def включена() -> bool:
    """Полоса вообще собрана? Сборка и симуляция идут и без этого флага."""
    return ST.env_int("BLOOM_OWN_SEND", 0) == 1


def живьём() -> bool:
    """ОТПРАВКА в сеть. Без этого не уходит ни одна транзакция полосы."""
    return ST.env_int("BLOOM_OWN_SEND_LIVE", 0) == 1


# ОТДЕЛЬНЫЙ КОШЕЛЁК ПОЛОСЫ (решение владельца 25.09). Причина прямая: автоордер
# Bloom продаёт ВЕСЬ баланс минта на кошельке, и на первой же живой отправке он
# смёл токены полосы вместе со своими -- итог полосы стало нечем считать. Свой
# кошелёк делает вход, остаток и выход полосы её собственными.
#
# Если переменных нет, полоса работает как раньше -- на кошельке исполнителя:
# так старые самопроверки и сухие прогоны остаются в силе, а не ломаются молча.
ENV_КОШЕЛЁК_ПОЛОСЫ = "OWN_SEND_WALLET"
ENV_КЛЮЧ_ПОЛОСЫ = "OWN_SEND_WALLET_KEY"


def кошелёк_полосы() -> str:
    """Публичный адрес, с которого полоса покупает и продаёт."""
    свой = (os.environ.get(ENV_КОШЕЛЁК_ПОЛОСЫ) or "").strip()
    return свой or ST.EXECUTOR_WALLET


def ключ_полосы() -> str | None:
    """Секрет кошелька полосы. None -- значит своего ключа нет и подписывать
    надо ключом исполнителя (старое поведение)."""
    к = (os.environ.get(ENV_КЛЮЧ_ПОЛОСЫ) or "").strip()
    return к or None


def свой_кошелёк() -> bool:
    return кошелёк_полосы() != ST.EXECUTOR_WALLET


def кошелёк_готов() -> dict:
    """Согласован ли кошелёк полосы с её ключом. Несогласован -- запрет.

    Проверка нужна ДО первой отправки и в признаке жизни: подписать чужим
    ключом значит отправить транзакцию, которую сеть отвергнет, потратив
    приоритет и чаевые, либо -- хуже -- подписать не тот кошелёк.
    """
    адрес, секрет = кошелёк_полосы(), ключ_полосы()
    из_ = {"wallet": адрес, "own_wallet": свой_кошелёк(), "ok": False,
            "why_not": None}
    if not свой_кошелёк():
        из_.update(ok=True, why_not=None,
                   note="своего кошелька нет -- полоса на кошельке исполнителя")
        return из_
    if not секрет:
        из_["why_not"] = f"{ENV_КЛЮЧ_ПОЛОСЫ} не задан -- подписывать нечем"
        return из_
    try:
        import bloom_jupiter_sell as J  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"модуль проверки ключа не загружен: {type(exc).__name__}"
        return из_
    свой = J.ключ_от_нашего_кошелька(адрес, секрет)
    из_.update(ok=bool(свой.get("ok")), why_not=свой.get("why_not"))
    return из_


def адрес_сендера() -> str:
    регион = (os.environ.get("BLOOM_SENDER_REGION") or "ams").strip().lower()
    return SENDER_HOSTS.get(регион, SENDER_HOSTS["ams"])


def имя_точки(url: str | None) -> str | None:
    """Имя точки входа из адреса: из "схема://хост/путь?ключ" остаётся только
    хост. Ни схемы, ни пути, ни ключа в имени быть не может -- оно уходит
    владельцу в строку "кто довёз". Пример разобран в самопроверке."""
    т = str(url or "").strip()
    if not т:
        return None
    т = т.split("://", 1)[-1].split("/", 1)[0]
    return т.split("@")[-1].split(":")[0] or None


# ПОТОЛОК ГИБКОГО БИЛЕТА (слово владельца 05.10: "билет = 2 % резерва
# SOL-стороны пула на момент входа, потолок 2.0 SOL, пол -- нынешний билет
# группы"). Поле группы bilet_potolok_sol может потолок только ОПУСТИТЬ: слово
# владельца -- 2.0, и опечатка в файле групп не должна его поднять.
ПОТОЛОК_ПОДЪЁМА_SOL = 2.0

# ПРЕДЕЛ РЕЗЕРВА ДЛЯ ПОДЪЁМА (слово владельца 06.10): поднимать билет только
# если резерв SOL-стороны пула на входе НЕ ВЫШЕ 150 SOL-экв.; выше -- обычный
# билет группы.
#
# ЗАЧЕМ, ЧИСЛАМИ ПО ЦЕПИ. 155 сделок за 11.5 ч гибкого билета (12:44Z 05.10 ->
# 00:21Z 06.10): корзина резерва выше 150 SOL дала -1.6160 SOL при 39.3 % в
# плюсе и билете, всегда упирающемся в потолок 2.0, тогда как середина
# 50-150 с билетом ~1.54 принесла +2.6249, а корзина ниже 50 -- +0.2524.
# Дверь закрывается именно у верхней корзины; доля, потолок и пол не меняются.
ПРЕДЕЛ_РЕЗЕРВА_ПОДЪЁМА_SOL = 150.0

# ПОДЪЁМ ВЫКЛЮЧЕН В КОДЕ (слово владельца 06.10: "подъём и гибкий билет
# выключить"). Поля bilet_dolya сняты у всех групп той же правкой, то есть
# подъём выключен и файлом; рубильник в коде стоит рядом по одной причине --
# ДЕНЬГИ: потолок полосы вернулся на 0.5, и если поле bilet_dolya когда-нибудь
# снова окажется в файле группы, подъём посчитает билет выше потолка и покупка
# ОТКАЖЕТ (живой случай 05.10 выше). Пока здесь False, поле в файле не может
# отнять ни одной покупки: билет остаётся билетом группы.
#
# ЧИСЛА ПО ЦЕПИ, ПОЧЕМУ ПОДЪЁМ ВЫКЛЮЧЕН: 155 сделок за 11.5 ч гибкого билета
# (12:44Z 05.10 -> 00:21Z 06.10) при вложенных 167.3626 SOL дали +0.0219 SOL --
# то есть ноль при двадцатикратном билете; корзина резерва выше 150 SOL дала
# -1.6160.
ПОДЪЁМ_ВКЛЮЧЁН = False


def подъём_билета(билет_группы_sol, ответ_билета,
                   *, потолок_sol: float = ПОТОЛОК_ПОДЪЁМА_SOL,
                   предел_резерва_sol: float = ПРЕДЕЛ_РЕЗЕРВА_ПОДЪЁМА_SOL) -> dict:
    """ЧИСТОЕ правило подъёма: билет = max(билет группы, min(доля x резерв, потолок)).

    Отдельной функцией, а не строчками в горячем пути, по одной причине: это
    ДЕНЬГИ, и правило должно проверяться без сети и без сборки -- семью
    случаями ниже в самопроверке, включая тот, который дороже всех остальных:
    резерва нет.

    билет_группы_sol -- нынешний билет группы, он же ПОЛ и ответ по умолчанию.
    ответ_билета     -- ответ c3_bilet_ot_rezerva.bilet_dlya_signala, которому
                        потолком отдали потолок ПОДЪЁМА, а полом -- билет группы.

    ПОЧЕМУ РЕЗЕРВ ОБЯЗАТЕЛЕН. Без резерва модуль честно отвечает "билет равен
    потолку", и потолок здесь -- 2.0 SOL. Без проверки на резерв каждый сигнал
    без резерва уехал бы на 2 SOL вместо билета группы -- то есть подъём
    случился бы ровно там, где о пуле ничего не известно.
    """
    из_ = {"лампорты": None, "подъём": False, "почему": None}
    try:
        пол = float(билет_группы_sol)
    except (TypeError, ValueError):
        из_["почему"] = "билет группы не число -- подъёма нет"
        return из_
    if not пол > 0:
        из_["почему"] = f"билет группы не положителен ({пол}) -- подъёма нет"
        return из_
    о = ответ_билета if isinstance(ответ_билета, dict) else {}
    if not о.get("ok"):
        из_["почему"] = (f"модуль билета не ответил: "
                          f"{str(о.get('pochemu') or о.get('rezerv_why_not'))[:120]}")
        return из_
    рез = о.get("rezerv_sol")
    if not (isinstance(рез, (int, float)) and not isinstance(рез, bool) and рез > 0):
        из_["почему"] = (f"резерва нет ({о.get('rezerv_why_not') or 'причина не названа'})"
                          f" -- билет группы {пол}")
        return из_
    # ПРЕДЕЛ РЕЗЕРВА -- ДВЕРЬ, А НЕ СРЕЗ (слово владельца 06.10). Выше предела
    # подъёма не происходит вовсе: покупка идёт обычным билетом группы, а не
    # уменьшенным. Числа, по которым дверь закрыта, -- в комментарии к
    # ПРЕДЕЛ_РЕЗЕРВА_ПОДЪЁМА_SOL.
    try:
        _пред = float(предел_резерва_sol)
    except (TypeError, ValueError):
        _пред = ПРЕДЕЛ_РЕЗЕРВА_ПОДЪЁМА_SOL
    if _пред > 0 and float(рез) > _пред:
        из_["почему"] = (f"резерв {рез} SOL-экв. выше предела подъёма {_пред}"
                          f" -- билет группы {пол}")
        из_["предел_резерва"] = _пред
        return из_
    бил = о.get("bilet_sol")
    if not (isinstance(бил, (int, float)) and not isinstance(бил, bool)):
        из_["почему"] = "модуль не дал числа билета -- билет группы"
        return из_
    # СРЕЗ ПО ПОТОЛКУ -- И В ЛАМПОРТАХ ТОЖЕ. Здесь стояло min() только по
    # SOL, а лампорты брались у модуля как есть: при ответе модуля ВЫШЕ
    # потолка подъём уехал бы на полное число (проверка «5.0 от модуля -> 2.0»
    # поймала это красным). На живом пути потолок у модуля и здесь один, то
    # есть срез уже сделан им, -- но правило не должно держаться на этом
    # совпадении: деньги считает оно.
    _бил_исх = float(бил)
    бил = min(_бил_исх, float(потолок_sol))
    if бил <= пол:
        из_["почему"] = (f"доля от резерва {рез} SOL-экв. даёт {бил} -- не выше "
                          f"пола {пол}, билет группы")
        return из_
    лам = о.get("bilet_lamporty")
    if бил < _бил_исх or not (isinstance(лам, int) and лам > 0):
        # ЛАМПОРТЫ ИЗ СРЕЗАННОГО ЧИСЛА, тем же точным умножением, что у модуля.
        from decimal import Decimal as _D  # noqa: PLC0415
        лам = int(_D(str(бил)) * _D(1_000_000_000))
    if not (isinstance(лам, int) and лам > 0):
        из_["почему"] = "лампортов билета нет -- билет группы"
        return из_
    из_.update(лампорты=int(лам), подъём=True,
                почему=(f"подъём: доля от резерва {рез} SOL-экв. даёт {бил} SOL "
                         f"при поле {пол} и потолке {float(потолок_sol)}"))
    return из_


def размер_sol(группа: str | None = None) -> float:
    """Размер сделки полосы. У ГРУППЫ ИСТОЧНИКА он свой.

    Владелец 25.09: "0.05 SOL на источниках 1.1 и BATCH-3/5, 0.01 на
    speed_only". Размер группы приходит из файла групп (источник правды --
    там), а окружение остаётся значением по умолчанию: группы, которой в файле
    нет, ведут себя как до 25.09.
    """
    если = None
    if группа:
        try:
            import bloom_source_groups as SG  # noqa: PLC0415

            если = SG.политика(группа).get("lane_sol")
        except Exception:  # noqa: BLE001
            если = None
    if если:
        return float(если)
    return ST.env_float("BLOOM_OWN_SEND_SOL", 0.01)


# РАЗМЕР ПЕРВЫХ СДЕЛОК ГРУППЫ. Слово владельца 27.09 (финальный план, п.2):
# "Первые три сделки каждой группы -- 0.01, затем lane_size группы
# автоматически, без ожидания сигнала штаба". Считаются СЕВШИЕ по цепи покупки:
# не севшая ничего не проверила, и уменьшать по ней размер нечестно.
# РАЗМЕР ПЕРВОЙ ДВУХШАГОВОЙ СДЕЛКИ. Слово владельца 27.09 (дополнение):
# "разгон «три по 0.01» убрать везде, кроме первой двухшаговой сделки". Разгон
# по группам снят: размер группы берётся сразу. Двухшаговый путь боем ещё не
# проверен ни разу (правило 10.2: проверка -- одна живая сделка), поэтому
# ПЕРВАЯ двухшаговая покупка идёт по 0.01, а дальше -- размер группы.
РАЗМЕР_ПЕРВОЙ_ДВУХШАГОВОЙ_SOL = 0.01
ДВУХШАГОВЫХ_ПЕРВЫХ = 1
# ПОТОЛОК БОЕВОЙ USDC-НОГИ (слово владельца 01.10: "п.9 USDC боевой 0.01").
#
# ПОЧЕМУ ОТДЕЛЬНЫМ ЧИСЛОМ, А НЕ ПРАВИЛОМ "первая двухшаговая". Размер
# USDC-ноги берётся у `размер_первой_двухшаговой`, а её счётчик
# `двухшаговых_село` считает позиции с меткой `lane_two_step`. У USDC-ноги
# маршрут свой, метки этой нет, и счётчик её покупок НЕ УВИДИТ: размер остался
# бы 0.01 СЛУЧАЙНО, по недосмотру счётчика, а не по правилу. Такое "везение"
# однажды кончится -- стоит двухшаговой сделке сесть, и следующая USDC-нога
# уйдёт полным размером группы (0.1 у cand1, 0.5 у lane_s0 завтра), чего
# владелец не велел.
#
# Поэтому потолок назван числом и поднимается ОДНИМ значением env, а не деплоем:
# владелец решает по числам первой боевой сделки.
ПОТОЛОК_USDC_НОГИ_SOL = ST.env_float("BLOOM_USDC_NOGA_POTOLOK_SOL", 0.01)
# ПЕРВАЯ СДЕЛКА НА НОВОМ ТИПЕ ПУЛА -- 0.01 SOL (слово владельца 28.09, очередь
# строителей). Считается по программе пула из записи позиции: пока на ней не
# село ни одной покупки, идёт проверочный размер, дальше -- размер группы.
РАЗМЕР_ПЕРВОЙ_НА_ПРОГРАММЕ_SOL = 0.01
ПЕРВЫХ_НА_ПРОГРАММЕ = 1


def сделок_группы(позиции: dict, группа: str | None) -> int:
    """Сколько покупок этой группы уже СЕЛИ по цепи."""
    if not группа:
        return 0
    return sum(1 for p in (позиции or {}).values()
               if (p or {}).get("lane") == МЕТКА
               and (p or {}).get("lane_group") == группа
               and (p or {}).get("chain_ok") is True)


# СКОЛЬКО ПОСАДОК USDC-НОГИ СНИМАЕТ ПОТОЛОК 0.01 (слово владельца 02.10, п.3):
# "после трёх посадок USDC-ноги на 0.01 ... потолок USDC-ноги для остальных групп
# -- размер их группы". До трёх посадок потолок стоит, после -- снимается, и
# размер становится обычным размером группы.
ПОСАДОК_USDC_НОГИ_ДЛЯ_РАЗМЕРА = 3


def усдс_ноги_село(позиции: dict | None) -> int:
    """Сколько покупок USDC-НОГОЙ уже сели по цепи -- по ВСЕМ группам.

    По всем группам намеренно: проверяется САМ МАРШРУТ, а он у групп один -- ровно
    та же причина, по которой так считается двухшаговый путь.

    СЧИТАЕТСЯ ПО ПОЛЮ route, А НЕ ПО lane_two_step. Это записано в комментарии к
    самому потолку: у USDC-ноги метки lane_two_step НЕТ ВОВСЕ, и счётчик
    двухшаговых её покупок не видит. Считать её тем счётчиком значило бы снять
    потолок на чужих посадках -- то есть отправить полный размер группы (0.1 у
    cand1, 0.5 у lane_s0) по маршруту, который владелец ещё не обкатал.
    """
    try:
        import c2_usdc_noga as UN  # noqa: PLC0415

        маршрут = UN.ROUTE
    except Exception:  # noqa: BLE001
        # МОДУЛЯ НЕТ -- НОЛЬ ПОСАДОК, а не "наверное уже обкатали": неизвестность
        # в сторону денег не трактуется, и потолок остаётся стоять.
        return 0
    return sum(1 for p in (позиции or {}).values()
               if (p or {}).get("lane") == МЕТКА
               and (p or {}).get("route") == маршрут
               and (p or {}).get("chain_ok") is True)


def потолок_usdc_ноги_sol(позиции: dict | None) -> dict:
    """Потолок размера USDC-ноги сейчас. None -- потолка нет (размер группы).

    Чистая функция от записей: ни сети, ни env сверх уже прочитанного числа.
    """
    село = усдс_ноги_село(позиции)
    если_снят = село >= ПОСАДОК_USDC_НОГИ_ДЛЯ_РАЗМЕРА
    return {"село": село, "нужно": ПОСАДОК_USDC_НОГИ_ДЛЯ_РАЗМЕРА,
             "потолок_sol": (None if если_снят else ПОТОЛОК_USDC_НОГИ_SOL),
             "снят": если_снят,
             "почему": (f"посадок USDC-ноги {село} из "
                         f"{ПОСАДОК_USDC_НОГИ_ДЛЯ_РАЗМЕРА} -- потолок "
                         f"{ПОТОЛОК_USDC_НОГИ_SOL} SOL стоит"
                         if not если_снят else
                         f"посадок USDC-ноги {село} -- потолок снят, размер группы")}


def двухшаговых_село(позиции: dict | None) -> int:
    """Сколько ДВУХШАГОВЫХ покупок полосы уже сели по цепи -- по всем группам.

    Считается по всем группам, а не по одной: проверяется САМ СТРОИТЕЛЬ, а он у
    всех групп один. Метку lane_two_step ставит отправка, когда маршрут вышел
    двухшаговым.
    """
    return sum(1 for p in (позиции or {}).values()
               if (p or {}).get("lane") == МЕТКА
               and (p or {}).get("lane_two_step") is True
               and (p or {}).get("chain_ok") is True)


def размер_для_группы(группа: str | None, позиции: dict | None = None) -> dict:
    """Размер ЭТОЙ покупки в SOL и словами -- почему он такой.

    Разгона по группам больше нет (слово владельца 27.09, дополнение): размер
    группы берётся сразу. Севшие сделки группы всё равно считаются -- число
    идёт в строку позиции и в доклад.
    """
    полный = размер_sol(группа)
    село = сделок_группы(позиции or {}, группа)
    return {"sol": полный, "first_trades": False, "landed": село,
             "full_sol": полный, "why": None}


# ПОКОЛЕНИЕ СБОРКИ ПО ПРОГРАММЕ ПУЛА. Правило "первая сделка на новом типе пула
# -- 0.01" считает СЕВШИЕ покупки полосы на этой программе. Но когда путь сборки
# для программы переписан, прежняя севшая покупка проверяла ДРУГОЙ код и больше
# не доказательство. Тогда поколение программы поднимается на единицу, и счётчик
# начинает с нуля -- БЕЗ ЕДИНОЙ ПРАВКИ В ЖУРНАЛЕ ПОЗИЦИЙ: история остаётся как
# была, просто севшие по прежнему поколению к новому не относятся.
#
# LBUZ... (Meteora DLMM) -- поколение 2 с 29.09 по слову владельца: сборка
# получила массивы корзин хвостом, точную цену от котировщика и отказ "массивов
# не хватает". Севшая 17:15:01Z покупка шла по поколению 1.
ПОКОЛЕНИЕ_СБОРКИ = {"LBUZKhRxPF3XUpBCjp4YzTKgLccjZhTSDM9YuVaPwxo": 2}


def тень_dlmm(сб: dict) -> tuple:
    """(годилось, почему_нет) теневого замера одного чтения DLMM из сборки.

    Рядом с чтения_dlmm и по тому же правилу: если раздела нет -- (None, None), а
    не выдуманный ноль. Поля идут в запись позиции и в выгрузку.
    """
    д = (сб or {}).get("dlmm")
    т = (д or {}).get("одно_чтение_тень") if isinstance(д, dict) else None
    if not isinstance(т, dict):
        return (None, None)
    г = т.get("годилось")
    return (г if isinstance(г, bool) else None, т.get("почему_нет"))


def тень_dlmm_нуль(сб: dict) -> dict:
    """Числа теневого замера НУЛЯ чтений из сборки: пусто -> пустые поля.

    Тем же правилом, что тень_dlmm: нет раздела -- None по каждому полю, а не
    выдуманный ноль. Возвращается словарь, а не пара, потому что полей тут шесть:
    годилось, причина, две цены и два минимума.
    """
    пусто = {"годилось": None, "почему_нет": None, "цена_полосы": None,
              "цена_тени": None, "min_out_полосы": None, "min_out_тени": None,
              "отклонение_%": None}
    д = (сб or {}).get("dlmm")
    т = (д or {}).get("нуль_чтений_тень") if isinstance(д, dict) else None
    if not isinstance(т, dict):
        return пусто
    из_ = dict(пусто)
    for ключ in пусто:
        из_[ключ] = т.get(ключ)
    г = из_.get("годилось")
    из_["годилось"] = г if isinstance(г, bool) else None
    return из_


def чтения_dlmm(сб: dict) -> tuple:
    """Сколько чтений узла стоила точная котировка DLMM и сколько это мс.

    ЗАЧЕМ (слово владельца в ночь 29->30.09, п.1): "счётчики чтений DLMM
    (чтений, мс_чтений_всего) -- писать в запись позиции". До этого они жили
    только внутри собрать(), в из_["dlmm"], и наружу не выходили: вопрос "из
    39 мс сборки сколько ушло в сеть" по записи позиции не имел ответа, а по
    журналу службы -- тоже, этих полей там нет вовсе.

    ЛОГИКИ ЗДЕСЬ НЕТ. Только достать два числа. Нет блока или чисел -- None, а
    не ноль: ноль читался бы как "сеть не трогали", а это ложь.
    """
    д = (сб or {}).get("dlmm")
    if not isinstance(д, dict):
        return (None, None)
    ч = д.get("чтений")
    мс = д.get("мс_чтений") if д.get("мс_чтений") is not None else д.get("мс_чтений_всего")
    return (ч if isinstance(ч, int) else None,
            round(float(мс), 3) if isinstance(мс, (int, float)) else None)


def поколение_сборки(программа: str | None) -> int:
    """Поколение пути сборки для этой программы пула. Неизвестной -- 1."""
    try:
        return int(ПОКОЛЕНИЕ_СБОРКИ.get(str(программа or ""), 1))
    except (TypeError, ValueError):
        return 1


def село_на_программе(позиции: dict | None, программа: str | None) -> int:
    """Сколько покупок полосы уже СЕЛИ на этой программе пула И в этом поколении.

    Программа пишется в позицию полем program при отправке, поколение -- полем
    program_gen. Считается по ВСЕМ группам: проверяется САМ СТРОИТЕЛЬ, а он у
    всех групп один -- как и у двухшагового пути. Позиция без program_gen -- это
    позиция ПЕРВОГО поколения: поля тогда просто не было.
    """
    if not программа:
        return 0
    нужно = поколение_сборки(программа)
    return sum(1 for p in (позиции or {}).values()
               if (p or {}).get("lane") == МЕТКА
               and (p or {}).get("program") == программа
               and (p or {}).get("chain_ok") is True
               and поколение_позиции(p) == нужно)


def поколение_позиции(поз: dict | None) -> int:
    """Поколение сборки, записанное в позицию. Поля нет -- значит первое."""
    з = (поз or {}).get("program_gen")
    try:
        return int(з) if з is not None else 1
    except (TypeError, ValueError):
        return 1


def размер_первой_на_программе(позиции: dict | None, программа: str | None,
                                полный_лампорты: int) -> dict:
    """Лампорты для НОВОГО типа пула: первая сделка -- 0.01, дальше размер группы.

    Слово владельца 28.09 (очередь строителей): "включение через lane_pools ->
    первая живая сделка 0.01 на его пуле -> размер группы". Порог тот же, что у
    двухшагового пути, и по той же причине: проверяется строитель, а не рынок,
    и платить за проверку полным размером группы незачем. Размер группы меньше
    0.01 -- берётся он: поднимать размер ради первой сделки было бы наоборот.
    """
    село = село_на_программе(позиции, программа)
    if село >= ПЕРВЫХ_НА_ПРОГРАММЕ:
        return {"lamports": int(полный_лампорты), "first": False, "landed": село,
                 "why": None}
    первые = int(round(РАЗМЕР_ПЕРВОЙ_НА_ПРОГРАММЕ_SOL * ЛАМПОРТОВ_В_SOL))
    взять = min(первые, int(полный_лампорты))
    return {"lamports": взять, "first": True, "landed": село,
             "why": (f"первая сделка на пуле {str(программа)[:10]} по "
                      f"{взять / ЛАМПОРТОВ_В_SOL} SOL (на этой программе село "
                      f"{село})")}


def размер_первой_двухшаговой(позиции: dict | None, полный_лампорты: int) -> dict:
    """Лампорты для ДВУХШАГОВОЙ сборки: первая -- 0.01, дальше размер группы.

    Если размер группы меньше 0.01, берётся он: поднимать размер "ради первой
    сделки" было бы наоборот.
    """
    село = двухшаговых_село(позиции)
    if село >= ДВУХШАГОВЫХ_ПЕРВЫХ:
        return {"lamports": int(полный_лампорты), "first": False, "landed": село,
                 "why": None}
    первые = int(round(РАЗМЕР_ПЕРВОЙ_ДВУХШАГОВОЙ_SOL * ЛАМПОРТОВ_В_SOL))
    взять = min(первые, int(полный_лампорты))
    return {"lamports": взять, "first": True, "landed": село,
             "why": (f"первая двухшаговая сделка по {взять / ЛАМПОРТОВ_В_SOL} SOL "
                      f"(двухшаговых село {село})")}


def _число_группы(группа: str | None, поле: str):
    """Число из политики группы или None. Одно место на все новые поля."""
    if not группа:
        return None
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        з = SG.политика(группа).get(поле)
    except Exception:  # noqa: BLE001
        return None
    return з if isinstance(з, (int, float)) and not isinstance(з, bool) else None


def _признак_группы(группа: str | None, поле: str) -> bool | None:
    """Признак (да/нет) из политики группы или None, если его там нет.

    Отдельно от _число_группы, потому что bool в питоне -- тоже int, и
    числовой читатель вернул бы True как 1, а отсутствие -- как None: отличить
    "выключено" от "не задано" стало бы нечем.
    """
    if not группа:
        return None
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        з = SG.политика(группа).get(поле)
    except Exception:  # noqa: BLE001
        return None
    if isinstance(з, bool):
        return з
    if isinstance(з, int) and з in (0, 1):
        return bool(з)
    return None


ПОЛЕ_СВОИМ_ПЕРВЫМ = "sell_own_first"


def своим_путём_первым(группа: str | None = None) -> bool:
    """Продавать позиции ЭТОЙ группы своим путём ДО Jupiter. По умолчанию нет.

    ЗАЧЕМ ПОЛЕ ГРУППЫ, А НЕ ВЫКЛЮЧАТЕЛЬ JUPITER. Чтобы обкатать круг 0.01 на
    своей продаже (правило 8), нужна позиция, которая пойдёт своим путём, а не
    Jupiter'ом. Единственный существующий рычаг -- BLOOM_SELL_VIA_JUPITER, и он
    ОБЩИЙ: выключив его при ПУСТОМ реестре обкатки, мы оставили бы без выхода
    КАЖДУЮ позицию полосы -- дверь круга не пускает своим путём ничего крупнее
    0.01, а Jupiter был бы выключен, и всё ушло бы в UNSOLD. Поэтому признак
    группы: одна группа идёт своим путём первой, остальные торгуют как торговали.

    JUPITER ОСТАЁТСЯ СЕТКОЙ. Признак меняет только ПОРЯДОК: свой путь
    спрашивается раньше, а отказал он -- позиция всё равно уходит Jupiter'ом.
    Иначе признак сам стал бы способом оставить позицию без выхода.
    """
    return _признак_группы(группа, ПОЛЕ_СВОИМ_ПЕРВЫМ) is True


def проскальзывание_группы(группа: str | None = None) -> float | None:
    """Допустимая наценка нашей цены входа к цене сразу ПОСЛЕ источника.

    Это же число и есть проскальзывание минимума выхода: min_out считается по
    резервам пула после сделки источника (c2_swap_build.min_out_from_reserves),
    поэтому одно поле задаёт и допуск по цене, и защиту транзакции. Выше --
    min-out не пропускает, и повтор НЕ делается (слово владельца 27.09).
    """
    з = _число_группы(группа, "slippage")
    return float(з) if з is not None and 0 < float(з) < 1 else None


def абс_разница(a, b) -> float:
    """|a - b| для чисел, которые могли прийти как None."""
    try:
        return abs(float(a) - float(b))
    except (TypeError, ValueError):
        return 0.0


def проскальзывание_тонкого_пула(группа: str | None = None):
    """Наценка на ТОНКОМ пуле и порог тонкости в SOL-экв. (None, None) -- правила нет.

    ПОЧЕМУ ОТДЕЛЬНЫЙ ЧИТАТЕЛЬ, А НЕ ТОТ ЖЕ. Обычная наценка обязана лежать
    строго между 0 и 1: единица там означала бы min_out = 0, то есть подпись
    без пола выхода. Наценка тонкого пула -- решение владельца 27.09 вечером, и
    он назвал именно 1.0, поэтому здесь единица ДОПУСКАЕТСЯ. Что она делает
    механически, видно в строке решения: min_out при ней обращается в ноль, и
    этот случай называется словами (min_out_floor_absent), а не проходит молча.
    """
    з = _число_группы(группа, "slippage_thin_pool")
    порог = _число_группы(группа, "thin_pool_below_sol")
    if з is None or порог is None:
        return None, None
    з, порог = float(з), float(порог)
    if not (0 < з <= 1.0) or порог <= 0:
        return None, None
    return з, порог


def проскальзывание_для_пула(группа: str | None, резерв_sol) -> dict:
    """Какая наценка берётся ДЛЯ ЭТОГО пула: обычная или для тонкого.

    резерв_sol -- резерв КОТИРОВОЧНОЙ стороны пула в SOL-эквиваленте, из meta
    сделки источника. Неизвестен -- берём обычную: отказывать по неизвестному
    числу нельзя, но и считать пул тонким наугад тоже.
    """
    обычная = проскальзывание_группы(группа)
    тонкая, порог = проскальзывание_тонкого_пула(группа)
    из_ = {"slippage": обычная, "thin": False, "threshold_sol": порог,
            "reserve_sol": (float(резерв_sol)
                            if isinstance(резерв_sol, (int, float)) else None),
            "why": None}
    if тонкая is None or порог is None:
        return из_
    if из_["reserve_sol"] is None:
        из_["why"] = "резерв пула неизвестен -- наценка обычная"
        return из_
    if из_["reserve_sol"] < порог:
        из_.update(slippage=тонкая, thin=True,
                    why=(f"резерв котировочной стороны {из_['reserve_sol']:.3f} "
                          f"SOL-экв. ниже {порог} -- наценка {тонкая}"))
    return из_


def резерв_пула_минимум_sol(группа: str | None = None) -> float | None:
    """Нижний предел резерва пула в SOL-эквиваленте на момент входа."""
    з = _число_группы(группа, "min_pool_sol_reserve")
    return float(з) if з is not None and float(з) > 0 else None


def предел_слотов_от_источника(группа: str | None = None) -> int | None:
    """Сколько слотов от s0 ещё можно покупать. None -- предела нет."""
    з = _число_группы(группа, "max_slots_from_source")
    return int(з) if з is not None and int(з) >= 0 else None


def слотов_держать(группа: str | None = None) -> float:
    """Сколько слотов от s0 держим позицию (выход по таймеру)."""
    з = _число_группы(группа, "hold_slots")
    return float(з) if з is not None and float(з) > 0 else 72.0


def слотов_держать_по_размеру(группа: str | None = None,
                                трата_источника_sol: float | None = None) -> float:
    """Таймер выхода с поправкой на размер покупки ИСТОЧНИКА.

    Слово владельца 27.09 (вечер): "leader: hold_slots 36 при размере покупки
    источника < 15 SOL-экв, 150 при >= 15". Правило задаётся двумя полями
    группы: hold_slots_small (сколько держать на мелкой) и
    hold_slots_small_below_sol (ниже какого размера покупка считается мелкой).
    Нет хотя бы одного поля -- правила нет, таймер обычный. Нет размера
    покупки источника -- тоже обычный: угадывать нельзя, а обычный таймер
    больше, то есть безопаснее для мелкой покупки, чем обрезанный для крупной.
    """
    обычный = слотов_держать(группа)
    мелкий = _число_группы(группа, "hold_slots_small")
    порог = _число_группы(группа, "hold_slots_small_below_sol")
    if мелкий is None or порог is None:
        return обычный
    if трата_источника_sol is None:
        return обычный
    try:
        размер = float(трата_источника_sol)
    except (TypeError, ValueError):
        return обычный
    if размер < float(порог) and float(мелкий) > 0:
        return float(мелкий)
    return обычный


def пропускать_перекупщиков(группа: str | None = None) -> bool:
    """Пропускать ли помеченных перекупщиков (доля "продал в окне" > 30 %)."""
    if not группа:
        return False
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        return bool(SG.политика(группа).get("skip_flippers"))
    except Exception:  # noqa: BLE001
        return False


def источник_перекупщик(источник: str | None) -> bool:
    """Помечен ли ЭТОТ адрес перекупщиком в файле групп."""
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        return bool(SG.перекупщик(источник))
    except Exception:  # noqa: BLE001
        return False


def налоговый_маршрут_разрешён(группа: str | None = None):
    """True -- берём и пишем налог в решение, False -- не берём, None -- как было."""
    if not группа:
        return None
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        з = SG.политика(группа).get("allow_taxed_route")
    except Exception:  # noqa: BLE001
        return None
    return bool(з) if isinstance(з, bool) else None


def веер_нужен(группа: str | None = None) -> bool:
    """Идёт ли по этой группе веер контролей.

    Владелец 25.09 про speed_only: "через пул без веера". Веер -- это замер, и
    на группе, которая сама и есть замер скорости, он лишний расход.
    """
    if not группа:
        return True
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        return bool(SG.политика(группа).get("fanout", True))
    except Exception:  # noqa: BLE001
        return True


def полоса_торгует(группа: str | None) -> bool:
    """Торгует ли полоса по этой группе.

    ЗАЧЕМ ОТДЕЛЬНЫЙ ПРИЗНАК. Ночью 26.09 владелец велел выключить speed_only
    целиком. Нулями это не выражается: в размер_sol и потолок_группы ноль
    ложен ("if если", "or потолок") и уходит в значение по умолчанию -- группа
    продолжала бы торговать размером из окружения. Поэтому выключение -- это
    признак lane_trades в файле групп, и читается он ЗДЕСЬ, на денежном пути.

    Групп нет вовсе или поля нет -- торгует: так было до этой правки.
    """
    if not группа:
        return True
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        return bool(SG.политика(группа).get("lane_trades", True))
    except Exception:  # noqa: BLE001
        return True


def предел_открытых(группа: str | None) -> int:
    """Сколько позиций полосы может быть открыто одновременно.

    Число берётся ИЗ ФАЙЛА ГРУПП (поле lane_open_max) и только при его
    отсутствии -- из ЛИМИТ_ОТКРЫТЫХ. Слово владельца 26.09 (ночь, в утреннюю
    очередь): "предел открытых позиций полосы 1 -> 3 для bloom_lane/lane_only/
    candidates". Поле, а не общая постоянная, потому что у групп разные деньги:
    поднять предел кандидатам не значит поднять его группе скорости.

    Ноль и отрицательное ГРУППУ НЕ ВЫКЛЮЧАЮТ -- уходят в общий предел, как и
    все прочие числа политики (в потолок_группы и размер_sol ноль тоже ложен).
    Выключает группу признак lane_trades, и только он.

    Считается при этом всё равно кошелёк целиком (состояние_полосы.open
    складывает все группы): предел -- про то, сколько покупок кошелёк вынесет,
    а берётся он у той группы, которая сейчас просит вход.
    """
    if not группа:
        return ЛИМИТ_ОТКРЫТЫХ
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        сырое = SG.политика(группа).get("lane_open_max")
    except Exception:  # noqa: BLE001
        return ЛИМИТ_ОТКРЫТЫХ
    try:
        число = int(сырое)
    except (TypeError, ValueError):
        return ЛИМИТ_ОТКРЫТЫХ
    return число if число > 0 else ЛИМИТ_ОТКРЫТЫХ


def потолок_группы(группа: str | None) -> dict:
    """Суточный потолок расхода и стоп убытка ДЛЯ ГРУППЫ.

    У группы скорости они свои (0.2 и 0.15 SOL по слову владельца); у
    остальных -- общие пределы полосы, НО если в файле групп стоит своё число,
    оно и действует: ночной стоп -0.15 на bloom_lane и lane_only (слово
    владельца 26.09) задаётся именно так, а раньше файл для этих групп не
    читался вовсе и стоп молча оставался -0.3.
    """
    if группа != ГРУППА_СКОРОСТИ:
        из_ = {"day_cap_sol": None, "stop_loss_sol": СТОП_УБЫТОК_SOL,
                "per_day": ЛИМИТ_В_СУТКИ,
                # ЧАСОВОГО ПРЕДЕЛА ПО УМОЛЧАНИЮ НЕТ. None значит "не
                # ограничиваем" -- ровно как было до правки 10.10, и ни одна
                # существующая группа от неё не меняется.
                "per_hour": None}
        try:
            import bloom_source_groups as SG  # noqa: PLC0415

            п = SG.политика(группа)
        except Exception:  # noqa: BLE001
            return из_
        # is not None, а не "or": ноль -- это осмысленный стоп (остановить
        # сразу), и подменять его значением по умолчанию нельзя.
        if п.get("stop_loss_sol") is not None:
            из_["stop_loss_sol"] = float(п["stop_loss_sol"])
        if п.get("day_cap_sol") is not None:
            из_["day_cap_sol"] = float(п["day_cap_sol"])
        # ПОЛЕ ГРУППЫ СИЛЬНЕЕ ВХОДА. is not None, а не "or": ноль -- осмысленный
        # запрет (группа не торгует вовсе), и подменять его умолчанием нельзя.
        # Мусор в поле не превращается в запрет: число не разобралось -- остаётся
        # общий предел, и причина видна в самом файле групп.
        if п.get("per_day") is not None:
            try:
                из_["per_day"] = int(п["per_day"])
            except (TypeError, ValueError):
                из_["per_day_spor"] = п.get("per_day")
        # ПРЕДЕЛ ПОКУПОК В ЧАС (слово владельца 10.10, п.2). МУСОР В ПОЛЕ --
        # ЭТО ЗАПРЕТ, А НЕ "предела нет". Здесь иначе, чем у per_day, и
        # нарочно: у per_day непонятное значение оставляет ОБЩИЙ предел полосы,
        # то есть защита остаётся; у per_hour общего предела не существует, и
        # "число не разобралось" означало бы торговлю без часового предела
        # вовсе -- ровно то, от чего это поле и ставят.
        if п.get("per_hour") is not None:
            try:
                из_["per_hour"] = int(п["per_hour"])
            except (TypeError, ValueError):
                из_["per_hour"] = 0
                из_["per_hour_spor"] = п.get("per_hour")
        # ПРАВИЛО 16: дневного стопа у группы нет -- и число из файла его
        # тоже не возвращает. Гасится ПОСЛЕ чтения файла нарочно: иначе
        # оставшееся поле stop_loss_sol тихо вернуло бы стоп обратно.
        if not _суточный_стоп_групп_включён():
            из_["stop_loss_sol"] = None
            из_["stop_loss_why_not"] = ("Правило 16: дневных стопов групп нет, "
                                         "вместо них стоп «авария»")
        return из_
    потолок, стоп = ПОТОЛОК_СУТОК_СКОРОСТИ_SOL, СТОП_УБЫТОК_СКОРОСТИ_SOL
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        п = SG.политика(группа)
        потолок = float(п.get("day_cap_sol") or потолок)
        стоп = float(п.get("stop_loss_sol") or стоп)
    except Exception:  # noqa: BLE001
        pass
    # Сколько сделок влезает в потолок -- считается, а не задаётся: при 0.01 на
    # сделку и потолке 0.2 SOL это двадцать сделок вместе с чаевыми.
    if not _суточный_стоп_групп_включён():
        # ПРАВИЛО 16 -- и для группы скорости тоже: "убрать у всех групп".
        return {"day_cap_sol": потолок, "stop_loss_sol": None, "per_day": None,
                 "stop_loss_why_not": ("Правило 16: дневных стопов групп нет, "
                                        "вместо них стоп «авария»")}
    return {"day_cap_sol": потолок, "stop_loss_sol": стоп, "per_day": None}


def чаевые_sol() -> float:
    """Чаевые Sender. Ниже документированного минимума не опускаемся.

    Меньший тип документация принимает, но он идёт мимо приоритетного
    буфера -- полоса тогда мерила бы не тот путь, ради которого заведена.
    """
    з = ST.env_float("BLOOM_OWN_SEND_TIP_SOL", TIP_MIN_SOL)
    return max(з, TIP_MIN_SOL)


def приоритет_sol() -> float:
    return ST.env_float("BLOOM_OWN_SEND_PRIORITY_SOL", 0.001)


def выбрать_чаевые(семя: str | None = None) -> str:
    """Адрес для чаевых. Разный от сделки к сделке.

    Документация даёт десять адресов не для красоты: один и тот же счёт на
    каждой отправке -- лишняя точка соперничества за запись.
    """
    if not семя:
        return random.choice(TIP_ACCOUNTS)
    return TIP_ACCOUNTS[sum(bytearray(семя.encode("utf-8"))) % len(TIP_ACCOUNTS)]


# ПРЕДЕЛ CU ПОКУПКИ. Слово владельца 28.09: "лимит CU покупки 400 000 ->
# 140 000 (по факту + 20 %)". По факту одношаговая покупка сжигает 115 210
# единиц (замер 28.09 по нашей транзакции KABUTSTR), плюс пятая часть запаса.
# ЦЕНА ЗА ЕДИНИЦУ СЧИТАЕТСЯ ОТ ЭТОГО ПРЕДЕЛА (цена_единицы_cu), поэтому сумма
# приоритета не меняется -- она по-прежнему 0.001 SOL, -- а цена за единицу
# втрое выше: 7 142 857 микролампортов против 2 500 000. Планировщику блока
# важна именно она, а запрошенный предел -- это ещё и место в блоке.
ПРЕДЕЛ_CU_ПОКУПКИ = ST.env_int("BLOOM_LANE_CU_LIMIT", 140_000)
# ПРЕДЕЛ CU -- ПО СТРОИТЕЛЮ, И ОТ МАКСИМУМА, А НЕ ОТ p99 (решение владельца
# 28.09: "приоритет место не покупает, а падение по лимиту теряет сделку").
# Числа названы владельцем по замеру суток 28.09 (p50/p99/макс):
#   pump_amm  p50 115 749, p99 136 100, макс 136 100 -> макс + 25 % = 170 000
#   bonding   p50 106 410, p99 110 646, макс 110 646 -> 140 000 (как было)
#   two_step  сделок в сутках нет -> 250 000 до первых 20 сделок
#   всё новое (launchlab, dlmm, whirlpool, amm v4 и любой неизвестный адрес,
#   а равно строители с меньше чем 20 сделками) -> 200 000 до 20 сделок,
#   потом макс + 25 % по замеру.
# Переход "после 20 сделок" делает владелец по вечерним числам: считать сделки
# на горячем пути значило бы читать журнал позиций перед каждой покупкой.
ПРЕДЕЛЫ_CU_СТРОИТЕЛЕЙ = {
    "pump_amm": ST.env_int("BLOOM_LANE_CU_PUMP_AMM", 170_000),
    "bonding": ST.env_int("BLOOM_LANE_CU_BONDING", 140_000),
    # ДВУХШАГОВАЯ -- 800 000 до первых 20 сделок (решение владельца 28.09,
    # после поправки про плату): лимит больше не стоит денег, а падение по
    # лимиту стоит сделку. Это и было прежнее умолчание модуля сборки.
    "two_step": ST.env_int("BLOOM_LANE_CU_TWO_STEP", 800_000),
}
ПРЕДЕЛ_CU_НОВОГО = ST.env_int("BLOOM_LANE_CU_NEW", 200_000)
# КРИВАЯ, РАЗНОВИДНОСТЬ V2 (BuyExactQuoteInV2, дискриминатор c2ab1c46684d5b2f,
# 27 счетов) -- СВОЙ ПРЕДЕЛ. Слово владельца 28.09: 220 000 отдельной
# переменной, BuyExactSolIn как было. Почему столько: источник 21:37Z сжёг
# 176 866 CU с тремя CreateIdempotent, наша симуляция той же покупки -- 146 133;
# 140 000 общего предела кривой на это не хватает, и покупка падает по лимиту,
# оставляя нам только комиссию.
ПРЕДЕЛ_CU_КРИВОЙ_V2 = ST.env_int("BLOOM_LANE_CU_BONDING_V2", 220_000)
# Дискриминатор разновидности V2 -- тот же, что в раскладке сборщика.
DISC_КРИВОЙ_V2 = "c2ab1c46684d5b2f"
# ПЛАТА ЗА ПРИОРИТЕТ = ЦЕНА x ЛИМИТ, А НЕ x ПОТРАЧЕННЫЕ CU. Так написано в
# документации Solana: prioritization_fee = compute_unit_price x
# compute_unit_LIMIT, и за неиспользованный запас возврата нет. Поправка
# владельца 28.09; моё прежнее рассуждение "платим за потраченные" было
# неверным, и база цены отсюда убрана: цена считается от ПРЕДЕЛА СТРОИТЕЛЯ,
# чтобы общая плата держалась на заданной сумме.
#
# ОБЩАЯ ПЛАТА ЗА ПРИОРИТЕТ, SOL НА СДЕЛКУ. Фиксируется здесь, а лимит CU на
# неё больше не влияет: подняли предел -- цена единицы упала во столько же раз.
ПЛАТА_ПРИОРИТЕТА_SOL = ST.env_float("BLOOM_PRIORITY_FEE", 0.001)


def имя_строителя_по_адресу(адрес: str | None) -> str | None:
    """Адрес программы пула -> короткое имя строителя, которым его зовёт владелец."""
    if not адрес:
        return None
    # Адреса лежат в c2_swap_build (он же B в _модули), но искать их по всем
    # четырём модулям дешевле, чем помнить порядок: первая версия этой функции
    # брала _модули()[0] -- c2_common -- и не находила ни одного адреса.
    try:
        модули = _модули()
    except Exception:  # noqa: BLE001
        return None
    имена = (("BONDING", "bonding"), ("PUMP_AMM", "pump_amm"), ("CPMM", "cpmm"),
             ("DAMM2", "damm2"), ("DBC", "dbc"), ("CLMM", "clmm"),
             ("AMMV4", "amm_v4"),
             ("LAUNCHLAB", "launchlab"), ("DLMM", "dlmm"),
             ("WHIRLPOOL", "whirlpool"))
    for м in модули:
        for конст, имя in имена:
            if getattr(м, конст, None) == адрес:
                return имя
    return None


def предел_cu(строитель: str | None, *, разновидность: str | None = None) -> int:
    """Предел CU покупки для этого строителя. Неизвестный -- как новый.

    Неизвестный адрес получает ПРЕДЕЛ НОВОГО (больший), а не общий: ошибиться в
    сторону большего предела значит заплатить чуть больше сети за неиспользованный
    запас, а в сторону меньшего -- потерять сделку на падении по лимиту.

    РАЗНОВИДНОСТЬ КРИВОЙ РЕШАЕТ ОТДЕЛЬНО: у 27-счётной V2 своя стоимость (у
    источника 176 866 CU), и общий предел кривой 140 000 её не вмещает.
    """
    имя = строитель if строитель in ПРЕДЕЛЫ_CU_СТРОИТЕЛЕЙ else (
        имя_строителя_по_адресу(строитель) or строитель)
    if имя == "bonding" and (разновидность or "") == DISC_КРИВОЙ_V2:
        return int(ПРЕДЕЛ_CU_КРИВОЙ_V2)
    if имя in ПРЕДЕЛЫ_CU_СТРОИТЕЛЕЙ:
        return int(ПРЕДЕЛЫ_CU_СТРОИТЕЛЕЙ[имя])
    return int(ПРЕДЕЛ_CU_НОВОГО)


def цена_единицы_cu(приоритет_лампорты: int, cu_units: int) -> int:
    """Микролампорты за единицу CU, чтобы приоритет вышел заданной суммой."""
    if cu_units <= 0:
        return 0
    return int(приоритет_лампорты * 1_000_000 // cu_units)


# ------------------------------------------------------------------ сборка

ПУЛЫ_ПОЛОСЫ = ("PUMP_AMM", "CPMM")     # имена констант в c2_swap_build


# ГРУППА ЗАПУСКОВ: ЧЛЕНСТВО ПРАВИЛОМ, А НЕ СПИСКОМ АДРЕСОВ.
#
# ЗАЧЕМ ПРАВИЛО. Группа адреса берётся из файла по самому адресу, и это верно
# для всех групп полосы: источник один и тот же, он в файле, его политика
# известна. У сигнала запуска источник -- СОЗДАТЕЛЬ ТОКЕНА, и он каждый раз
# другой: в файле его не бывает и быть не может. Поэтому членство в этой
# ОДНОЙ группе решается правилом по самой транзакции.
#
# ЧЕГО ПРАВИЛО НЕ МОЖЕТ. Оно умеет вернуть РОВНО ОДНО имя -- zapusk_dev -- и
# только когда: (1) группа есть в файле групп, (2) у неё включён lane_trades,
# (3) транзакция прошла ВСЕ условия signal_zapuska, (4) источник сигнала и есть
# создатель из этой транзакции. Любой сбой -- None, то есть прежнее поведение.
# Пока группы в файле нет или она выключена, правило не возвращает ничего, и
# денежный путь не меняется ни на один байт.
ГРУППА_ЗАПУСКОВ = "zapusk_dev"


def группа_запуска_по_транзакции(tx: dict | None,
                                  источник: str | None) -> str | None:
    """zapusk_dev, если источник -- создатель в ГОДНОМ создании. Иначе None."""
    if not tx or not источник:
        return None
    try:
        import bloom_source_groups as SG  # noqa: PLC0415
        import c1_zapusk_zhurnal as ZH  # noqa: PLC0415
    except Exception:  # noqa: BLE001
        return None
    try:
        # ГРУППА ДОЛЖНА СУЩЕСТВОВАТЬ И ТОРГОВАТЬ. Проверяется ДО разбора
        # транзакции: пока владелец группу не создал и не включил, правило не
        # тратит ни микросекунды на пути покупки.
        сводка = SG.загрузить()
        if ГРУППА_ЗАПУСКОВ not in (сводка.get("политики") or {}):
            return None
        пол = SG.политика(ГРУППА_ЗАПУСКОВ)
        if not пол.get("lane_trades"):
            return None
        сг = ZH.signal_zapuska(tx)
        if сг.get("ok") and сг.get("istochnik") == источник:
            return ГРУППА_ЗАПУСКОВ
    except Exception:  # noqa: BLE001
        return None
    return None


def группа_источника(источник: str | None, *, tx: dict | None = None) -> str | None:
    """Группа источника или None, если групп нет вовсе.

    Отдельной функцией, потому что кривая включается ПО ГРУППАМ, а групп в
    полосе спрашивают из трёх мест. None значит "группу узнать не удалось" и
    читается строго: кривая по такому сигналу не идёт.

    tx -- ТОЛЬКО ДЛЯ ПРАВИЛА ГРУППЫ ЗАПУСКОВ, и спрашивается оно лишь тогда,
    когда по адресу группа не нашлась (то есть вышло off). Для всех прежних
    сигналов этот довод ничего не меняет: их адреса в файле есть.
    """
    try:
        import bloom_source_groups as SG  # noqa: PLC0415
    except Exception:  # noqa: BLE001
        return None
    try:
        г = SG.группа(источник)
    except Exception:  # noqa: BLE001
        return None
    if tx is not None and г == getattr(SG, "ГРУППА_ПО_УМОЛЧАНИЮ", "off"):
        по_правилу = группа_запуска_по_транзакции(tx, источник)
        if по_правилу:
            return по_правилу
    return г


def кривая_включена(группа: str | None = None) -> bool:
    """Кривая pump.fun в полосе -- ПО ФЛАГУ, по умолчанию выключена.

    Сборщик кривую умеет (I.2б), но включение полосы на новый тип пула -- это
    деньги: отдельный деплой и отдельная живая сделка 0.01, как просил
    владелец. Поэтому флаг, а не молчаливое расширение белого списка.

    ДВА ФЛАГА, И СПИСОК СИЛЬНЕЕ ОБЩЕГО (решение владельца 26.09, пункт 4:
    "LANE_BONDING_CURVE=1 сначала только на speed_only (0.01); если ок -- на все
    группы"):
      LANE_BONDING_CURVE_GROUPS=speed_only -- кривая только по этим группам;
      LANE_BONDING_CURVE=1                 -- кривая по всем группам.
    Пока список задан, общий флаг кривую на остальные группы НЕ расширяет:
    иначе "включить на одной группе" зависело бы от порядка правок env.
    Группа неизвестна -- кривой нет: молчаливое расширение на всех дороже
    пропущенного сигнала.
    """
    # У кривой историческое имя флага (LANE_BONDING_CURVE), поэтому окружение
    # читается своим именем, а файл групп -- общим "bonding".
    из_файла = _типы_из_файла(группа)
    if из_файла is not None:
        return "bonding" in из_файла
    return _тип_по_флагу("LANE_BONDING_CURVE", группа)


def _тип_по_флагу(имя: str, группа: str | None) -> bool:
    """Включён ли тип пула для этой группы. Правило одно для всех типов:
    <ИМЯ>_GROUPS перечисляет группы и СИЛЬНЕЕ общего <ИМЯ>=1; группа
    неизвестна -- тип выключен (молчаливое расширение на всех дороже
    пропущенного сигнала)."""
    список = [г.strip() for г in (os.environ.get(f"{имя}_GROUPS") or "")
              .replace(";", ",").split(",") if г.strip()]
    if список:
        return bool(группа) and группа in список
    return os.environ.get(имя, "0").strip() == "1"


# Имена типов пулов в файле групп (поле lane_pools) -- по одному на константу
# программы в c2_swap_build.
ИМЕНА_ТИПОВ = {"BONDING": "bonding", "DAMM2": "damm2", "DBC": "dbc",
                "DLMM": "dlmm", "PUMP_AMM": "pump_amm", "CPMM": "cpmm",
                "LAUNCHLAB": "launchlab", "CLMM": "clmm",
                "WHIRLPOOL": "whirlpool", "AMMV4": "amm_v4"}
# Имя двухшагового маршрута в списке lane_pools. Программы у него нет: это не
# тип пула, а способ сборки (п.3 финального плана), поэтому в набор программ он
# не попадает и спрашивается отдельно.
ИМЯ_ДВУХШАГОВОГО = "two_step"


def _типы_из_файла(группа: str | None) -> set | None:
    """Список типов пулов из политики группы или None, если его там нет.

    ЗАЧЕМ ФАЙЛ, А НЕ ТОЛЬКО ОКРУЖЕНИЕ. Слово владельца 27.09: "включение по
    одному флагом с живой сделкой, без перезапусков". Окружение службы меняется
    только перезапуском, а правку файла достаточно положить рядом.

    ПОПРАВКА 27.09, ИЗМЕРЕНО НА ЖИВОЙ СЛУЖБЕ: здесь стояло "файл групп детектор
    перечитывает на ходу". На тот день это было неверно и стоило денег:
    bloom_source_groups.загрузить() держал _КЭШ и второй раз файл не читал, а
    утром 27.09 на этом основании правки групп сочли применёнными -- Bloom
    продолжал покупать по старой политике (-0.141711 SOL).

    СЕГОДНЯ ЭТО УЖЕ НЕ ТАК, И ДЕРЖАТЬ ЗДЕСЬ СТАРОЕ ПРЕДУПРЕЖДЕНИЕ ОПАСНО В
    ДРУГУЮ СТОРОНУ. По п.1а финального плана загрузить() снимает кэш ПО МЕТКЕ
    ФАЙЛА (путь, mtime_ns, размер): переписали файл -- политика читается заново,
    БЕЗ перезапуска службы. Проверять применённость всё равно по строке
    признака жизни (там mtime и hash файла), а не по факту правки.

    Пустой список читается как "поля нет" (та же договорённость, что и с
    нулями: выключает только явный признак), и тогда работают флаги окружения.
    """
    if not группа:
        return None
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        пулы = SG.политика(группа).get("lane_pools")
    except Exception:  # noqa: BLE001
        return None
    if not isinstance(пулы, (list, tuple)) or not пулы:
        return None
    return {str(x).strip().lower() for x in пулы if str(x).strip()}


def _тип_включён(имя_типа: str, группа: str | None) -> bool:
    """Включён ли тип пула: сначала файл групп, потом флаги окружения."""
    из_файла = _типы_из_файла(группа)
    if из_файла is not None:
        return ИМЕНА_ТИПОВ.get(имя_типа, имя_типа.lower()) in из_файла
    return _тип_по_флагу(f"LANE_{имя_типа}", группа)


def damm2_включён(группа: str | None = None) -> bool:
    """Meteora DAMM v2 в полосе -- по флагу LANE_DAMM2 / LANE_DAMM2_GROUPS.

    Сборщик сверен на 17 живых сделках (16 байт в байт, одна не сверяема), цена
    считается по событию свопа и сделке источника (c2_cl_quote). Включение --
    отдельным флагом и живой сделкой, как было с кривой.
    """
    return _тип_включён("DAMM2", группа)


def dbc_включён(группа: str | None = None) -> bool:
    """Meteora DBC (кривая запуска) -- по флагу LANE_DBC / LANE_DBC_GROUPS."""
    return _тип_включён("DBC", группа)


def dlmm_включён(группа: str | None = None) -> bool:
    """Meteora DLMM -- по флагу LANE_DLMM / LANE_DLMM_GROUPS."""
    return _тип_включён("DLMM", группа)


def clmm_включён(группа: str | None = None) -> bool:
    """Raydium CLMM -- по флагу LANE_CLMM / LANE_CLMM_GROUPS (строитель N2).

    ЧТО УЖЕ СВЕРЕНО НА ЦЕПИ. Сборка: из 38 живых сделок 27 восстановлены байт в
    байт, расхождений нет. Цена: событие свопа лежит в ЛОГАХ и отдаёт
    ликвидность и цену после сделки прямо, ставка комиссии читается из счёта
    amm_config (раскладка подтверждена на девяти конфигах), а модель обязана
    воспроизвести сделку источника -- иначе она перешла границу диапазона
    ликвидности и сигнал не берётся. Плюс отказ, если наша покупка уходит за
    край массива тиков источника.

    ПОЧЕМУ ВСЁ РАВНО ПО ФЛАГУ. По живым образцам минимум выхода считается у 23
    сделок из 37, то есть примерно две трети сигналов CLMM полоса возьмёт, а
    треть отвергнет. Это ожидаемо, но проверяется живой сделкой 0.01 SOL при
    нуле позиций, как и все прежние строители.
    """
    return _тип_включён("CLMM", группа)


def ammv4_включён(группа: str | None = None) -> bool:
    """Raydium AMM v4 -- по флагу LANE_AMMV4 / LANE_AMMV4_GROUPS.

    Тип, которого у полосы не было: классический двухрезервный пул Raydium, и
    записи в SPECS у него нет -- он идёт СВОИМ строителем (Code-3). Этот флаг
    решает "брать ли тип", а BLOOM_AMMV4_STROITEL -- "считать ли цену"; нужны ОБА.

    ЧТО НАДО ЗНАТЬ ПЕРЕД ВКЛЮЧЕНИЕМ. Ставка комиссии свопа у строителя -- 25/10000
    ЧИСЛОМ, а не с цепи: она сошлась до единицы на 22 из 22 живых свопов, и
    ставки 20 и 30 не дали ни одного совпадения. Но счёт пула (AmmInfo) строитель
    не разбирает, поэтому у пула с нестандартным swap_fee_numerator потолок
    комиссии пула у полосы становится неинформативным, а минимум выйдет
    завышенным -- то есть откат, а не тихая потеря.
    """
    return _тип_включён("AMMV4", группа)


def whirlpool_включён(группа: str | None = None) -> bool:
    """Orca Whirlpool -- по флагу LANE_WHIRLPOOL / LANE_WHIRLPOOL_GROUPS.

    Тип, которого у полосы не было вовсе: в журнале это 368 отказов "тип пула
    не покрыт сборщиком: whirLb...". Записи в SPECS у него не будет -- он идёт
    СВОИМ строителем через развилку в собрать(). Этот флаг решает "брать ли
    тип", а BLOOM_WHIRLPOOL_STROITEL -- "считать ли цену и живые счета"; нужны
    ОБА.
    """
    return _тип_включён("WHIRLPOOL", группа)


# Типы пулов, которые полоса берёт ТОЛЬКО ПО ФЛАГУ. Имя константы в
# c2_swap_build -- функция, решающая по группе источника.
def launchlab_включён(группа: str | None = None) -> bool:
    """Raydium LaunchLab -- по флагу LANE_LAUNCHLAB / LANE_LAUNCHLAB_GROUPS.

    СТРОИТЕЛЬ N3 в очереди владельца 28.09 (после DAMM v2 + DBC и CLMM).
    Сборка у LaunchLab уже сверена на живых сделках источников: инструкция
    buy_exact_in, 18 счетов, подставляем только подписанта и два наших ATA,
    остальное переносится из сделки источника (c2_swap_build.SPECS). Цена
    считается НЕ по хранилищам, а по событию TradeEvent из логов: у кривой
    запуска резервы виртуальные, и хранилища цену не дают. Событие даёт
    virtual_base/virtual_quote и real_* до и после, доля комиссии выводится из
    самой сделки источника (amount_in минус прирост реальной котировки), а
    формула кривой воспроизводит выход источника точно -- это и проверено
    самопроверкой сборщика на десятке живых сделок.
    """
    return _тип_включён("LAUNCHLAB", группа)


ДОП_ТИПЫ_ПОЛОСЫ = (("BONDING", кривая_включена), ("DAMM2", damm2_включён),
                    ("DBC", dbc_включён), ("DLMM", dlmm_включён),
                    ("CLMM", clmm_включён), ("LAUNCHLAB", launchlab_включён),
                    ("WHIRLPOOL", whirlpool_включён), ("AMMV4", ammv4_включён))

# ПОТОЛОК КОМИССИИ ПУЛА. У свежих пулов Meteora бывает расписание комиссии: в
# живой сделке 26.09 комиссия пула была 50.9 % (и это правда, а не ошибка
# разбора -- модель цены при ней воспроизвела сделку источника точно). Покупать
# с такой комиссией значит отдать половину входа пулу, поэтому на денежном пути
# стоит потолок. Значение -- решение владельца; по умолчанию 5 %.
ПОТОЛОК_КОМИССИИ_ПУЛА = ST.env_float("BLOOM_LANE_MAX_POOL_FEE", 0.05)


def _доля_комиссии_пула(мо: dict, tpl=None, tx=None):
    """Комиссия пула по ответу сборщика минимума -- одним числом для всех типов.

    Считает bloom_lane_two_step.доля_комиссии: fee_share у сосредоточенной
    ликвидности, а у пулов x*y=k -- ЗАМЕР по сделке источника (какая доля его
    траты не дошла до хранилища пула). Раньше спрашивался только fee_share, и
    потолок не срабатывал на CPMM, Pump AMM, Launchlab и кривой вовсе.
    Модуль подтягивается лениво: он же держит двухшаговую сборку, и обратной
    зависимости во время загрузки быть не должно.
    """
    if мо.get("fee_share") is not None:
        return float(мо["fee_share"])
    if tpl is None or tx is None:
        return None
    try:
        import bloom_lane_two_step as TS_  # noqa: PLC0415
    except Exception:  # noqa: BLE001
        return None
    return TS_.доля_мимо_пула(tpl, tx)


# ---------------------------------------- маршрут покупки (Jupiter, 27.09)

# Имя маршрута в поле группы lane_route. Второго имени не изобретаем: одно
# слово в файле, одна константа в коде.
МАРШРУТ_JUPITER = "jupiter"
# Порог налога маршрута по умолчанию, когда маршрут включён, а поле
# lane_route_tax_bps не задано. Слово владельца 27.09: "порог по налогу --
# поле группы, по умолчанию 600 bps".
ПОРОГ_НАЛОГА_МАРШРУТА_BPS = 600
# Общий рубильник: включает маршрут ТОЛЬКО поле группы (слово владельца), а
# выключить его целиком можно окружением, не правя файл. Нужен потому, что
# файл групп читается один раз при старте (см. поправку в _типы_из_файла), и
# выключать деньги правкой, которая подействует только после перезапуска, --
# не рубильник.
ENV_МАРШРУТ_ВЫКЛ = "BLOOM_LANE_ROUTE_OFF"


def маршруты_выключены() -> bool:
    return (os.environ.get(ENV_МАРШРУТ_ВЫКЛ) or "").strip() == "1"


def маршрут_полосы(группа: str | None = None) -> str | None:
    """Какой второй маршрут покупки разрешён этой группе. None -- никакой.

    Слово владельца 27.09: "включается полем группы lane_route=jupiter (по
    умолчанию off), только для сигналов, где прямой сборщик отказал по
    котировке; SOL-пулы идут прямой сборкой как сейчас".

    Группа неизвестна -- маршрута нет. Это то же правило, что у типов пулов:
    молчаливое расширение на всех дороже пропущенного сигнала.
    """
    if маршруты_выключены():
        return None
    if not группа:
        return None
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        знач = SG.политика(группа).get("lane_route")
    except Exception:  # noqa: BLE001
        return None
    имя = str(знач or "").strip().lower()
    return МАРШРУТ_JUPITER if имя == МАРШРУТ_JUPITER else None


# ПОРОГ "БЕЗ ПРЕДЕЛА" для группы, которая налоговый маршрут РАЗРЕШИЛА. В bps
# налог не может быть выше 10 000 (это 100 % перевода), поэтому сравнение
# "налог маршрута выше порога" при этом числе не срабатывает никогда, а налог
# всё равно пишется в строку решения -- ровно то, что просил владелец:
# "не отказывать, а писать налог в строку решения".
ПОРОГ_НАЛОГА_БЕЗ_ПРЕДЕЛА = 10_000


def порог_налога_маршрута_bps(группа: str | None = None) -> int | None:
    """Порог налога маршрута в bps или None -- значит прежние режущие правила.

    Число включает пороговый режим bloom_route_tax.фильтр_маршрута: ниже порога
    покупаем и пишем налог в строку решения, выше -- пропуск. Поле группы
    сильнее умолчания; если поля нет, а маршрут включён, берётся 600 bps.
    Отрицательное и нецелое значение поля -- как будто поля нет: на денежном
    пути мусор из файла не должен превращаться в решение.
    """
    if not группа:
        return None
    try:
        import bloom_source_groups as SG  # noqa: PLC0415

        п = SG.политика(группа)
    except Exception:  # noqa: BLE001
        return None
    знач = п.get("lane_route_tax_bps")
    if isinstance(знач, bool):
        знач = None
    if isinstance(знач, (int, float)) and not isinstance(знач, bool):
        try:
            цел = int(знач)
        except (TypeError, ValueError):
            цел = None
        if цел is not None and цел >= 0:
            return цел
    # ГРУППА РАЗРЕШИЛА НАЛОГОВЫЙ МАРШРУТ -- значит фильтр по налогу не режет.
    # ЧТО БЫЛО СЛОМАНО (найдено 27.09 вечером). Поле allow_taxed_route
    # читалось в политику, а спрашивал его только налоговый_маршрут_разрешён(),
    # которого не звал НИКТО: поле было мёртвым. Порог же брался лишь из
    # lane_route_tax_bps, а умолчание 600 bps действовало только там, где у
    # группы задан lane_route (маршрут Jupiter) -- у лидера его нет по слову
    # владельца. Итого у лидера порог выходил None, фильтр резал по правилам до
    # 27.09, и все шесть его налоговых сигналов за сутки ушли в
    # SKIP_TAXED_ROUTE, а полоса на таком решении не запускалась вовсе (стадии
    # журнала ['shadow', 'skip_price'], гейта нет). GP -- налоговый токен, и без
    # этой правки двухшаговый путь по нему не открылся бы никогда.
    if налоговый_маршрут_разрешён(группа) is True:
        return ПОРОГ_НАЛОГА_БЕЗ_ПРЕДЕЛА
    # Поля нет или оно негодное. Маршрут включён -- умолчание владельца.
    return (ПОРОГ_НАЛОГА_МАРШРУТА_BPS
            if маршрут_полосы(группа) is not None else None)


# Строка отказа прямой сборки, по которой включается второй маршрут. Слово
# владельца 27.09: "только для сигналов, где прямой сборщик отказал по
# котировке". Сравниваем по подстроке, а не по коду, потому что кода у этого
# отказа нет; строка задана в собрать() и меняться не должна молча -- на это
# есть самопроверка.
ПРИЗНАК_КОТИРОВКИ_НЕ_SOL = "котировка пула не SOL"
# Признак отказа ОПРЕДЕЛЕНИЯ ПУЛА (c2_common.identify_pool): встречных
# котировочных счетов нашлось больше одного, и выбрать единственный нечем.
# Текст задан там же и в нём перечислены ПЕРВЫЕ ШЕСТЬ знаков минтов этих
# счетов -- по ним и видно, USDC это или нет.
ПРИЗНАК_НЕОДНОЗНАЧНОЙ_КОТИРОВКИ = "неоднозначная котировка"
ЗНАКОВ_МИНТА_В_ПРИЧИНЕ = 6


def _усдс_минт() -> str | None:
    """Минт USDC -- У МОДУЛЯ c2_common, вторым написанием строки нигде."""
    try:
        C, _, _, _ = _модули()
    except Exception:  # noqa: BLE001
        return None
    return getattr(C, "USDC", None)


def предлагать_усдс_ногу(why_not, *, usdc: str | None = None) -> dict:
    """Открывать ли ветку USDC-ноги по причине отказа ПРЯМОЙ сборки.

    ЧТО БЫЛО СЛОМАНО (разбор 04.10, вечер, п.2). Обе ветки USDC-ноги
    открывались ТОЛЬКО по признаку «котировка пула не SOL». Но определение пула
    (c2_common.identify_pool) стоит РАНЬШЕ всякой котировки, и когда встречных
    котировочных счетов два, оно отказывает своим текстом -- «неоднозначная
    котировка: 2 встречных счетов (EPjFWd)». Этого признака в нём нет, значит
    ветка не открывалась вовсе. Замер по журналу за 16.1 часа: таких отказов
    18, и минт в них -- РОВНО USDC. То есть сигналы, ради которых нога и
    делалась, до её строителя не доходили: старый одношаговый гейт стоял
    раньше.

    ПОЧЕМУ ЭТО ЧЕСТНО ОТКРЫТЬ. Строитель USDC-ноги стороны пула выводит САМ
    (своей таблицей счетов), а не через identify_pool: его отказ в журнале
    звучит иначе -- «котировка пула не EPjFWdd5: стороны пула X/Y». Значит там,
    где определение пула сдалось на двух счетах, нога может собраться. Не
    сможет -- откажет сама и напишет почему, как и сейчас.

    ПРАВИЛО ОДНО И ЖИВЁТ ЗДЕСЬ. Обе ветки (c2_usdc_noga и сигнальные типы)
    спрашивают эту функцию; второго написания условия в файле нет -- на это
    есть самопроверка.
    """
    строка = "" if why_not is None else str(why_not)
    из_ = {"да": False, "почему": None, "признак": None}
    if not строка:
        из_["почему"] = "причины отказа нет -- ветку не открываем"
        return из_
    if ПРИЗНАК_КОТИРОВКИ_НЕ_SOL in строка:
        из_.update(да=True, признак="котировка не SOL",
                    почему="прямая сборка отказала по котировке пула")
        return из_
    if ПРИЗНАК_НЕОДНОЗНАЧНОЙ_КОТИРОВКИ not in строка:
        из_["почему"] = "отказ не про котировку пула"
        return из_
    u = usdc if usdc is not None else _усдс_минт()
    if not u:
        # НЕЗНАНИЕ -- НЕ ПОВОД ОТКРЫВАТЬ ДЕНЕЖНЫЙ ПУТЬ. Минт USDC не прочитан,
        # значит сверить его с причиной нечем, и ветка остаётся закрытой, как
        # была до правки.
        из_["почему"] = "минт USDC не прочитан у модуля -- ветку не открываем"
        return из_
    # МИНТЫ ИЗ ТЕКСТА ПРИЧИНЫ -- ТОЛЬКО ИЗ СКОБОК, и сравниваются по той же
    # длине, какой их туда положили.
    в_скобках = re.findall(r"\(([^()]*)\)", строка)
    префиксы = {ч.strip() for к in в_скобках for ч in к.split(",") if ч.strip()}
    if u[:ЗНАКОВ_МИНТА_В_ПРИЧИНЕ] in префиксы:
        из_.update(да=True, признак="неоднозначная котировка в USDC",
                    почему=(f"определение пула сдалось на встречных счетах "
                            f"{sorted(префиксы)}, и среди них USDC"))
        return из_
    из_["почему"] = (f"неоднозначная котировка, но USDC среди встречных счетов "
                      f"нет: {sorted(префиксы)}")
    return из_


def собрать_маршрутом(*, минт: str, наш_кошелёк: str, лампорты: int,
                       проскальзывание: float = 0.35,
                       cu_units: int = ПРЕДЕЛ_CU_ПОКУПКИ,
                       приоритет_лампорты: int = 1_000_000,
                       чаевые_лампорты: int = 1_000_000,
                       чаевые_списком: list | None = None,
                       семя: str | None = None,
                       нонс: tuple | None = None,
                       rpc_call=None) -> dict:
    """Покупка вторым маршрутом (Jupiter). Возвращает то же, что собрать().

    Порядок намеренно такой: котировка -> ПРОВЕРКА КОТИРОВКИ -> инструкции ->
    таблицы адресов -> сборка. Проверка стоит до инструкций: просить их по
    котировке, которую мы всё равно не примем, значит платить 27 мс на
    горячем пути ни за что.

    Чаевые и их белый список -- те же, что у прямой сборки: получатель не из
    списка счетов Sender это утечка, и здесь она тоже отказ.
    """
    из_ = {"ok": False, "why_not": None, "pool_program": "JUPITER",
            "lane_route": МАРШРУТ_JUPITER, "min_out": None, "expected_out": None,
            "build_ms": None, "quote_ms": None, "ix_ms": None, "lut_ms": None}
    t0 = time.perf_counter()
    if наш_кошелёк != кошелёк_полосы():
        из_["why_not"] = ("сборка маршрутом не на кошелёк полосы: "
                           f"{str(наш_кошелёк)[:12]} вместо {кошелёк_полосы()[:12]}")
        return из_
    if not isinstance(лампорты, int) or лампорты <= 0:
        из_["why_not"] = f"размер не положительное целое: {лампорты!r}"
        return из_
    if лампорты > потолок_лампортов():
        из_["why_not"] = (f"размер {лампорты / ЛАМПОРТОВ_В_SOL} SOL выше потолка "
                           f"полосы {ПОТОЛОК_РАЗМЕРА_SOL} SOL")
        return из_
    try:
        import bloom_lane_jupiter as JR  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"модуль маршрута не загружен: {type(exc).__name__}"
        return из_

    к = JR.котировка(минт, лампорты, проскальзывание=проскальзывание)
    из_["quote_ms"] = к.get("quote_ms")
    из_["route"] = к.get("route")
    из_["route_steps"] = к.get("route_steps")
    из_["quote_slot"] = к.get("context_slot")
    if not к.get("ok"):
        из_["why_not"] = f"маршрут: {к.get('why_not')}"
        return из_
    пр = JR.проверить_котировку(к, лампорты=лампорты,
                                 проскальзывание=проскальзывание)
    из_["quote_checks"] = пр.get("checks")
    if not пр.get("ok"):
        из_["why_not"] = f"маршрут, котировка: {пр.get('why_not')}"
        return из_

    и = JR.инструкции(к["quote"], наш_кошелёк, база=к.get("база"))
    из_["ix_ms"] = и.get("ix_ms")
    if not и.get("ok"):
        из_["why_not"] = f"маршрут, инструкции: {и.get('why_not')}"
        return из_

    т = JR.таблицы_адресов(rpc_call, и.get("таблицы") or [])
    из_["lut_ms"] = т.get("lut_ms")
    из_["lut_cached"] = т.get("из_кеша")
    из_["lut_asked"] = т.get("спрошено")
    if not т.get("ok"):
        из_["why_not"] = f"маршрут, таблицы адресов: {т.get('why_not')}"
        return из_

    if чаевые_списком:
        чаевые = чаевые_списком[0][0]
        сумма_ч = sum(int(л) for _, л in чаевые_списком)
        потолок_ч = int(round(ПОТОЛОК_ЧАЕВЫХ_ПУЛА_SOL * ЛАМПОРТОВ_В_SOL))
        if сумма_ч > потолок_ч:
            из_["why_not"] = (f"суммарные чаевые пула {сумма_ч} выше потолка "
                               f"{потолок_ч} -- сборка маршрутом отменена")
            return из_
        чаевые_для_сборки = list(чаевые_списком)
    else:
        чаевые = выбрать_чаевые(семя)
        if чаевые not in TIP_ACCOUNTS:
            из_["why_not"] = ("адрес чаевых не из списка счетов Sender -- "
                               "сборка отменена")
            return из_
        чаевые_для_сборки = [(чаевые, int(чаевые_лампорты))]

    сб = JR.собрать(ответ_инструкций=и["ответ"], котировка_разбор=к,
                     наш_кошелёк=наш_кошелёк, лампорты=лампорты,
                     таблицы=т.get("accounts") or [], cu_units=cu_units,
                     cu_price_micro=цена_единицы_cu(приоритет_лампорты, cu_units),
                     чаевые=чаевые_для_сборки, нонс=нонс,
                     белый_список_чаевых=TIP_ACCOUNTS)
    if not сб.get("ok"):
        из_["why_not"] = f"маршрут, сборка: {сб.get('why_not')}"
        return из_
    if int(сб.get("size") or 0) > ПРЕДЕЛ_РАЗМЕРА_TX:
        из_["size"] = сб.get("size")
        из_["too_big"] = True
        из_["why_not"] = (f"транзакция маршрута {сб.get('size')} байт при пределе "
                           f"сети {ПРЕДЕЛ_РАЗМЕРА_TX} -- отправлять нельзя")
        return из_
    из_.update(ok=True, min_out=сб.get("min_out"),
               expected_out=сб.get("expected_out"),
               tx_base64=сб.get("tx_base64"), size=сб.get("size"),
               n_instructions=сб.get("n_instructions"),
               tip_account=чаевые,
               tips=(list(чаевые_списком) if чаевые_списком else None),
               tips_total_lamports=сб.get("tips_total_lamports"),
               in_tx=сб.get("in_tx"),
               nonce_account=(str(нонс[0]) if нонс else None),
               quote_mint=WSOL_МИНТ_МАРШРУТА,
               build_ms=round((time.perf_counter() - t0) * 1000, 3),
               route_build_ms=сб.get("build_ms"))
    return из_


# Котировочный минт маршрута: вход у нас всегда нативный SOL, и обёртку делает
# сам Jupiter своими setup-инструкциями. Имя поля -- как у прямой сборки, чтобы
# разборы позиций читали одно и то же.
WSOL_МИНТ_МАРШРУТА = "So11111111111111111111111111111111111111112"


def _модули():
    """Модули тени подгружаются лениво: без них полоса просто выключена."""
    import c2_common as C  # noqa: PLC0415
    import c2_pool_programs as PP  # noqa: PLC0415
    import c2_shadow_build as SB  # noqa: PLC0415
    import c2_swap_build as B  # noqa: PLC0415
    return C, PP, SB, B


def типы_полосы(группа: str | None = None) -> set:
    """Какие программы пулов полоса берёт по ЭТОЙ группе.

    СПИСОК lane_pools В ФАЙЛЕ -- ПОЛНЫЙ И ЗАПРЕЩАЮЩИЙ (перемена 27.09, п.2).
    Раньше он только ДОБАВЛЯЛ типы к постоянным Pump AMM и Raydium CPMM, и
    выразить "только кривая pump.fun" было нечем -- а финальный план требует
    именно этого для группы lane_s0. Теперь: список задан -- берём ровно
    перечисленное; списка нет -- прежнее поведение (постоянные два плюс флаги
    окружения).

    Двухшаговый маршрут в набор программ не входит: он не тип пула, а способ
    сборки, и спрашивается отдельно (двухшаговый_включён).
    """
    try:
        _, _, _, B = _модули()
    except Exception:  # noqa: BLE001
        return set()
    из_файла = _типы_из_файла(группа)
    if из_файла is not None:
        из_ = set()
        for имя_конст, слово in ИМЕНА_ТИПОВ.items():
            if слово in из_файла:
                знач = getattr(B, имя_конст, None)
                if знач:
                    из_.add(знач)
        return из_
    типы = {getattr(B, имя) for имя in ПУЛЫ_ПОЛОСЫ}
    for имя_типа, флаг_типа in ДОП_ТИПЫ_ПОЛОСЫ:
        if флаг_типа(группа):
            типы.add(getattr(B, имя_типа, f"нет типа {имя_типа}"))
    return типы


def двухшаговый_включён(группа: str | None = None) -> bool:
    """Разрешён ли по группе двухшаговый маршрут SOL -> котировочный -> токен."""
    из_файла = _типы_из_файла(группа)
    if из_файла is not None:
        return ИМЯ_ДВУХШАГОВОГО in из_файла
    return _тип_по_флагу("LANE_TWO_STEP", группа)


def тип_пула_подходит(программа: str, группа: str | None = None) -> bool:
    """Берёт ли полоса пул этой программы по этой группе. Один список на всех."""
    return программа in типы_полосы(группа)


def потолок_лампортов() -> int:
    return int(round(ПОТОЛОК_РАЗМЕРА_SOL * ЛАМПОРТОВ_В_SOL))


# ---------------------------------------- боевой пул отправителей (шаг 1)

# Владелец 25.09: "Боевой пул, шаг 1 ... суммарные чаевые <= 0.005 SOL на
# сделку". Смысл: ОДНА подписанная покупка уходит сразу всеми подключёнными
# сервисами; сядет она один раз (подпись одна), но поедет разными путями, и
# выиграет тот, чей путь короче. Каждый сервис смотрит ТОЛЬКО свои чаевые и
# ниже своего минимума молча отбрасывает транзакцию -- поэтому чаевые кладутся
# КАЖДОМУ, а не одни на всех.
ПОТОЛОК_ЧАЕВЫХ_ПУЛА_SOL = 0.005

# ПРЕДЕЛ РАЗМЕРА ТРАНЗАКЦИИ. Solana принимает пакет не больше 1232 байт, и это
# не наша настройка, а предел сети. Каждые чаевые добавляют к покупке около 49
# байт (счёт получателя плюс инструкция перевода), поэтому пять чаевых пула --
# это примерно +196 байт к обычной покупке. Замерено 25.09 на СОХРАНЁННЫХ
# образцах: у пула CPMM покупка с одними чаевыми 767 байт (с пятью 963 --
# влезает), а у pump.fun AMM уже 1132 байта (с пятью 1328 -- НЕ влезает).
# Без этой проверки такая покупка ушла бы в сеть и была бы отвергнута, а у
# полосы это считается упавшей отправкой: три подряд -- стоп полосы. То есть
# молчаливое превышение размера стоило бы не только сделки.
ПРЕДЕЛ_РАЗМЕРА_TX = 1232


def пул_включён() -> bool:
    """Боевой пул -- отдельный рубильник, и по умолчанию он выключен.

    Он не включается ни деплоем полосы, ни контролем доставки: это другой
    расход (чаевые всем сразу) и другое поведение (отправка в несколько
    адресов), и включать его владелец должен отдельным словом.
    """
    return (os.environ.get("BLOOM_POOL_SEND") or "").strip() == "1"


# ---------------------------------- вариант пула на долговечном nonce (шаг 2)

# ЗАЧЕМ ОН НУЖЕН. В шаге 1 одна подписанная покупка уходит всеми сервисами
# сразу, и в ней лежат чаевые КАЖДОМУ -- иначе сервис молча её выбросит. Отсюда
# две беды: пакет растёт (пять чаевых на pump.fun AMM это 1328 байт при пределе
# сети 1232, замерено 25.09) и мы платим всем, а место в блоке получаем одно.
#
# ВАРИАНТ ВЛАДЕЛЬЦА (сводный промпт 25.09, пункт 3): "по транзакции на сервис,
# только его чаевые, один durable nonce". Тогда у каждого отправителя своя
# транзакция со СВОИМИ чаевыми -- пакет маленький, -- а исполниться может
# только ОДНА: первая сдвигает nonce, остальные становятся недействительны.
# Платим при этом только тому, кто довёз.
#
# ЧЕГО ЭТОТ ВАРИАНТ ТРЕБУЕТ. Аккаунт nonce на цепи, созданный кошельком полосы
# (рента около 0.00145 SOL) и им же распоряжаемый. Нет аккаунта -- варианта нет,
# и полоса идёт обычным путём; выдумывать адрес nonce нельзя.
def нонс_аккаунт() -> str:
    return (os.environ.get("BLOOM_LANE_NONCE") or "").strip()


def пул_нонсом_включён() -> bool:
    """Отдельный рубильник, по умолчанию выключен.

    Это ДРУГОЙ путь денег: N подписанных транзакций вместо одной, и решает,
    какая из них села, цепь, а не ответ сервиса. Включать его владелец должен
    отдельным словом, как и сам пул.
    """
    return ((os.environ.get("BLOOM_POOL_NONCE") or "").strip() == "1"
            and bool(нонс_аккаунт()))


def прочитать_нонс(rpc_call, *, аккаунт: str | None = None) -> dict:
    """Хеш и распорядитель ИЗ АККАУНТА nonce. Ни того, ни другого не угадываем.

    Хеш, сохранённый в аккаунте, и есть recent_blockhash наших транзакций:
    подставить вместо него обычный хеш значит отправить транзакцию, которую
    сеть отвергнет, потратив чаевые.
    """
    из_ = {"ok": False, "why_not": None, "blockhash": None, "authority": None,
            "account": (аккаунт or нонс_аккаунт()) or None}
    if not из_["account"]:
        из_["why_not"] = "аккаунт nonce не задан (BLOOM_LANE_NONCE)"
        return из_
    if rpc_call is None:
        из_["why_not"] = "узел не передан -- nonce читать нечем"
        return из_
    try:
        от = rpc_call("getAccountInfo",
                       [из_["account"], {"encoding": "jsonParsed",
                                          "commitment": "processed"}])
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"узел не ответил про nonce: {type(exc).__name__}"
        return из_
    значение = ((от or {}).get("value") or {})
    разбор = (((значение.get("data") or {}).get("parsed") or {}).get("info") or {})
    хеш = разбор.get("blockhash")
    кто = разбор.get("authority")
    if not хеш or not кто:
        из_["why_not"] = ("в аккаунте nonce нет ни хеша, ни распорядителя -- "
                           "это не аккаунт nonce либо он не создан")
        return из_
    if кто != кошелёк_полосы():
        # ЧУЖОЙ РАСПОРЯДИТЕЛЬ значит, что сдвинуть nonce нашей подписью нельзя:
        # транзакции уйдут и будут отвергнуты, а чаевые спишутся.
        из_["why_not"] = (f"распорядитель nonce {str(кто)[:12]} не кошелёк полосы "
                           f"{кошелёк_полосы()[:12]}")
        return из_
    из_.update(ok=True, blockhash=хеш, authority=кто)
    return из_


# ТЁПЛЫЙ NONCE. Замер 25.09 (I.7): от решения до отправки первого варианта
# медиана 60.2 мс при сборке 0.57 мс и подписи, которая стоит доли
# миллисекунды (разбор ключа 0.021 мс, PDA 0.010 мс -- мерено). Остаток сидел
# в СЕТИ: getAccountInfo за nonce стоял прямо в горячем пути, круг до Helius --
# это и есть десятки миллисекунд, а на сигнале 21:07:03Z это дало 910 мс и
# посадку на четыре слота позже источника.
#
# Долговечный nonce не истекает по времени: его значение меняется ТОЛЬКО когда
# садится транзакция, которая его сдвигает, а сдвинуть его может лишь наша
# подпись (распорядитель -- кошелёк полосы). Поэтому значение можно держать
# тёплым, как blockhash, и читать его ЧАСАМИ вне сделки. Правило одно и
# строгое: после нашей отправки тёплое значение считается ГРЯЗНЫМ, пока часы
# не перечитают аккаунт, -- потому что именно наша отправка могла его сдвинуть.
#
# Цена ошибки в обе стороны названа честно: устаревшее значение даёт
# транзакцию, которую сеть отвергнет (чаевые в отвергнутой транзакции не
# списываются -- теряется покупка, не деньги), а отказ от тёплого значения
# возвращает старое поведение с чтением по сети. Поэтому при любой неясности
# путь берёт СИНХРОННОЕ чтение, а не "подпишем как есть".
СРОК_ТЁПЛОГО_НОНСА_S = ST.env_float("BLOOM_LANE_NONCE_WARM_S", 30.0)

_ТЁПЛЫЙ_НОНС: dict = {"значение": None, "ts": 0.0, "грязный": True,
                       "почему": "ещё не читали", "обновлений": 0,
                       "взят_тёплым": 0, "взят_по_сети": 0}
_ЗАМОК_НОНСА = threading.Lock()


def обновить_тёплый_нонс(rpc_call) -> dict:
    """Перечитать аккаунт nonce ВНЕ пути сделки и положить в тёплый слот.

    Зовётся с часов детектора рядом с тёплым blockhash. Отказ не стирает
    прошлое значение молча: он помечает слот грязным и называет причину.
    """
    н = прочитать_нонс(rpc_call)
    with _ЗАМОК_НОНСА:
        if н.get("ok"):
            _ТЁПЛЫЙ_НОНС.update(значение=dict(н), ts=time.time(), грязный=False,
                                 почему="", обновлений=_ТЁПЛЫЙ_НОНС["обновлений"] + 1)
        else:
            _ТЁПЛЫЙ_НОНС.update(грязный=True,
                                 почему=(н.get("why_not") or "nonce не прочитан"))
    return н


def испортить_тёплый_нонс(почему: str) -> None:
    """Пометить тёплое значение грязным. Зовётся ПОСЛЕ нашей отправки и после
    сдвига: и то, и другое могло сдвинуть nonce."""
    with _ЗАМОК_НОНСА:
        _ТЁПЛЫЙ_НОНС.update(грязный=True, почему=почему)


def тёплый_нонс(*, сейчас: float | None = None) -> dict:
    """Готовое значение nonce или отказ СЛОВАМИ. Грязь и просрочка -- отказ."""
    сейчас = сейчас if сейчас is not None else time.time()
    with _ЗАМОК_НОНСА:
        з = dict(_ТЁПЛЫЙ_НОНС)
    if з["грязный"] or not з["значение"]:
        return {"ok": False, "warm": False,
                 "why_not": ("тёплого nonce нет: "
                              + (з["почему"] or "помечен грязным после нашей отправки"))}
    возраст = сейчас - float(з["ts"] or 0.0)
    if возраст > СРОК_ТЁПЛОГО_НОНСА_S:
        return {"ok": False, "warm": False,
                 "why_not": (f"тёплый nonce старше {СРОК_ТЁПЛОГО_НОНСА_S} с "
                              f"(возраст {возраст:.1f} с)")}
    из_ = dict(з["значение"])
    из_.update(warm=True, warm_age_s=round(возраст, 3))
    return из_


def нонс_для_сделки(rpc_call, *, сейчас: float | None = None) -> dict:
    """Одна дверь за значением nonce для пути сделки: сначала тёплое, иначе сеть.

    Ровно одно место, где решается "тёплое или по сети": два места однажды
    разойдутся, и разойдутся они в деньгах.
    """
    т0 = time.perf_counter()
    т = тёплый_нонс(сейчас=сейчас)
    if т.get("ok"):
        with _ЗАМОК_НОНСА:
            _ТЁПЛЫЙ_НОНС["взят_тёплым"] += 1
        т["nonce_ms"] = round((time.perf_counter() - т0) * 1000, 3)
        return т
    н = прочитать_нонс(rpc_call)
    with _ЗАМОК_НОНСА:
        _ТЁПЛЫЙ_НОНС["взят_по_сети"] += 1
    н["warm"] = False
    н["warm_why_not"] = т.get("why_not")
    н["nonce_ms"] = round((time.perf_counter() - т0) * 1000, 3)
    return н


ФАЙЛ_ТАБЛИЦЫ_НОГИ = "usdc_noga_alt.json"


def таблица_ноги(состояние) -> dict:
    """Адрес НАШЕЙ таблицы адресов для USDC-ноги из каталога состояния.

    ЗАЧЕМ ЭТО ВООБЩЕ. Замер на трёх живых образцах DAMM v2: без таблицы боевая
    нога весит 1326-1327 байт при пределе сети 1232, то есть ПЕРВАЯ же боевая
    нога откажет по размеру -- починки KeyError для неё НЕ ХВАТАЕТ. Таблица
    сжимает счёта до индексов и вносит сборку в предел.

    Имя файла взято у того же прогона, что таблицу создаёт
    (deploy/checks/usdc_noga_razmer_cu.ФАЙЛ_ALT) -- второе имя разошлось бы молча.
    Нет файла или нет адреса -- ОТКАЗ СЛОВАМИ: размер назовёт сам сборщик, но
    причина "таблицы нет" обязана стоять в записи, иначе отказ по размеру
    читается как поломка сборщика.
    """
    из_ = {"ok": False, "адрес": None, "адресов": None, "why_not": None}
    база = getattr(состояние, "base", None)
    if not база:
        из_["why_not"] = "каталог состояния не задан"
        return из_
    п = Path(база) / ФАЙЛ_ТАБЛИЦЫ_НОГИ
    if not п.exists():
        из_["why_not"] = f"файла таблицы нет: {ФАЙЛ_ТАБЛИЦЫ_НОГИ}"
        return из_
    try:
        д = json.loads(п.read_text(encoding="utf-8"))
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"файл таблицы не разобран: {type(exc).__name__}"
        return из_
    а = д.get("адрес") or д.get("address")
    if not а:
        из_["why_not"] = "в файле таблицы нет адреса"
        return из_
    из_.update(ok=True, адрес=str(а), адресов=д.get("адресов"))
    return из_


def след_сбоя(exc: BaseException) -> str:
    """Строка сбоя для записи: repr исключения И файл:строка, где упало.

    ПОЧЕМУ НЕ ОДНО ИМЯ КЛАССА. 02.10 по сигналу Xk9onqHkpULD в журнале решений
    стояло ровно "сборка USDC-ноги не загрузилась: KeyError" -- ни ключа, ни
    файла, ни строки. Причину по такой записи назвать нельзя: путь пришлось
    повторять руками. repr даёт сам ключ (KeyError(0)), последний кадр traceback --
    место падения, а не место поимки.

    Разбор берётся у двухшагового модуля (bloom_lane_two_step.след_сбоя), чтобы
    у полосы и у сборщиков строка сбоя была ОДНА. Зовут это из обработчика, и
    бросать второе исключение он права не имеет -- поэтому худший случай здесь
    имя класса, но СКАЗАННОЕ, а не молчание.
    """
    try:
        import bloom_lane_two_step as TS  # noqa: PLC0415

        return TS.след_сбоя(exc)
    except Exception:  # noqa: BLE001
        return f"{type(exc).__name__} (место падения не разобрано)"


def свод_тёплого_нонса() -> dict:
    """Что показывать в признаке жизни: есть ли тёплое значение и его возраст."""
    with _ЗАМОК_НОНСА:
        з = dict(_ТЁПЛЫЙ_НОНС)
    возраст = (round(time.time() - float(з["ts"]), 2) if з["ts"] else None)
    return {"есть": bool(з["значение"]) and not з["грязный"],
             "возраст_с": возраст, "почему": з["почему"] or "",
             "обновлений": з["обновлений"], "взят_тёплым": з["взят_тёплым"],
             "взят_по_сети": з["взят_по_сети"],
             "срок_с": СРОК_ТЁПЛОГО_НОНСА_S}


# СКОЛЬКО ЖДЁМ ПОСАДКИ ВАРИАНТОВ. Решение владельца 25.09: "если ни один вариант
# не сел за 8 слотов (~3.2 с) -- отправить сдвиг nonce (advance) отдельной
# транзакцией, чтобы все старые варианты стали недействительными; пока сдвиг не
# подтверждён, новая покупка на этом nonce не собирается".
#
# ЗАЧЕМ ЭТО НУЖНО. Долговечный nonce не истекает, как blockhash: подписанный
# вариант, который не сел сейчас, останется годным СКОЛЬКО УГОДНО и может сесть
# через минуту, через час -- когда цена уже другая, а мы об этой покупке забыли.
# Сдвиг nonce одной транзакцией убивает сразу все висящие варианты: они
# ссылаются на прежний хеш, и сеть их отвергнет. Стоит сдвиг базовый тариф
# (5000 лампортов) и ничего больше -- в нём нет ни перевода, ни чаевых.
СЛОТОВ_ЖДЁМ_ВАРИАНТЫ = 8
# ДЛИНА СЛОТА -- ИЗМЕРЯЕМАЯ, А НЕ КОНСТАНТА (решение владельца 28.09, вариант 2).
# Замер 28.09: 0.2659 с/слот (113 слотов за 30.044 с) -- на 33.5 % короче 0.4, и
# все удержания, заданные в слотах, выходили в полтора раза длиннее задуманного.
# Значение меряет фон детектора раз в 5 минут (два getSlot по монотонным часам) и
# кладёт в общий файл; читатели берут СВЕЖЕЕ, при отсутствии замера -- последнее
# известное, и только если файла нет вовсе -- эту константу.
ДЛИНА_СЛОТА_S = 0.4
ФАЙЛ_ДЛИНЫ_СЛОТА = "slot_length.json"
# Замер старше этого возраста считается несвежим, но всё равно лучше константы:
# длина слота меняется эпохами, а не минутами.
ДЛИНА_СЛОТА_СВЕЖЕСТЬ_S = ST.env_float("BLOOM_SLOT_LEN_FRESH_S", 3600.0)
_ДЛИНА_СЛОТА_КЕШ: dict = {"когда_читали": 0.0, "значение": None, "возраст_с": None,
                           "источник": "константа"}


def путь_длины_слота(state_dir=None):
    """Где лежит замер длины слота. Тот же каталог состояния, что у позиций."""
    from pathlib import Path as _P  # noqa: PLC0415

    if state_dir:
        return _P(state_dir) / ФАЙЛ_ДЛИНЫ_СЛОТА
    return _P(ST.ExecState().base) / ФАЙЛ_ДЛИНЫ_СЛОТА


def записать_длину_слота(измерено_с: float, *, слотов: int, окно_с: float,
                          state_dir=None) -> dict:
    """Замер -- в общий файл. Пишет фон детектора, читают все."""
    из_ = {"ok": False, "why_not": None}
    if not isinstance(измерено_с, (int, float)) or not (0.05 <= float(измерено_с) <= 5.0):
        из_["why_not"] = f"длина слота вне разумного: {измерено_с!r}"
        return из_
    запись = {"измерено_с": round(float(измерено_с), 5), "слотов": int(слотов),
               "окно_с": round(float(окно_с), 3), "когда": time.time(),
               "когда_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
               "источник": "getSlot x2, монотонные часы"}
    try:
        п = путь_длины_слота(state_dir)
        п.parent.mkdir(parents=True, exist_ok=True)
        врем = п.with_suffix(".tmp")
        врем.write_text(json.dumps(запись, ensure_ascii=False), encoding="utf-8")
        врем.replace(п)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"{type(exc).__name__}: {str(exc)[:120]}"
        return из_
    _ДЛИНА_СЛОТА_КЕШ.update(когда_читали=0.0)   # следующий читатель перечитает
    из_.update(ok=True, запись=запись)
    return из_


def длина_слота_s(*, state_dir=None, сейчас: float | None = None) -> float:
    """Длина слота в секундах: СВЕЖИЙ замер, иначе последний известный.

    Константа 0.4 остаётся только на случай, когда замера не было ни разу:
    решение владельца -- "при отсутствии замера брать последнее известное, а не
    0.4". Файл перечитывается не чаще раза в 10 с: эту функцию зовёт и горячий
    путь сборки.
    """
    now = сейчас if сейчас is not None else time.time()
    if (now - float(_ДЛИНА_СЛОТА_КЕШ.get("когда_читали") or 0.0) < 10.0
            and _ДЛИНА_СЛОТА_КЕШ.get("значение")):
        return float(_ДЛИНА_СЛОТА_КЕШ["значение"])
    значение, возраст, источник = None, None, "константа"
    try:
        п = путь_длины_слота(state_dir)
        д = json.loads(п.read_text(encoding="utf-8"))
        зн = д.get("измерено_с")
        когда = д.get("когда")
        if isinstance(зн, (int, float)) and 0.05 <= float(зн) <= 5.0:
            значение = float(зн)
            источник = "замер"
            if isinstance(когда, (int, float)):
                возраст = max(0.0, now - float(когда))
                if возраст > ДЛИНА_СЛОТА_СВЕЖЕСТЬ_S:
                    источник = "замер (несвежий)"
    except Exception:  # noqa: BLE001
        значение = None
    _ДЛИНА_СЛОТА_КЕШ.update(когда_читали=now, значение=значение,
                             возраст_с=возраст, источник=источник)
    return float(значение) if значение else float(ДЛИНА_СЛОТА_S)


def длина_слота_подробно(*, state_dir=None) -> dict:
    """То же число плюс откуда оно взялось -- для признака жизни и отчётов."""
    зн = длина_слота_s(state_dir=state_dir)
    return {"длина_слота_с": зн, "источник": _ДЛИНА_СЛОТА_КЕШ.get("источник"),
             "возраст_замера_с": (round(_ДЛИНА_СЛОТА_КЕШ["возраст_с"], 1)
                                   if _ДЛИНА_СЛОТА_КЕШ.get("возраст_с") is not None
                                   else None),
             "константа_в_коде_с": ДЛИНА_СЛОТА_S}


def ожидание_вариантов_s() -> float:
    """Сколько ждать посадки. Восемь слотов по слову владельца; переменной
    окружения можно уточнить, но ноль означает "не ждать и не сдвигать"."""
    з = ST.env_float("BLOOM_NONCE_WAIT_S", СЛОТОВ_ЖДЁМ_ВАРИАНТЫ * ДЛИНА_СЛОТА_S)
    return max(0.0, float(з))
ИМЯ_ФАЙЛА_ОЖИДАНИЯ_НОНСА = "lane_nonce_pending.json"


def путь_ожидания_нонса(состояние) -> Path | None:
    """Файл "сдвиг nonce не подтверждён". Рядом с состоянием, не в памяти.

    В памяти его держать нельзя: перезапуск службы забыл бы про висящие
    варианты, и следующая покупка собралась бы на том же nonce -- то есть
    оказалась бы в очереди со старыми.
    """
    база = getattr(состояние, "base", None)
    if база is None:
        return None
    try:
        return Path(база) / ИМЯ_ФАЙЛА_ОЖИДАНИЯ_НОНСА
    except Exception:  # noqa: BLE001
        return None


def _ожидание_нонса_читать(состояние) -> dict:
    п = путь_ожидания_нонса(состояние)
    if п is None or not п.exists():
        return {}
    try:
        return json.loads(п.read_text(encoding="utf-8")) or {}
    except Exception:  # noqa: BLE001
        # Нечитаемый файл -- это НЕ "ожидания нет": считаем, что сдвиг висит.
        # Ошибиться в эту сторону значит не собрать покупку; в другую -- собрать
        # её в очередь к старым вариантам.
        return {"pending": True, "why": "файл ожидания сдвига не читается"}


def _ожидание_нонса_писать(состояние, з: dict) -> dict:
    п = путь_ожидания_нонса(состояние)
    if п is None:
        return {"ok": False, "why_not": "у состояния нет каталога"}
    try:
        п.parent.mkdir(parents=True, exist_ok=True)
        ST.atomic_write_json(п, з)
        return {"ok": True}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "why_not": f"{type(exc).__name__}"}


def нонс_ожидает(состояние, *, rpc_call=None) -> dict:
    """Висит ли неподтверждённый сдвиг nonce. Если висит -- покупок на нём нет.

    Подтверждением считается НЕ ответ сети на нашу отправку, а сам факт: хеш в
    аккаунте nonce ИЗМЕНИЛСЯ по сравнению с тем, на котором собирались старые
    варианты. Это верно и когда сдвиг довезли мы, и когда nonce сдвинул один из
    вариантов, успевший сесть, -- в обоих случаях старые варианты мертвы.
    """
    з = _ожидание_нонса_читать(состояние)
    если = {"pending": bool(з.get("pending")), "why": з.get("why"),
             "signature": з.get("signature"), "old_blockhash": з.get("blockhash")}
    if not если["pending"]:
        return если
    if rpc_call is None:
        если["why"] = (з.get("why") or "сдвиг nonce не подтверждён") + \
                       " (узла нет -- проверить нечем)"
        return если
    н = прочитать_нонс(rpc_call)
    если["nonce_read"] = {"ok": н.get("ok"), "why_not": н.get("why_not")}
    if not н.get("ok"):
        return если
    if з.get("blockhash") and н.get("blockhash") != з.get("blockhash"):
        # Хеш сменился -- старые варианты недействительны, ожидание снято.
        _ожидание_нонса_писать(состояние, {"pending": False,
                                            "cleared_ts": time.time(),
                                            "cleared_blockhash": н.get("blockhash")})
        если.update(pending=False, why="сдвиг подтверждён: хеш nonce сменился",
                    new_blockhash=н.get("blockhash"))
        return если
    если["why"] = "сдвиг nonce ещё не подтверждён: хеш в аккаунте тот же"
    return если


def собрать_сдвиг_нонса(*, нонс: dict) -> dict:
    """Транзакция ТОЛЬКО со сдвигом nonce. Ни перевода, ни чаевых.

    В ней одна инструкция AdvanceNonceAccount: единственное, что она может
    сделать с деньгами, -- списать базовый тариф за подпись. Это проверяется
    самопроверкой: транзакция сдвига обязана быть без переводов.
    """
    из_ = {"ok": False, "why_not": None, "tx_base64": None, "size": None}
    if not нонс.get("ok"):
        из_["why_not"] = нонс.get("why_not") or "nonce не прочитан"
        return из_
    try:
        from solders.hash import Hash  # noqa: PLC0415
        from solders.message import MessageV0  # noqa: PLC0415
        from solders.pubkey import Pubkey  # noqa: PLC0415
        from solders.signature import Signature  # noqa: PLC0415
        from solders.transaction import VersionedTransaction  # noqa: PLC0415

        _, _, _, B = _модули()
        ix = B.advance_nonce(нонс["account"], нонс["authority"])
        msg = MessageV0.try_compile(Pubkey.from_string(нонс["authority"]), [ix], [],
                                     Hash.from_string(нонс["blockhash"]))
        vtx = VersionedTransaction.populate(
            msg, [Signature.default()] * msg.header.num_required_signatures)
        сырое = bytes(vtx)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"сдвиг не собран: {type(exc).__name__}: {str(exc)[:160]}"
        return из_
    из_.update(ok=True, tx_base64=base64.b64encode(сырое).decode(),
               size=len(сырое), n_instructions=1)
    return из_


def сдвинуть_нонс(*, состояние, rpc_call=None, секрет: str | None = None,
                   отправитель=None, сервис: str | None = None,
                   подписать_фн=None, нонс: dict | None = None) -> dict:
    """Отправить сдвиг nonce и запомнить, что он не подтверждён.

    Порядок важен: ЗАПИСЬ ОЖИДАНИЯ идёт ДО отправки. Если процесс упадёт между
    отправкой и записью, следующая покупка собралась бы на том же nonce в
    очередь к висящим вариантам -- а это две покупки на один сигнал.
    """
    из_ = {"ok": False, "why_not": None, "signature": None, "sent": False}
    н = нонс if нонс is not None else прочитать_нонс(rpc_call)
    if not н.get("ok"):
        из_["why_not"] = н.get("why_not") or "nonce не прочитан"
        return из_
    сб = собрать_сдвиг_нонса(нонс=н)
    if not сб.get("ok"):
        из_["why_not"] = сб.get("why_not")
        return из_
    подписать_ = подписать_фн or подписать
    пд = подписать_(сб["tx_base64"], blockhash=н["blockhash"],
                    ожидаемый_кошелёк=кошелёк_полосы(),
                    секрет=(секрет if секрет is not None else ключ_полосы()))
    if not пд.get("ok"):
        из_["why_not"] = пд.get("why_not") or "сдвиг не подписан"
        return из_
    из_["signature"] = пд.get("signature")
    зап = _ожидание_нонса_писать(состояние, {
        "pending": True, "why": "сдвиг nonce отправлен, подтверждения нет",
        "signature": пд.get("signature"), "blockhash": н["blockhash"],
        "account": н["account"], "ts": time.time()})
    if not зап.get("ok"):
        # НЕ ОТПРАВЛЯЕМ, если не смогли записать ожидание: иначе сдвиг уйдёт, а
        # знания о нём не останется.
        из_["why_not"] = f"ожидание сдвига не записано ({зап.get('why_not')}) -- сдвиг не отправлен"
        return из_
    try:
        import bloom_senders as SS  # noqa: PLC0415

        имя = сервис or (SS.подключённые() or ["helius"])[0]
        от = SS.отправить_через(имя, пд["tx_base64"], отправитель=отправитель)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"сдвиг не отправлен: {type(exc).__name__}"
        return из_
    из_.update(ok=bool(от.get("ok")), sent=bool(от.get("sent")),
               sender=от.get("sender"), http=от.get("http"),
               why_not=(None if от.get("ok") else от.get("why_not")))
    # СДВИГ МЕНЯЕТ ЗНАЧЕНИЕ NONCE. Тёплое значение после него недостоверно, и
    # держать его значило бы подписать покупку прежним хешем.
    испортить_тёплый_нонс("отправлен сдвиг nonce")
    return из_


def посадка_вариантов(rpc_call, кандидаты: list) -> dict:
    """Сел ли хоть один вариант. По цепи, а не по ответам сервисов."""
    из_ = {"landed": None, "signature": None, "why_not": None, "statuses": {}}
    ряд = [п for п in (кандидаты or []) if п]
    if not ряд:
        из_["why_not"] = "кандидатов нет"
        return из_
    if rpc_call is None:
        из_["why_not"] = "узел не передан -- посадку проверить нечем"
        return из_
    try:
        от = rpc_call("getSignatureStatuses", [ряд, {"searchTransactionHistory": False}])
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"узел не ответил: {type(exc).__name__}"
        return из_
    значения = ((от or {}).get("value") or [])
    for подпись, з in zip(ряд, значения):
        if not з:
            из_["statuses"][подпись] = None
            continue
        из_["statuses"][подпись] = {"slot": з.get("slot"),
                                     "status": з.get("confirmationStatus"),
                                     "err": з.get("err")}
        if з.get("slot") is not None and из_["landed"] is None:
            из_.update(landed=True, signature=подпись)
    if из_["landed"] is None:
        из_["landed"] = False
    return из_


def спасти_нонс_если_не_село(*, состояние, кандидаты, rpc_call=None, нонс=None,
                             секрет: str | None = None, отправитель=None,
                             ждать_s: float | None = None,
                             подписать_фн=None, спать=None,
                             строки_вариантов: list | None = None) -> dict:
    """Ждём 8 слотов и, если не сел НИ ОДИН вариант, сдвигаем nonce.

    Висящий вариант не истекает: nonce живёт, пока его не сдвинут, и подписанная
    покупка может сесть через минуту или через час -- по цене, которой уже нет.
    Сдвиг убивает сразу все: они ссылаются на прежний хеш.

    Ждём в потоке полосы -- Bloom он не задерживает, покупка к этому моменту уже
    отправлена. Сон подменяем в самопроверке, чтобы не ждать три секунды.
    """
    из_ = {"landing": None, "shift": None}
    ряд = [п for п in (кандидаты or []) if п]
    if not ряд:
        из_["landing"] = {"landed": None, "why_not": "кандидатов нет"}
        return из_
    пауза = ожидание_вариантов_s() if ждать_s is None else max(0.0, float(ждать_s))
    if пауза > 0:
        (спать or time.sleep)(пауза)
    пос = посадка_вариантов(rpc_call, ряд)
    # КТО ДОВЁЗ -- это тот, ЧЕЙ вариант сел, а не тот, кто первым ответил
    # "принял". Варианты отличаются только чаевыми, значит подпись однозначно
    # называет сервис; без этого сопоставления "кто довёз" в варианте на nonce
    # осталось бы неизвестным, а в позицию попала бы чужая подпись.
    по_подписи = {}
    for с_ in (строки_вариантов or []):
        if (с_ or {}).get("signature"):
            по_подписи[с_["signature"]] = с_.get("sender")
    из_["landing"] = {"landed": пос.get("landed"),
                       "signature": пос.get("signature"),
                       "sender": по_подписи.get(пос.get("signature")),
                       "why_not": пос.get("why_not"),
                       "waited_s": пауза, "waited_slots": СЛОТОВ_ЖДЁМ_ВАРИАНТЫ}
    if пос.get("landed") is not False:
        # Сел кто-то из вариантов (или проверить нечем) -- сдвиг не отправляем:
        # он стоит тарифа, а севший вариант уже сдвинул nonce сам.
        return из_
    сдвиг = сдвинуть_нонс(состояние=состояние, rpc_call=rpc_call, секрет=секрет,
                           отправитель=отправитель, нонс=нонс,
                           подписать_фн=подписать_фн)
    из_["shift"] = {"ok": сдвиг.get("ok"), "signature": сдвиг.get("signature"),
                     "sender": сдвиг.get("sender"),
                     "why_not": сдвиг.get("why_not")}
    return из_


def чаевые_пула(семя: str | None = None, *, сервисы: list | None = None,
                 путь: str | None = None) -> dict:
    """Кому и сколько чаевых в боевой покупке пула.

    Адрес каждого сервиса -- ТОЛЬКО из его списка в реестре: перевод на адрес
    не из списка это перевод неизвестно кому. Сумма сверяется с потолком
    владельца ДО сборки; вылезли за потолок -- пул не собирается вовсе, а не
    "урежем кому-нибудь": чаевые ниже минимума сервиса означают, что этот
    сервис молча выбросит транзакцию, и платить их бессмысленно.
    """
    из_ = {"ok": False, "tips": [], "total_lamports": 0, "senders": [],
            "why_not": None}
    try:
        import bloom_senders as SS  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"реестр отправителей не загружен: {type(exc).__name__}"
        return из_
    имена = сервисы if сервисы is not None else SS.подключённые(путь)
    if not имена:
        из_["why_not"] = "подключённых отправителей нет -- пулу нечего слать"
        return из_
    пары = []
    всего = 0
    for имя in имена:
        з = (SS.реестр(путь) or {}).get(имя) or {}
        адрес = SS.счёт_чаевых(имя, семя=семя, путь=путь)
        разрешённые = set(з.get("tip_accounts") or [])
        if not адрес or адрес not in разрешённые:
            из_["why_not"] = (f"адрес чаевых не из списка сервиса {имя} -- "
                               "пул не собирается")
            return из_
        лам = SS.минимум_чаевых(имя, путь=путь)
        пары.append((адрес, int(лам)))
        всего += int(лам)
        из_["senders"].append({"sender": имя, "tip_account": адрес,
                                "tip_lamports": int(лам)})
    потолок = int(round(ПОТОЛОК_ЧАЕВЫХ_ПУЛА_SOL * ЛАМПОРТОВ_В_SOL))
    if всего > потолок:
        из_["why_not"] = (f"суммарные чаевые пула {всего} лампортов выше потолка "
                           f"{потолок} ({ПОТОЛОК_ЧАЕВЫХ_ПУЛА_SOL} SOL на сделку) "
                           "-- пул не собирается")
        из_["total_lamports"] = всего
        return из_
    из_.update(ok=True, tips=пары, total_lamports=всего)
    из_["total_sol"] = всего / ЛАМПОРТОВ_В_SOL
    return из_


def подогнать_чаевые_под_размер(*, сборщик, чаевые: list,
                                 сервисы: list | None = None) -> dict:
    """Убрать САМЫХ ДОРОГИХ сервисов, пока транзакция не влезет в пакет сети.

    Отдельной функцией, потому что это правило про деньги и его надо проверять:
    убранному сервису транзакция НЕ отправляется (чаевые ниже его минимума
    значат, что он молча её выбросит, и отправка была бы ложным замером), а
    если не влезло даже с одними чаевыми -- пул на этой сделке пропускается, но
    ПОКУПКА ОСТАЁТСЯ: терять сделку из-за замера нельзя.

    ПОЧЕМУ УБИРАЕМ ДОРОГИХ, А НЕ "С КОНЦА". Место в пакете одинаково стоит для
    любого сервиса, а чаевые -- нет: у Jito минимум 1 000 лампортов, у Helius,
    Nozomi и Astralane -- миллион. Убирая с конца алфавита, мы выбросили бы
    сначала Nozomi, а потом Jito -- то есть самого дешёвого и того, кому по З1
    платят те, кто садится в S+0 впереди нас. При равной цене порядок обратный
    алфавитному -- только чтобы решение было одинаковым от прогона к прогону.

    сборщик(чаевые_списком) -> результат собрать(); None значит обычный путь
    полосы с одними чаевыми.
    """
    из_ = {"сб": None, "чаевые": list(чаевые or []), "сервисы": list(сервисы or []),
            "убраны": [], "why_not": None, "пул": True}
    сб = сборщик(из_["чаевые"] or None)
    из_["сб"] = сб
    if not сб.get("too_big"):
        return из_
    подгон = list(из_["чаевые"])
    серв = list(из_["сервисы"])
    while подгон and сб.get("too_big"):
        # Кого убрать: самые дорогие чаевые, при равенстве -- обратный алфавит.
        порядок = sorted(range(len(подгон)),
                          key=lambda и: (-int(подгон[и][1]),
                                          серв[и] if и < len(серв) else ""),
                          reverse=False)
        # sorted по (-цена, имя) даёт самых дорогих первыми; при равной цене
        # берём ПОСЛЕДНЕГО по алфавиту, поэтому переворачиваем равную группу.
        дорогая_цена = -int(подгон[порядок[0]][1])
        равные = [и for и in порядок if -int(подгон[и][1]) == дорогая_цена]
        кого = равные[-1] if len(равные) > 1 else порядок[0]
        из_["убраны"].append(серв[кого] if кого < len(серв) else "?")
        подгон = [п for и, п in enumerate(подгон) if и != кого]
        серв = [с for и, с in enumerate(серв) if и != кого]
        сб = сборщик(подгон or None)
    из_["сб"] = сб
    if подгон:
        из_.update(чаевые=подгон, сервисы=серв,
                    why_not=("по размеру пакета сети убраны сервисы: "
                              + ", ".join(из_["убраны"])))
    else:
        из_.update(чаевые=[], сервисы=[], пул=False,
                    why_not=("покупка не влезает в пакет сети даже с одними "
                              "чаевыми -- пул на этой сделке пропущен, покупка "
                              "идёт обычным путём полосы"))
    return из_


# ------------------------------------------------- Meteora DLMM: массивы корзин
# ЗАЧЕМ ЭТО НА ДЕНЕЖНОМ ПУТИ (слово владельца 29.09, вариант 1б: "два чтения,
# отказ без траты"). Цена у DLMM живёт в КОРЗИНАХ, а адреса массивов корзин
# стоят в хвосте счетов инструкции. Шаблон покупки мы берём из сделки
# ИСТОЧНИКА, то есть массивы в нём -- те, что были нужны ЕМУ. К нашему времени
# активная корзина другая, и на замере 10 сделок 29.09 подстановка нынешних
# массивов подняла симуляцию с 0/10 до 7/10; остальные 3 падали с Token
# Custom: 1 именно потому, что источник передал ОДИН массив, а сейчас нужно
# два-три -- места в шаблоне не хватает.
#
# ОТПРАВЛЯТЬ ТАКОЕ НЕЛЬЗЯ: чаевые и приоритет (0.002 SOL) списываются, а своп
# откатывается. Поэтому "массивов не хватает" -- ОТКАЗ ДО сборки, а не промах
# на цепи. И поэтому же чтений два: первое даёт пул и какие массивы нужны,
# второе -- сам пул вместе с массивами из ОДНОГО слота.
#
# БЕЗ УЗЛА -- ТОЖЕ ОТКАЗ. Не знать нынешние массивы и всё равно отправить
# значит платить за промах: незнание тут стоит денег, а не времени.
def тень_одного_чтения(tx_источника: dict | None, пул: str | None,
                        к: dict) -> dict:
    """Годился ли путь ОДНОГО чтения на этом сигнале -- БЕЗ чтений узла.

    ЗАЧЕМ ИМЕННО ТЕНЬ. Владелец 30.09 (п.3) просил принять "DLMM одним чтением"
    на живых покупках: село >= прежнего пути и цены равны. Измерить это на
    готовых строках нельзя, и это установлено, а не предположено: массивы корзин
    берутся из сделки источника, а строка журнала несёт сделку возрастом в тысячи
    слотов (самая свежая, поймана 00:52:53Z: 3266 слотов). На таком отставании
    путь обязан отказать -- и отказывает, но про бой это не говорит ничего.
    В бою полоса считает цену через слот-два после сделки источника.

    Поэтому замер переносится ВНУТРЬ полосы и стоит нуль чтений: прежний путь уже
    прочитал пул и знает active_id и нужные массивы; здесь мы только выводим
    адреса массивов ИЗ САМОЙ СДЕЛКИ (чистая арифметика, p50 0.3 мс у Code-3) и
    сверяем, хватило бы их. Цена при этом берётся прежняя -- решения тень не
    принимает.
    """
    из_ = {"годилось": None, "почему_нет": None, "массивов_в_сделке": None,
            "индексы_в_сделке": None, "активный_массив": None, "мс": None}
    if not isinstance(tx_источника, dict) or not пул or not isinstance(к, dict):
        из_["почему_нет"] = "нет транзакции источника, пула или ответа котировки"
        return из_
    try:
        import c2_dlmm_odno_chtenie as OD  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["почему_нет"] = f"модуля одного чтения нет: {type(exc).__name__}"
        return из_
    т0 = time.perf_counter()
    try:
        сд = OD.массивы_сделки(tx_источника, пул)
        из_["мс"] = round((time.perf_counter() - т0) * 1000, 3)
        if not сд.get("ok"):
            из_.update(годилось=False, почему_нет=f"в сделке: {сд.get('why_not')}")
            return из_
        в_сделке = set(сд.get("индексы") or [])
        из_["массивов_в_сделке"] = len(в_сделке)
        из_["индексы_в_сделке"] = sorted(в_сделке)
        нужные = set(к.get("массивы_индексы") or [])
        акт = к.get("active_id")
        индекс_акт = None
        if isinstance(акт, int):
            Q = OD._порт()
            индекс_акт = Q.индекс_массива(акт)
            из_["активный_массив"] = индекс_акт
        if индекс_акт is not None and индекс_акт not in в_сделке:
            из_.update(годилось=False,
                        почему_нет="активного массива в сделке источника нет")
            return из_
        не_хватает = sorted(нужные - в_сделке)
        if не_хватает:
            из_.update(годилось=False,
                        почему_нет=f"не хватило массивов {не_хватает[:4]}")
            return из_
        из_["годилось"] = True
    except Exception as exc:  # noqa: BLE001
        из_.update(годилось=None,
                    почему_нет=f"тень упала: {type(exc).__name__}: {str(exc)[:80]}")
    return из_


# ТЕНЬ НУЛЯ ЧТЕНИЙ (утренний пакет 01.10, п.1). Третья ступень лестницы: два
# чтения -> одно чтение -> НУЛЬ чтений. Цена берётся из события свопа источника,
# сети не нужно ни на байт. РЕШЕНИЙ ТЕНЬ НЕ ПРИНИМАЕТ: модуль min_out для
# отправки не отдаёт вовсе (это его собственная самопроверка), а min_out тени
# считается ЗДЕСЬ -- и только чтобы положить рядом с боевым в запись.
#
# ДВА ЧИСЛА ЦЕНЫ И ДВА ЧИСЛА МИНИМУМА -- слово владельца: "на каждом сигнале
# DLMM писать обе цены и оба min_out". Формула минимума взята ОДНА И ТА ЖЕ, что
# у денежного пути (c2_dlmm_tochnaya_kotirovka: int(ожидаем * (1 - прск))):
# посчитай её здесь иначе -- и расхождение показывало бы разницу формул, а не
# разницу цен.
def тень_нуля_чтений(tx_источника: dict | None, пул: str | None, к: dict, *,
                      лампорты: int, минт_котировки: str | None,
                      проскальзывание: float = 0.0, налог_выхода=None,
                      программа_выхода: str | None = None,
                      группа: str | None = None) -> dict:
    """Годился ли путь НУЛЯ чтений. Нуль чтений, решений не принимает."""
    из_ = {"годилось": None, "почему_нет": None,
            "цена_полосы": None, "цена_тени": None,
            "min_out_полосы": None, "min_out_тени": None,
            "отклонение_%": None, "запас_нужен_%": None, "мс": None}
    try:
        import c2_dlmm_bez_chteniy as НЧ  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["почему_нет"] = f"модуля нуля чтений нет: {type(exc).__name__}"
        return из_
    if not НЧ.включён(группа):
        из_["почему_нет"] = "тень нуля чтений выключена флагом"
        return из_
    if not минт_котировки:
        из_["почему_нет"] = "минт котировки не известен -- сторона свопа не выводится"
        return из_
    т = НЧ.тень(tx_источника, пул, к, лампорты=int(лампорты),
                 минт_котировки=минт_котировки,
                 проскальзывание=float(проскальзывание),
                 налог_выхода=налог_выхода, программа_выхода=программа_выхода)
    т = т if isinstance(т, dict) else {}
    из_.update({ключ: т.get(ключ) for ключ in
                 ("годилось", "почему_нет", "отклонение_%", "запас_нужен_%", "мс")})
    из_.update(корзин_у_источника=т.get("корзин_у_источника"),
                корзин_нашего_размера=т.get("корзин_нашего_размера"),
                корзин_доказано=т.get("корзин_доказано"))
    # ОБЕ ЦЕНЫ. "цена_полосы" -- выход боевой точной котировки (двумя чтениями),
    # "цена_тени" -- выход нуля чтений. Нет числа -- None, а не ноль: ноль читался
    # бы как "пул ничего не отдаёт".
    цена_п = т.get("выход_полосы")
    цена_т = т.get("наш_выход")
    из_["цена_полосы"] = int(цена_п) if isinstance(цена_п, int) and цена_п > 0 else None
    из_["цена_тени"] = int(цена_т) if isinstance(цена_т, int) and цена_т > 0 else None
    # ОБА МИНИМУМА. Боевой берём ИЗ ОТВЕТА КОТИРОВКИ (то самое число, что уйдёт
    # в транзакцию), а не пересчитываем: пересчёт мог бы разойтись с отправленным.
    мо_п = (к or {}).get("min_out")
    из_["min_out_полосы"] = int(мо_п) if isinstance(мо_п, int) and мо_п > 0 else None
    if из_["цена_тени"] is not None:
        мо_т = int(из_["цена_тени"] * (1.0 - float(проскальзывание)))
        из_["min_out_тени"] = мо_т if мо_т > 0 else None
    return из_


# ТЕНЬ USDC-НОГИ (утренний пакет 01.10, п.2). Вторая нога на СТРОИТЕЛЯХ ТИПОВ:
# сигнал с котировкой USDC в CLMM/DLMM/Whirlpool/DAMM v2 двухшаговый путь не
# берёт (у него вторая нога только CPMM и Pump AMM), и полоса такой сигнал теряет
# целиком. Число Code-2 за 28-29.09: 9 сигналов в сутки в денежных группах.
#
# ЗДЕСЬ ТОЛЬКО ЧИСЛА. Флаг BLOOM_USDC_NOGA по умолчанию выключен, режим "ten"
# решений полосы не меняет вовсе: поля идут в журнал решений (его пишет детектор,
# запись.update(рез)) -- и потому видны даже по сигналам, которые полоса не взяла.
#
# В ЭТОЙ ФУНКЦИИ БОЕВОГО РЕЖИМА НЕТ НАРОЧНО: тень -- чтение, и смешивать её с
# отправкой значило бы, что выключить бой нельзя, не выключив числа. Бой стоит
# отдельной веткой в `провести`, за этим вызовом, и min_out там берёт котировщик
# типа -- цена события источника, которой считает тень, наш объём не учитывает
# и потому выход ЗАВЫШАЕТ.
def тень_usdc_ноги(*, tx_источника: dict | None, источник: str | None,
                    минт: str | None, лампорты: int, кэш_ног,
                    проскальзывание: float, группа: str | None = None) -> dict:
    """Поля тени USDC-ноги для журнала решений. Решений не принимает."""
    из_ = {"lane_usdc_noga_godilos": None,
            "lane_usdc_noga_why_not": "модуль USDC-ноги не загружен",
            "lane_usdc_noga_size_sol": лампорты / ЛАМПОРТОВ_В_SOL,
            "lane_usdc_noga": None, "lane_usdc_noga_boj_why_not": None}
    try:
        import c2_usdc_noga as UN  # noqa: PLC0415

        тн = UN.ten(tx_istochnika=tx_источника or {}, istochnik=источник or "",
                     mint=минт or "", lamporty=int(лампорты), kesh_nog=кэш_ног,
                     proskalzyvanie=float(проскальзывание), gruppa=группа)
        тн = тн if isinstance(тн, dict) else {}
        из_["lane_usdc_noga_godilos"] = тн.get("ok")
        из_["lane_usdc_noga_why_not"] = тн.get("why_not")
        из_["lane_usdc_noga"] = {к: тн.get(к) for к in
                                  ("rezhim", "pool_program", "label", "way",
                                   "leg1_pool_program", "leg1_template_age_s",
                                   "leg1_min_out", "leg2_amount_in",
                                   "leg2_to_pool", "quote_fee_bps", "min_out",
                                   "expected_out", "razvernut", "chtenij")}
        # БОЕВАЯ ВЕТКА ЖИВЁТ НЕ ЗДЕСЬ: тень обязана остаться чтением без
        # решений. Она стоит в `провести` сразу за этим вызовом, и причину её
        # отказа кладёт туда же -- `lane_usdc_noga_boj_why_not`.
    except Exception as exc:  # noqa: BLE001
        из_["lane_usdc_noga_why_not"] = (
            f"тень USDC-ноги упала: {type(exc).__name__}: {str(exc)[:120]}")
    return из_


def бой_usdc_ноги(группа: str | None = None) -> bool:
    """Включён ли БОЕВОЙ режим USDC-ноги у этой группы.

    Правило флага написано ОДИН раз -- в c2_usdc_noga.boj (три значения флага и
    список групп сильнее общего). Здесь только обёртка: модуля на хосте нет --
    отвечаем "нет", потому что собрать всё равно нечем.
    """
    try:
        import c2_usdc_noga as UN  # noqa: PLC0415

        return bool(UN.boj(группа))
    except Exception:  # noqa: BLE001
        return False


def массивы_dlmm_сейчас(B, tpl: dict, mv: dict, *, лампорты: int,
                         проскальзывание: float, rpc_call=None,
                         котировщик=None, tx_источника: dict | None = None,
                         группа: str | None = None) -> dict:
    """Шаблон DLMM с НЫНЕШНИМИ массивами корзин плюс точная цена.

    Возвращает {ok, why_not, шаблон, min_out, expected_out, ...}. Шаблон
    подменяется целиком: исходный не меняется (см. c2_swap_build.
    шаблон_с_нынешними_массивами -- он же считает, сколько не влезло).
    """
    из_ = {"ok": False, "why_not": None, "шаблон": None, "min_out": None,
            "expected_out": None, "массивов_нужно": None, "массивов_влезло": None,
            "не_влезло": None, "чтений": None, "мс_чтений": None,
            "корзин": None, "slot": None}
    if rpc_call is None:
        из_["why_not"] = ("узел недоступен, нынешние массивы корзин не прочитать "
                           "-- отправка без них платит за промах")
        return из_
    пул = (tpl.get("accounts") or [None])[0]
    if not пул:
        из_["why_not"] = "в инструкции DLMM нет счёта пула"
        return из_
    if not mv or not mv.get("quote_mint") or not mv.get("base_mint"):
        из_["why_not"] = "минты пула не восстановились -- куда идёт своп, неясно"
        return из_
    if котировщик is None:
        try:
            import c2_dlmm_tochnaya_kotirovka as K  # noqa: PLC0415
        except Exception as exc:  # noqa: BLE001
            из_["why_not"] = (f"модуль точной котировки DLMM не загружен: "
                               f"{type(exc).__name__}")
            return из_
        котировщик = K.котировка
    try:
        к = котировщик(пул=пул, минт_базы=mv["base_mint"],
                        минт_котировки=mv["quote_mint"], лампорты=int(лампорты),
                        проскальзывание=float(проскальзывание), rpc_call=rpc_call)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"точная котировка DLMM упала: {type(exc).__name__}: {str(exc)[:120]}"
        return из_
    к = к if isinstance(к, dict) else {}
    из_.update(чтений=к.get("чтений"), мс_чтений=к.get("мс_чтений_всего"),
                корзин=к.get("корзин"), slot=к.get("slot"),
                bin_step=к.get("bin_step"), active_id=к.get("active_id"))
    # ТЕНЬ ОДНОГО ЧТЕНИЯ: годился бы этот сигнал для пути Code-3. Нуль чтений,
    # решения не принимает, идёт в запись позиции -- по ней и будет видно
    # "село >= прежнего" на БОЕВОМ отставании.
    if к.get("ok"):
        из_["одно_чтение_тень"] = тень_одного_чтения(
            tx_источника, (tpl.get("accounts") or [None])[0], к)
        # ТЕНЬ НУЛЯ ЧТЕНИЙ -- ТЕМ ЖЕ ПОРЯДКОМ И ТУТ ЖЕ: ей нужна готовая точная
        # цена полосы (к["expected_out"]), иначе сверять не с чем и ответ будет
        # "не с чем сверить", а не True.
        из_["нуль_чтений_тень"] = тень_нуля_чтений(
            tx_источника, (tpl.get("accounts") or [None])[0], к,
            лампорты=int(лампорты), минт_котировки=(mv or {}).get("quote_mint"),
            проскальзывание=float(проскальзывание), группа=группа)
    сейчас_адреса = list(к.get("массивы_адреса") or [])
    из_["массивов_нужно"] = len(сейчас_адреса)
    из_["массивы_индексы"] = list(к.get("массивы_индексы") or [])
    if not к.get("ok"):
        из_["why_not"] = f"точная цена не выдана: {к.get('why_not')}"
        return из_
    if not сейчас_адреса:
        из_["why_not"] = "котировка не назвала ни одного массива корзин"
        return из_
    # МАССИВЫ ШАБЛОНА -- ТЕ ЖЕ, ЧТО У ИСТОЧНИКА: их адреса берутся из хвоста
    # счетов и опознаются по PDA. Опознание живёт в сборщике, здесь только
    # решение.
    # ДОПИСЫВАТЬ ХВОСТ РАЗРЕШЕНО: у DLMM массивы корзин -- remaining accounts,
    # и когда мест у источника меньше нужного, недостающие дописываются в конец
    # (сборщик делает это только если места массивов -- настоящий непрерывный
    # хвост, иначе отказывает). Замер 29.09: без дописывания из 10 живых сделок
    # мест хватало лишь у 3, то есть 7 сигналов из 10 полоса теряла бы зря.
    шаб = B.шаблон_с_нынешними_массивами(
        tpl, массивы_сейчас=сейчас_адреса, дописывать=True,
        массивы_шаблона=B.массивы_корзин_шаблона(
            tpl, пул, индексы_сейчас=из_["массивы_индексы"]))
    шаб = шаб if isinstance(шаб, dict) else {}
    из_["массивов_влезло"] = шаб.get("подставлено")
    из_["массивов_дописано"] = шаб.get("дописано")
    из_["массивы_хвостом"] = шаб.get("хвост")
    # НЕ_ВЛЕЗЛО -- СПИСОК АДРЕСОВ, а не счёт: сравнивать его с нулём как число
    # нельзя (самопроверка поймала это на первом же прогоне). Наружу отдаём и
    # сам список, и его длину -- по длине принимается денежное решение.
    не_влезли = list(шаб.get("не_влезло") or [])
    из_["не_влезло"] = не_влезли
    из_["не_влезло_сколько"] = len(не_влезли)
    из_["мест_у_источника"] = шаб.get("массивов_шаблона")
    if not шаб.get("ok"):
        из_["why_not"] = f"подстановка массивов не вышла: {шаб.get('why_not')}"
        return из_
    if не_влезли:
        из_["why_not"] = (f"массивов корзин не хватает: нужно {len(сейчас_адреса)}, "
                           f"а у источника мест {шаб.get('массивов_шаблона')} -- "
                           "своп откатился бы, а чаевые и приоритет списались")
        return из_
    из_.update(ok=True, шаблон=шаб.get("шаблон"),
                min_out=к.get("min_out"), expected_out=к.get("expected_out"),
                fee=к.get("fee"), protocol_fee=к.get("protocol_fee"))
    return из_


# ------------------------------------------- типы со СВОИМ строителем (29.09)

# Программа пула -> ИМЯ МОДУЛЯ строителя. Имя, а не сам модуль, нарочно: импорт
# трёх модулей на загрузке bloom_own_send стоил бы времени на каждом запуске и
# уронил бы ВСЮ полосу, если один из них не собрался. Модуль подтягивается лениво
# и только для той программы, которая пришла с сигналом.
# Приёмка (deploy/checks/priemka_stroitelya.py:642) читает КЛЮЧИ этого словаря,
# чтобы не отказывать типу, которого нет в SPECS, ещё до единого вызова узла.
МОДУЛИ_СТРОИТЕЛЕЙ = {
    "CAMMCzo5YL8w4VFF8KVHrK22GGUsp5VTaW7grrKgrWqK": "c2_clmm_stroitel",
    "whirLbMiicVdio4qvUfM5KAg6Ct8VwpYzGff3uctyCc": "c2_whirlpool_stroitel",
    "dbcij3LWUppWqq96dh6gJWwBifmcGfLSB5D4DuSMaqN": "c2_dbc_stroitel",
    "675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8": "c2_ammv4_stroitel",
}
# ЧТЕНИЕ НАЛОГА TOKEN-2022 (Code-3). Модуля может не быть на хосте -- тогда
# NALOG_2022 остаётся None, и путь идёт прежним правилом (кеш, потом отказ при
# незнании). Импорт лениво тут, а не в функции: один раз на процесс.
try:
    import c2_nalog_2022 as НАЛОГ_2022  # noqa: E402
except Exception:  # noqa: BLE001
    НАЛОГ_2022 = None

ПРОГРАММА_TOKEN_2022 = "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb"
# Ставка налога, когда сторона базы на Token-2022, а ставку прочитать не удалось.
# То же число и та же причина, что у двухшагового (bloom_lane_two_step.
# ЗАПАС_НАЛОГА_BPS = 600): взято с потолка налога маршрута, то есть худшее из
# допустимых. Нулём неизвестное подменять нельзя.
ЗАПАС_НАЛОГА_BPS_СБОРКИ = ST.env_int("BLOOM_LANE_TAX_FALLBACK_BPS", 600)


def _модуль_строителя(прог: str | None):
    """Модуль своего строителя для этой программы или None."""
    имя = МОДУЛИ_СТРОИТЕЛЕЙ.get(прог or "")
    if not имя:
        return None
    try:
        return importlib.import_module(имя)
    except Exception:  # noqa: BLE001
        return None


def программа_минта_из_сделки(tx: dict, минт: str | None) -> str | None:
    """Программа токена этого минта ИЗ БАЛАНСОВ сделки источника. Сети нет.

    Единственный офлайновый способ узнать, Token-2022 ли сторона базы, не
    завязываясь на тип пула: у Whirlpool счета делятся на A/B, и
    c2_swap_build.mints_and_vaults на нём падает KeyError. programId в балансах
    может и не прийти -- тогда None, и это ЧЕСТНОЕ "не знаю", а не SPL.
    """
    if not минт:
        return None
    for когда in ("postTokenBalances", "preTokenBalances"):
        for б in ((tx or {}).get("meta") or {}).get(когда) or []:
            if isinstance(б, dict) and б.get("mint") == минт and б.get("programId"):
                return б["programId"]
    return None


# КЕШ ПРОЧИТАННОГО НАЛОГА -- НА ПРОЦЕСС, ПО МИНТУ. Читается он одним
# getAccountInfo и только на минтах Token-2022; второй раз по тому же минту
# платить кругом до сети незачем. Ключ -- минт; эпоху в ключ НЕ берём и это
# названо нарочно: ставка может смениться на границе эпохи, и Code-3 сказал это
# прямо. Пока служба живёт минуты-часы, а не сутки, риск мал; когда чтение
# станет постоянным, срок годности придётся добавить -- это записано владельцу.
_КЕШ_НАЛОГА_2022: dict = {}


def налог_базы_для_строителя(tx: dict, минт: str | None, налог_минта=None,
                              *, rpc_call=None, группа: str | None = None) -> dict:
    """Пара (bps, максимум) для налог_выхода строителя -- ТОЛЬКО из кеша.

      * ставка есть в кеше -> (bps, max_fee). max_fee из кеша почти всегда None,
        и это безопасно: без потолка сбор считается ПОЛНЫМ, то есть ожидаемый
        выход и min_out выходят МЕНЬШЕ настоящих, а не больше;
      * кеш доказал ноль (taxed is False ПРИ token_program == Token-2022)
        -> (0, None);
      * БАЗА НА Token-2022, А СТАВКА НЕ ПРОЧИТАНА -> ОТКАЗ (отказ=True,
        налог=None). Слово владельца 30.09: "оставить отказ при незнании".
        Запас 600 bps здесь -- догадка: если настоящий сбор больше, минимум
        выходит ЗАВЫШЕННЫМ и покупка откатывается, сжигая приоритет и чаевые на
        каждой попытке. Точное чтение расширения TransferFeeConfig из счёта
        минта владелец поставил В ОЧЕРЕДЬ ("не сейчас");
      * во всех прочих состояниях -> запас (ЗАПАС_НАЛОГА_BPS_СБОРКИ, None).

    ПОЧЕМУ ЗАПАС ОСТАЁТСЯ ТАМ, ГДЕ МИНТ НЕ Token-2022. Сторону выхода строитель
    определяет САМ по состоянию пула, а снаружи видна только программа минта из
    балансов сделки. Отказывать и здесь значило бы отказывать почти на каждой
    сборке (сбор Code-2 кладёт в поле mint адрес WSOL -- это 93 отказа строителя
    в приёмке 22:36Z), а ошибка запаса тут идёт В БЕЗОПАСНУЮ СТОРОНУ: налога на
    классическом SPL нет, значит min_out выходит МЕНЬШЕ настоящего -- откат
    невозможен, платим лишь частью защиты по цене, и это сказано в base_fee_from.

    Пары (None, None) не бывает НИ В ОДНОЙ ветке. налог=None выходит ТОЛЬКО
    вместе с отказ=True, и тогда собрать() отказывает ДО вызова строителя:
    молчаливого нуля, от которого ставился гейт, по-прежнему нет.
    """
    из_ = {"налог": None, "откуда": None, "программа_базы": None, "bps": None,
            "отказ": False}
    прог_минта = программа_минта_из_сделки(tx, минт)
    из_["программа_базы"] = прог_минта
    н = {}
    if callable(налог_минта) and минт:
        try:
            н = dict(налог_минта(минт) or {})   # КОПИЯ: кеш отдаёт свой объект
        except Exception:  # noqa: BLE001
            н = {}
    из_кеша_прог = н.get("token_program")
    это_2022 = (прог_минта == ПРОГРАММА_TOKEN_2022
                 or из_кеша_прог == ПРОГРАММА_TOKEN_2022)
    # НАЛОГ ПЕРЕДАЁТСЯ ВСЕГДА, ДАЖЕ ЕСЛИ ЭТОТ МИНТ -- КЛАССИЧЕСКИЙ SPL.
    # Почему не "классический SPL -- налога нет": строитель проверяет программу
    # СВОЕЙ стороны выхода, которую определяет сам по состоянию пула, а снаружи
    # её дёшево не узнать. Сбор Code-2 кладёт в поле mint адрес WSOL, и первый
    # заход по нему решал "налога нет" -- 93 отказа строителя в приёмке 22:36Z
    # ровно на этом. Правило "единственный не-WSOL минт в балансах" замерено и
    # отвергнуто: оно верно лишь у 6 образцов из 143 (4.2 %).
    # Передать налог там, где его нет, -- ошибка в БЕЗОПАСНУЮ сторону: сбор
    # вычтется из ожидаемого выхода, min_out выйдет МЕНЬШЕ настоящего, а
    # программа сравнивает порог с настоящей суммой. Отката не будет, платим
    # лишь частью защиты по цене -- и это сказано в base_fee_from.
    if isinstance(н.get("fee_bps"), int) and 0 <= int(н["fee_bps"]) <= 10_000:
        из_.update(налог=(int(н["fee_bps"]), н.get("max_fee")),
                    bps=int(н["fee_bps"]),
                    откуда=("кеш процесса" if н.get("max_fee") is not None
                            else "кеш процесса, потолок неизвестен"))
        return из_
    # НОЛЬ ПРИНИМАЕТСЯ ТОЛЬКО ПО ДОКАЗАТЕЛЬСТВУ, А НЕ ПО taxed is False.
    # Найдено 30.09 при разборе переноса Code-3: у детектора стоит
    # taxed = bool(fee_bps) (bloom_detector.py), и НЕразобранный счёт минта даёт
    # ровно то же taxed=False, что и разобранный без расширения налога, -- при
    # token_program, уже записанном из owner как Token-2022. По прежнему условию
    # такой случай проходил как "ноль доказан", минимум выходил ЗАВЫШЕННЫМ и
    # покупка откатывалась бы на каждой попытке: это и есть тот молчаливый ноль,
    # против которого владелец велел отказывать при незнании. Теперь ноль берём,
    # когда кеш его ДОКАЗАЛ (ноль_доказан) или когда ставка прочитана нулём
    # (ветка fee_bps выше); во всех прочих случаях -- отказ ниже.
    if (н.get("ноль_доказан") is True and н.get("taxed") is False
            and из_кеша_прог == ПРОГРАММА_TOKEN_2022):
        из_.update(налог=(0, None), bps=0,
                    откуда="кеш ДОКАЗАЛ: расширения налога у минта нет")
        return из_
    # ЧТЕНИЕ НАЛОГА С ЦЕПИ -- ЗА ФЛАГОМ BLOOM_NALOG_2022 (перенос Code-3,
    # c2_nalog_2022). Стоит ПЕРЕД отказом при незнании и ПОСЛЕ кеша полосы:
    # кеш промахивается именно на свежем минте, то есть тогда, когда это важно.
    #
    # ЧТО ДАЁТ. Ноль без чтения на классическом SPL (расширений там не бывает) --
    # вместо запаса 600 bps, который отдавался даром: по сборам Code-2 из восьми
    # известных баз на Token-2022 налога нет у семи. И ОДНО getAccountInfo на
    # минтах Token-2022 -- ставку и потолок на текущую эпоху.
    #
    # ЧЕГО НЕ ДАЁТ. Эпоху мы не спрашиваем (это был бы второй круг до сети):
    # модуль тогда берёт ХУДШУЮ из двух ставок и помечает эпоха_известна=False.
    # Ошибка в эту сторону безопасна: налог посчитан больше настоящего, минимум
    # выходит МЕНЬШЕ -- отката не будет, заплатим частью защиты по цене.
    if НАЛОГ_2022 is not None and НАЛОГ_2022.включён(группа):
        о = НАЛОГ_2022.налог(минт, прог_минта, rpc_call=rpc_call,
                              группа=группа, кеш=_КЕШ_НАЛОГА_2022)
        if о.get("ok") and isinstance(о.get("bps"), int):
            из_.update(налог=(int(о["bps"]),
                               (int(о["максимум"]) if о.get("максимум") is not None
                                else None)),
                        bps=int(о["bps"]), отказ=False,
                        откуда=(f"чтение цепи: {о.get('откуда')}"
                                 + ("" if о.get("эпоха_известна")
                                    else "; эпоха неизвестна -- худшая из двух")),
                        чтений_налога=int(о.get("чтений") or 0),
                        мс_налога=о.get("мс_чтения"),
                        эпоха_известна=о.get("эпоха_известна"))
            return из_
        # НЕ ПРОЧИТАЛОСЬ -- НЕ ПОВОД ПОДСТАВИТЬ НОЛЬ. Дальше идёт прежнее
        # правило: Token-2022 без ставки -- отказ, прочее -- запас.
        из_["налог_чтение_why_not"] = о.get("why_not")
        из_["чтений_налога"] = int(о.get("чтений") or 0)

    if это_2022:
        # СЛОВО ВЛАДЕЛЬЦА 30.09: "оставить отказ при незнании". База ДОКАЗАННО
        # на Token-2022 (программа минта из балансов сделки или из кеша), а
        # ставку сбора не прочитал никто. Запас был догадкой в 600 bps: при
        # настоящем сборе выше минимум выходит завышенным и покупка откатывается
        # на каждой попытке, сжигая приоритет и чаевые.
        из_.update(налог=None, bps=None, отказ=True,
                    откуда="отказ: база на Token-2022, ставка сбора не прочитана")
        return из_
    из_.update(налог=(int(ЗАПАС_НАЛОГА_BPS_СБОРКИ), None),
                bps=int(ЗАПАС_НАЛОГА_BPS_СБОРКИ),
                откуда="запас: сторона выхода снаружи неизвестна")
    return из_


def собрать(*, tx_источника: dict, источник: str, минт: str, наш_кошелёк: str,
             лампорты: int, проскальзывание: float = 0.35,
             cu_units: int | None = None, приоритет_лампорты: int = 1_000_000,
             чаевые_лампорты: int = 1_000_000, семя: str | None = None,
             чаевые_списком: list | None = None,
             нонс: tuple | None = None,
             чаевые_вперёд: bool = False, rpc_call=None,
             dlmm_шаг=None, налог_минта=None) -> dict:
    """Наша покупка одной транзакцией: своп + приоритет + чаевые Sender.

    Возвращает НЕПОДПИСАННУЮ транзакцию. Ни подписи, ни отправки здесь нет
    намеренно: собрать -- дёшево и безопасно, а подпись это уже деньги.
    """
    из_ = {"ok": False, "why_not": None, "pool_program": None, "min_out": None,
            "expected_out": None, "tip_account": None, "build_ms": None}
    t0 = time.perf_counter()
    # ПОТОЛОК И КОШЕЛЁК -- ДО всякой работы. Проверять их после сборки
    # бессмысленно: собранную транзакцию уже можно подписать.
    if наш_кошелёк != кошелёк_полосы():
        из_["why_not"] = ("сборка не на кошелёк полосы: "
                           f"{str(наш_кошелёк)[:12]} вместо {кошелёк_полосы()[:12]}")
        return из_
    if not isinstance(лампорты, int) or лампорты <= 0:
        из_["why_not"] = f"размер не положительное целое: {лампорты!r}"
        return из_
    if лампорты > потолок_лампортов():
        из_["why_not"] = (f"размер {лампорты / ЛАМПОРТОВ_В_SOL} SOL выше потолка "
                           f"полосы {ПОТОЛОК_РАЗМЕРА_SOL} SOL")
        return из_
    try:
        C, PP, SB, B = _модули()
    except Exception as exc:  # noqa: BLE001
        # ИМЯ НЕДОСТАЮЩЕГО МОДУЛЯ -- В ПРИЧИНУ. Без него "ModuleNotFoundError"
        # не отличить от десятка других: ровно на этом сухой прогон 25.09
        # сказал "модули не загружены" и не сказал, какие. Имена модулей и
        # пакетов -- не секрет, в отличие от ключей.
        из_["why_not"] = (f"модули сборки не загружены: {type(exc).__name__}: "
                           f"{str(exc)[:120]}")
        return из_
    try:
        пул = C.identify_pool(tx_источника, источник, минт)
        if not пул.get("ok"):
            из_["why_not"] = f"пул: {пул.get('why_not')}"
            return из_
        прог = PP.pool_program(tx_источника, пул["pool_vault"], SB._labels())["pool_program"]
        из_["pool_program"] = прог
        # ТИПЫ -- ПО ГРУППЕ ИСТОЧНИКА, одним списком (типы_полосы). Группа
        # берётся здесь, а не в подписи функции: сборка уже знает адрес
        # источника, а протягивать группу через три вызова значило бы менять
        # денежный путь ради флага.
        группа_сигнала = группа_источника(источник, tx=tx_источника)
        из_["lane_group"] = группа_сигнала
        # ФАКТЫ ЗАПУСКА -- В ОТЧЁТ СБОРКИ, и только когда группа пришла ПО
        # ПРАВИЛУ. У сигнала запуска подпись и слот источника -- это подпись и
        # слот САМОГО СОЗДАНИЯ (сигналом служит транзакция создания), поэтому
        # отдельно нужны лишь те числа, которых у прочих сигналов не бывает:
        # сколько вложил создатель и какой разновидностью токен создан. Они
        # уходят и в строку решения, и в запись позиции -- по ним Code-2 считает
        # валовой итог без издержек.
        if группа_сигнала == ГРУППА_ЗАПУСКОВ:
            try:
                import c1_zapusk_zhurnal as ZH_  # noqa: PLC0415

                сз = ZH_.signal_zapuska(tx_источника)
                из_["zapusk_sol_sozdatelya"] = сз.get("sol_sozdatelya")
                из_["zapusk_lamportov_sozdatelya"] = сз.get(
                    "lamportov_sozdatelya")
                из_["zapusk_sozdanie"] = сз.get("sozdanie")
                из_["zapusk_pokupka_sozdatelya"] = сз.get("pokupka")
                из_["zapusk_mint_authority"] = ZH_.pda_mint_authority()
            except Exception as сбой_з:  # noqa: BLE001
                из_["zapusk_why_not"] = (f"факты запуска не собраны: "
                                          f"{type(сбой_з).__name__}")
        разрешённые = типы_полосы(группа_сигнала)
        if прог not in разрешённые:
            из_["why_not"] = f"тип пула вне полосы: {прог}"
            return из_
        # РАЗВИЛКА: ТИПЫ СО СВОИМ СТРОИТЕЛЕМ (CLMM, Whirlpool, DBC).
        # СТОИТ ДО extract_template НАРОЧНО. У Whirlpool записи в SPECS нет и не
        # будет (счета делятся на A/B, а не на вход/выход), а spec_of берёт
        # SPECS[tpl["program"]] БЕЗ .get -- любой из трёх вызовов B на его
        # шаблоне (mints_and_vaults, min_out_from_reserves, build_buy) дал бы
        # KeyError, и наружу он вышел бы невнятным "сборка: KeyError".
        #
        # НАЦЕНКА ВЫБИРАЕТСЯ ЗДЕСЬ, ДО котировки строителя. Ни один из трёх не
        # отдаёт reserves_after/virtual_reserves_after, поэтому правило тонкого
        # пула для них всё равно уходит в ветку "резерв неизвестен -- наценка
        # обычная"; посчитать её ЗАРАНЕЕ дешевле, чем звать подготовить() второй
        # раз с другой наценкой: это второй круг чтений узла в горячем пути.
        М = _модуль_строителя(прог)
        if М is not None and not М.включён(группа_сигнала):
            # Флаг строителя выключен (сегодня так у DBC: точной цены нет).
            # Путь идёт ПРЕЖНЕЙ дорогой, а не в отказ.
            из_["строитель"] = {"модуль": МОДУЛИ_СТРОИТЕЛЕЙ.get(прог),
                                 "использован": False,
                                 "почему": "флаг строителя выключен"}
            М = None
            # ПРЕЖНЕЙ ДОРОГИ У ЭТОГО ТИПА МОЖЕТ НЕ БЫТЬ ВОВСЕ.
            # У Whirlpool и AMM v4 записи в SPECS нет и не будет: счета делятся
            # не на вход/выход. spec_of берёт SPECS[tpl["program"]] БЕЗ .get, и
            # дальше путь упал бы на KeyError -- наружу это вышло бы невнятным
            # "сборка: KeyError", то есть сигнал терялся бы молча.
            #
            # ПОЧЕМУ ЭТО ЖИВАЯ УГРОЗА, А НЕ ТЕОРИЯ: lane_pools лежит в файле и
            # перечитывается БЕЗ перезапуска, а флаг строителя живёт в
            # окружении службы и меняется только с перезапуском. Значит тип
            # может стоять в полосе, а флаг -- отсутствовать (забытая строка
            # env, откат окружения, перезапуск со старым файлом). Whirlpool и
            # amm_v4 стоят в lane_pools у торгующих групп с 30.09, так что зазор
            # уже открыт.
            #
            # ОТКАЗ СО СЛОВАМИ ДЕШЕВЛЕ ПАДЕНИЯ: сигнал всё равно не купить, но
            # причина названа и видна в отказах, а не спрятана в KeyError.
            # ИМПОРТ ЗДЕСЬ, А НЕ ЧЕРЕЗ B: в этой функции имени B нет вовсе
            # (c2_swap_build импортируется локально в другом месте). Через B
            # вышел бы NameError, ушёл бы в except -- и отказ получили бы ВСЕ
            # типы с выключенным флагом, в том числе DBC, у которого прежний
            # путь есть и работает.
            try:
                import c2_swap_build as _Bсп  # noqa: PLC0415
                есть_прежний_путь = прог in _Bсп.SPECS
            except Exception:  # noqa: BLE001 -- неясность на деньгах = запрет
                есть_прежний_путь = False
            if not есть_прежний_путь:
                из_["строитель"]["почему"] = (
                    "флаг строителя выключен, а прежнего пути у типа нет "
                    "(записи в SPECS нет)")
                из_["why_not"] = (
                    f"тип пула {прог} идёт только своим строителем, а его флаг "
                    f"выключен: записи в SPECS нет, прежней дорогой не собрать")
                return из_
        if М is not None:
            выбор = проскальзывание_для_пула(группа_сигнала, None)
            из_["slippage_rule"] = выбор
            if выбор.get("slippage") is not None:
                проскальзывание = float(выбор["slippage"])
            из_["slippage"] = проскальзывание
            нал = налог_базы_для_строителя(tx_источника, минт, налог_минта,
                                            rpc_call=rpc_call,
                                            группа=группа_сигнала)
            из_["base_program"] = нал.get("программа_базы")
            из_["base_fee_bps"] = нал.get("bps")
            из_["base_fee_from"] = нал.get("откуда")
            из_["base_fee_reads"] = нал.get("чтений_налога")
            из_["base_fee_ms"] = нал.get("мс_налога")
            из_["base_fee_epoch_known"] = нал.get("эпоха_известна")
            из_["base_fee_read_why_not"] = нал.get("налог_чтение_why_not")
            # ОТКАЗ ПРИ НЕЗНАНИИ СТАВКИ -- ДО ВЫЗОВА СТРОИТЕЛЯ (слово владельца
            # 30.09). Ни одного чтения узла на такой сигнал не делаем: считать
            # цену по догадке о сборе значит платить откатами.
            if нал.get("отказ"):
                из_["why_not"] = нал.get("откуда")
                return из_
            # НАЛОГ ПРИНИМАЮТ НЕ ВСЕ ТРИ. У c2_dbc_stroitel.подготовить
            # параметров налог_выхода/налог_входа НЕТ ВОВСЕ (на их месте стоит
            # разрешить_приближение), и общий вызов с налогом даёт на нём
            # TypeError, а не отказ -- проверено прогоном. Спрашиваем саму
            # функцию, а не помним наизусть.
            имена_пар = getattr(getattr(М.подготовить, "__code__", None),
                                 "co_varnames", ())
            принимает_налог = "налог_выхода" in имена_пар
            if нал.get("налог") is not None and not принимает_налог:
                # Сторона базы на Token-2022, а вычесть налог этот строитель не
                # умеет: его минимум вышел бы ЗАВЫШЕННЫМ и откатывался бы на
                # каждой попытке, сжигая приоритет и чаевые.
                из_["why_not"] = ("строитель не принимает налог перевода, а база "
                                   "на Token-2022 -- минимум вышел бы завышенным")
                return из_
            доп_пары = ({"налог_выхода": нал.get("налог"), "налог_входа": None}
                         if принимает_налог else {})
            # ХРАНИЛИЩЕ ПУЛА И МИНТ БАЗЫ -- ДВА ПРЕДОХРАНИТЕЛЯ САМИХ СТРОИТЕЛЕЙ,
            # и без них они спят. Строитель выбирает пул по ПЕРВОЙ инструкции
            # своей программы, а на сделке роутера их несколько: наше хранилище
            # (C.identify_pool) доказывает, что выбран ТОТ пул. Минт базы даёт
            # ему проверить "минт сигнала -- действительно база этого пула",
            # иначе купили бы не тот токен. Оба параметра у всех трёх
            # строителей необязательные, поэтому спрашиваем их по co_varnames и
            # не ломаемся на строителе, который их не знает.
            имена_подг = getattr(getattr(М.подготовить, "__code__", None),
                                  "co_varnames", ())
            if "хранилище_пула" in имена_подг:
                доп_пары["хранилище_пула"] = пул.get("pool_vault")
            if "минт_базы" in имена_подг:
                доп_пары["минт_базы"] = минт or None
            try:
                д = М.подготовить(tx_источника, лампорты=лампорты,
                                   проскальзывание=проскальзывание,
                                   rpc_call=rpc_call, минт_котировки=C.WSOL,
                                   группа=группа_сигнала, **доп_пары)
            except Exception as exc:  # noqa: BLE001
                # подготовить() внутри не обёрнут try/except: сломанная meta или
                # недостающий перенос цены вышли бы исключением наверх.
                из_["why_not"] = (f"строитель: {type(exc).__name__}: "
                                   f"{str(exc)[:140]}")
                return из_
            д = д if isinstance(д, dict) else {}
            из_["строитель"] = {к: v for к, v in д.items() if к != "шаблон"}
            из_["строитель"]["модуль"] = МОДУЛИ_СТРОИТЕЛЕЙ.get(прог)
            из_["строитель"]["использован"] = True
            if not д.get("ok"):
                из_["why_not"] = f"строитель: {д.get('why_not')}"
                return из_
            tpl, мо, СБОРЩИК = д["шаблон"], д, М
            mv = {"quote_mint": д.get("минт_котировки"),
                   "base_mint": д.get("минт_базы"),
                   "quote_program": д.get("программа_котировки"),
                   "base_program": д.get("программа_базы")}
            if mv["quote_mint"] != C.WSOL:
                из_["why_not"] = "котировка пула не SOL -- полоса только одношаговая"
                return из_
            # НАТИВНАЯ КОТИРОВКА -- ТОЛЬКО У КРИВОЙ pump.fun, и у этих трёх
            # типов её не бывает. Локальную переменную задаём ЗДЕСЬ: общий хвост
            # ниже читает её, и без этого выходил UnboundLocalError -- живой след
            # 29 отказов в приёмке 22:36:28Z.
            нативная = False
            из_["native_quote"] = False
            # ПУЛ СТРОИТЕЛЬ ВЫБРАЛ САМ: адреса pool_state у полосы нет, у неё
            # только хранилище (C.identify_pool). На сделке роутера, трогающей
            # несколько пулов одной программы, шаблон() взял бы ПЕРВУЮ
            # инструкцию -- то есть чужой пул. Сверяем: наше хранилище обязано
            # быть среди счетов выбранной инструкции.
            if пул["pool_vault"] not in set((tpl or {}).get("accounts") or []):
                из_["why_not"] = ("строитель взял инструкцию другого пула той же "
                                   "программы (сделка роутера) -- цена вышла бы "
                                   "по чужому пулу")
                return из_
            # ПОТОЛОК КОМИССИИ ПУЛА БЕЗ fee_share НЕ ПРОВЕРЯЕТСЯ ВООБЩЕ:
            # _доля_комиссии_пула ушёл бы в замер доля_мимо_пула, а тот на
            # шаблоне Whirlpool ловит KeyError внутри себя и возвращает None,
            # после чего условие "if доля_ком is not None" ТИХО пропускает
            # покупку без проверки потолка. Поэтому здесь отказ, а не молчание.
            # Ноль здесь -- НЕ "комиссии нет", а "порт не отдал fee": у CLMM и
            # Whirlpool fee_share = int(q["fee"] or 0) / лампорты, и при
            # отсутствии fee выходит 0.0. Это НЕ None, поэтому потолок прошёл бы
            # с нулём, а замер-подстраховка не запустился бы. У пула
            # сосредоточенной ликвидности ставка комиссии не бывает нулевой.
            if not д.get("fee_share"):
                из_["why_not"] = (
                    "строитель не дал доли комиссии пула "
                    f"(fee_share={д.get('fee_share')!r}) -- потолок "
                    f"{ПОТОЛОК_КОМИССИИ_ПУЛА * 100:.2f} % не проверить, "
                    "покупка не берётся")
                return из_
            из_["min_out_from"] = f"строитель {МОДУЛИ_СТРОИТЕЛЕЙ.get(прог)}"
        else:
            СБОРЩИК = B
            tpl = B.extract_template(tx_источника, прог, пул["pool_vault"])
            if not tpl.get("ok"):
                из_["why_not"] = f"шаблон: {tpl.get('why_not')}"
                return из_
            mv = B.mints_and_vaults(tpl, tx_источника)
            # Кривая pump.fun платит НАТИВНЫМ SOL: токенового счёта котировки у неё
            # нет вовсе, оборачивать нечего. Это такой же один шаг, как WSOL, но
            # пускаем его только по флагу и только для кривой.
            нативная = bool(mv) and mv.get("quote_mint") == getattr(C, "NATIVE_QUOTE", "native_sol") \
                and прог == getattr(B, "BONDING", None) and кривая_включена(группа_сигнала)
            if not mv or (mv.get("quote_mint") != C.WSOL and not нативная):
                из_["why_not"] = "котировка пула не SOL -- полоса только одношаговая"
                return из_
            из_["native_quote"] = нативная
            точная_dlmm = None
            # НАЦЕНКА ЗАВИСИТ ОТ РЕЗЕРВА, А РЕЗЕРВ ИЗВЕСТЕН ТОЛЬКО ИЗ ЭТОГО ЖЕ
            # СЧЁТА (слово владельца 27.09 вечером, leader: 0.25 при резерве
            # котировочной стороны >= 30 SOL-экв., иначе 1.0). Поэтому считаем
            # дважды: первый счёт -- ради РЕЗЕРВА (он от наценки не зависит вовсе,
            # это балансы хранилищ из meta сделки источника), второй -- с той
            # наценкой, которую резерв и выбрал. Сети здесь нет, оба счёта
            # арифметические.
            мо = B.min_out_from_reserves(tpl, tx_источника, лампорты, проскальзывание)
            if мо.get("ok"):
                рез_дв = мо.get("reserves_after") or мо.get("virtual_reserves_after")
                резерв_sol_дв = None
                if isinstance(рез_дв, (list, tuple)) and рез_дв:
                    try:
                        резерв_sol_дв = int(рез_дв[0]) / ЛАМПОРТОВ_В_SOL
                    except (TypeError, ValueError):
                        резерв_sol_дв = None
                выбор = проскальзывание_для_пула(группа_сигнала, резерв_sol_дв)
                из_["slippage_rule"] = выбор
                новая = выбор.get("slippage")
                if (новая is not None and абс_разница(новая, проскальзывание) > 1e-12):
                    проскальзывание = float(новая)
                    из_["slippage"] = проскальзывание
                    мо = B.min_out_from_reserves(tpl, tx_источника, лампорты,
                                                  проскальзывание)
            # DLMM: НЫНЕШНИЕ МАССИВЫ КОРЗИН И ТОЧНАЯ ЦЕНА (вариант 1б, слово
            # владельца 29.09: два чтения, отказ без траты). Шаг стоит ПОСЛЕ счёта
            # минимума по резервам нарочно: тот счёт попутно даёт долю комиссии пула
            # (её проверяет потолок ниже) и ставит пул в очередь фонового чтения шага
            # корзины. Убрав его, мы потеряли бы обе вещи молча.
            if прог == getattr(B, "DLMM", None):
                шаг_dlmm = dlmm_шаг or массивы_dlmm_сейчас
                # ОДНО ЧТЕНИЕ ВМЕСТО ДВУХ -- ЗА СВОИМ ФЛАГОМ (Code-3,
                # c2_dlmm_odno_chtenie, BLOOM_DLMM_ODNO_CHTENIE, по умолчанию
                # выключен). Модуль отдаёт котировщик С ТОЙ ЖЕ ПОДПИСЬЮ и сам
                # держит откат на прежний двухчтенийный путь: флаг выключен или
                # его собственный отказ (активный массив сменился, свопу не
                # хватило массивов) -- зовётся K.котировка, и сигнал не теряется.
                #
                # МОДУЛЯ МОЖЕТ НЕ БЫТЬ НА ХОСТЕ -- И ЭТО НЕ ОТКАЗ СИГНАЛА: тогда
                # котировщик остаётся None, и массивы_dlmm_сейчас берёт прежний
                # путь сама. Причина кладётся в запись, чтобы молчания не было.
                котировщик_dlmm = None
                try:
                    import c2_dlmm_odno_chtenie as OD  # noqa: PLC0415
                    import c2_dlmm_tochnaya_kotirovka as K1  # noqa: PLC0415

                    котировщик_dlmm = OD.котировщик_для(
                        tx_источника, откат=K1.котировка, группа=группа_сигнала)
                except Exception as exc:  # noqa: BLE001
                    из_["dlmm_odno_chtenie_why_not"] = (
                        f"{type(exc).__name__}: {str(exc)[:80]}")
                д = шаг_dlmm(B, tpl, mv, лампорты=лампорты,
                              проскальзывание=проскальзывание, rpc_call=rpc_call,
                              котировщик=котировщик_dlmm,
                              tx_источника=tx_источника,
                              группа=группа_сигнала)
                д = д if isinstance(д, dict) else {}
                из_["dlmm"] = {к: v for к, v in д.items() if к != "шаблон"}
                if not д.get("ok"):
                    из_["why_not"] = f"DLMM: {д.get('why_not')}"
                    return из_
                if д.get("шаблон"):
                    tpl = д["шаблон"]
                точная_dlmm = д
            # ТОЧНАЯ ЦЕНА DLMM СИЛЬНЕЕ ПРИБЛИЖЁННОЙ. dlmm_min_out считает по ОДНОЙ
            # корзине -- по той, на которой остановился источник; точная котировка
            # проходит корзины и массивы по-настоящему, из живого состояния пула.
            # Доля комиссии при этом остаётся от приближённого счёта, если он вышел:
            # потолок комиссии пула -- отдельная защита, и терять её нельзя.
            if точная_dlmm is not None and точная_dlmm.get("min_out"):
                если_было = dict(мо) if isinstance(мо, dict) else {}
                доля_прежняя = если_было.get("fee_share")
                мо = {"ok": True, "pool": (tpl.get("accounts") or [None])[0],
                       "min_out": int(точная_dlmm["min_out"]),
                       "expected_out": int(точная_dlmm.get("expected_out") or 0),
                       "bin_step": точная_dlmm.get("bin_step"),
                       "путь_цены": "точная котировка DLMM",
                       "корзин": точная_dlmm.get("корзин")}
                # Доля комиссии: своя из котировки, а если её нет -- прежняя.
                вход_ком = точная_dlmm.get("fee")
                if вход_ком is not None and лампорты:
                    try:
                        мо["fee_share"] = float(вход_ком) / float(лампорты)
                    except (TypeError, ValueError, ZeroDivisionError):
                        мо["fee_share"] = доля_прежняя
                else:
                    мо["fee_share"] = доля_прежняя
                из_["min_out_from"] = "точная котировка DLMM"
                из_["min_out_pribliz"] = если_было.get("min_out")
        if not мо.get("ok"):
            # Без минимума отправлять нельзя: это покупка по любой цене.
            из_["why_not"] = f"минимум не выдаётся: {мо.get('why_not')}"
            return из_
        # Флага ok мало: значение минимума тоже обязано быть положительным.
        # min_out=0 -- это и есть "куплю по любой цене", только под видом
        # посчитанного числа.
        if not isinstance(мо.get("min_out"), int) or мо["min_out"] <= 0:
            из_["why_not"] = f"минимум не положителен: {мо.get('min_out')!r}"
            return из_
        # КОМИССИЯ ПУЛА -- ДЕНЬГИ, И У НЕЁ ПОТОЛОК. Расписание комиссии у свежих
        # пулов Meteora начинается с десятков процентов: в живой сделке 26.09
        # пул брал 50.9 %, и покупка по такой цене -- это минус половина входа
        # сразу. Считает долю сборщик (по событию свопа), решение "дорого" --
        # здесь, на денежном пути.
        # РЕЗЕРВ ПУЛА В SOL-ЭКВ. НА ВХОДЕ -- наружу: по нему стоит нижний
        # предел группы (min_pool_sol_reserve) и он же идёт в строку позиции
        # (п.1д). У кривой и Launchpad резервы ВИРТУАЛЬНЫЕ -- так и называем,
        # чтобы 30 SOL у кривой не путали с 30 SOL у настоящего хранилища.
        рез = мо.get("reserves_after") or мо.get("virtual_reserves_after")
        if isinstance(рез, (list, tuple)) and рез:
            try:
                из_["pool_reserve_sol"] = round(int(рез[0]) / ЛАМПОРТОВ_В_SOL, 9)
                из_["pool_reserve_kind"] = ("реальный" if мо.get("reserves_after")
                                             else "виртуальный")
            except (TypeError, ValueError):
                из_["pool_reserve_sol"] = None
        # КОМИССИЯ ПУЛА -- ОДНОЙ ФУНКЦИЕЙ ДЛЯ ВСЕХ ТИПОВ. У x*y=k сборщик
        # отдаёт fee_factor (доля, доходящая до пула), у сосредоточенной
        # ликвидности -- fee_share (сама комиссия). Спрашивать только второй
        # ключ значило не проверять потолок на CPMM, Pump AMM, Launchlab и
        # кривой вовсе.
        доля_ком = _доля_комиссии_пула(мо, tpl, tx_источника)
        из_["pool_fee_share"] = доля_ком
        if доля_ком is not None and float(доля_ком) > ПОТОЛОК_КОМИССИИ_ПУЛА:
            из_["why_not"] = (f"комиссия пула {float(доля_ком) * 100:.2f} % выше "
                               f"потолка {ПОТОЛОК_КОМИССИИ_ПУЛА * 100:.2f} % -- "
                               "покупка не берётся")
            return из_
        if чаевые_списком:
            # БОЕВОЙ ПУЛ: чаевые каждому подключённому сервису. Получателей и
            # сумму проверил чаевые_пула(); здесь ещё раз убеждаемся, что ни
            # один адрес не пустой и сумма не выше потолка -- это деньги, и
            # проверка на пути к ним дешевле разбора потом.
            чаевые = чаевые_списком[0][0]
            сумма_ч = sum(int(л) for _, л in чаевые_списком)
            потолок_ч = int(round(ПОТОЛОК_ЧАЕВЫХ_ПУЛА_SOL * ЛАМПОРТОВ_В_SOL))
            if any((not а) or int(л) <= 0 for а, л in чаевые_списком):
                из_["why_not"] = "в списке чаевых пула пустой адрес или ноль -- отказ"
                return из_
            if сумма_ч > потолок_ч:
                из_["why_not"] = (f"суммарные чаевые пула {сумма_ч} выше потолка "
                                   f"{потолок_ч} -- сборка отменена")
                return из_
            чаевые_для_сборки = list(чаевые_списком)
        else:
            чаевые = выбрать_чаевые(семя)
            # ПОЛУЧАТЕЛЬ ЧАЕВЫХ -- ТОЛЬКО СЧЁТ SENDER ИЗ ДОКУМЕНТАЦИИ. Проверка
            # стоит в рабочем пути, а не только в самопроверке: список правится
            # руками, и опечатка в нём отправила бы 0.001 SOL неизвестно кому.
            if чаевые not in TIP_ACCOUNTS:
                из_["why_not"] = ("адрес чаевых не из списка счетов Sender -- "
                                   "сборка отменена")
                return из_
            чаевые_для_сборки = (чаевые, чаевые_лампорты)
        # ПРЕДЕЛ CU -- ПО СТРОИТЕЛЮ (решение владельца 28.09). Вызов может
        # задать своё число (двухшаговая сборка так и делает); если не задал --
        # берём по типу пула, который к этому месту уже известен. Цена единицы
        # считается от БАЗЫ, а не от предела: иначе поднятый предел удешевил бы
        # приоритет и просадил нас в очереди блока.
        разновидность = (tpl or {}).get("ix") if isinstance(tpl, dict) else None
        cu_предел = (int(cu_units) if cu_units is not None
                      else предел_cu(из_.get("pool_program"),
                                      разновидность=разновидность))
        из_["cu_limit"] = cu_предел
        из_["cu_limit_from"] = ("задан вызовом" if cu_units is not None
                                 else ("по разновидности кривой"
                                        if (разновидность or "") == DISC_КРИВОЙ_V2
                                        else "по строителю"))
        из_["ix_raznovidnost"] = разновидность
        собрано = СБОРЩИК.build_buy(
            tpl, tx_источника, user=наш_кошелёк, payer=наш_кошелёк,
            amount_in=лампорты, min_out=мо["min_out"], cu_units=cu_предел,
            cu_price_micro=цена_единицы_cu(приоритет_лампорты, cu_предел),
            tip=чаевые_для_сборки, wrap_sol=True, tip_first=чаевые_вперёд,
            # ДОЛГОВЕЧНЫЙ NONCE (вариант пула по слову владельца 25.09): на
            # каждого отправителя своя транзакция со своими чаевыми, а
            # исполниться может только одна -- первая сдвигает nonce.
            nonce=нонс)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"сборка: {type(exc).__name__}: {str(exc)[:160]}"
        return из_
    # РАЗМЕР -- ДО ПОДПИСИ И ДО ОТПРАВКИ. Сеть отвергнет пакет больше 1232
    # байт, а для полосы отвергнутая отправка -- упавшая сделка.
    if int(собрано.get("size") or 0) > ПРЕДЕЛ_РАЗМЕРА_TX:
        сколько_ч = (len(чаевые_списком) if чаевые_списком else 1)
        из_["size"] = собрано.get("size")
        из_["why_not"] = (f"транзакция {собрано.get('size')} байт при пределе сети "
                           f"{ПРЕДЕЛ_РАЗМЕРА_TX} (чаевых в ней {сколько_ч}) -- "
                           "отправлять нельзя, сеть отвергнет")
        из_["too_big"] = True
        return из_
    if нативная:
        # У кривой две разновидности инструкции, и предел траты в них выражен
        # по-разному: у "точного выхода" это второй аргумент (предел), у
        # "точного входа" -- первый (сама трата). Трата в обоих случаях ровно
        # наша, поэтому пишем и её, и то, сколько дойдёт до кривой.
        из_["spend_lamports"] = int(лампорты)
        из_["curve_exact_out"] = bool(tpl.get("exact_out"))
        if tpl.get("exact_out"):
            из_["max_sol_cost_lamports"] = int(лампорты)
        из_["sol_to_curve_lamports"] = мо.get("sol_to_curve")
    из_.update(ok=True, min_out=мо["min_out"], expected_out=мо.get("expected_out"),
               nonce_account=(str(нонс[0]) if нонс else None),
               tip_account=чаевые,
               tips=(list(чаевые_списком) if чаевые_списком else None),
               tips_total_lamports=(sum(int(л) for _, л in чаевые_списком)
                                     if чаевые_списком else чаевые_лампорты),
               tx_base64=собрано["tx_base64"],
               size=собрано["size"], quote_mint=собрано.get("quote_mint"),
               build_ms=round((time.perf_counter() - t0) * 1000, 3))
    return из_


# ------------------------------------------------------------------ подпись

def подписать(tx_base64: str, *, blockhash: str, ожидаемый_кошелёк: str,
               секрет: str | None = None) -> dict:
    """Подставить настоящий blockhash и подписать нашим ключом.

    Сборщик компилирует сообщение с пустым blockhash -- подписывать такое
    бессмысленно, сеть его не примет. Здесь сообщение пересобирается с
    настоящим blockhash и только потом подписывается.

    Публичный ключ сверяется с кошельком позиции ПЕРЕД подписью и на каждой
    сделке. Чужой ключ подписал бы чужой кошелёк: это не предупреждение, а
    запрет.
    """
    из_ = {"ok": False, "why_not": None, "signature": None}
    try:
        import bloom_jupiter_sell as J  # noqa: PLC0415
        from solders.hash import Hash  # noqa: PLC0415
        from solders.message import MessageV0  # noqa: PLC0415
        from solders.transaction import VersionedTransaction  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"модули подписи не загружены: {type(exc).__name__}"
        return из_
    # ПУСТОЙ BLOCKHASH -- ОТКАЗ. Сборщик компилирует сообщение с нулевым
    # хешем, и он же -- законный Hash.default(). Подписать такую транзакцию
    # можно, отправить тоже, а сеть её не примет: деньги на чаевые и
    # приоритет при этом уже потрачены. Проверка стоит ДО подписи.
    НУЛЕВОЙ = "1" * 32
    if not blockhash or str(blockhash) == НУЛЕВОЙ or set(str(blockhash)) == {"1"}:
        из_["why_not"] = "blockhash пустой -- такую транзакцию сеть не примет"
        return из_
    свой = J.ключ_от_нашего_кошелька(ожидаемый_кошелёк, секрет)
    if not свой.get("ok"):
        из_["why_not"] = свой.get("why_not") or "ключ не проверен"
        return из_
    try:
        сырой = base64.b64decode(tx_base64)
        tx = VersionedTransaction.from_bytes(сырой)
        msg = tx.message
        новое = MessageV0(msg.header, msg.account_keys, Hash.from_string(blockhash),
                           msg.instructions, msg.address_table_lookups)
        # Разбор ключа -- ОДИН на весь репозиторий, из dbot_rescue: он
        # понимает и base58, и массив байтов. Второй разборщик здесь значил
        # бы два разных понимания одного секрета, а это деньги.
        from dbot_rescue import load_rescue_keypair  # noqa: PLC0415
        # Разбор ключа -- в СВОЁМ try, и текст его исключения наружу не
        # уходит: в сообщение об ошибке разбора может попасть сам секрет.
        # Наружу идёт только имя класса исключения.
        try:
            kp = load_rescue_keypair(секрет if секрет is not None else J.ключ_сырой())
        except Exception as exc_ключ:  # noqa: BLE001
            из_["why_not"] = f"ключ не разобрался ({type(exc_ключ).__name__})"
            return из_
        if str(kp.pubkey()) != ожидаемый_кошелёк:
            из_["why_not"] = "публичный ключ не совпал с кошельком -- подпись отменена"
            return из_
        подписанная = VersionedTransaction(новое, [kp])
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"подпись: {type(exc).__name__}: {str(exc)[:160]}"
        return из_
    из_.update(ok=True, signature=str(подписанная.signatures[0]),
               tx_base64=base64.b64encode(bytes(подписанная)).decode())
    return из_


def запустить_тень_симуляции(rpc_call, tx_base64: str | None, *, журнал,
                              метка: dict | None = None) -> bool:
    """Симуляция СВОИМ потоком и только в журнал.

    Зачем отдельно: на пути сделки она стоила 52.95 мс и отняла у нас блок
    (пара 05:11Z -- мы позже Bloom на 11.4 мс). Здесь она уже ничего не
    задерживает: результат никому не нужен для решения, он нужен для разбора.
    Ошибка внутри не выходит наружу -- замер не имеет права уронить сделку.
    """
    if not tx_base64 or rpc_call is None or журнал is None:
        return False

    def работа():
        запись = {"stage": "lane_sim", **(метка or {})}
        t0 = time.perf_counter()
        try:
            _, _, SB, _ = _модули()
            знач = (rpc_call("simulateTransaction",
                             [tx_base64, SB.SIM_OPTS]) or {}).get("value") or {}
            запись.update(SB.classify_sim(знач))
        except Exception as exc:  # noqa: BLE001
            запись["why_not"] = f"{type(exc).__name__}: {str(exc)[:160]}"
        запись["sim_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        try:
            журнал(запись)
        except Exception:  # noqa: BLE001
            pass

    try:
        threading.Thread(target=работа, name="lane-sim", daemon=True).start()
    except Exception:  # noqa: BLE001
        return False
    return True


# ------------------------------------------------------------------ отправка

# ОТПРАВЛЕННЫЕ КЛЮЧИ ОПЕРАЦИЙ. Одна операция -- одна отправка, и точка.
# Повторная сборка по тому же сигналу даёт ДРУГУЮ транзакцию с другой
# подписью, то есть вторую настоящую покупку. Защита здесь, у самой отправки,
# а не у вызывающего: вызывающих может стать больше.
_ОТПРАВЛЕНО: dict = {}
_ЗАМОК = threading.Lock()


def забыть_отправленные() -> None:
    """Только для самопроверки: очистить память отправленных ключей."""
    with _ЗАМОК:
        _ОТПРАВЛЕНО.clear()


def уже_отправляли(ключ: str) -> dict | None:
    with _ЗАМОК:
        з = _ОТПРАВЛЕНО.get(ключ)
    return dict(з) if з else None


def _запомнить_отказ(ключ: str | None, почему: str) -> None:
    """Неудачная отправка тоже занимает ключ операции.

    Повторять её вслепую нельзя: транзакция могла уйти в сеть и не дойти до
    нас ответом. Снимать замок вправе только человек, разобравшись.
    """
    if not ключ:
        return
    with _ЗАМОК:
        _ОТПРАВЛЕНО[ключ] = {"result": None, "why_not": почему}


def остановить_полосу(состояние, причина: str) -> dict:
    """Рубильник ТОЛЬКО полосы. Bloom и тень не трогаются вовсе.

    ПРАВИЛО ВЛАДЕЛЬЦА, уточнённое 25.09: рубильник -- только при РЕАЛЬНОЙ
    УТЕЧКЕ ДЕНЕГ, и утечка перечислена по именам:
      * сумма выше предела;
      * чужой получатель (адрес чаевых не из списка Sender);
      * неучтённый расход (потратили и не записали).
    Расхождение УЧЁТА ИТОГА на одной паре рубильником не является: такая пара
    помечается "итог несчитаем" (отметить_итог_несчитаемым), и полоса
    продолжает работать. Скорость -- слот, место, время -- считается по цепи
    и от учёта итога не зависит вовсе.

    Одна точка на модуль: иначе часть странностей останавливала бы полосу, а
    часть -- нет.
    """
    из_ = {"ok": False, "why": причина}
    if состояние is None or not hasattr(состояние, "set_lane_kill"):
        из_["error"] = "состояние не умеет останавливать полосу"
        return из_
    try:
        из_.update(состояние.set_lane_kill(причина))
    except Exception as exc:  # noqa: BLE001
        из_["error"] = f"{type(exc).__name__}: {str(exc)[:160]}"
    return из_


def путь_суток_полосы(состояние):
    """Файл суток полосы: баланс кошелька на 00:00 Мадрида."""
    try:
        return Path(состояние.base) / "lane_day.json"
    except Exception:  # noqa: BLE001
        return None


# ВЫВОДЫ ВЛАДЕЛЬЦА -- НЕ УБЫТОК ПОЛОСЫ (слово владельца 28.09 ночью, п.4).
# Владелец снимает свои деньги с кошелька полосы своим ключом. Для порога
# "просадка от 00:00" такой перевод выглядит потерей размером со вывод, и
# 28.09 он поставил бы рубильник на ровном месте. Поэтому выводы записываются
# отдельным списком и вычитаются из просадки: рубильник считает ТОРГОВЛЮ.
ФАЙЛ_ВЫВОДОВ = "lane_withdrawals.json"


def путь_выводов(состояние):
    к = путь_суток_полосы(состояние)
    return None if к is None else к.with_name(ФАЙЛ_ВЫВОДОВ)


# ВВОД ВЛАДЕЛЬЦА -- ТОЖЕ НЕ ТОРГОВЛЯ (слово владельца 01.10, 23:07 Мадрид).
# На кошелёк полосы внесено +1.4 SOL. Для просадки от 00:00 это выглядит
# ПРИБЫЛЬЮ размером со взнос -- то есть ослабляет рубильник ровно так же, как
# вывод его ложно ставил: фальшивый плюс способен закрыть собой настоящий
# убыток, и стоп не сработает. Поэтому ввод учитывается ТЕМ ЖЕ списком и ТОЙ ЖЕ
# формулой, что вывод, только с другим знаком: нетто = выведено − введено, и
# все потребители вычитают нетто, как вычитали выводы. Второго файла и второго
# написания правила здесь нет намеренно -- расходятся именно копии.
ВИД_ВЫВОД = "вывод"
ВИД_ВВОД = "ввод"


def выводы_владельца(состояние, *, с_ts: float | None = None) -> dict:
    """Движения владельца на кошельке полосы, записанные не раньше с_ts.

    `sol` -- НЕТТО, которое вычитают потребители: выведено МИНУС введено.
    Рядом стоят обе половины по отдельности (`выведено_sol`, `введено_sol`) --
    без них в отчёте нельзя отличить "владелец ничего не делал" от "вывел
    столько же, сколько внёс".

    Запись без поля `вид` считается ВЫВОДОМ: до 01.10 в этом списке других не
    было, и трактовать старую запись как ввод значило бы задним числом сдвинуть
    порог рубильника.
    """
    из_ = {"sol": 0.0, "выведено_sol": 0.0, "введено_sol": 0.0,
            "записей": 0, "выводов": 0, "вводов": 0,
            "why_not": None, "подписи": []}
    путь = путь_выводов(состояние)
    if путь is None:
        из_["why_not"] = "каталог состояния неизвестен"
        return из_
    try:
        если_есть = json.loads(путь.read_text(encoding="utf-8")) if путь.exists() else []
    except (OSError, ValueError) as exc:
        из_["why_not"] = f"{type(exc).__name__}"
        return из_
    for з in (если_есть or []):
        try:
            когда = float(з.get("ts"))
            сколько = abs(float(з.get("sol")))
        except (TypeError, ValueError):
            continue
        if с_ts is not None and когда < float(с_ts):
            continue
        ввод = (str((з or {}).get("вид") or ВИД_ВЫВОД) == ВИД_ВВОД)
        if ввод:
            из_["введено_sol"] = round(из_["введено_sol"] + сколько, 9)
            из_["вводов"] += 1
        else:
            из_["выведено_sol"] = round(из_["выведено_sol"] + сколько, 9)
            из_["выводов"] += 1
        из_["записей"] += 1
        if з.get("signature"):
            из_["подписи"].append(з["signature"])
    из_["sol"] = round(из_["выведено_sol"] - из_["введено_sol"], 9)
    return из_


def записать_вывод(состояние, *, подпись: str, sol: float,
                    когда: float | None = None, примечание: str = "",
                    вид: str = ВИД_ВЫВОД) -> dict:
    """Добавить движение владельца в список. Повтор той же подписи не задваивает.

    `sol` ВСЕГДА положителен -- сколько денег двигалось; направление задаёт
    `вид` (`вывод` или `ввод`). Знак в сумме был бы вторым способом сказать то
    же самое, а два способа однажды разойдутся.
    """
    из_ = {"ok": False, "why_not": None}
    if str(вид) not in (ВИД_ВЫВОД, ВИД_ВВОД):
        из_["why_not"] = f"вид движения неизвестен: {вид!r}"
        return из_
    путь = путь_выводов(состояние)
    if путь is None:
        из_["why_not"] = "каталог состояния неизвестен"
        return из_
    if not подпись or not isinstance(sol, (int, float)) or float(sol) <= 0:
        из_["why_not"] = "нужна подпись и положительная сумма вывода"
        return из_
    try:
        было = json.loads(путь.read_text(encoding="utf-8")) if путь.exists() else []
    except (OSError, ValueError):
        было = []
    было = было if isinstance(было, list) else []
    if any((з or {}).get("signature") == подпись for з in было):
        из_.update(ok=True, повтор=True, why_not="эта подпись уже записана")
        return из_
    было.append({"signature": подпись, "sol": round(abs(float(sol)), 9),
                  "ts": float(когда if когда is not None else time.time()),
                  "вид": str(вид), "note": str(примечание)[:200]})
    try:
        врем = путь.with_name(путь.name + ".tmp")
        врем.write_text(json.dumps(было, ensure_ascii=False, indent=1),
                         encoding="utf-8")
        os.replace(врем, путь)
    except OSError as exc:
        из_["why_not"] = f"не записалось: {type(exc).__name__}"
        return из_
    из_.update(ok=True, записей=len(было), sol=round(abs(float(sol)), 9),
                вид=str(вид))
    return из_


def записать_ввод(состояние, *, подпись: str, sol: float,
                   когда: float | None = None, примечание: str = "") -> dict:
    """Пополнение кошелька полосы владельцем. Та же писалка, другой вид."""
    return записать_вывод(состояние, подпись=подпись, sol=sol, когда=когда,
                           примечание=(примечание or "ввод владельца"),
                           вид=ВИД_ВВОД)


def порог_kill_по_балансу(состояние, *, баланс_sol, сейчас: float | None = None,
                           порог: float | None = None) -> dict:
    """Баланс упал от баланса на 00:00 больше чем на порог -- рубильник полосы.

    ЗАЧЕМ ОТДЕЛЬНО ОТ УЧЁТА ПО ПОЗИЦИЯМ (слово владельца 27.09, п.1е:
    "KILL-порог: баланс кошелька полосы <= баланс на 00:00 - 0.5 SOL -> KILL").
    Учёт видит только то, что сам записал: покупку, продажу, чаевые. Баланс
    видит ВСЁ, в том числе то, чего в учёте нет вовсе -- чужую трату, ошибку в
    сборке, утёкшую ренту. Поэтому порог стоит по балансу, а не по учёту.

    Баланс неизвестен -- НИЧЕГО не делаем и говорим об этом: ставить рубильник
    по неизвестному числу нельзя, снимать порог из-за него -- тоже.
    """
    порог = float(порог if порог is not None else ПОРОГ_KILL_ПО_БАЛАНСУ_SOL)
    из_ = {"ok": False, "kill": False, "why": None, "threshold_sol": порог}
    if not isinstance(баланс_sol, (int, float)):
        из_["why"] = "баланс полосы неизвестен -- рубильник не проверить"
        return из_
    путь = путь_суток_полосы(состояние)
    if путь is None:
        из_["why"] = "каталог состояния неизвестен -- сутки полосы не записать"
        return из_
    сут = начало_суток(сейчас)
    из_["day"] = сут["day"]
    было = {}
    try:
        if путь.exists():
            было = json.loads(путь.read_text(encoding="utf-8")) or {}
    except (OSError, ValueError):
        было = {}
    if было.get("day") != сут["day"] or not isinstance(было.get("open_sol"),
                                                        (int, float)):
        # НОВЫЕ СУТКИ: баланс на 00:00 -- это первый баланс, увиденный в этих
        # сутках. Точнее не бывает: в саму полночь нас никто не спрашивает.
        запись = {"day": сут["day"], "open_sol": round(float(баланс_sol), 9),
                   "open_ts": float(сейчас if сейчас is not None else time.time()),
                   "day_how": сут["how"]}
        try:
            врем = путь.with_name(путь.name + ".tmp")
            врем.write_text(json.dumps(запись, ensure_ascii=False),
                             encoding="utf-8")
            os.replace(врем, путь)
        except OSError as exc:
            из_["why"] = f"сутки полосы не записаны: {type(exc).__name__}"
            return из_
        из_.update(ok=True, opened=True, open_sol=запись["open_sol"],
                    why=(f"баланс на начало суток {сут['day']}: "
                          f"{запись['open_sol']} SOL"))
        return из_
    открытие = float(было["open_sol"])
    # ВЫВОД ВЛАДЕЛЬЦА ИЗ ПРОСАДКИ ВЫЧИТАЕТСЯ. Порог про торговлю, а не про то,
    # что владелец снял свои деньги: без этого вывод 1.84 SOL поставил бы
    # рубильник сам по себе.
    выв = выводы_владельца(состояние, с_ts=было.get("open_ts"))
    # НЕТТО ВЛАДЕЛЬЦА: выведено минус введено. Вывод просадку уменьшает (его
    # вычли), ввод -- увеличивает обратно: без этого взнос 1.4 SOL подарил бы
    # рубильнику 1.4 SOL запаса и спрятал бы настоящий убыток такого размера.
    просадка = открытие - float(баланс_sol) - float(выв.get("sol") or 0.0)
    из_.update(ok=True, open_sol=открытие, balance_sol=round(float(баланс_sol), 9),
                drop_sol=round(просадка, 9),
                withdrawals_sol=round(float(выв.get("выведено_sol") or 0.0), 9),
                deposits_sol=round(float(выв.get("введено_sol") or 0.0), 9),
                net_owner_sol=round(float(выв.get("sol") or 0.0), 9),
                withdrawals_n=выв.get("выводов"),
                deposits_n=выв.get("вводов"))
    if просадка >= порог:
        из_["kill"] = True
        причина = (f"баланс полосы {round(float(баланс_sol), 6)} SOL ниже баланса "
                    f"на 00:00 ({round(открытие, 6)}) на {round(просадка, 6)} SOL "
                    f"при рубильнике {порог}"
                    + (f" (выводы владельца {из_['withdrawals_sol']} SOL уже "
                       "вычтены)" if из_.get("withdrawals_sol") else "")
                    + (f" (ввод владельца {из_['deposits_sol']} SOL в просадку "
                       "НЕ зачтён)" if из_.get("deposits_sol") else ""))
        из_["kill_set"] = остановить_полосу(состояние, причина)
        из_["why"] = причина
        return из_
    из_["why"] = (f"просадка от 00:00 {round(просадка, 6)} SOL при рубильнике "
                   f"{порог}")
    return из_


# ---------------------------------------------------------------------------
# СУТОЧНЫЙ СТОП ПОЛОСЫ СЧИТАЕТСЯ ПО ЦЕПИ (слово владельца 29.09)
#
# ПОЧЕМУ НЕ ПО УЧЁТУ. Учёт видит только то, что записал сам, и 29.09 это стоило
# суток работы: он показал -2.189326375 SOL при пороге -1.5 и закрыл ВСЕ
# группы, тогда как кошелёк полосы по цепи за те же сутки потерял 0.800006050.
# Разница набралась из трёх мест, и ни одно из них не убыток полосы:
#   * обёртка 0.3 SOL в WSOL записана расходом, а развёрнутый возврат учтён
#     отдельным приходом -- 0.6 SOL задвоено (чинится своей правкой);
#   * пять позиций продал владелец своим ключом через Jupiter -- 0.718634188
#     SOL вернулось на кошелёк, а учёт этих продаж не видит вовсе;
#   * возврат ренты закрытых пустых счетов 0.007180657 SOL.
#
# ЧТО ИМЕННО СЧИТАЕТСЯ ПО ЦЕПИ. То же число, которое уже считает KILL-порог по
# балансу: баланс кошелька полосы на начало суток Мадрида МИНУС баланс сейчас
# МИНУС выводы владельца. Оно приходит с цепи целиком (getBalance), а не из
# наших записей, и поэтому видит и чужую трату, и утёкшую ренту, и продажу
# чужим ключом. Второго написания того же числа здесь нет намеренно: два
# написания одного числа когда-нибудь разойдутся.
#
# НЕЗНАНИЕ = ЗАМОК (слово владельца 29.09). Баланс неизвестен, старше
# ПРЕДЕЛ_ВОЗРАСТА_ЦЕПИ_S, сутки в файле не те, баланс на начало суток не
# записан или файл не прочитан -- стоп считается СТОЯЩИМ, а не снятым.
#
# ЧЕГО ЭТО ЧИСЛО НЕ УМЕЕТ. Оно не делится по группам: кошелёк один. Групповые
# стопы (stop_loss_sol) остаются на учёте -- это отдельные пределы, и владелец
# про них не говорил. И оно КОНСЕРВАТИВНО: открытая позиция (заплатили, токен
# держим) и не развёрнутая обёртка выглядят просадкой кошелька, пока не
# проданы. То есть ошибиться оно может только в сторону раннего замка.
ФАЙЛ_СЧЁТА_ПО_ЦЕПИ = "lane_chain_day.json"
# Стоп по цепи включён по умолчанию: это и есть правка 29.09. Флаг оставлен,
# чтобы правку можно было снять одним значением env, не деплоем.
СТОП_ПО_ЦЕПИ = (os.environ.get("LANE_STOP_CHAIN", "1").strip() != "0")
# Старше этого -- цепь считается непрочитанной (слово владельца: 5 минут).
ПРЕДЕЛ_ВОЗРАСТА_ЦЕПИ_S = ST.env_float("LANE_CHAIN_MAX_AGE_S", 300.0)
# Расхождение цепи и учёта, о котором говорим владельцу строкой.
РАСХОЖДЕНИЕ_ЦЕПЬ_УЧЁТ_SOL = ST.env_float("LANE_CHAIN_VS_LEDGER_SOL", 0.05)


def путь_счёта_по_цепи(состояние=None):
    """Файл счёта по цепи. Без состояния -- по каталогу состояния из env."""
    try:
        if состояние is not None:
            return Path(состояние.base) / ФАЙЛ_СЧЁТА_ПО_ЦЕПИ
        return Path(ST.state_dir()) / ФАЙЛ_СЧЁТА_ПО_ЦЕПИ
    except Exception:  # noqa: BLE001
        return None


def открытые_по_входу(позиции: dict, *, сейчас: float | None = None) -> dict:
    """Сколько SOL СЕЙЧАС лежит в открытых позициях полосы, по цене входа.

    ЗАЧЕМ. Счёт по цепи -- это просадка баланса кошелька: открытая позиция
    выглядит в нём чистым убытком размером со вход, потому что SOL из кошелька
    ушёл, а токен ещё не продан. Учёт же открытую позицию убытком не считает
    (у неё итог ещё неизвестен, в счёт идёт только расход на отправку). Отсюда
    расхождение РОВНО В РАЗМЕР ОТКРЫТЫХ: 30.09 это дало ложную тревогу на 0.3
    SOL при одной открытой позиции на 0.3. Теперь открытые считаются по цене
    входа В ОБОИХ, и для этого нужна одна величина -- эта.

    ЧТО СЧИТАЕТСЯ ВХОДОМ. Сначала НАТИВНАЯ ДЕЛЬТА самой покупки
    (`lane_buy_native_sol`, отрицательна и включает вход, чаевые и плату за
    счета) -- это ровно то, что цепь и увидела. Её нет -- берётся `sol_in`,
    цена входа по полям. Нет ни того ни другого (покупка только что ушла и
    цепь ещё не прочитана) -- позиция считается ОТДЕЛЬНО, в
    `открытых_без_числа`, и в сумму не идёт: выдуманный ноль здесь означал бы
    "в позиции ничего не лежит", то есть снова ложное расхождение.
    """
    сейчас = time.time() if сейчас is None else float(сейчас)
    из_ = {"открытых": 0, "сумма_sol": 0.0, "открытых_без_числа": 0,
            "по_натив": 0, "по_полям": 0}
    for p_ in (позиции or {}).values():
        p_ = p_ or {}
        if p_.get("lane") != МЕТКА:
            continue
        # СПИСАННАЯ -- НЕ КАПИТАЛ В ОТКРЫТОЙ ПОЗИЦИИ. Её вход уже вычтен
        # как полный убыток (closed_sol_net=0.0), и держать его ещё и здесь
        # значило бы вычесть одни деньги дважды: сверка кошелька разошлась бы
        # ровно на вход списанной позиции.
        if p_.get("state") in (ST.STATE_CLOSED, "unsold", "closed",
                                ST.STATE_SPISANA):
            continue
        # ЗАВИСШАЯ СЧИТАЕТСЯ НАРАВНЕ С ОТКРЫТОЙ. Её дожимает сторож, но деньги
        # из кошелька уже ушли и в токене лежат -- для счёта важно это, а не то,
        # ждёт ли она продажи или сторожа. (В `состояние_полосы` зависшие
        # исключены из `open` нарочно: там предел "одна открытая" про право
        # покупать, а тут -- про деньги.)
        из_["открытых"] += 1
        натив = p_.get("lane_buy_native_sol")
        вход = p_.get("sol_in")
        if isinstance(натив, (int, float)) and натив:
            из_["сумма_sol"] += abs(float(натив))
            из_["по_натив"] += 1
        elif isinstance(вход, (int, float)) and вход:
            из_["сумма_sol"] += abs(float(вход))
            из_["по_полям"] += 1
        else:
            из_["открытых_без_числа"] += 1
    из_["сумма_sol"] = round(из_["сумма_sol"], 9)
    return из_


def суточный_счёт_по_цепи(состояние, *, баланс_sol, баланс_ts=None,
                           позиции: dict | None = None,
                           сейчас: float | None = None,
                           макс_возраст_с: float | None = None) -> dict:
    """Итог полосы за сутки ПО ЦЕПИ. Читает, но НИЧЕГО не пишет.

    Отдельно от порога_kill_по_балансу именно потому, что тот ПИШЕТ файл суток
    и может поставить рубильник. Гейт не имеет права ни на то, ни на другое:
    он только спрашивает.

    итог_sol отрицателен при убытке -- той же стороной, что и порог.
    """
    сейчас = time.time() if сейчас is None else float(сейчас)
    предел = float(макс_возраст_с if макс_возраст_с is not None
                    else ПРЕДЕЛ_ВОЗРАСТА_ЦЕПИ_S)
    сут = начало_суток(сейчас)
    возраст = (round(сейчас - float(баланс_ts), 1)
                if isinstance(баланс_ts, (int, float)) and баланс_ts else None)
    из_ = {"годен": False, "почему_нет": None, "итог_sol": None,
            "день": сут["day"], "начало_суток_ts": сут["ts"],
            "как_считаются_сутки": сут["how"],
            "баланс_sol": (round(float(баланс_sol), 9)
                            if isinstance(баланс_sol, (int, float)) else None),
            "возраст_баланса_с": возраст, "предел_возраста_с": предел,
            "открытие_sol": None, "выводы_sol": None, "выводов": None,
            "вводы_sol": None, "вводов": None, "нетто_владельца_sol": None,
            "кошелёк": кошелёк_полосы()}
    if not isinstance(баланс_sol, (int, float)):
        из_["почему_нет"] = "баланс кошелька полосы неизвестен"
        return из_
    if возраст is None:
        из_["почему_нет"] = "время баланса неизвестно"
        return из_
    if возраст > предел:
        из_["почему_нет"] = (f"баланс полосы старше {предел:.0f} с "
                              f"(возраст {возраст} с)")
        return из_
    путь = путь_суток_полосы(состояние)
    if путь is None:
        из_["почему_нет"] = "каталог состояния неизвестен"
        return из_
    try:
        было = json.loads(путь.read_text(encoding="utf-8")) if путь.exists() else {}
    except (OSError, ValueError) as exc:
        из_["почему_нет"] = f"файл суток полосы не прочитан ({type(exc).__name__})"
        return из_
    было = было if isinstance(было, dict) else {}
    if not было:
        # ОТДЕЛЬНАЯ ПРИЧИНА ДЛЯ ПУСТОГО ФАЙЛА. Иначе она выглядела бы как
        # "в файле день None", и владелец читал бы про чужие сутки вместо
        # "баланс на начало суток ещё не записан".
        из_["почему_нет"] = "баланс на начало суток не записан (файла суток нет)"
        return из_
    if было.get("day") != сут["day"]:
        из_["почему_нет"] = (f"в файле суток день {было.get('day')!r}, "
                              f"а идут сутки {сут['day']}")
        return из_
    if not isinstance(было.get("open_sol"), (int, float)):
        из_["почему_нет"] = "баланс на начало суток не записан"
        return из_
    выв = выводы_владельца(состояние, с_ts=было.get("open_ts"))
    if выв.get("why_not"):
        из_["почему_нет"] = f"выводы владельца не прочитаны: {выв['why_not']}"
        return из_
    открытие = float(было["open_sol"])
    просадка = открытие - float(баланс_sol) - float(выв.get("sol") or 0.0)
    # ОТКРЫТЫЕ -- ПО ЦЕНЕ ВХОДА, И ЭТО ОТДЕЛЬНОЕ ЧИСЛО (слово владельца 30.09
    # вечером). `итог_sol` остаётся сырой просадкой кошелька -- его смысл менять
    # нельзя, на него смотрит порог KILL по балансу. Гейт стопа и тревога
    # смотрят на `итог_с_открытыми_sol`: в нём деньги, лежащие в ещё не проданных
    # токенах, не считаются убытком.
    if позиции is None:
        try:
            позиции = состояние.positions()
        except Exception:  # noqa: BLE001
            позиции = None
    отк = (открытые_по_входу(позиции, сейчас=сейчас)
            if позиции is not None else None)
    из_.update(годен=True, открытие_sol=round(открытие, 9),
                выводы_sol=round(float(выв.get("выведено_sol") or 0.0), 9),
                вводы_sol=round(float(выв.get("введено_sol") or 0.0), 9),
                нетто_владельца_sol=round(float(выв.get("sol") or 0.0), 9),
                выводов=выв.get("выводов"), вводов=выв.get("вводов"),
                итог_sol=round(-просадка, 9))
    if отк is None:
        из_["открытых_why_not"] = "позиции не прочитаны -- открытые не посчитаны"
        return из_
    из_.update(открытых=отк["открытых"],
                открытых_по_входу_sol=отк["сумма_sol"],
                открытых_без_числа=отк["открытых_без_числа"],
                итог_с_открытыми_sol=round(-просадка + отк["сумма_sol"], 9))
    return из_


def записать_счёт_по_цепи(состояние, счёт: dict,
                            *, когда: float | None = None) -> dict:
    """Счёт по цепи -- в файл целиком или никак. Пишет ТОЛЬКО детектор.

    Гейт может жить в другом процессе (сторож, разбор владельца), поэтому
    число кладётся на диск, а не в память: иначе у второго процесса его нет,
    и он торговал бы по учёту, пока первый считает по цепи.
    """
    из_ = {"ok": False, "why_not": None}
    путь = путь_счёта_по_цепи(состояние)
    if путь is None:
        из_["why_not"] = "каталог состояния неизвестен"
        return из_
    тело = dict(счёт or {})
    # ВРЕМЯ ЗАПИСИ -- ПАРАМЕТРОМ. Служба его не передаёт (берутся часы), а
    # самопроверка передаёт: иначе "файл пролежал дольше предела" проверить
    # нечем -- настоящие часы всегда свежее любого поддельного "сейчас".
    тело["записано_ts"] = float(когда if когда is not None else time.time())
    тело["записано_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ",
                                          time.gmtime(тело["записано_ts"]))
    try:
        ST.atomic_write_json(Path(путь), тело)
    except OSError as exc:
        из_["why_not"] = f"не записалось: {type(exc).__name__}"
        return из_
    из_.update(ok=True, путь=str(путь))
    return из_


_КЭШ_СЧЁТА_ПО_ЦЕПИ: dict = {}


def прочитать_счёт_по_цепи(состояние=None, *, сейчас: float | None = None,
                            макс_возраст_с: float | None = None) -> dict:
    """Счёт по цепи из файла -- для гейта. Кэш по mtime: путь горячий.

    ВОЗРАСТ СЧИТАЕТСЯ ДВУМЯ СЛАГАЕМЫМИ: сколько лежит файл плюс каким был
    возраст баланса в момент записи. Иначе мёртвый писатель выглядел бы
    свежим числом, а именно это и надо ловить.
    """
    сейчас = time.time() if сейчас is None else float(сейчас)
    предел = float(макс_возраст_с if макс_возраст_с is not None
                    else ПРЕДЕЛ_ВОЗРАСТА_ЦЕПИ_S)
    сут = начало_суток(сейчас)
    из_ = {"годен": False, "почему_нет": None, "итог_sol": None,
            "день": сут["day"], "предел_возраста_с": предел,
            "возраст_числа_с": None}
    путь = путь_счёта_по_цепи(состояние)
    if путь is None:
        из_["почему_нет"] = "каталог состояния неизвестен"
        return из_
    try:
        ст = os.stat(путь)
    except OSError:
        из_["почему_нет"] = "файла счёта по цепи нет -- его никто не писал"
        return из_
    ключ = (str(путь), ст.st_mtime_ns, ст.st_size)
    тело = None
    if _КЭШ_СЧЁТА_ПО_ЦЕПИ.get("ключ") == ключ:
        тело = _КЭШ_СЧЁТА_ПО_ЦЕПИ.get("тело")
    if тело is None:
        try:
            тело = json.loads(Path(путь).read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            из_["почему_нет"] = f"файл счёта по цепи не прочитан ({type(exc).__name__})"
            return из_
        if not isinstance(тело, dict):
            из_["почему_нет"] = "файл счёта по цепи не словарь"
            return из_
        _КЭШ_СЧЁТА_ПО_ЦЕПИ.clear()
        _КЭШ_СЧЁТА_ПО_ЦЕПИ.update(ключ=ключ, тело=тело)
    из_["кошелёк"] = тело.get("кошелёк")
    из_["открытие_sol"] = тело.get("открытие_sol")
    из_["баланс_sol"] = тело.get("баланс_sol")
    из_["выводы_sol"] = тело.get("выводы_sol")
    # ВВОД ПЕРЕНОСИТСЯ НАСКВОЗЬ: по докладу должно быть видно, что число цепи
    # учло взнос владельца, а не приняло его за прибыль полосы.
    из_["вводы_sol"] = тело.get("вводы_sol")
    из_["нетто_владельца_sol"] = тело.get("нетто_владельца_sol")
    из_["вводов"] = тело.get("вводов")
    # ОТКРЫТЫЕ ПО ЦЕНЕ ВХОДА -- НАСКВОЗЬ ИЗ ФАЙЛА. Гейт смотрит именно на
    # `итог_с_открытыми_sol`; его отсутствие -- не повод молча взять сырую
    # просадку, поэтому поля переносятся как есть, а решает ниже сам гейт.
    for имя_поля in ("открытых", "открытых_по_входу_sol", "открытых_без_числа",
                      "итог_с_открытыми_sol", "открытых_why_not"):
        if имя_поля in тело:
            из_[имя_поля] = тело.get(имя_поля)
    if тело.get("годен") is not True:
        из_["почему_нет"] = ("в файле счёт негоден: "
                              + str(тело.get("почему_нет") or "причина не названа"))
        return из_
    if тело.get("день") != сут["day"]:
        из_["почему_нет"] = (f"в файле счёт за сутки {тело.get('день')!r}, "
                              f"а идут сутки {сут['day']}")
        return из_
    записано = тело.get("записано_ts")
    if not isinstance(записано, (int, float)):
        из_["почему_нет"] = "в файле нет времени записи"
        return из_
    возраст_баланса = тело.get("возраст_баланса_с")
    возраст = (сейчас - float(записано)) + float(
        возраст_баланса if isinstance(возраст_баланса, (int, float)) else 0.0)
    из_["возраст_числа_с"] = round(возраст, 1)
    if возраст > предел:
        из_["почему_нет"] = (f"счёт по цепи старше {предел:.0f} с "
                              f"(возраст {round(возраст, 1)} с)")
        return из_
    итог = тело.get("итог_sol")
    if not isinstance(итог, (int, float)):
        из_["почему_нет"] = "в файле нет числа итога"
        return из_
    из_.update(годен=True, итог_sol=round(float(итог), 9))
    return из_


def отметить_итог_несчитаемым(состояние, cid: str, причина: str) -> dict:
    """Пара, у которой ИТОГ не сходится, помечается и живёт дальше.

    Уточнение владельца 25.09: расхождение учёта на одной паре -- это не
    рубильник. Пара помечается "итог несчитаем", её итог не идёт ни в PnL, ни
    в серию упавших, а полоса продолжает работать. Замер скорости у такой
    пары остаётся годным: слот, место и время считаются по цепи и об учёте
    итога ничего не знают.

    Пометка нужна именно явная. Молча забытая пара в отчёте выглядит как
    сделка с нулевым итогом, то есть как удачная.
    """
    из_ = {"ok": False, "cid": cid, "why": причина}
    if состояние is None or not cid:
        из_["error"] = "нечего помечать: нет состояния или ключа позиции"
        return из_
    try:
        состояние.update_position(cid, result_uncountable=True,
                                   result_uncountable_why=str(причина)[:300],
                                   result_uncountable_ts=time.time())
        из_["ok"] = True
    except Exception as exc:  # noqa: BLE001
        из_["error"] = f"{type(exc).__name__}: {str(exc)[:160]}"
    return из_


def кэш_чтений(rpc_call, *, кэшируемые=("getMultipleAccounts", "getAccountInfo",
                                        "getTokenAccountBalance")):
    """Обёртка над rpc_call: один и тот же запрос в пределах ОДНОЙ покупки
    уходит в сеть РОВНО раз.

    ЗАЧЕМ. Варианты на nonce собираются по одному на сервис, и сборка зовётся
    внутри цикла -- шесть раз. У сборщиков, которые читают состояние пула
    (Meteora DLMM, Whirlpool), это шесть одинаковых getMultipleAccounts вместо
    одного. Измерено по записям за 01.10: у DLMM сборка 62.4 мс медиана, а
    варианты 356.7 -- то есть ~59 мс на вариант, ровно стоимость сборки; у
    Whirlpool 49.6 и 255.2. На сборщиках без чтений (Pump AMM, pump bonding,
    CPMM, DBC) вариант стоит ~1 мс, и там кэшу нечего делать.

    ЭТО НЕ ТОЛЬКО СКОРОСТЬ, ЭТО СОГЛАСОВАННОСТЬ. Шесть вариантов -- это шесть
    транзакций ОДНОГО сигнала, и цениться они должны одинаково. Пока каждый
    читал пул заново, у них мог выйти разный минимум выхода: сядет один, но
    какой именно -- решает цепь, то есть цена сделки зависела от того, какому
    варианту повезло. Один снимок состояния на все варианты это убирает.

    ЖИЗНЬ КЭША -- ОДНА ПОКУПКА. Обёртка создаётся на каждый сигнал заново и
    умирает с ним: кэш между сигналами означал бы сборку по устаревшему пулу,
    а это деньги. Кэшируются только ЧТЕНИЯ из списка; sendTransaction и всё
    прочее проходят насквозь, даже если кто-то однажды впишет их в список.
    """
    import json as _js  # noqa: PLC0415

    хранилище: dict = {}

    def можно_кэшировать(метод) -> bool:
        """Кэшируется только ЧТЕНИЕ, и правило -- по ВИДУ имени, а не по списку
        запретов. У Solana RPC читающие методы начинаются с get, а всё, что
        меняет состояние (отправка, симуляция, airdrop), -- нет. Так список
        кэшируемых нельзя однажды пополнить денежным методом по
        невнимательности: имя без get не пройдёт, даже если его туда впишут.
        """
        return str(метод).startswith("get") and метод in кэшируемые

    def зов(метод, параметры, **кв):
        if not можно_кэшировать(метод):
            зов.в_сеть += 1
            return rpc_call(метод, параметры, **кв)
        try:
            ключ = (метод, _js.dumps(параметры, sort_keys=True, default=str))
        except (TypeError, ValueError):
            зов.в_сеть += 1
            return rpc_call(метод, параметры, **кв)
        зов.запросов += 1
        if ключ in хранилище:
            зов.из_кэша += 1
            return хранилище[ключ]
        о = rpc_call(метод, параметры, **кв)
        зов.в_сеть += 1
        # ОТКАЗ НЕ КЭШИРУЕТСЯ: повторить неудачное чтение -- это шанс собрать
        # вариант, а запомнить отказ значит провалить все шесть на одном сбое.
        if isinstance(о, dict) and о.get("ok") is False:
            return о
        хранилище[ключ] = о
        return о

    зов.запросов = 0
    зов.из_кэша = 0
    зов.в_сеть = 0
    return зов


def собрать_варианты_нонсом(*, сборщик, сервисы: list, нонс: dict,
                             семя: str | None = None,
                             секрет: str | None = None,
                             подписать_фн=None) -> dict:
    """По одной ПОДПИСАННОЙ транзакции на сервис: только его чаевые, один nonce.

    сборщик(чаевые_списком, нонс) -> результат собрать(): сборка остаётся в
    вызывающем, здесь только раздача чаевых по одному и подпись.

    Все транзакции РАЗНЫЕ (разные чаевые -- разные байты и разные подписи), и
    это НЕ странность, а суть варианта: замок здесь не подпись, а nonce. Купить
    дважды нельзя, потому что первая исполнившаяся транзакция его сдвигает.
    """
    из_ = {"ok": False, "why_not": None, "rows": [], "candidates": [],
            "tips_total_lamports": 0}
    if not нонс.get("ok"):
        из_["why_not"] = нонс.get("why_not") or "nonce не прочитан"
        return из_
    try:
        import bloom_senders as SS  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"реестр отправителей не загружен: {type(exc).__name__}"
        return из_
    пара_нонса = (нонс["account"], нонс["authority"])
    подписать_ = подписать_фн or подписать
    всего_чаевых = 0
    потолок_ч = int(round(ПОТОЛОК_ЧАЕВЫХ_ПУЛА_SOL * ЛАМПОРТОВ_В_SOL))
    for имя in сервисы:
        строка = {"sender": имя, "ok": False, "why_not": None,
                   "signature": None, "size": None, "tip_lamports": None}
        адрес = SS.счёт_чаевых(имя, семя=семя)
        разрешённые = set(((SS.реестр() or {}).get(имя) or {}).get("tip_accounts")
                           or [])
        лам = SS.минимум_чаевых(имя)
        if not адрес or адрес not in разрешённые:
            строка["why_not"] = f"адрес чаевых не из списка сервиса {имя}"
            из_["rows"].append(строка)
            continue
        # ПОТОЛОК СЧИТАЕТСЯ ПО ВСЕМ ВАРИАНТАМ ВМЕСТЕ, хотя заплатит только
        # один: пока цепь не решила, потратить мы можем любой из них, и
        # считать надо худший случай.
        if всего_чаевых + int(лам) > потолок_ч:
            строка["why_not"] = (f"чаевые всех вариантов вышли бы за потолок "
                                  f"{потолок_ч} лампортов")
            из_["rows"].append(строка)
            continue
        # ЧАЕВЫЕ ВПЕРЁД, если сервис этого требует (0slot: "инструкцию чаевых
        # ставить в начало транзакции"). В варианте на nonce это возможно
        # честно: у каждого сервиса своя транзакция.
        вперёд = bool(((SS.реестр() or {}).get(имя) or {}).get("tip_first"))
        сб = сборщик([(адрес, int(лам))], пара_нонса, вперёд)
        if not сб.get("ok"):
            строка["why_not"] = сб.get("why_not") or "вариант не собрался"
            строка["size"] = сб.get("size")
            из_["rows"].append(строка)
            continue
        пд = подписать_(сб["tx_base64"], blockhash=нонс["blockhash"],
                        ожидаемый_кошелёк=кошелёк_полосы(), секрет=секрет)
        if not пд.get("ok"):
            строка["why_not"] = пд.get("why_not") or "вариант не подписан"
            из_["rows"].append(строка)
            continue
        всего_чаевых += int(лам)
        строка.update(ok=True, signature=пд.get("signature"), size=сб.get("size"),
                      tip_lamports=int(лам), tip_account=адрес,
                      tx_base64=пд.get("tx_base64"), min_out=сб.get("min_out"),
                      nonce_account=сб.get("nonce_account"))
        из_["rows"].append(строка)
        из_["candidates"].append(пд.get("signature"))
    готовые = [с for с in из_["rows"] if с.get("ok")]
    из_["tips_total_lamports"] = всего_чаевых
    if not готовые:
        из_["why_not"] = ("ни один вариант не собрался: "
                           + "; ".join(f"{с['sender']}: {с['why_not']}"
                                        for с in из_["rows"])[:300])
        return из_
    # ОДИН NONCE НА ВСЕ ВАРИАНТЫ -- это и есть замок. Вариант, собранный с
    # другим nonce (или вовсе без него), может исполниться ВТОРЫМ, то есть
    # купить дважды на одном сигнале. Это деньги, поэтому здесь не
    # предупреждение, а отказ всей отправки.
    нонсы = {с.get("nonce_account") for с in готовые}
    if нонсы != {нонс["account"]}:
        из_["ok"] = False
        из_["why_not"] = (f"варианты собраны с разными nonce {sorted(str(н) for н in нонсы)} "
                           f"вместо одного {нонс['account'][:12]} -- отправка отменена: "
                           "так можно купить дважды")
        из_["nonce_same"] = False
        return из_
    из_.update(ok=True, nonce_account=нонс["account"],
               blockhash=нонс["blockhash"], n_variants=len(готовые),
               nonce_same=True)
    return из_


def _отправить_вариантами(варианты: dict, *, из_: dict, ключ_операции: str | None,
                           отправитель=None, таймаут: float = 5.0,
                           состояние=None, региональные: dict | None = None) -> dict:
    """Каждому сервису -- СВОЙ подписанный вариант, все сразу.

    Победителя здесь НЕ объявляем по ответу: ответ сервиса значит "принял", а
    села ли транзакция -- решает цепь, и с разными подписями это видно только по
    ней. Поэтому в позицию уходят ВСЕ подписи-кандидаты, а детектор узнает ту,
    что села, в потоке нашего кошелька.
    """
    try:
        import bloom_senders as SS  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"реестр отправителей не загружен: {type(exc).__name__}"
        _запомнить_отказ(ключ_операции, из_["why_not"])
        return из_
    import threading as _th  # noqa: PLC0415

    готовые = [с for с in варианты.get("rows") or [] if с.get("ok")]
    ответы: dict = {}
    t0 = time.perf_counter()

    адреса_рег = (региональные or {}).get("адреса") or {}

    def один(строка):
        try:
            ответы[строка["sender"]] = SS.отправить_через(
                строка["sender"], строка["tx_base64"], отправитель=отправитель,
                таймаут=таймаут,
                url_переопределение=адреса_рег.get(строка["sender"]))
        except Exception as exc:  # noqa: BLE001
            ответы[строка["sender"]] = {"sender": строка["sender"], "ok": False,
                                         "why_not": f"{type(exc).__name__}"}

    нити = [_th.Thread(target=один, args=(с,), daemon=True) for с in готовые]
    for н in нити:
        н.start()
    for н in нити:
        н.join(timeout=таймаут + 1.0)
    из_["send_ms"] = round((time.perf_counter() - t0) * 1000, 2)
    строки = []
    for с in готовые:
        от = ответы.get(с["sender"]) or {"ok": False, "why_not": "не ответил"}
        строки.append({"sender": с["sender"], "signature": с.get("signature"),
                        "tip_lamports": с.get("tip_lamports"),
                        "size": с.get("size"), "ok": bool(от.get("ok")),
                        "http": от.get("http"), "send_ms": от.get("send_ms"),
                        "why_not": от.get("why_not")})
    приняли = [с for с in строки if с["ok"]]
    из_["pool"] = {"mode": "nonce", "nonce_account": варианты.get("nonce_account"),
                    # КУДА УШЛО: регион лидера, его ключ и точки по сервисам.
                    "region": ({"регион": (региональные or {}).get("регион"),
                                 "лидер": (региональные or {}).get("лидер"),
                                 "точек": len(адреса_рег),
                                 "why_not": (региональные or {}).get("why_not")}
                                if региональные else None),
                    "senders": [с["sender"] for с in строки],
                    "ok_senders": [с["sender"] for с in приняли],
                    "candidates": [с["signature"] for с in строки if с["signature"]],
                    "tips_total_lamports": варианты.get("tips_total_lamports"),
                    "rows": строки}
    if not приняли:
        причины = "; ".join(f"{с['sender']}: {с['why_not']}" for с in строки)
        из_["why_not"] = f"вариантами не довезли: {причины}"[:400]
        _запомнить_отказ(ключ_операции, из_["why_not"])
        return из_
    # ПЕРВЫЙ ОТВЕТИВШИЙ -- ЭТО НЕ ПОБЕДИТЕЛЬ, а только "принял быстрее".
    первый = min(приняли, key=lambda с: (с.get("send_ms") or 1e9))
    из_.update(ok=True, sent=True, result=первый.get("signature"),
               http=первый.get("http"))
    из_["pool"]["accepted_first"] = первый["sender"]
    из_["pool_winner"] = None  # решит цепь
    if ключ_операции:
        with _ЗАМОК:
            _ОТПРАВЛЕНО[ключ_операции] = {"result": первый.get("signature"),
                                           "why_not": None}
    return из_


def региональные_адреса(rpc_call, целевой_слот, отправители) -> dict:
    """{'регион','лидер','адреса'} для слота -- или пусто, если ничего не меняем.

    III.14: вариант уходит в точку ТОГО ЖЕ отправителя, ближайшую к лидеру
    слота. Считается ДО отправки и в горячем пути стоит один вызов узла на
    эпоху (расписание лидеров держится в памяти процесса).
    """
    # ТОЧКИ -- ОТДЕЛЬНО ОТ АДРЕСОВ, и вот почему: в "адреса" лежит РАБОЧИЙ url,
    # а у Helius ключ стоит В ПУТИ адреса. Такой url нельзя писать ни в запись
    # позиции, ни в выгрузку. Поэтому для отчёта собираются host и регион точки
    # -- они не секреты, а ответить на "куда ушло" их хватает.
    из_ = {"регион": None, "лидер": None, "адреса": {}, "точки": {},
            "why_not": None}
    try:
        import bloom_region_send as RS  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"модуль региональной отправки не загружен: {type(exc).__name__}"
        return из_
    if not RS.включено():
        из_["why_not"] = "путь выключен (BLOOM_REGION_SEND не равен 1)"
        return из_
    if not целевой_слот or rpc_call is None:
        из_["why_not"] = "целевой слот или узел неизвестны"
        return из_
    try:
        рс = RS.регион_слота(rpc_call, int(целевой_слот))
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"регион слота не определён ({type(exc).__name__})"
        return из_
    из_["регион"], из_["лидер"] = рс.get("регион"), рс.get("лидер")
    if из_["регион"] in (None, "неизвестно"):
        из_["why_not"] = "регион лидера неизвестен -- адреса как сейчас"
        return из_
    for имя in (отправители or []):
        а = RS.адрес_для(имя, из_["регион"])
        if а.get("ok"):
            из_["адреса"][имя] = а["url"]
            из_["точки"][имя] = {"host": а.get("host"),
                                  "регион_точки": а.get("point_region")}
    if not из_["адреса"]:
        из_["why_not"] = f"для региона {из_['регион']} точек ни у кого нет"
    return из_


def _отправить_пулом(tx_base64: str, *, из_: dict, сервисы: list,
                      ключ_операции: str | None, отправитель=None,
                      таймаут: float = 5.0, состояние=None) -> dict:
    """Одни и те же подписанные байты -- всеми сервисами ПАРАЛЛЕЛЬНО.

    Успех -- это подпись хотя бы от одного: подпись у всех одна и та же (мы её
    сами и считали), поэтому "успел первый" не создаёт второй покупки. Кто
    ответил первым и кто вообще ответил -- в отчёт: это и есть замер пула.
    """
    try:
        import bloom_senders as SS  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"реестр отправителей не загружен: {type(exc).__name__}"
        _запомнить_отказ(ключ_операции, из_["why_not"])
        return из_
    t0 = time.perf_counter()
    веер = SS.отправить_всеми(tx_base64, имена=сервисы, отправитель=отправитель,
                               таймаут=таймаут)
    из_["send_ms"] = round((time.perf_counter() - t0) * 1000, 2)
    строки = list((веер.get("results") or {}).values())
    из_["pool"] = {"senders": веер.get("senders"),
                    "ok_senders": веер.get("ok_senders"),
                    "total_ms": веер.get("total_ms"),
                    "signatures": веер.get("signatures"),
                    "one_signature": веер.get("one_signature"),
                    "rows": строки}
    # ПОДПИСЬ ОБЯЗАНА БЫТЬ ОДНА. Байт один и подпись мы считали сами: разные
    # подписи от разных сервисов означают, что кто-то отправил НЕ ТО, что мы
    # подписали. Это денежная странность, а не мелочь -- полоса встаёт до
    # разбора человеком.
    if веер.get("one_signature") is False:
        из_["why_not"] = ("сервисы вернули РАЗНЫЕ подписи "
                           f"{веер.get('signatures')} -- отправлено не то, что мы "
                           "подписали")
        из_["tamper"] = True
        # ЭТО РУБИЛЬНИК, А НЕ ОТКАЗ. Правило владельца 25.09 называет утечкой
        # "чужого получателя" и "неучтённый расход" -- а чужая подпись значит
        # ровно это: в цепь ушла транзакция, которой мы не подписывали, то есть
        # деньги кошелька полосы могли уйти по чужим правилам, и в цепи их две.
        # Отказаться и ждать следующего сигнала было бы приглашением повторить.
        # Bloom и тень при этом работают: рубильник только полосы.
        из_["kill_set"] = остановить_полосу(
            состояние, f"разные подписи от сервисов пула: {из_['why_not']}")
        _запомнить_отказ(ключ_операции, из_["why_not"])
        return из_
    удачные = [с for с in строки if с.get("ok") and с.get("signature")]
    if not удачные:
        причины = "; ".join(f"{с.get('sender')}: {с.get('why_not')}"
                             for с in строки) or "ни один сервис не ответил"
        из_["why_not"] = f"пул не довёз: {причины}"[:400]
        _запомнить_отказ(ключ_операции, из_["why_not"])
        return из_
    первый = min(удачные, key=lambda с: (с.get("send_ms") or 1e9))
    подпись = первый.get("signature")
    из_.update(ok=True, sent=True, result=подпись, http=первый.get("http"),
               pool_winner=первый.get("sender"))
    if ключ_операции:
        with _ЗАМОК:
            _ОТПРАВЛЕНО[ключ_операции] = {"result": подпись, "why_not": None}
    return из_


def отправить(tx_base64: str, *, состояние=None, ключ_операции: str | None = None,
               минт: str | None = None, лампорты: int | None = None,
               источник_подпись: str | None = None,
               источник_слот: int | None = None,
               источник: str | None = None,
               адрес: str | None = None, таймаут: float = 5.0,
               отправитель=None, сейчас: float | None = None,
               без_учёта: bool = False, сервисы: list | None = None,
               группа: str | None = None, варианты: dict | None = None,
               региональные: dict | None = None,
               тип_пула: str | None = None,
               держать_слотов: float | None = None,
               # ФАКТЫ ЗАПУСКА -- НЕОБЯЗАТЕЛЬНЫМ СЛОВАРЁМ. Ни одно прежнее
               # место вызова не меняется: без довода он пуст, и в запись
               # позиции не идёт ни одно поле. Нужен потому, что write_intent
               # делается ЗДЕСЬ, под замком и с бронью, а факты запуска
               # известны в сборке -- протягивать их через три вызова ради
               # этого значило бы менять денежный путь шире, чем надо.
               запуск: dict | None = None) -> dict:
    """Одна отправка в Helius Sender. Метод и параметры -- из документации.

    Sender не тратит кредиты тарифа и берёт плату чаевыми в SOL; предел 50
    транзакций в секунду. skipPreflight=true и maxRetries=0 стоят так же,
    как в примере документации: предполётная проверка стоит задержки, а
    повторы делаем сами, зная своё состояние.

    Без BLOOM_OWN_SEND_LIVE=1 не уходит ничего. Это не настройка скорости,
    а рубильник живых денег.
    """
    из_ = {"ok": False, "sent": False, "why_not": None, "http": None,
            "result": None, "send_ms": None, "cid": None}
    if not живьём():
        из_["why_not"] = "BLOOM_OWN_SEND_LIVE не равен 1 -- отправка выключена"
        return из_
    # ВСЁ, ЧТО РЕШАЕТ ПРО ДЕНЬГИ, -- ПОД ОДНИМ ЗАМКОМ И ДО СЕТИ: ключ
    # операции, рубильник, пределы полосы и резервирующая запись позиции.
    # Раньше пределы проверял вызывающий, а замок держал только ключ
    # операции; два сигнала в двух потоках оба видели "открытых 0" и оба
    # отправляли -- предел "одна открытая" не работал именно тогда, когда он
    # нужен. Теперь позиция ложится на диск ЗДЕСЬ, внутри замка, и второй
    # поток видит её как открытую.
    with _ЗАМОК:
        if ключ_операции:
            прежнее = _ОТПРАВЛЕНО.get(ключ_операции)
            if прежнее is not None:
                из_["why_not"] = (f"по ключу операции {ключ_операции} уже отправляли: "
                                   f"{прежнее.get('result') or прежнее.get('why_not')}")
                из_["duplicate"] = True
                return из_
        if not без_учёта:
            if состояние is None:
                из_["why_not"] = ("состояние не передано -- ни рубильник, ни пределы "
                                   "полосы проверить нечем, отправка отменена")
                return из_
            убит, почему_kill = состояние.kill_active()
            if not убит and hasattr(состояние, "lane_kill_active"):
                убит, почему_kill = состояние.lane_kill_active()
            if убит:
                из_["why_not"] = f"рубильник: {почему_kill}"
                из_["kill"] = True
                return из_
            try:
                позиции = состояние.positions()
            except Exception as exc:  # noqa: BLE001
                из_["why_not"] = (f"позиции не прочитаны ({type(exc).__name__}) -- "
                                   "пределы полосы не проверить")
                return из_
            # СОСТОЯНИЕ ПЕРЕДАЁТСЯ ЯВНО: счёт по цепи читается из каталога
            # ЭТОГО состояния, а не из того, что сложится по env. Каталог у
            # службы один и тот же, но полагаться на это незачем -- у вызова он
            # уже есть в руках.
            гейт = можно_отправлять(позиции, сейчас=сейчас, группа=группа,
                                      минт=минт, размер_лампорты=лампорты,
                                      состояние=состояние,
                                      # СЛОТ ИСТОЧНИКА -- часы запрета второго
                                      # минта на группу: окно владельца задано
                                      # в слотах цепи, а не в секундах.
                                      слот=источник_слот,
                                      подпись_источника=источник_подпись)
            if not гейт.get("ok"):
                из_["why_not"] = f"предел полосы: {гейт.get('why_not')}"
                из_["lane_state"] = гейт.get("state")
                return из_
            if not минт or not isinstance(лампорты, int) or лампорты <= 0:
                из_["why_not"] = ("для записи позиции полосы нужны минт и размер "
                                   f"(минт {минт!r}, лампорты {лампорты!r})")
                return из_
            if лампорты > потолок_лампортов():
                из_["why_not"] = (f"размер {лампорты} лампортов выше потолка полосы "
                                   f"{потолок_лампортов()} -- отправка отменена")
                # СЛОВО ВЛАДЕЛЬЦА 25.09: сумма выше предела -- это не просто
                # отказ, это денежная странность. Полоса встаёт до разбора
                # человеком; Bloom и тень продолжают работать.
                из_["kill_set"] = остановить_полосу(
                    состояние, f"сумма выше предела: {из_['why_not']}")
                return из_
            # РЕЗЕРВИРУЮЩАЯ ЗАПИСЬ. Позиция с state=intent и меткой полосы --
            # это и есть бронь: её видит и второй поток, и сторож, и она
            # остаётся на диске, если процесс упадёт между отправкой и ответом.
            cid = f"lane-{ключ_операции or int(time.time() * 1000)}"
            try:
                состояние.write_intent(
                    client_order_id=cid, mint=минт, source_sig=источник_подпись or "",
                    source_slot=источник_слот, sol_in=лампорты / ЛАМПОРТОВ_В_SOL,
                    # ТИП ПУЛА -- В ЗАПИСЬ ПОЗИЦИИ. Здесь стояло program=None, и
                    # по позициям нельзя было сказать, каким строителем сделана
                    # сделка: вечерний итог по строителям выходил одной графой
                    # "поля нет". Программа известна сборщиком, и подставлять
                    # её надо здесь, в БРОНИ, а не дописывать потом: если
                    # процесс упадёт между отправкой и ответом, позиция всё
                    # равно будет знать свой тип.
                    pool=None, program=(тип_пула or None), taxed=None, tax_bps=None,
                    mode=ST.MODE_LIVE, sell_after_s=срок_продажи_s(держать_слотов),
                    lane=МЕТКА,
                    # АДРЕС ИСТОЧНИКА -- в позицию: предел покупок считается по
                    # паре "источник + минт" (слово владельца 27.09, вечер).
                    source=(источник or None),
                    # СВОЙ КОШЕЛЁК -- В ЗАПИСЬ. Без этого в позиции полосы стоял
                    # адрес исполнителя, и проверка токенов по цепи смотрела не
                    # тот кошелёк.
                    lane_wallet=кошелёк_полосы(),
                    # ГРУППА ИСТОЧНИКА -- В ПОЗИЦИЮ. По ней считаются деньги:
                    # у speed_only свой потолок и свой стоп, и в общий итог её
                    # сделки не идут (слово владельца).
                    lane_group=(группа or None))
            except Exception as exc:  # noqa: BLE001
                из_["why_not"] = (f"позиция полосы не записана ({type(exc).__name__}) "
                                   "-- без записи отправлять нельзя: сторож о ней не "
                                   "узнает")
                return из_
            # УДЕРЖАНИЕ В СЛОТАХ И ДЛИНА СЛОТА -- В ЗАПИСЬ, отдельной дописью:
            # подпись write_intent фиксирована, а сторожу нужно пересчитывать
            # срок по СВЕЖЕЙ длине слота (решение владельца 28.09, вариант 2), а
            # отчёту -- показывать удержание и в секундах, и в слотах. Дописка
            # не имеет права ронять отправку: позиция уже на диске.
            try:
                _зап_поля = {к: v for к, v in (запуск or {}).items()
                             if к.startswith("zapusk_") and v is not None}
                состояние.update_position(
                    cid,
                    hold_slots=(float(держать_слотов)
                                 if держать_слотов not in (None, "") else None),
                    slot_len_at_buy_s=длина_слота_s(),
                    # ФАКТЫ ЗАПУСКА -- В ЗАПИСЬ ПОЗИЦИИ, иначе выгрузка их не
                    # увидит: она читает позиции, а не строку решения. Пусто у
                    # всех прочих групп, и None не пишется вовсе (дописка None
                    # стирала бы прежнее значение: журнал позиций склеивается
                    # обычным dict.update).
                    **_зап_поля)
            except Exception as exc:  # noqa: BLE001
                из_["hold_slots_why_not"] = f"{type(exc).__name__}"
            # ЗАПРЕТ ВТОРОГО МИНТА НА ГРУППУ -- отмечается ЗДЕСЬ, в брони.
            # Почему здесь, а не после ответа сети: бронь -- единственное
            # место, где покупка уже решена и ещё одна, из второго потока,
            # этот минт группе не откроет. Цена выбора названа прямо: если
            # отправка потом упадёт, минт для группы закрыт до конца окна --
            # пропущенный дубль дешевле второй покупки того же минта, а
            # именно её владелец и запретил.
            try:
                из_["group_mint_mark"] = состояние.отметить_минт_группы(
                    группа, минт, slot=источник_слот, sig=источник_подпись,
                    mode=ST.MODE_LIVE)
            except Exception as exc:  # noqa: BLE001
                из_["group_mint_mark"] = {"ok": False,
                                           "why_not": f"{type(exc).__name__}"}
            из_["cid"] = cid
        if ключ_операции:
            _ОТПРАВЛЕНО[ключ_операции] = {"result": None, "why_not": "отправка идёт"}
    # БОЕВОЙ ПУЛ: те же подписанные байты уходят ВСЕМИ сервисами сразу.
    # Гейт выше (ключ операции, рубильник, пределы, бронь) не меняется ни на
    # строку -- меняется только дорога. Подпись одна, поэтому в цепь транзакция
    # сядет один раз, кто бы её ни довёз.
    # ВАРИАНТЫ НА NONCE -- отдельный путь: транзакций N, подписи разные, и
    # решает, какая села, ЦЕПЬ. Проверка "подпись одна" здесь неприменима, её
    # место занимает сам nonce (он уже проверен в сборке вариантов).
    if варианты:
        return _отправить_вариантами(варианты, из_=из_,
                                      ключ_операции=ключ_операции,
                                      отправитель=отправитель, таймаут=таймаут,
                                      состояние=состояние,
                                      региональные=региональные)
    if сервисы:
        return _отправить_пулом(tx_base64, из_=из_, сервисы=сервисы,
                                 ключ_операции=ключ_операции,
                                 отправитель=отправитель, таймаут=таймаут,
                                 состояние=состояние)
    тело = {"jsonrpc": "2.0", "id": str(int(time.time() * 1000)),
             "method": "sendTransaction",
             "params": [tx_base64, {"encoding": "base64", "skipPreflight": True,
                                     "maxRetries": 0}]}
    t0 = time.perf_counter()
    try:
        if отправитель is None:
            import requests  # noqa: PLC0415

            def отправитель(url, данные, таймаут_):  # noqa: E306
                r = requests.post(url, json=данные, timeout=таймаут_,
                                  headers={"Content-Type": "application/json"})
                return r.status_code, r.text
        адрес_отправки = адрес or адрес_сендера()
        # КТО ДОВЁЗ, КОГДА ПУЛА НЕТ. У пула есть pool_winner (его называет
        # цепь), а у одиночной отправки победителя нет -- есть ровно одна
        # точка, в которую мы постучались. Её имя (без схемы, пути и ключа) и
        # есть честный ответ на вопрос владельца "кто довёз".
        из_["send_point"] = имя_точки(адрес_отправки)
        код, текст = отправитель(адрес_отправки, тело, таймаут)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"сеть: {type(exc).__name__}: {str(exc)[:160]}"
        из_["send_ms"] = round((time.perf_counter() - t0) * 1000, 2)
        _запомнить_отказ(ключ_операции, из_["why_not"])
        return из_
    из_["send_ms"] = round((time.perf_counter() - t0) * 1000, 2)
    из_["http"] = код
    try:
        ответ = json.loads(текст)
    except ValueError:
        из_["why_not"] = f"ответ не JSON: {текст[:160]}"
        return из_
    if isinstance(ответ, dict) and ответ.get("error"):
        из_["why_not"] = f"Sender отказал: {json.dumps(ответ['error'], ensure_ascii=False)[:200]}"
        # ОТКАЗ ОПРЕДЕЛЁННЫЙ: узел разобрал транзакцию и отверг её -- в цепь
        # она не попала. Только на таком отказе бронь можно закрывать. Все
        # прочие неудачи (сеть, не-JSON, 200 без подписи) неопределённы:
        # транзакция могла уйти, и закрывать бронь по ним нельзя.
        из_["definite_refusal"] = True
        return из_
    # УСПЕХ -- ЭТО HTTP 200 И ПОДПИСЬ В ОТВЕТЕ. Без подписи мы не знаем, что
    # ушло, и считать такую отправку удачной значит потом искать в цепи то,
    # чего, возможно, нет.
    подпись = (ответ or {}).get("result") if isinstance(ответ, dict) else None
    if код != 200:
        из_["why_not"] = f"Sender ответил кодом {код}, а не 200"
        return из_
    if not isinstance(подпись, str) or not подпись:
        из_["why_not"] = "Sender не вернул подпись -- отправка не подтверждена"
        return из_
    из_.update(ok=True, sent=True, result=подпись)
    if ключ_операции:
        with _ЗАМОК:
            _ОТПРАВЛЕНО[ключ_операции] = {"result": подпись, "why_not": None}
    return из_


# ------------------------------------------------------------------ пределы полосы

# Срок продажи позиции полосы. Слово владельца: сторожем через 28.8 с, как у
# боевых покупок -- сравнение честно только при одинаковом горизонте.
СРОК_ПРОДАЖИ_S = ST.env_float("BLOOM_OWN_SEND_SELL_AFTER_S", 28.8)


def срок_продажи_s(держать_слотов: float | None = None) -> float:
    """Через сколько секунд продавать. Считается ИЗ УДЕРЖАНИЯ ГРУППЫ.

    НАЙДЕНО 28.09 ПО ЖИВОЙ СДЕЛКЕ. В запись позиции шёл флаг окружения
    (28.8 с) на все группы подряд, а удержание группы (hold_slots) только
    считалось и писалось в отчёт. Цена ошибки измерена: снайперская покупка
    zVbJ3e (группа sniper_src, hold_slots 12, то есть 4.8 с) держалась 29.96 с
    -- в шесть раз дольше, чем назначил владелец, и продана по цене шестого
    десятка секунд вместо двенадцатого слота.

    ДЛИНА СЛОТА -- ИЗМЕРЕННАЯ (решение владельца 28.09, вариант 2), а не 0.4:
    замер 28.09 дал 0.2659 с, и удержание в слотах выходило в полтора раза
    длиннее задуманного. Нет замера -- берётся последнее известное, и только при
    полном его отсутствии константа. Удержания нет -- остаётся флаг окружения:
    он и был поведением по умолчанию.
    """
    try:
        слотов = float(держать_слотов) if держать_слотов is not None else None
    except (TypeError, ValueError):
        слотов = None
    if слотов is None or слотов <= 0:
        return float(СРОК_ПРОДАЖИ_S)
    return round(слотов * длина_слота_s(), 3)

# ПРЕДЕЛЫ ПОЛОСЫ. Сводный промпт владельца 25.09 15:45 Madrid, пункт 3:
# "Одна открытая позиция, 50 сделок в сутки; стоп -0.3 SOL за сутки или 5
# упавших подряд". До этого было 20 сделок, -0.1 SOL и 3 упавших.
#
# ЭТО ТЕПЕРЬ ТОЛЬКО ЗНАЧЕНИЕ ПО УМОЛЧАНИЮ: у группы может стоять своё число в
# файле групп (поле lane_open_max), и его читает предел_открытых().
ЛИМИТ_ОТКРЫТЫХ = 1

# ЗАВИСШАЯ ПОЗИЦИЯ НЕ ЗАНИМАЕТ МЕСТО. Решение владельца 25.09 (вечер):
# "зависшая позиция полосы (не продана за 120 с) не считается открытой для
# предела «1 открытая» -- полоса продолжает покупать, зависшую сторож дожимает
# отдельно". Причина прямая: у сторожа предел попыток снят, и позиция, которую
# он додавливает минутами, иначе закрывала бы полосе вход на всю ночь.
СРОК_ЗАВИСАНИЯ_S = ST.env_float("BLOOM_OWN_SEND_STUCK_AFTER_S", 120.0)


def позиция_зависла(p: dict, *, сейчас: float) -> bool:
    """Позиция полосы висит дольше срока: место в пределе она не занимает."""
    основа = (p or {}).get("ts_sent") or (p or {}).get("ts_accepted") \
        or (p or {}).get("ts_intent")
    if not основа:
        return False
    try:
        return (float(сейчас) - float(основа)) > float(СРОК_ЗАВИСАНИЯ_S)
    except (TypeError, ValueError):
        return False
# СКОЛЬКО СДЕЛОК В СУТКИ РАЗРЕШЕНО ПОЛОСЕ. Было жёсткое 50 в коде: 01.10 в
# 05:16:42Z cand1 упёрся в него и молчал до сброса суток по Мадриду, то есть
# шестнадцать часов. Теперь это ВХОД, и его можно поднять без деплоя; поле
# группы per_day сильнее входа (слово владельца 01.10, 11:24: "cand1 = 150").
ЛИМИТ_В_СУТКИ = ST.env_int("BLOOM_LANE_DAY_LIMIT", 50)
СТОП_ПОДРЯД_УПАВШИХ = 5
СТОП_УБЫТОК_SOL = 0.3

# ---- ПРАВИЛО 16 (слово владельца 02.10, вечер) ----------------------------
# СУТОЧНЫХ СТОПОВ ГРУПП БОЛЬШЕ НЕТ. Дневной стоп группы снимался только сменой
# суток и за день съедал группу целиком на обычной плохой серии: 02.10 cand1
# встала на -0.345 при -0.3 и стояла, пока владелец не снял её словом. Вместо
# него -- стоп "авария" на группу (признаки ошибки, а не убытка), а общий
# рубильник полосы по цепи остаётся как был.
#
# ЗАЩЁЛКА В КОДЕ ОСТАЁТСЯ (слово владельца дословно), но для групп она больше
# не срабатывает: ставить её нечему, а старая запись суток не блокирует --
# см. _суточный_стоп_групп_включён ниже, он гасит и проверку, и постановку.
# Вход оставлен, чтобы вернуть прежнее поведение без деплоя.
СУТОЧНЫЙ_СТОП_ГРУПП = ST.env_int("LANE_GROUP_DAILY_STOP", 0)


def _суточный_стоп_групп_включён() -> bool:
    """Действует ли дневной стоп группы. По Правилу 16 -- нет."""
    return bool(ST.env_int("LANE_GROUP_DAILY_STOP", СУТОЧНЫЙ_СТОП_ГРУПП))

# ---- СУТКИ ПОЛОСЫ НАЧИНАЮТСЯ В 00:00 МАДРИД (финальный план 27.09, п.1е) ----
# Было скользящее окно 24 часа. Владелец считает сутками календарные сутки
# своего времени, и стоп, съезжающий вместе с часами, нельзя ни проверить, ни
# объяснить: "-0.174 за сутки" утром значило одно окно, вечером другое.
ЗОНА_СУТОК = "Europe/Madrid"
# СУТОЧНОГО СТОПА ПОЛОСЫ БОЛЬШЕ НЕТ (правило 16, слово владельца 03.10):
# останавливает только рубильник по балансу LANE_KILL_DROP_SOL. Имя оставлено,
# чтобы стоп можно было вернуть значением окружения, без деплоя.
#
# ОТСУТСТВИЕ ИМЕНИ ЗНАЧИТ "СТОПА НЕТ", А НЕ УМОЛЧАНИЕ. Здесь стояло 0.5, и
# "убрать LANE_DAILY_LOSS_SOL из окружения" затянуло бы стоп с живых 1.5 до
# 0.5, а не сняло его -- то есть все группы вставали бы на -0.5 за сутки, и
# молча. Ровно та ловушка, что была у DAILY_LOSS_LIMIT (умолчание 1.0),
# названная в докладе 06:30Z. None здесь -- именно "не проверять".
_СТОП_СУТОК_ЧИСЛО = ST.env_float("LANE_DAILY_LOSS_SOL", 0.0)
СТОП_ПОЛОСЫ_СУТКИ_SOL = _СТОП_СУТОК_ЧИСЛО if _СТОП_СУТОК_ЧИСЛО > 0 else None
# KILL-ПОРОГ ПО БАЛАНСУ: баланс кошелька полосы упал от баланса на 00:00 больше
# чем на это число -- рубильник полосы. Это защита от того, чего учёт по
# позициям не видит вовсе (чужая трата, ошибка в сборке, утечка ренты).
ПОРОГ_KILL_ПО_БАЛАНСУ_SOL = ST.env_float("LANE_KILL_DROP_SOL", 0.5)


def _зона_суток():
    """Зона Мадрида или None, если базы зон на хосте нет."""
    try:
        from zoneinfo import ZoneInfo  # noqa: PLC0415

        return ZoneInfo(ЗОНА_СУТОК)
    except Exception:  # noqa: BLE001
        return None


def начало_суток(сейчас: float | None = None) -> dict:
    """00:00 Мадрида для текущих суток: метка времени, имя суток и как считали.

    Базы зон нет -- берём +02:00 (Мадрид летом) и ГОВОРИМ об этом в ответе.
    Молча считать сутки по UTC значило бы сдвинуть стоп на два часа.
    """
    сейчас = float(сейчас if сейчас is not None else time.time())
    зона = _зона_суток()
    if зона is not None:
        мест = datetime.datetime.fromtimestamp(сейчас, зона)
        полночь = мест.replace(hour=0, minute=0, second=0, microsecond=0)
        return {"ts": полночь.timestamp(), "day": полночь.strftime("%Y%m%d"),
                 "how": ЗОНА_СУТОК}
    сдвиг = 2 * 3600
    мест = datetime.datetime.utcfromtimestamp(сейчас + сдвиг)
    полночь = мест.replace(hour=0, minute=0, second=0, microsecond=0)
    return {"ts": полночь.timestamp() - сдвиг, "day": полночь.strftime("%Y%m%d"),
             "how": "смещение +02:00 -- базы зон на хосте нет"}
МЕТКА = ST.МЕТКА_ПОЛОСЫ        # одно написание на весь репозиторий

# ГРУППА СКОРОСТИ (пункт 1.2). Её сделки в деньги не входят, у них свой
# суточный потолок РАСХОДА (покупки плюс чаевые) и свой стоп. Значения берутся
# из файла групп, здесь -- только откат на случай, если файла нет.
# Решение владельца 25.09 (вечер): "speed_only: потолок 1 SOL в сутки
# (покупки + чаевые), стоп -0.5 SOL". Было 0.2 и -0.15: при 0.01 SOL на сделку
# это всего 20 сделок, а цель теперь 30+ покупок в час.
ГРУППА_СКОРОСТИ = "speed_only"
ПОТОЛОК_СУТОК_СКОРОСТИ_SOL = 1.0
СТОП_УБЫТОК_СКОРОСТИ_SOL = 0.5


# БАЗОВЫЙ ТАРИФ СЕТИ ЗА ПОДПИСЬ. 5000 лампортов за подпись -- цена, которую
# Solana берёт с любой транзакции; у нас подпись одна.
БАЗОВЫЙ_ТАРИФ_ЛАМПОРТОВ = 5000


def стоимость_сделки_sol(позиция: dict) -> float:
    """Сколько эта покупка стоила кошельку полосы СВЕРХ купленной суммы.

    ОДНА ФОРМУЛА НА РЕПОЗИТОРИЙ (I.5): считает ST.расход_отправки, здесь
    только округление для отчётов. Когда написаний было два, числа
    расходились -- и расходились ровно там, где на них смотрит стоп.

    Расход контролей (веер) сюда НЕ входит: у него свой суточный потолок и
    свой файл счёта, и это замер, а не сделка.
    """
    return round(ST.расход_отправки(позиция or {}), 9)


# ПРАВИЛО 13 В СТОПЕ: ЧИСЛО БЕРЁТСЯ ПО ЦЕПИ (слово владельца 01.10, вечер).
#
# ПОЧЕМУ. 01.10 в 19:47:06Z групповой стоп закрыл cand1 числом -5.013347883 --
# ПО УЧЁТУ, тогда как по цепи сутки шли в +0.871228561. Учёт в тот момент был
# перезаписан правкой (выручка свопа вместо нативной дельты), и стоп послушно
# сработал на испорченное поле. Пока стоп читает журнал, ЛЮБАЯ правка учёта
# способна его обрушить -- и обрушит на следующем бэкфиле.
#
# ОТКУДА БЕРЁТСЯ ЧИСЛО. `c2_itog_po_cepi.ПОЛЕ` (`lane_chain_pnl_sol`) --
# сумма изменений ВСЕХ наших счетов по двум подписям сделки. Его пишет продавец
# при каждом закрытии (bloom_seller: `итог_по_двум` сразу после подтверждения
# продажи), поэтому гейту не нужно ни одного лишнего чтения узла: поле уже
# лежит в позиции. Второго написания формулы здесь нет намеренно.
#
# ЧЕГО ЭТА ПРАВКА НЕ ДЕЛАЕТ. Она не отменяет счёт по полям: `pnl_sol` остаётся
# в ответе контролем и в отчёте, и расхождение двух чисел видно строкой. Она не
# трогает ни суммарный суточный стоп полосы (он по цепи с 29.09: баланс
# кошелька на 00:00 минус баланс сейчас), ни KILL по балансу (там тоже цепь,
# getBalance) -- им правка не нужна.
#
# ЧЕГО У ЦЕПИ НЕТ. У ОТКРЫТОЙ позиции цепного числа быть не может: продажи ещё
# не было. Такая позиция идёт в счёт тем же расходом на отправку, что и в счёте
# по полям, и считается отдельно (`pnl_chain_open_n`). У ЗАКРЫТОЙ поле может не
# успеть записаться (продавец пишет его после подтверждения) или не посчитаться
# -- тогда берётся счёт по полям, и это НАЗВАНО числом `pnl_chain_fields_n`:
# молча подменить одно другим значило бы снова два числа под одним именем.
def цепной_итог_позиции(позиция: dict) -> dict:
    """Итог ОДНОЙ позиции по цепи из её записи: {'есть','итог_sol','почему_нет'}.

    Обёртка над `c2_itog_po_cepi.из_записи` -- ровно для того, чтобы гейт не
    держал в себе ни знания имени поля, ни своей копии формулы. Модуля нет на
    хосте (старая доставка) -- говорим это словами, а не считаем нулём.
    """
    try:
        import c2_itog_po_cepi as C13  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        return {"есть": False, "итог_sol": None,
                 "почему_нет": f"модуль c2_itog_po_cepi не загружен ({type(exc).__name__})"}
    try:
        return C13.из_записи(позиция or {})
    except Exception as exc:  # noqa: BLE001
        return {"есть": False, "итог_sol": None,
                 "почему_нет": f"итог по цепи не прочитан ({type(exc).__name__})"}


def состояние_полосы(позиции: dict, *, сейчас: float | None = None,
                      группа: str | None = None) -> dict:
    """Что полоса сделала за сутки и можно ли ей ещё.

    Считается по ПОЗИЦИЯМ с меткой полосы, а не по журналу: журнал говорит о
    намерениях, а пределы владельца -- про сделки. Упавшей считается покупка,
    которая по цепи не села (chain_ok=false), а не та, что ушла в минус:
    три убыточных подряд -- это рынок, три упавших -- это мы.
    """
    сейчас = сейчас if сейчас is not None else time.time()
    # СУТКИ -- КАЛЕНДАРНЫЕ, ОТ 00:00 МАДРИДА (слово владельца 27.09, п.1е).
    сут = начало_суток(сейчас)
    сутки_назад = сут["ts"]
    все_свои = [p for p in (позиции or {}).values()
                if (p or {}).get("lane") == МЕТКА]
    # КАЖДАЯ ГРУППА СЧИТАЕТСЯ САМА ПО СЕБЕ (финальный план 27.09, п.1е: "группа
    # достигла своего stop_loss_sol -- только она off до полуночи"). Здесь
    # раньше все группы кроме скорости складывались в одни деньги: тогда это
    # было верно (у них был один стоп), а теперь стопы РАЗНЫЕ -- 0.30 у лидера,
    # 0.15 у batch5 и lane_s0 -- и общий счёт закрывал бы лидера убытком
    # batch5. Суммарный предел по всем группам считается отдельным числом
    # (pnl_all_groups_sol) и стоит ПЕРЕД групповым.
    def своя(p):
        if not группа:
            return True
        return (p or {}).get("lane_group") == группа

    свои = [p for p in все_свои if своя(p)]
    за_сутки = [p for p in свои if float(p.get("ts_intent") or 0) >= сутки_назад]
    # ЗА ПОСЛЕДНИЙ ЧАС -- СКОЛЬЗЯЩЕЕ ОКНО, А НЕ КАЛЕНДАРНЫЙ ЧАС. Календарный
    # час пускал бы десять покупок в 10:59 и ещё десять в 11:01; окно "час
    # назад от сейчас" такого не даёт. Считается по ts_intent -- тому же
    # времени, по которому считаются сутки, чтобы два предела не считали по
    # разным часам.
    час_назад = сейчас - 3600.0
    за_час = [p for p in свои if float(p.get("ts_intent") or 0) >= час_назад]
    # А ВОТ ОТКРЫТАЯ ПОЗИЦИЯ СЧИТАЕТСЯ ПО ВСЕМ ГРУППАМ СРАЗУ: кошелёк у полосы
    # один, и две покупки одновременно он не вынесет, из какой бы группы они ни
    # пришли. Предел "одна открытая" -- про кошелёк, а не про учёт.
    # СПИСАННАЯ ПОЗИЦИЯ МЕСТА НЕ ЗАНИМАЕТ (слово владельца 04.10, 23:03:
    # "списать ... полосу не держать ... не считается в lane_open_max и в
    # зависших"). Её убыток уже окнижен полностью, и держать из-за неё полосу
    # значит платить за один рагпул дважды: деньгами и простоем.
    открытых = [p for p in все_свои
                if p.get("state") not in (ST.STATE_CLOSED, "unsold", "closed",
                                           ST.STATE_SPISANA)
                and not позиция_зависла(p, сейчас=сейчас)]
    # Зависшие считаются ОТДЕЛЬНО и в признак жизни: полоса из-за них не
    # стоит, но молчать о них нельзя -- их дожимает сторож.
    зависших = [p for p in все_свои
                if p.get("state") not in (ST.STATE_CLOSED, "unsold", "closed",
                                           ST.STATE_SPISANA)
                and позиция_зависла(p, сейчас=сейчас)]
    по_времени = sorted(за_сутки, key=lambda p: float(p.get("ts_intent") or 0))
    подряд = 0
    for p in reversed(по_времени):
        # РАЗОБРАННЫЙ СБОЙ В СЕРИЮ НЕ ИДЁТ. 28.09 семь покупок источника
        # 6qudAN2k упали по одной и той же причине (чужой связанный накопитель
        # в 27-счётной кривой), причина названа цепью и починена; держать из-за
        # них полосу остановленной значит наказывать её за уже устранённое.
        if (p or {}).get("failure_reviewed"):
            continue
        if p.get("chain_ok") is False:
            подряд += 1
        elif p.get("chain_ok") is True:
            break
        elif p.get("lane_landed_signature") and not p.get("lane_not_landed"):
            # ПОКУПКА СЕЛА -- СЕРИЯ ОБОРВАНА, даже если количество ещё не
            # добрано и chain_ok пока None. Иначе свежая удачная сделка не
            # сбрасывала серию, и полоса стояла при живых покупках: ровно это
            # случилось 28.09 в 21:18:48Z.
            break
    # СУТОЧНЫЙ СЧЁТ СЧИТАЕТСЯ ТОЙ ЖЕ ФОРМУЛОЙ, ЧТО И СЧЁТ СОСТОЯНИЯ (I.5).
    # Здесь было второе написание: оно пропускало несчитаемые пары целиком, а
    # их за ночь 25->26.09 оказалось 61 из 63 закрытых -- то есть стоп смотрел
    # почти только на чаевые. Теперь одна формула: ST.итог_позиции.
    итог_с_расходом = 0.0
    расход_сделок_sol = 0.0
    непосчитанных = 0
    # ТО ЖЕ ЧИСЛО ПО ЦЕПИ -- В ТОМ ЖЕ ПРОХОДЕ (Правило 13). Отдельного перебора
    # нет намеренно: два перебора по журналу суток стоят вдвое, а стоит это в
    # гейте, то есть в пути решения полосы.
    итог_по_цепи = 0.0
    цепь_по_цепи_n = 0
    цепь_по_полям_n = 0
    цепь_открытых_n = 0
    цепь_почему_нет = []
    # ИНДЕКС МИНТОВ -- ОДИН РАЗ НА ВЫЗОВ, а не полный перебор журнала на каждую
    # сделку суток. Этот счёт стоит в гейте, то есть в пути решения полосы, и
    # цена была измерена 01.10: 158.9 мс при журнале 5499 и 129 сделках суток,
    # 97 % из них -- в делит_минт. Ответ от индекса тот же (см. его docstring).
    _инд = ST.индекс_минтов(позиции)
    for p in за_сутки:
        общий = ST.делит_минт(p.get("client_order_id"), p, позиции, индекс=_инд)
        поз_для_счёта = dict(p)
        if общий:
            поз_для_счёта["uncountable_shared_mint"] = общий
        итог_p, расход_p = ST.итог_позиции(поз_для_счёта)
        # РАСХОД НА САМУ ОТПРАВКУ СЧИТАЕТСЯ ВСЕГДА -- даже у покупки, которая
        # не села: приоритет и тариф с кошелька уже ушли. Стоп владельца про
        # деньги кошелька, а не про разницу цен.
        расход_сделок_sol += расход_p
        if итог_p is None:
            # Итог неизвестен (позиция ещё открыта или продажа не подтверждена):
            # в счёт идёт только расход, а ноль не выдумывается.
            итог_с_расходом -= расход_p
            непосчитанных += 1
        else:
            итог_с_расходом += итог_p
        # --- то же по цепи ---
        ц_п = цепной_итог_позиции(p)
        if ц_п.get("есть"):
            итог_по_цепи += float(ц_п["итог_sol"])
            цепь_по_цепи_n += 1
        elif итог_p is None:
            # Открытая (или неподтверждённая) позиция: цепного числа быть не
            # может -- в счёт идёт тот же расход на отправку, что и по полям.
            итог_по_цепи -= расход_p
            цепь_открытых_n += 1
            if ц_п.get("почему_нет"):
                цепь_почему_нет.append(str(ц_п["почему_нет"])[:80])
        else:
            # Закрытая, а цепного числа нет: берём поля и ГОВОРИМ об этом.
            итог_по_цепи += итог_p
            цепь_по_полям_n += 1
            if ц_п.get("почему_нет"):
                цепь_почему_нет.append(str(ц_п["почему_нет"])[:80])
    # Разница цен -- справочное поле: итог без расхода на доставку.
    итог_sol = итог_с_расходом + расход_сделок_sol
    # ЧТО ИМЕННО СРАВНИВАЕТСЯ С ПОРОГОМ: итог С РАСХОДОМ на отправку. Раньше
    # это была только разница "продали минус купили", то есть стоп не видел ни
    # чаевых, ни приоритета, ни базового тарифа. С боевым пулом чаевые платятся
    # КАЖДОМУ сервису (до 0.005 SOL на сделку по слову владельца), и двадцать
    # сделок могли увести кошелёк на 0.1 SOL мимо стопа, который при этом
    # показывал бы "0.0".
    несчитаемых = [p for p in за_сутки if p.get("result_uncountable")]
    # ИТОГ ПО ВСЕМ ГРУППАМ СРАЗУ -- для суммарного суточного стопа полосы 0.5
    # SOL (п.1е). Считается той же формулой, что и групповой: иначе два числа
    # про одни деньги разошлись бы.
    итог_всех = 0.0
    итог_всех_цепь = 0.0
    сделок_всех = 0
    for p in все_свои:
        if float(p.get("ts_intent") or 0) < сутки_назад:
            continue
        сделок_всех += 1
        общий_в = ST.делит_минт(p.get("client_order_id"), p, позиции, индекс=_инд)
        поз_в = dict(p)
        if общий_в:
            поз_в["uncountable_shared_mint"] = общий_в
        итог_в, расход_в = ST.итог_позиции(поз_в)
        итог_всех += (-расход_в if итог_в is None else итог_в)
        ц_в = цепной_итог_позиции(p)
        if ц_в.get("есть"):
            итог_всех_цепь += float(ц_в["итог_sol"])
        else:
            итог_всех_цепь += (-расход_в if итог_в is None else итог_в)
    return {"open": len(открытых), "stuck": len(зависших),
            # СУТКИ: начало и как посчитано -- в отчёт, чтобы "за сутки" можно
            # было проверить, а не принимать на слово.
            "day": сут["day"], "day_start_ts": сут["ts"], "day_how": сут["how"],
            "pnl_all_groups_sol": round(итог_всех, 9),
            # ПО ЦЕПИ (Правило 13) -- ровно это число сравнивает групповой стоп.
            "pnl_chain_sol": round(итог_по_цепи, 9),
            "pnl_chain_all_groups_sol": round(итог_всех_цепь, 9),
            # Из чего оно сложилось: сколько сделок дали число ЦЕПИ, сколько
            # пришлось взять по полям и сколько открыты (у них цепи быть не
            # может). Без этих трёх чисел "по цепи" нечем проверить.
            "pnl_chain_n": цепь_по_цепи_n,
            "pnl_chain_fields_n": цепь_по_полям_n,
            "pnl_chain_open_n": цепь_открытых_n,
            "pnl_chain_why_not": цепь_почему_нет[:3],
            # Расхождение учёта и цепи за сутки по этой группе -- контроль, а не
            # запрет: по нему владелец видит бэкфил, не дожидаясь ложного стопа.
            "pnl_vs_chain_sol": round(итог_с_расходом - итог_по_цепи, 9),
            "today_all_groups": сделок_всех,
            "today": len(за_сутки),
            "hour": len(за_час),
            "failed_in_row": подряд,
            # pnl_sol -- ИТОГ С РАСХОДОМ: именно его сравнивает стоп владельца.
            # Разница цен осталась отдельным полем, чтобы было видно, где
            # потеряно: на рынке или на доставке.
            "pnl_sol": round(итог_с_расходом, 9),
            "pnl_trade_sol": round(итог_sol, 9),
            "spend_sol": round(расход_сделок_sol, 9),
            # Несчитаемые считаются ОТДЕЛЬНО и НИЧЕГО не запрещают: они и
            # нужны для того, чтобы такие пары не притворялись удачными.
            "uncountable_today": len(несчитаемых),
            # Сколько сделок за сутки вообще не дали числа итога (открыты или
            # продажа не подтверждена). Это НЕ то же самое, что несчитаемые:
            # у несчитаемых итог теперь считается по возврату и входу.
            "no_result_today": непосчитанных,
            "uncountable_why": [str(p.get("result_uncountable_why") or "")[:80]
                                 for p in несчитаемых][:5],
            "total": len(свои),
            "group": группа or "деньги (все группы кроме скорости)",
            # РАСХОД ЗА СУТКИ ВМЕСТЕ С КУПЛЕННОЙ СУММОЙ -- оставлен как
            # справка (оборот за сутки), но потолок группы его БОЛЬШЕ НЕ
            # сравнивает: уточнение владельца 25.09 (вечер) -- "потолок 1 SOL --
            # только чаевые + приоритет + тариф; сами покупки 0.01 в него не
            # идут, деньги ограничивает стоп -0.5 SOL за сутки". Купленная сумма
            # и правда не расход: она возвращается продажей.
            "day_turnover_sol": round(
                sum(float(p.get("sol_in") or 0.0) + стоимость_сделки_sol(p)
                    for p in за_сутки), 9),
            # А ВОТ ЧТО СРАВНИВАЕТ ПОТОЛОК: только то, что с кошелька ушло и не
            # вернётся -- чаевые, приоритет и тариф сети.
            "day_spend_sol": round(расход_сделок_sol, 9)}


def минт_уже_открыт(позиции: dict | None, минт: str | None, *,
                     сейчас: float | None = None) -> dict:
    """Есть ли УЖЕ открытая позиция полосы по этому минту.

    Слово владельца 28.09: "один открытый минт на кошелёк -- ДА. Второй сигнал
    на тот же минт при открытой позиции отказывается с кодом «минт уже
    открыт»". Причина не только в деньгах: 28.09 дубли по C1mBfBoD и EMBKvWhk
    дали и убыток, и задержку решения (второй экземпляр шёл на 300 мс позже).

    Зависшая позиция тоже считается открытой: токен у нас на руках, и вторая
    покупка того же минта смешала бы остатки, а продавать их пришлось бы одним
    счётом.
    """
    если = {"открыт": False, "cid": None, "минт": минт}
    if not минт:
        return если
    for п in (позиции or {}).values():
        if (п or {}).get("lane") != МЕТКА:
            continue
        if (п or {}).get("mint") != минт:
            continue
        if (п or {}).get("state") in (ST.STATE_CLOSED, "unsold", "closed"):
            continue
        if (п or {}).get("lane_not_landed"):
            continue
        если.update(открыт=True, cid=п.get("client_order_id"))
        return если
    return если


ОКНО_ГРУППЫ_МИНТА_СЛОТОВ = 1800


def окно_слотов_группы_минта_с() -> float:
    """Окно запрета второго минта на группу -- В СЕКУНДАХ.

    Нужно только там, где у сигнала нет слота: по слотам цепи считается
    точнее. Число слотов владельца (1800) умножается на ИЗМЕРЕННУЮ длину
    слота, а не на константу 0.4 -- решение владельца 28.09, вариант 2.
    """
    try:
        return float(ОКНО_ГРУППЫ_МИНТА_СЛОТОВ) * float(длина_слота_s())
    except Exception:  # noqa: BLE001
        return float(ОКНО_ГРУППЫ_МИНТА_СЛОТОВ) * float(ДЛИНА_СЛОТА_S)


# ---- СТОП «АВАРИЯ» НА ГРУППУ (Правило 16, слово владельца 02.10, вечер) ----
# Дневной стоп группы ловил УБЫТОК, а убыток -- это рынок. Авария ловит
# ОШИБКУ: наши деньги ушли, а сделки не получилось. Признаки назвал владелец:
#   (а) 2 позиции подряд закрыты БЕЗ ПРОДАЖИ или с итогом -100 %;
#   (б) 3 неудачные попытки продажи подряд по ОДНОЙ позиции;
#   (в) покупка села, а токенов на нашем счёте НОЛЬ.
# Обычная плохая серия (пять убыточных сделок подряд, но все проданы) аварией
# НЕ является -- это прямое слово владельца, и на этом стоит проверка.
АВАРИЯ_БЕЗ_ПРОДАЖИ_ПОДРЯД = 2
АВАРИЯ_НЕУДАЧ_ПРОДАЖИ_ПОДРЯД = 3


def _продана_ли(п: dict) -> bool:
    """Была ли продажа. Доказательство -- ПОДПИСЬ или признанный итог продажи.

    ИМЕНА ПОЛЕЙ -- ИЗ ЖИВОГО ЖУРНАЛА, А НЕ ИЗ ВЫГРУЗКИ. 02.10 в 19:06Z первая
    версия смотрела только sell_sig -- поле ВЫГРУЗКИ сделок, которого в
    positions.jsonl нет вовсе. Поэтому КАЖДАЯ закрытая позиция читалась как
    непроданная, и признак (а) дал аварию шести группам из семи сразу. В самом
    журнале продажа видна по lane_chain_sell_sig (подпись, сверенная по цепи),
    last_sell_reported / last_sell_signatures (что отправил сторож) и
    last_sell_outcome.ok (итог попытки). Проверяются все, и выгрузочные имена
    тоже -- этой же функцией считают и по выгрузке.
    """
    п = п or {}
    if п.get("lane_chain_sell_sig") or п.get("last_sell_reported"):
        return True
    подписи = п.get("last_sell_signatures")
    if isinstance(подписи, (list, tuple)) and any(подписи):
        return True
    итог = п.get("last_sell_outcome")
    if isinstance(итог, dict) and итог.get("ok") is True:
        return True
    if "продажа полосы подтверждена" in str(п.get("closed_reason") or ""):
        return True
    return bool(п.get("sell_sig") or п.get("sell_signature"))


def _токен_остался_у_нас(п: dict) -> dict:
    """Остался ли купленный токен на нашем счёте к закрытию позиции.

    {'знаем', 'остался', 'почему'}. ЗАЧЕМ ЭТО ОТДЕЛЬНО. Сторож закрывает
    позицию строкой "продавать нечего: ... остаток минта 0" -- и это НЕ
    неудача продажи: нулевой остаток значит, что токен со счёта УШЁЛ, то есть
    он продан -- нами или владельцем вручную. Ровно так закрыты BTN и Fantasy
    Index 6900 (01.10, слово владельца: проданы вне службы, +0.0137 и +0.0134).
    Авария же ловит случай "деньги ушли, а сделки не получилось", и путать с
    ним чужую продажу нельзя: 02.10 в 19:18:43Z признак (а) встал у cand1
    именно на этой паре.
    """
    из_ = {"знаем": False, "остался": None, "почему": None}
    п = п or {}
    причина = str(п.get("closed_reason") or "")
    м = re.search(r"остаток минта (\d+)", причина)
    if м:
        из_.update(знаем=True, остался=(int(м.group(1)) > 0),
                    почему=f"из причины закрытия: остаток минта {м.group(1)}")
        return из_
    if "остаток ноль" in причина or "крошка" in причина:
        из_.update(знаем=True, остался=False, почему=причина[:80])
        return из_
    ост = п.get("sell_ostatok_raw")
    if isinstance(ост, int):
        из_.update(знаем=True, остался=(ост > 0),
                    почему=f"поле остатка {ост}")
        return из_
    из_["почему"] = "остаток минта к закрытию в записи не назван"
    return из_


def _покупка_села(п: dict) -> bool:
    """Села ли покупка в цепь. Не села -- денег в токене нет, и авария не о ней.

    Доказательство -- либо признак цепи, либо купленное количество. Незнание
    НЕ считается севшей покупкой: аварию надо доказывать, а не предполагать.
    """
    if (п or {}).get("chain_ok") is True:
        return True
    куплено = (п or {}).get("lane_bought_raw")
    return isinstance(куплено, int) and куплено > 0


def _итог_минус_сто(п: dict) -> bool:
    """Итог -100 %: вернулось ноль при ненулевом входе.

    Считается по цепному итогу, если он есть (Правило 13), иначе по возврату.
    Незнание -100 % НЕ даёт: признак должен быть доказан, а не предположен.
    """
    вход = (п or {}).get("sol_in")
    if not isinstance(вход, (int, float)) or float(вход) <= 0:
        return False
    # ИМЯ ЦЕПНОГО ПОЛЯ ЗДЕСЬ НЕ ПИШЕТСЯ: оно живёт в одном месте
    # (c2_itog_po_cepi), и гейт читает его через обёртку. Проверка
    # "имя цепного поля в рабочей части не продублировано" ловит обратное.
    ц = цепной_итог_позиции(п or {})
    итог = ц.get("итог_sol") if ц.get("есть") else None
    if isinstance(итог, (int, float)):
        # Минус весь вход (с поправкой на чаевые и приоритет -- они сверху
        # входа): считаем -100 % при потере не меньше самого входа.
        return float(итог) <= -float(вход)
    возврат = (п or {}).get("closed_sol_net")
    if isinstance(возврат, (int, float)):
        return float(возврат) <= 0.0
    return False


def признаки_аварии(позиции: dict, группа: str | None, *,
                     сейчас: float | None = None) -> dict:
    """Есть ли у группы признак ОШИБКИ (а/б/в). Чистая функция, без состояния.

    {'авария', 'признак', 'что', 'число', 'почему_нет'}. Признак назван буквой
    владельца, чтобы в тревоге и в докладе стояло то же слово, что в его пакете.

    ТРИ ГРАНИЦЫ, И КАЖДАЯ СТОИТ ЗДЕСЬ НЕ ДЛЯ КРАСОТЫ. Первая версия этой
    функции смотрела ВСЮ историю позиций и считала плохой любую закрытую без
    продажи. На живом журнале 02.10 в 19:06Z она дала аварию ШЕСТИ группам из
    семи сразу -- то есть остановила бы всю полосу на старых записях. Поэтому:

      1. СУТКИ. Считаются только позиции, ЗАКРЫТЫЕ в текущих сутках по
         Мадриду. Пара закрытий вчерашней ночью -- это не идущая ошибка, а
         история, и останавливать по ней нельзя.
      2. ТОЛЬКО СЕВШИЕ ПОКУПКИ. Покупка, которая в цепь не села, денег в
         токене не оставила: там потерян только расход на попытку, и такие
         серии ловит свой предел (пять упавших подряд). Авария -- про случай
         "деньги ушли, а сделки не получилось".
      3. ПОДРЯД -- ЭТО ПОСЛЕДНИЕ ДВА ЗАКРЫТИЯ. Не "где-то в истории нашлись
         две рядом", а именно ДВА последних: признак должен говорить о том, что
         идёт СЕЙЧАС.
    """
    из_ = {"авария": False, "признак": None, "что": None, "число": None,
            "почему_нет": None}
    if not группа:
        из_["почему_нет"] = "группа не названа -- аварию считать не по чему"
        return из_
    свои = [p for p in (позиции or {}).values()
            if isinstance(p, dict) and p.get("lane") == МЕТКА
            and (p.get("lane_group") or p.get("group")) == группа]
    if not свои:
        из_["почему_нет"] = f"позиций группы {группа} нет"
        return из_
    сут = начало_суток(сейчас)
    начало = float(сут["ts"])

    def _сегодня(п: dict) -> bool:
        # Время ЗАКРЫТИЯ, а при его отсутствии -- время последней правки
        # записи: у живой позиции ts_closed ещё нет, а судить о ней надо.
        т = п.get("ts_closed") or п.get("ts_update") or п.get("ts_intent")
        return isinstance(т, (int, float)) and float(т) >= начало

    сегодня = [p for p in свои if _сегодня(p)]
    if not сегодня:
        из_["почему_нет"] = (f"у группы {группа} нет позиций, закрытых в эти "
                              f"сутки ({сут['day']} по {сут['how']})")
        return из_
    # (в) ПОКУПКА СЕЛА, А ТОКЕНОВ НОЛЬ. Самый прямой признак ошибки: деньги
    # ушли в цепь, цепь сделку приняла, а покупать было нечего.
    for п in сегодня:
        if п.get("chain_ok") is True and п.get("lane_bought_raw") == 0:
            из_.update(авария=True, признак="в",
                        что="покупка села, а токенов на нашем счёте ноль",
                        число=f"минт {str(п.get('mint') or '?')[:8]}, "
                              f"сделка {п.get('client_order_id') or '?'}")
            return из_
    # (б) ТРИ НЕУДАЧНЫЕ ПОПЫТКИ ПРОДАЖИ ПОДРЯД ПО ОДНОЙ ПОЗИЦИИ. Только по
    # ЖИВОЙ позиции: закрытую мы уже не продаём, и её случай ловит признак (а).
    for п in сегодня:
        попыток = п.get("sell_attempts")
        if (isinstance(попыток, int) and попыток >= АВАРИЯ_НЕУДАЧ_ПРОДАЖИ_ПОДРЯД
                and not _продана_ли(п)
                and п.get("state") not in (ST.STATE_CLOSED, "closed", "unsold")):
            из_.update(авария=True, признак="б",
                        что=(f"{попыток} неудачные попытки продажи подряд по "
                              "одной позиции"),
                        число=f"сделка {п.get('client_order_id') or '?'}, "
                              f"попыток {попыток}")
            return из_
    # (а) ДВА ПОСЛЕДНИХ ЗАКРЫТИЯ -- БЕЗ ПРОДАЖИ ИЛИ С -100 %. Порядок по
    # времени ЗАКРЫТИЯ: его и видит владелец.
    закрытые = [p for p in сегодня
                if p.get("state") in (ST.STATE_CLOSED, "closed", "unsold")
                and _покупка_села(p)]
    закрытые.sort(key=lambda p: float(p.get("ts_closed")
                                       or p.get("ts_intent") or 0.0))
    последние = закрытые[-АВАРИЯ_БЕЗ_ПРОДАЖИ_ПОДРЯД:]

    def _плохое_закрытие(п: dict) -> str | None:
        """Почему это закрытие -- ошибка. None -- не ошибка.

        ДВА СЛУЧАЯ, И ОБА ОЗНАЧАЮТ "ДЕНЬГИ УШЛИ, А СДЕЛКИ НЕ ПОЛУЧИЛОСЬ":
          * итог -100 % -- вернулось ноль при ненулевом входе;
          * токен ОСТАЛСЯ у нас, а позицию закрыли -- это и есть непроданная
            позиция (UNSOLD).
        НЕ ошибка: закрытие с НУЛЕВЫМ остатком без нашей подписи продажи --
        токен со счёта ушёл, значит он продан (нами или владельцем вручную), и
        деньги за него есть, просто не в нашем журнале. Незнание остатка тоже
        НЕ ошибка: аварию надо доказывать, а не предполагать.
        """
        if _итог_минус_сто(п):
            return "итог -100 %"
        if _продана_ли(п):
            return None
        ост = _токен_остался_у_нас(п)
        if ост.get("знаем") and ост.get("остался"):
            return f"токен остался у нас ({ост.get('почему')})"
        if п.get("state") == "unsold":
            return "позиция закрыта как UNSOLD"
        return None

    почему_плохо = [_плохое_закрытие(п) for п in последние]
    if (len(последние) == АВАРИЯ_БЕЗ_ПРОДАЖИ_ПОДРЯД
            and all(почему_плохо)):
        имена = ", ".join(f"{x.get('client_order_id') or '?'} ({п})"
                           for x, п in zip(последние, почему_плохо))
        из_.update(авария=True, признак="а",
                    что=(f"{len(последние)} последние позиции закрыты с "
                          "потерей всего входа или непроданными"),
                    число=f"сделки {имена}")
        return из_
    из_["почему_нет"] = (f"признаков ошибки у группы {группа} нет "
                          f"(за сутки позиций {len(сегодня)}, из них севших "
                          f"закрытых {len(закрытые)})")
    return из_


def можно_отправлять(позиции: dict, *, kill: bool = False,
                      сейчас: float | None = None,
                      группа: str | None = None,
                      минт: str | None = None,
                      размер_лампорты: int | None = None,
                      состояние=None,
                      счёт_по_цепи: dict | None = None,
                      слот: int | None = None,
                      подпись_источника: str | None = None) -> dict:
    # размер_лампорты оставлен для вызывающих, но в ПОТОЛОК он больше не идёт:
    # уточнение владельца 25.09 (вечер) -- сама покупка в потолок не входит.
    """Пропускать ли ещё одну сделку полосы. Отказ называется словами.

    Пределы зависят от ГРУППЫ ИСТОЧНИКА: у группы скорости свой суточный
    потолок РАСХОДА (0.2 SOL вместе с чаевыми) и свой стоп (-0.15 SOL), а числа
    сделок у неё нет вовсе -- потолок денег кончится раньше. У остальных групп
    пределы владельца: 50 сделок, -0.3 SOL, 5 упавших подряд.
    """
    с = состояние_полосы(позиции, сейчас=сейчас, группа=группа)
    пг = потолок_группы(группа)
    по = предел_открытых(группа)
    почему = None
    # СУТОЧНЫЙ СТОП ПО ЦЕПИ СЧИТАЕТСЯ ЗДЕСЬ, ДО ЦЕПОЧКИ ОТКАЗОВ. Внутри elif
    # его считать нельзя: ветка сработала бы и с пустой причиной, закрыв собой
    # проверки, которые идут ниже.
    стоп_суток_почему = None
    if СТОП_ПО_ЦЕПИ:
        ц = (счёт_по_цепи if isinstance(счёт_по_цепи, dict)
              else прочитать_счёт_по_цепи(состояние, сейчас=сейчас))
        if not ц.get("годен"):
            # НЕЗНАНИЕ = ЗАМОК (слово владельца 29.09): цепь не прочитана или
            # число старше предела -- стоп СТОИТ. Молчаливое "значит можно"
            # стоило бы ровно столько, сколько полоса успеет потратить.
            стоп_суток_почему = ("суточный стоп полосы по цепи не прочитан "
                                  f"({ц.get('почему_нет') or 'причина не названа'})"
                                  " -- стоп считается СТОЯЩИМ")
        elif not isinstance(ц.get("итог_с_открытыми_sol"), (int, float)):
            # ОТКРЫТЫЕ ПО ЦЕНЕ ВХОДА ОБЯЗАТЕЛЬНЫ (слово владельца 30.09
            # вечером). Их нет в файле -- значит файл написан старым писателем;
            # брать вместо них сырую просадку нельзя: она считает открытую
            # позицию чистым убытком и закрыла бы полосу на её же покупке.
            # Незнание = замок, как и всюду в этом гейте.
            # СНЯТЫЙ СТОП НЕ ЗАПИРАЕТ НЕЗНАНИЕМ. "Незнание = замок" верно, пока
            # стоп есть: запирать нечем, если проверять нечего. Иначе снятие
            # стопа оставило бы полосу стоять на каждом пробеле счёта по цепи.
            стоп_суток_почему = (None if СТОП_ПОЛОСЫ_СУТКИ_SOL is None else
                                  ("в счёте по цепи нет итога с открытыми по цене "
                                   f"входа ({ц.get('открытых_why_not') or 'поля нет'})"
                                   " -- стоп считается СТОЯЩИМ"))
        elif (СТОП_ПОЛОСЫ_СУТКИ_SOL is not None
                and float(ц["итог_с_открытыми_sol"])
                <= -float(СТОП_ПОЛОСЫ_СУТКИ_SOL)):
            # Источник истины один: баланс кошелька на начало суток минус
            # баланс сейчас минус выводы владельца, ПЛЮС деньги, лежащие в ещё
            # не проданных токенах (по цене входа). Учёт остался контролем и в
            # гейт больше не ходит: 29.09 он закрыл сутки числом -2.189326375
            # при цепных -0.800006050.
            стоп_суток_почему = (f"суточный убыток полосы ПО ЦЕПИ "
                                  f"{ц['итог_с_открытыми_sol']} SOL (просадка "
                                  f"{ц['итог_sol']} плюс открытых по входу "
                                  f"{ц.get('открытых_по_входу_sol')}) при рубильнике "
                                  f"-{СТОП_ПОЛОСЫ_СУТКИ_SOL} -- все группы до "
                                  f"конца суток ({ц.get('день')} по Мадриду)")
    # ЗАЩЁЛКА ГРУППОВОГО СТОПА. Слово владельца 02.10: "пороги не
    # пересчитываются; стоп сохраняемый, снимается только по часам".
    # ЧТО БЫЛО. Групповой стоп НИГДЕ не хранился -- он считался ниже в цепочке
    # как pnl_chain_sol <= -stop_loss_sol по журналу позиций. Значит он снимался
    # САМ, как только суточный итог группы поднимался выше порога: 02.10 cand1
    # стояла на -0.345571818 при пороге -0.3, а к 14:44Z стопов не стало ни
    # одного -- не потому, что их сняли, а потому что число пересчиталось.
    # Перезапуск 14:37Z тут не при чём: терять было нечего.
    #
    # ТЕПЕРЬ ДВЕ ПРИЧИНЫ, И ЗАЩЁЛКА ПЕРВАЯ: стоит защёлка -- отказ, каким бы ни
    # стал итог; сработал пересчёт -- защёлкиваем, чтобы следующий вызов отказал
    # уже по ней. Снимает защёлку ТОЛЬКО смена суток (запись чужих суток не
    # считается) -- то есть часы, а не прибыль.
    #
    # НЕЗНАНИЕ -- ЗАМОК, как и везде на этом пути: файл защёлок не прочитался --
    # считаем стоп стоящим и говорим это словами. Молча торговать при
    # непрочитанном стопе дороже, чем простоять до разбора.
    защёлка_почему = None
    # ПРАВИЛО 16: дневного стопа у групп нет -- значит и защёлка не проверяется.
    # Старая запись суток (cand1 от 02.10) этим и снимается: код её больше не
    # читает, а сам файл остаётся на диске как история.
    if группа and состояние is not None and _суточный_стоп_групп_включён():
        try:
            _з = состояние.стоп_группы_стоит(группа, с.get("day"))
        except Exception as сбой:  # noqa: BLE001
            _з = {"стоит": None,
                   "почему_нет": f"{type(сбой).__name__}: {str(сбой)[:120]}"}
        if _з.get("стоит") is None:
            защёлка_почему = (
                f"стоп группы {группа} не проверить "
                f"({_з.get('почему_нет') or 'причина не названа'}) -- "
                "незнание на денежном пути читается как стоящий стоп")
        elif _з.get("стоит"):
            зап = _з.get("запись") or {}
            защёлка_почему = (
                f"суточный стоп группы {группа} ЗАЩЁЛКНУТ "
                f"{зап.get('поставлен_utc')}: убыток при постановке "
                f"{зап.get('убыток_при_постановке_sol')} SOL при стопе "
                f"{зап.get('порог_sol')} -- снимается только сменой суток "
                f"({зап.get('сутки')} по {зап.get('как_сутки') or 'Мадриду'}), "
                "а не улучшением итога")
    # СТОП «АВАРИЯ» НА ГРУППУ (Правило 16). Считается ДО цепочки по той же
    # причине, что и защёлка, и стоит в цепочке СРАЗУ ПОСЛЕ рубильника:
    # авария -- это признак ошибки, а не предел, и пропускать сигнал, пока
    # она стоит, нельзя ни по какой причине.
    авария_почему = None
    авария_итог = None
    if группа and состояние is not None and hasattr(состояние,
                                                     "авария_группы_стоит"):
        try:
            _а = состояние.авария_группы_стоит(группа)
        except Exception as сбой:  # noqa: BLE001
            авария_почему = (f"авария группы не проверена "
                              f"({type(сбой).__name__}) -- неясность на денежном "
                              "пути читается как стоящая авария")
        else:
            if _а.get("стоит") is None:
                авария_почему = (f"авария группы {группа} не прочитана "
                                  f"({_а.get('почему_нет')}) -- считается СТОЯЩЕЙ")
            elif _а.get("стоит"):
                зп = _а.get("запись") or {}
                авария_почему = (
                    f"авария группы {группа} с {зп.get('поставлена_utc')}: "
                    f"{зп.get('что')} ({зп.get('число')}) -- снимается только "
                    "словом владельца")
            else:
                # ПРИЗНАКИ СЧИТАЮТСЯ ТОЛЬКО ЕСЛИ АВАРИЯ ЕЩЁ НЕ СТОИТ: стоящая
                # уже всё сказала, а второй счёт стоил бы позиций на каждом
                # сигнале.
                try:
                    пр = признаки_аварии(позиции, группа, сейчас=сейчас)
                except Exception as сбой:  # noqa: BLE001
                    пр = {"авария": False,
                           "почему_нет": f"{type(сбой).__name__}"}
                if пр.get("авария"):
                    try:
                        авария_итог = состояние.авария_группы_поставить(
                            группа, признак=пр.get("признак") or "?",
                            что=пр.get("что") or "признак не назван",
                            число=пр.get("число"), сутки=с.get("day"))
                    except Exception as сбой:  # noqa: BLE001
                        авария_итог = {"ok": False, "already": False,
                                        "why_not": f"{type(сбой).__name__}"}
                    авария_почему = (
                        f"авария группы {группа}: {пр.get('что')} "
                        f"({пр.get('число')}) -- пауза до слова владельца")
        # ЗАПРЕТ ВТОРОГО МИНТА НА ГРУППУ (слово владельца 02.10). Считается ДО
    # цепочки по той же причине, что и защёлка: внутри elif ветка сработала бы
    # и с пустой причиной, закрыв собой проверки ниже.
    второй_минт_почему = None
    if группа and минт and состояние is not None \
            and hasattr(состояние, "второй_минт_на_группу"):
        try:
            _зап, _сл = состояние.второй_минт_на_группу(
                группа, минт, slot=(слот if isinstance(слот, int) else None),
                now=сейчас,
                # ПОДПИСЬ СИГНАЛА -- чтобы повтор того же сигнала не назывался
                # вторым минтом на группу (правда о повторе -- в ключе
                # операции, и этот запрет её не подменяет).
                sig=подпись_источника,
                # ОКНО В СЕКУНДАХ -- ПО ИЗМЕРЕННОЙ ДЛИНЕ СЛОТА (решение
                # владельца 28.09, вариант 2). Нужно только когда слота у
                # сигнала нет: по слотам считается точнее.
                окно_с=(окно_слотов_группы_минта_с()))
        except Exception as сбой:  # noqa: BLE001
            второй_минт_почему = (
                f"запрет второго минта на группу не проверен "
                f"({type(сбой).__name__}) -- неясность на денежном пути читается "
                "как запрет")
        else:
            if _зап:
                второй_минт_почему = _сл
    if kill:
        почему = "рубильник KILL включён"
    elif авария_почему:
        почему = авария_почему
    elif not включена():
        почему = "полоса выключена (BLOOM_OWN_SEND не равен 1)"
    elif not полоса_торгует(группа):
        почему = f"по группе {группа} полоса не торгует (lane_trades выключен)"
    elif минт_уже_открыт(позиции, минт, сейчас=сейчас)["открыт"]:
        # ОДИН ОТКРЫТЫЙ МИНТ НА КОШЕЛЁК (слово владельца 28.09). Проверка стоит
        # ПЕРЕД общим пределом открытых: причина точнее, и по её коду считается
        # число в часовой сводке. Иначе при пределе 1 дубль назывался бы просто
        # "открытых позиций 1", и дубли в сводке было бы не отличить.
        почему = "минт уже открыт"
    elif второй_минт_почему:
        # ПОСЛЕ "минт уже открыт" и ПЕРЕД общим пределом: открытый минт -- это
        # про кошелёк, а этот запрет про группу и работает уже ПОСЛЕ продажи,
        # когда позиции нет и первая проверка молчит.
        почему = второй_минт_почему
    elif с["open"] >= по:
        почему = f"открытых позиций полосы {с['open']} при пределе {по}"
    elif пг["per_day"] and с["today"] >= пг["per_day"]:
        почему = f"за сутки уже {с['today']} сделок при пределе {пг['per_day']}"
    elif пг.get("per_hour") is not None and с.get("hour") is None:
        # НЕИЗВЕСТНОЕ СОСТОЯНИЕ -- ЗАПРЕТ, как и всюду на денежном пути.
        # Предел в час задан, а числа за час нет: считать его нулём значило бы
        # пускать покупки мимо предела, который владелец поставил.
        почему = (f"предел {пг['per_hour']} покупок в час задан, а числа за "
                   "час нет -- не знаем, значит не покупаем")
    elif пг.get("per_hour") is not None and с["hour"] >= пг["per_hour"]:
        # ПРЕДЕЛ В ЧАС (слово владельца 10.10, п.2). Окно скользящее: час
        # назад от сейчас, а не календарный час.
        почему = (f"за час уже {с['hour']} покупок при пределе "
                   f"{пг['per_hour']}"
                   + (f" (в поле группы было {пг['per_hour_spor']!r} -- не "
                      "число, поэтому предел ноль)"
                      if пг.get("per_hour_spor") is not None else ""))
    elif с["failed_in_row"] >= СТОП_ПОДРЯД_УПАВШИХ:
        почему = (f"{с['failed_in_row']} упавших подряд -- полоса остановлена "
                   "до разбора")
    elif стоп_суток_почему:
        # СУММАРНЫЙ СУТОЧНЫЙ СТОП ПОЛОСЫ -- ПО ЦЕПИ (слово владельца 29.09).
        # Причина уже посчитана ВЫШЕ цепочки и здесь только вставляется: если
        # считать её прямо в elif, ветка съедает остаток цепочки, и при годной
        # цепи ни групповой стоп, ни потолок расхода уже не проверяются. Именно
        # так и было написано в первой версии этой правки.
        почему = стоп_суток_почему
    elif (not СТОП_ПО_ЦЕПИ) and СТОП_ПОЛОСЫ_СУТКИ_SOL is not None \
            and с.get("pnl_chain_all_groups_sol") is not None and \
            с["pnl_chain_all_groups_sol"] <= -float(СТОП_ПОЛОСЫ_СУТКИ_SOL):
        # ОТКАТНЫЙ ПУТЬ -- ТОЛЬКО ПРИ СНЯТОМ ФЛАГЕ LANE_STOP_CHAIN. Оставлен,
        # чтобы правку 29.09 можно было снять значением env, а не деплоем. Но
        # ЧИСЛО И ЗДЕСЬ ПО ЦЕПИ (Правило 13, 01.10): когда флаг снят, суммарный
        # стоп считается по позициям -- и до этой правки он считал их по
        # журналу, то есть снятый флаг возвращал и ложные стопы на бэкфиле.
        почему = (f"суточный убыток полосы по всем группам ПО ЦЕПИ "
                   f"{с['pnl_chain_all_groups_sol']} SOL при рубильнике "
                   f"-{СТОП_ПОЛОСЫ_СУТКИ_SOL} -- все группы до полуночи "
                   f"({с.get('day')} по Мадриду)"
                   + (f"; по учёту {с['pnl_all_groups_sol']}"
                      if abs(с["pnl_all_groups_sol"]
                              - с["pnl_chain_all_groups_sol"]) > 1e-9 else ""))
    elif защёлка_почему:
        # ЗАЩЁЛКА СИЛЬНЕЕ ПЕРЕСЧЁТА и стоит ПЕРЕД ним: иначе улучшившийся итог
        # прошёл бы ветку пересчёта и до защёлки дело не дошло бы вовсе.
        почему = защёлка_почему
    elif (isinstance(пг.get("stop_loss_sol"), (int, float))
           and с["pnl_chain_sol"] <= -float(пг["stop_loss_sol"])):
        # ГРУППОВОЙ СТОП -- ПО ЦЕПИ (слово владельца 01.10, вечер; Правило 13).
        # Число по полям названо рядом: когда они расходятся, в причине видно
        # сразу, что это бэкфил учёта, а не убыток группы.
        почему = (f"убыток полосы за сутки ПО ЦЕПИ {с['pnl_chain_sol']} SOL при "
                   f"стопе -{пг['stop_loss_sol']}"
                   + (f" (группа {группа})" if группа else "")
                   + (f"; по учёту {с['pnl_sol']}"
                      if abs(с["pnl_sol"] - с["pnl_chain_sol"]) > 1e-9 else "")
                   + (f"; из них по цепи {с['pnl_chain_n']}, по полям "
                      f"{с['pnl_chain_fields_n']}, открытых {с['pnl_chain_open_n']}"))
    elif пг["day_cap_sol"] is not None:
        # ПОТОЛОК РАСХОДА ГРУППЫ. Считается ВПЕРЁД: к уже потраченному за сутки
        # прибавляются предельные чаевые пула этой сделки. Проверять по факту
        # значило бы разрешить сделку, которая сама и прогрызает потолок.
        #
        # САМА ПОКУПКА В ПОТОЛОК НЕ ИДЁТ -- уточнение владельца 25.09 (вечер):
        # "потолок 1 SOL -- только чаевые + приоритет + тариф; сами покупки
        # 0.01 в него не идут, деньги ограничивает стоп -0.5 SOL за сутки".
        # Раньше к потолку прибавлялся и размер сделки, и при 0.01 на сделку
        # потолок 1 SOL кончался бы на 83-й покупке вместо ~490.
        вперёд = с["day_spend_sol"] + ПОТОЛОК_ЧАЕВЫХ_ПУЛА_SOL
        if вперёд > float(пг["day_cap_sol"]):
            почему = (f"потолок расхода группы {группа}: за сутки "
                       f"{round(с['day_spend_sol'], 6)} SOL чаевых и приоритета, "
                       f"эта сделка довела бы до {round(вперёд, 6)} при потолке "
                       f"{пг['day_cap_sol']}")
    # ЗАЩЁЛКНУТЬ СТОП, КОТОРЫЙ ТОЛЬКО ЧТО СРАБОТАЛ ПЕРЕСЧЁТОМ. Делается ПОСЛЕ
    # цепочки и только для группового стопа: иначе следующий вызов с
    # улучшившимся итогом снова разрешил бы покупку, и ровно это и случилось с
    # cand1 02.10. Запись идёт один раз на сутки и первую причину не затирает.
    # Сбой записи НЕ отменяет отказ: в ответе он назван словами, а запрет уже
    # стоит по пересчёту.
    если_защёлкнуть = (почему is not None and группа and состояние is not None
                       and _суточный_стоп_групп_включён()
                       and not защёлка_почему
                       and isinstance(с.get("pnl_chain_sol"), (int, float))
                       and isinstance(пг.get("stop_loss_sol"), (int, float))
                       and float(с["pnl_chain_sol"])
                       <= -abs(float(пг["stop_loss_sol"])))
    защёлка_итог = None
    if если_защёлкнуть:
        try:
            защёлка_итог = состояние.стоп_группы_поставить(
                группа, сутки=с.get("day"), убыток_sol=с.get("pnl_chain_sol"),
                порог_sol=-abs(float(пг["stop_loss_sol"])),
                как_сутки=с.get("day_how"))
        except Exception as сбой:  # noqa: BLE001
            защёлка_итог = {"ok": False,
                             "why_not": f"{type(сбой).__name__}: {str(сбой)[:120]}"}
    из_ = {"ok": почему is None, "why_not": почему, "state": с}
    из_["group_limits"] = пг
    из_["stop_latch"] = защёлка_итог
    # АВАРИЯ -- В ОТВЕТ: по этому полю детектор посылает ОДНО сообщение. Поле
    # появляется только в тот вызов, когда авария ПОСТАВЛЕНА (already=False);
    # на всех следующих сигналах стоит отказ, а сообщения нет.
    из_["avarija_set"] = авария_итог
    return из_


# --------------------------------------------- сколько купила полоса

def купленное_raw(tx: dict, кошелёк: str, минт: str) -> dict:
    """Сколько СЫРЫХ единиц минта прибыло на наш адрес этой транзакцией.

    Это количество -- то самое, которое сторож потом продаёт. Считается
    ТОЛЬКО в сырых единицах (uiTokenAmount.amount): у токена с девятью
    знаками движение в единицах показывается в ui нулём, а пыль -- числом.
    Цена ошибки прямая: по ui продали бы не то количество, что купили.

    Своих счетов минта может быть несколько (ATA плюс созданный в этой же
    транзакции), поэтому суммируем по всем, где владелец -- наш кошелёк.
    Отсутствие счёта в preTokenBalances -- обычный случай: счёт создан
    здесь же, и до транзакции его не было вовсе.
    """
    из_ = {"ok": False, "raw": None, "why_not": None}
    if not isinstance(tx, dict):
        из_["why_not"] = "транзакции нет"
        return из_
    мета = tx.get("meta")
    if not isinstance(мета, dict):
        из_["why_not"] = "у транзакции нет meta -- количество не посчитать"
        return из_
    if мета.get("err") is not None:
        из_["why_not"] = f"транзакция упала: {json.dumps(мета.get('err'), ensure_ascii=False)[:120]}"
        из_["chain_ok"] = False
        return из_
    if not кошелёк or not минт:
        из_["why_not"] = f"нужны кошелёк и минт (кошелёк {кошелёк!r}, минт {минт!r})"
        return из_
    было: dict = {}
    стало: dict = {}
    for где, куда in (("preTokenBalances", было), ("postTokenBalances", стало)):
        for б in (мета.get(где) or []):
            if not isinstance(б, dict) or б.get("owner") != кошелёк:
                continue
            if б.get("mint") != минт:
                continue
            сырое = (б.get("uiTokenAmount") or {}).get("amount")
            try:
                куда[б.get("accountIndex")] = int(сырое)
            except (TypeError, ValueError):
                из_["why_not"] = f"количество не число: {сырое!r}"
                return из_
    if not стало:
        из_["why_not"] = "нашего счёта этого минта в postTokenBalances нет"
        return из_
    дельта = sum(стало.values()) - sum(было.get(и, 0) for и in стало)
    if дельта <= 0:
        из_["why_not"] = f"приход не положителен: {дельта}"
        из_["raw"] = дельта
        return из_
    из_.update(ok=True, raw=дельта, chain_ok=True)
    return из_


def натив_покупки(tx: dict, кошелёк: str) -> dict:
    """Сколько покупка СТОИЛА кошельку полосы -- по самой транзакции.

    ЗАЧЕМ ЭТО ОТДЕЛЬНО ОТ ПОЛЕЙ ПОЗИЦИИ. Расход, собранный из полей (чаевые +
    приоритет + тариф), не видит платы за СОЗДАНИЕ СЧЕТОВ. Живая покупка
    25.09 18:09:41Z: с кошелька ушло 0.053493440, а поля дают 0.052005 --
    разница 0.001488440 осела на счёте, который транзакция создала. На 63
    сделках ночи это 0.09 SOL незамеченного расхода, и ровно на столько
    суточный стоп видел убыток меньше настоящего.

    Возвращает:
      native_sol -- изменение нативного баланса, ОЧИЩЕННОЕ от комиссии сети
                    (комиссия отдельным числом, иначе она бы считалась дважды);
      fee_sol    -- комиссия этой транзакции (приоритет плюс базовый тариф).
    Нет meta или нет кошелька среди счетов -- честный отказ с причиной.
    """
    из_ = {"ok": False, "native_sol": None, "fee_sol": None, "why_not": None}
    мета = (tx or {}).get("meta")
    if not isinstance(мета, dict):
        из_["why_not"] = "у транзакции нет meta -- расход по цепи не посчитать"
        return из_
    сообщение = ((tx or {}).get("transaction") or {}).get("message") or {}
    сырые = сообщение.get("accountKeys") or []
    ключи = [к.get("pubkey") if isinstance(к, dict) else к for к in сырые]
    if not кошелёк or кошелёк not in ключи:
        из_["why_not"] = "кошелька полосы нет среди счетов транзакции"
        return из_
    и = ключи.index(кошелёк)
    до = мета.get("preBalances") or []
    после = мета.get("postBalances") or []
    if и >= len(до) or и >= len(после):
        из_["why_not"] = "балансов по этому счёту в транзакции нет"
        return из_
    комиссия = int(мета.get("fee") or 0)
    дельта = int(после[и]) - int(до[и])
    # Плательщик комиссии -- всегда первый счёт. Очищаем только у него:
    # иначе чужая комиссия попала бы в наш расход.
    if и == 0:
        дельта += комиссия
    из_.update(ok=True,
               native_sol=round(дельта / ЛАМПОРТОВ_В_SOL, 9),
               fee_sol=round(комиссия / ЛАМПОРТОВ_В_SOL, 9))
    # ЧТО ИМЕННО ОСЕЛО НА СЧЕТАХ (слово владельца 29.09 ночью: назвать каждое
    # слагаемое по имени). Нативная дельта покупки -- это билет плюс чаевые
    # плюс то, что осталось на СОЗДАННЫХ этой же транзакцией счетах. Последнее
    # до сих пор было безымянным остатком, и именно из-за него счёт по полям
    # расходился с цепью. Теперь оно раскладывается на два числа.
    из_.update(**рента_и_завёрнутое_покупки(tx, кошелёк))
    return из_


def рента_и_завёрнутое_покупки(tx: dict, кошелёк: str) -> dict:
    """{rent_sol, wrapped_sol, rent_why_not} -- что осталось на НОВЫХ счетах.

    ОБЩАЯ СУММА БЕРЁТСЯ ГОТОВОЙ -- bloom_detector.рента_новых_счетов: она уже
    считает только УДЕРЖАННОЕ (счёт, закрытый в той же транзакции, к концу
    имеет ноль и в сумму не попадает), и второй арифметики для того же числа в
    репозитории быть не должно. Здесь добавляется только РАЗДЕЛЕНИЕ: у счёта
    WSOL его лампорты -- это рента ПЛЮС завёрнутый SOL, и называть завёрнутое
    рентой значит задвоить его (те же лампорты вернутся нативно при закрытии
    счёта).

    Сумма двух чисел равна общей: если не равна, оба отдаются как None и
    причина называется словами -- выдумывать разложение нельзя.
    """
    из_ = {"rent_sol": None, "wrapped_sol": None, "rent_why_not": None}
    try:
        import bloom_detector as BD  # noqa: PLC0415

        всего = float(BD.рента_новых_счетов(tx or {}, кошелёк))
    except Exception as exc:  # noqa: BLE001
        из_["rent_why_not"] = (f"общую сумму на новых счетах не посчитать: "
                                f"{type(exc).__name__}")
        return из_
    мета = (tx or {}).get("meta") or {}
    до_н = мета.get("preBalances") or []
    после_н = мета.get("postBalances") or []
    было = {b.get("accountIndex") for b in (мета.get("preTokenBalances") or [])
             if isinstance(b, dict) and b.get("owner") == кошелёк}
    завёрнуто_л = 0
    for b in мета.get("postTokenBalances") or []:
        if not isinstance(b, dict) or b.get("owner") != кошелёк:
            continue
        и_ = b.get("accountIndex")
        if и_ in было or not isinstance(и_, int):
            continue
        if b.get("mint") != WSOL_МИНТ_МАРШРУТА:
            continue
        if и_ >= len(до_н) or и_ >= len(после_н):
            continue
        # Завёрнутое -- это остаток самого счёта WSOL в лампортах, но не больше
        # того, на сколько счёт вырос: рента отдельно.
        try:
            остаток = int((b.get("uiTokenAmount") or {}).get("amount") or 0)
        except (TypeError, ValueError):
            остаток = 0
        рост = max(0, int(после_н[и_]) - int(до_н[и_]))
        завёрнуто_л += max(0, min(остаток, рост))
    завёрнуто = round(завёрнуто_л / ЛАМПОРТОВ_В_SOL, 9)
    рента = round(всего - завёрнуто, 9)
    if рента < -1e-12 or abs((рента + завёрнуто) - всего) > 1e-9:
        из_["rent_why_not"] = (f"разложение не сходится: всего {всего}, "
                                f"завёрнуто {завёрнуто}")
        return из_
    из_.update(rent_sol=рента, wrapped_sol=завёрнуто)
    return из_


# ЛЕСТНИЦЫ ПЛАТЫ (З3) ЗДЕСЬ НЕТ -- И НЕ ДОЛЖНО БЫТЬ. Владелец отменил её
# 25.09 по итогам З1, и вот почему, чтобы никто не добавил её обратно: в
# 66 % наших покупок перед нами в блоке стояли транзакции, заплатившие
# МЕНЬШЕ нас (171 более дешёвая против 19 более дорогих), а медиана платы
# тех, кто садится в S+0 сразу за источником, -- около 9 500 лампортов
# против наших 995 000. Ступени "средний" и "высокий" оказались бы ниже
# базового уровня, а вопрос "плата или путь" уже отвечен: путь. Тратить на
# лестницу 0.05 SOL и живые сигналы незачем.

# ------------------------------------------------- контроль доставки (З2)

# Слово владельца 25.09: "На каждом сигнале с покупкой полосы -- в ту же
# миллисекунду тем же путём (Helius Sender, те же чаевые) пустая транзакция
# без касания пула (memo или перевод 0 себе)". Смысл замера: если контроль
# садится заметно быстрее покупки, задержка -- это очередь к горячему пулу
# (плата). Если он так же медленный -- задержка в пути, и её надо разбирать
# по этапам.
#
# ПОЧЕМУ ПЕРЕВОД НУЛЯ СЕБЕ, А НЕ MEMO. Владелец разрешил и то и другое.
# Перевод нуля собирается теми же кирпичами, что уже проверены сборкой
# покупки (c2_swap_build.sol_transfer), и не требует заводить в репозитории
# ещё один адрес программы. Получатель -- наш же кошелёк, сумма ноль:
# ошибиться адресом тут нечем.
#
# ЧТО ЭТО СТОИТ. Приоритет и чаевые у контроля ровно те же, что у покупки
# (иначе сравнение нечестно): 0.001 + 0.001 SOL плюс базовая подпись. Отсюда
# два предела владельца: не больше 20 контролей в сутки и не больше 0.03 SOL
# на контроли. Первым срабатывает тот, который ближе.
ЛИМИТ_КОНТРОЛЕЙ_В_СУТКИ = 20
# ПОТОЛОК РАСХОДА НА КОНТРОЛИ. Решение владельца 25.09: "Потолок на контроли
# поднять до 0.1 SOL в сутки, 20 сигналов в сутки" (было 0.05, до того 0.03).
# Двадцать сигналов по пятерым сервисам стоят около 0.0625 SOL -- в 0.1 SOL
# они укладываются, то есть первым срабатывает счёт сигналов, а не деньги.
ПОТОЛОК_РАСХОДА_КОНТРОЛЯ_SOL = 0.1
# И ОТДЕЛЬНО НА СЕРВИС НА СИГНАЛ: "0.001 SOL на сервис на сигнал". Считается
# по УПРАВЛЯЕМОЙ части -- чаевые плюс приоритет; базовый тариф сети за подпись
# (5000 лампортов) неизбежен и в этот предел не входит, но в суточный расход
# считается полностью.
ПОТОЛОК_КОНТРОЛЯ_НА_СЕРВИС_SOL = 0.001
КЛЮЧ_СЧЁТЧИКА_КОНТРОЛЯ = "lane_control"

# ЗАМОК УЧЁТА КОНТРОЛЕЙ. Веер по сервисам уходит ПАРАЛЛЕЛЬНО, а расход
# считается чтением-изменением-записью одного файла счётчиков. Без замка два
# потока читают одно и то же число и по очереди записывают свой итог: один
# расход исчезает, и это ровно тот "неучтённый расход", из-за которого владелец
# велел рубить полосу. Поймано самопроверкой веера 25.09: из двух контролей в
# счётчике оставался один.
_ЗАМОК_КОНТРОЛЯ = threading.Lock()

# ФАЙЛ СЧЁТА КОНТРОЛЕЙ -- СВОЙ, А НЕ ОБЩИЙ counters.json. Общий файл пишут
# чтением-изменением-записью сразу несколько писателей, и один из них -- ДРУГОЙ
# ПРОЦЕСС: сторож продаж, а ещё note_api_result на каждый ответ Bloom. Наш
# внутрипроцессный замок для них не значит ничего: посторонняя запись, начатая
# до нашей, вернёт файл к своему снимку, и суточный расход контролей вместе с
# числом сигналов обнулится. Потолок владельца 0.1 SOL в сутки после каждого
# такого обнуления отсчитывался бы заново -- то есть предел не работал бы.
# Поэтому счёт контролей живёт отдельным файлом и правится под ФАЙЛОВЫМ
# замком: он виден всем процессам на хосте.
ИМЯ_ФАЙЛА_КОНТРОЛЯ = "lane_control_day.json"


def путь_счёта_контроля(состояние):
    """Свой файл счёта рядом с counters.json. Нет пути -- нет файла."""
    п = getattr(состояние, "counters_path", None)
    if п is None:
        return None
    try:
        from pathlib import Path as _P  # noqa: PLC0415

        return _P(п).parent / ИМЯ_ФАЙЛА_КОНТРОЛЯ
    except Exception:  # noqa: BLE001
        return None


class _ФайловыйЗамок:
    """Межпроцессный замок на правку счёта контролей.

    Без него два процесса (детектор и сторож, или два детектора после
    неудачного перезапуска) могут пройти предел одновременно. Не вышло взять
    замок -- работаем без него, но говорим об этом: замок это защита, а не
    условие работы, и молчать о его отсутствии нельзя.
    """

    def __init__(self, путь):
        self.путь = путь
        self.файл = None
        self.почему = None

    def __enter__(self):
        if self.путь is None:
            self.почему = "пути счёта нет -- замок не берётся"
            return self
        try:
            import fcntl  # noqa: PLC0415

            self.путь.parent.mkdir(parents=True, exist_ok=True)
            self.файл = open(str(self.путь) + ".lock", "a+")  # noqa: SIM115
            fcntl.flock(self.файл.fileno(), fcntl.LOCK_EX)
        except Exception as exc:  # noqa: BLE001
            self.почему = f"{type(exc).__name__}: {str(exc)[:120]}"
            self.файл = None
        return self

    def __exit__(self, *_):
        if self.файл is not None:
            try:
                import fcntl  # noqa: PLC0415

                fcntl.flock(self.файл.fileno(), fcntl.LOCK_UN)
            except Exception:  # noqa: BLE001, S110
                pass
            try:
                self.файл.close()
            except Exception:  # noqa: BLE001, S110
                pass
        return False


def _счёт_контроля_читать(состояние) -> dict:
    """Запись счёта контролей: сначала свой файл, потом старый общий.

    Переход со старого места сделан без потери: если своего файла ещё нет, а в
    общих счётчиках сегодняшняя запись есть, берём её как начало. Иначе в день
    перехода потолок начался бы заново.
    """
    п = путь_счёта_контроля(состояние)
    if п is not None and п.exists():
        try:
            return json.loads(п.read_text(encoding="utf-8")) or {}
        except (ValueError, OSError):
            # Битый счёт -- это не повод считать, что расхода не было.
            return {"corrupt": True}
    try:
        с = состояние.counters() or {}
    except Exception as exc:  # noqa: BLE001
        # НЕИЗВЕСТНЫЙ РАСХОД ЗАПРЕЩАЕТ ТРАТИТЬ. Своего файла ещё нет, а старые
        # счётчики не читаются -- значит сколько ушло сегодня, мы не знаем, и
        # это не то же самое, что "ушло ноль".
        return {"corrupt": True, "why_not": f"{type(exc).__name__}"}
    return dict(с.get(КЛЮЧ_СЧЁТЧИКА_КОНТРОЛЯ) or {})


def _счёт_контроля_писать(состояние, з: dict) -> dict:
    п = путь_счёта_контроля(состояние)
    if п is None:
        # Состояние без пути (заглушка в самопроверке) -- пишем как раньше, в
        # общие счётчики: на хосте этот путь есть всегда.
        try:
            с = состояние.counters() or {}
            с[КЛЮЧ_СЧЁТЧИКА_КОНТРОЛЯ] = з
            состояние.save_counters(с)
            return {"ok": True}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False, "why_not": f"{type(exc).__name__}: {str(exc)[:160]}"}
    try:
        import bloom_exec_state as _ST  # noqa: PLC0415

        _ST.atomic_write_json(п, з)
        return {"ok": True}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "why_not": f"{type(exc).__name__}: {str(exc)[:160]}"}


def проверить_и_учесть_контроль(состояние, *, цена_лампорты: int,
                                 сейчас: float | None = None,
                                 новый_сигнал: bool = True) -> dict:
    """Предел и запись расхода -- ОДНИМ неделимым шагом, под замком.

    Порядок именно такой: сначала убедиться, что можно, и сразу же записать
    расход. Между этими двумя действиями не должно влезать ничего -- ни
    соседний поток веера, ни отправка.
    """
    with _ЗАМОК_КОНТРОЛЯ, _ФайловыйЗамок(путь_счёта_контроля(состояние)):
        можно = можно_контроль(состояние, цена_лампорты=цена_лампорты,
                                сейчас=сейчас, новый_сигнал=новый_сигнал)
        if not можно.get("ok"):
            return {"ok": False, "why_not": можно.get("why_not"),
                     "limits": можно.get("state"), "accounted": None}
        учёт = учесть_контроль(состояние, цена_лампорты=цена_лампорты,
                                сейчас=сейчас, новый_сигнал=новый_сигнал)
    return {"ok": bool(учёт.get("ok")), "why_not": учёт.get("why_not"),
             "limits": можно.get("state"), "accounted": учёт}


def контроль_включён() -> bool:
    return (os.environ.get("BLOOM_LANE_CONTROL") or "").strip() == "1"


def цена_контроля_лампорты(*, приоритет_лампорты: int | None = None,
                            чаевые_лампорты: int | None = None) -> int:
    """Во сколько обходится один контроль, если он сядет.

    Считаем ПЕССИМИСТИЧНО и до отправки: приоритет платится за запрошенный
    предел CU целиком, чаевые -- полностью, плюс базовый тариф за подпись.
    Занизить эту цену значит прогрызть потолок 0.03 SOL незаметно.
    """
    п = (приоритет_лампорты if приоритет_лампорты is not None
         else int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)))
    ч = (чаевые_лампорты if чаевые_лампорты is not None
         else int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)))
    return int(п) + int(ч) + 5000


def _день_utc(сейчас: float | None = None) -> str:
    return time.strftime("%Y%m%d", time.gmtime(сейчас if сейчас else time.time()))


def расход_контроля(состояние, *, сейчас: float | None = None) -> dict:
    """Сколько контролей и на сколько лампортов уже ушло СЕГОДНЯ.

    Сутки -- UTC, как и суточный предел покупок полосы: два разных начала
    суток в одном модуле означали бы, что один предел уже сработал, а второй
    ещё нет, и объяснить это было бы нечем.
    """
    из_ = {"day": _день_utc(сейчас), "n": 0, "signals": 0,
           "spent_lamports": 0, "why_not": None}
    if состояние is None or not hasattr(состояние, "counters"):
        из_["why_not"] = "состояние не умеет считать -- расход контроля неизвестен"
        return из_
    try:
        з = _счёт_контроля_читать(состояние)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"счёт контролей не прочитан: {type(exc).__name__}"
        return из_
    if з.get("corrupt"):
        из_["why_not"] = ("счёт контролей повреждён -- считаем, что тратить "
                           "нельзя, пока человек не разберётся")
        return из_
    if з.get("day") == из_["day"]:
        из_["n"] = int(з.get("n") or 0)
        # СИГНАЛЫ -- это события "контроль на сигнале", а не транзакции: с
        # веером по сервисам на один сигнал уходит несколько контролей.
        # У прежних записей поля signals нет -- там один контроль и был одним
        # сигналом, поэтому берём n.
        из_["signals"] = int(з.get("signals") if з.get("signals") is not None
                              else з.get("n") or 0)
        из_["spent_lamports"] = int(з.get("spent_lamports") or 0)
    из_["spent_sol"] = из_["spent_lamports"] / ЛАМПОРТОВ_В_SOL
    return из_


def можно_контроль(состояние, *, цена_лампорты: int,
                    сейчас: float | None = None,
                    новый_сигнал: bool = True) -> dict:
    """Пределы контроля: 20 СИГНАЛОВ в сутки И не больше 0.05 SOL. Оба -- до
    отправки.

    ПОЧЕМУ 20 СЧИТАЕТСЯ ПО СИГНАЛАМ, А НЕ ПО ТРАНЗАКЦИЯМ. Предел "не больше
    20 контролей в сутки" владелец назвал, когда контроль был один на сигнал.
    Веер по сервисам (владелец 25.09: "контрольную транзакцию через КАЖДЫЙ
    подключённый сервис") превращает один сигнал в несколько транзакций, и
    при счёте по транзакциям четырёх сервисов хватило бы на четыре сигнала --
    З2 на десяти парах стал бы недостижим. Поэтому счёт 20 -- по событиям
    "контроль на сигнале", а ДЕНЬГИ ограничены как сказано: 0.05 SOL в сутки
    и 0.001 SOL на сервис на сигнал. Потратить больше названного нельзя ни в
    какой трактовке -- меняется только, сколько сигналов в эти деньги влезет.

    Неизвестный расход запрещает отправку: "счётчики не прочитались" не
    имеет права означать "трать дальше".
    """
    р = расход_контроля(состояние, сейчас=сейчас)
    если = None
    потолок = int(round(ПОТОЛОК_РАСХОДА_КОНТРОЛЯ_SOL * ЛАМПОРТОВ_В_SOL))
    if р.get("why_not"):
        если = р["why_not"]
    elif новый_сигнал and р["signals"] >= ЛИМИТ_КОНТРОЛЕЙ_В_СУТКИ:
        если = (f"{р['signals']} сигналов с контролем за сутки при пределе "
                 f"{ЛИМИТ_КОНТРОЛЕЙ_В_СУТКИ}")
    elif р["spent_lamports"] + int(цена_лампорты) > потолок:
        если = (f"расход контроля {(р['spent_lamports'] + int(цена_лампорты)) / ЛАМПОРТОВ_В_SOL} "
                f"SOL вышел бы за потолок {ПОТОЛОК_РАСХОДА_КОНТРОЛЯ_SOL} SOL")
    return {"ok": если is None, "why_not": если, "state": р}


def учесть_контроль(состояние, *, цена_лампорты: int,
                     сейчас: float | None = None,
                     новый_сигнал: bool = True) -> dict:
    """Расход контроля на диск СРАЗУ, ещё до ответа Sender.

    Пессимизм намеренный: транзакция могла уйти и сесть, даже если ответ до
    нас не дошёл. Незаписанный расход -- это тихо прогрызенный потолок.
    """
    if состояние is None or not hasattr(состояние, "counters"):
        return {"ok": False, "why_not": "состояние не умеет считать"}
    try:
        день = _день_utc(сейчас)
        з = _счёт_контроля_читать(состояние)
        if з.get("corrupt"):
            return {"ok": False, "why_not": "счёт контролей повреждён"}
        if з.get("day") != день:
            з = {"day": день, "n": 0, "signals": 0, "spent_lamports": 0}
        было_сигналов = int(з.get("signals") if з.get("signals") is not None
                             else з.get("n") or 0)
        з["n"] = int(з.get("n") or 0) + 1
        з["signals"] = было_сигналов + (1 if новый_сигнал else 0)
        з["spent_lamports"] = int(з.get("spent_lamports") or 0) + int(цена_лампорты)
        з["last_ts"] = сейчас if сейчас else time.time()
        зап = _счёт_контроля_писать(состояние, з)
        if not зап.get("ok"):
            return {"ok": False, "why_not": зап.get("why_not")}
        return {"ok": True, "state": з}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "why_not": f"{type(exc).__name__}: {str(exc)[:160]}"}


def отметить_сигнал_контроля(состояние, *, сейчас: float | None = None) -> dict:
    """Один сигнал -- одна отметка в суточном счёте СИГНАЛОВ.

    Зачем отдельно от учёта денег. Предел владельца "20 в сутки" считается по
    сигналам, а на сигнале уходит веер из нескольких транзакций. Пока был
    отдельный "основной" контроль, сигнал отмечал он; его убрали (Helius уже в
    веере), и без этой отметки предел 20 не срабатывал бы ВООБЩЕ -- сутки
    контролей ограничивались бы только деньгами. Проверка и запись -- один шаг
    под тем же замком, что и деньги: иначе два сигнала в двух потоках оба
    увидят "сигналов 19" и оба пройдут.
    """
    сейчас = сейчас if сейчас is not None else time.time()
    with _ЗАМОК_КОНТРОЛЯ, _ФайловыйЗамок(путь_счёта_контроля(состояние)) as фз:
        р = расход_контроля(состояние, сейчас=сейчас)
        if р.get("why_not"):
            return {"ok": False, "why_not": р["why_not"], "state": р}
        if р["signals"] >= ЛИМИТ_КОНТРОЛЕЙ_В_СУТКИ:
            return {"ok": False, "state": р,
                     "why_not": (f"{р['signals']} сигналов с контролем за сутки "
                                  f"при пределе {ЛИМИТ_КОНТРОЛЕЙ_В_СУТКИ}")}
        try:
            день = _день_utc(сейчас)
            з = _счёт_контроля_читать(состояние)
            if з.get("day") != день:
                з = {"day": день, "n": 0, "signals": 0, "spent_lamports": 0}
            з["signals"] = int(з.get("signals") if з.get("signals") is not None
                                else з.get("n") or 0) + 1
            з["last_signal_ts"] = сейчас
            зап = _счёт_контроля_писать(состояние, з)
            if not зап.get("ok"):
                return {"ok": False,
                         "why_not": f"отметка сигнала не записана: {зап.get('why_not')}"}
            return {"ok": True, "state": з, "lock_why_not": фз.почему}
        except Exception as exc:  # noqa: BLE001
            return {"ok": False,
                     "why_not": f"отметка сигнала не записана: {type(exc).__name__}"}


def собрать_контроль(*, наш_кошелёк: str, cu_units: int = ПРЕДЕЛ_CU_ПОКУПКИ,
                      приоритет_лампорты: int | None = None,
                      чаевые_лампорты: int | None = None,
                      семя: str | None = None,
                      сервис: str | None = None) -> dict:
    """Пустая транзакция ТЕМ ЖЕ путём: приоритет, перевод нуля себе, чаевые.

    Пула она не касается вовсе -- в этом и смысл: всё, что отличает её от
    покупки, это отсутствие свопа. Если она садится раньше -- мешает пул.

    СЕРВИС задаёт, КОМУ чаевые и сколько: адрес и минимум берутся из реестра
    отправителей (data/senders.json, собран из их документации). Без сервиса
    всё как раньше -- счёт Helius Sender из списка репозитория. У контроля
    приоритет по умолчанию НУЛЕВОЙ, когда сервис задан: пустая транзакция за
    место в пуле не соперничает, и платить за приоритет ей незачем -- мы мерим
    путь отправителя, а не очередь.
    """
    из_ = {"ok": False, "why_not": None, "tip_account": None, "build_ms": None}
    t0 = time.perf_counter()
    if not наш_кошелёк:
        из_["why_not"] = "кошелёк полосы не задан -- контроль собирать не на что"
        return из_
    реестр_сервиса = None
    if сервис:
        try:
            import bloom_senders as SS  # noqa: PLC0415
        except Exception as exc:  # noqa: BLE001
            из_["why_not"] = f"реестр отправителей не загружен: {type(exc).__name__}"
            return из_
        реестр_сервиса = SS.реестр().get(сервис)
        if not реестр_сервиса:
            из_["why_not"] = f"отправителя {сервис} нет в реестре"
            return из_
        if приоритет_лампорты is None:
            приоритет_лампорты = 0
        if чаевые_лампорты is None:
            чаевые_лампорты = SS.минимум_чаевых(сервис)
    приоритет_лампорты = (приоритет_лампорты if приоритет_лампорты is not None
                          else int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)))
    чаевые_лампорты = (чаевые_лампорты if чаевые_лампорты is not None
                       else int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)))
    # ПРЕДЕЛ НА СЕРВИС НА СИГНАЛ -- до сборки: управляемая часть (чаевые плюс
    # приоритет) не имеет права выйти за 0.001 SOL.
    if сервис:
        управляемое = int(приоритет_лампорты) + int(чаевые_лампорты)
        потолок_с = int(round(ПОТОЛОК_КОНТРОЛЯ_НА_СЕРВИС_SOL * ЛАМПОРТОВ_В_SOL))
        if управляемое > потолок_с:
            из_["why_not"] = (f"контроль через {сервис}: чаевые и приоритет "
                               f"{управляемое} лампортов выше предела {потолок_с} "
                               "на сервис на сигнал")
            return из_
    try:
        _, _, _, B = _модули()
        from solders.hash import Hash  # noqa: PLC0415
        from solders.message import MessageV0  # noqa: PLC0415
        from solders.pubkey import Pubkey  # noqa: PLC0415
        from solders.signature import Signature  # noqa: PLC0415
        from solders.transaction import VersionedTransaction  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"модули сборки контроля не загружены: {type(exc).__name__}"
        return из_
    if сервис:
        import bloom_senders as SS  # noqa: PLC0415

        чаевые = SS.счёт_чаевых(сервис, семя=семя)
        разрешённые = set((реестр_сервиса or {}).get("tip_accounts") or [])
        if not чаевые or чаевые not in разрешённые:
            из_["why_not"] = (f"адрес чаевых не из списка сервиса {сервис} -- "
                               "сборка отменена")
            return из_
    else:
        чаевые = выбрать_чаевые(семя)
        if чаевые not in TIP_ACCOUNTS:
            из_["why_not"] = "адрес чаевых не из списка счетов Sender -- сборка отменена"
            return из_
    try:
        инструкции = [B.cu_limit(cu_units),
                      B.cu_price(цена_единицы_cu(приоритет_лампорты, cu_units)),
                      # ПЕРЕВОД НУЛЯ СЕБЕ. Ни пула, ни чужого адреса.
                      B.sol_transfer(наш_кошелёк, наш_кошелёк, 0),
                      B.sol_transfer(наш_кошелёк, чаевые, чаевые_лампорты)]
        сообщение = MessageV0.try_compile(Pubkey.from_string(наш_кошелёк),
                                           инструкции, [], Hash.default())
        подписей = сообщение.header.num_required_signatures
        vtx = VersionedTransaction.populate(сообщение,
                                             [Signature.default()] * подписей)
        сырое = bytes(vtx)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"сборка контроля: {type(exc).__name__}: {str(exc)[:160]}"
        return из_
    import base64 as _b64  # noqa: PLC0415
    из_.update(ok=True, tx_base64=_b64.b64encode(сырое).decode(), size=len(сырое),
               tip_account=чаевые, priority_lamports=приоритет_лампорты,
               tip_lamports=чаевые_лампорты, sender=сервис,
               cost_lamports=цена_контроля_лампорты(
                   приоритет_лампорты=приоритет_лампорты,
                   чаевые_лампорты=чаевые_лампорты),
               build_ms=round((time.perf_counter() - t0) * 1000, 3))
    return из_


# ОДИНОЧНОГО КОНТРОЛЯ (провести_контроль / подготовить_контроль) ЗДЕСЬ БОЛЬШЕ
# НЕТ. Решение владельца 25.09: "убрать отдельный основной контроль через
# Helius -- Helius уже есть в веере, это дубль". Одна и та же пустая
# транзакция уходила Helius'у дважды: один раз путём полосы, второй -- в веере
# по сервисам, и платились обе. Возвращать её нельзя: замер от этого не
# становится точнее, а сутки контролей дорожают на треть.

# ---------------------------------- контроль через КАЖДЫЙ отправитель (З2+пул)

# Владелец 25.09: "З2 расширить: контрольную транзакцию ... через КАЖДЫЙ
# подключённый сервис ... Предел: 0.001 SOL на сервис на сигнал, всего
# <= 0.05 SOL в сутки на контроли."
#
# ЗАЧЕМ. Один и тот же пустой байт, ушедший в одну и ту же миллисекунду
# разными путями, отвечает на вопрос, который нельзя решить чтением
# документации: КТО ИЗ ОТПРАВИТЕЛЕЙ ДОВОЗИТ БЫСТРЕЕ. По З1 мы знаем, что
# отстаём путём, а не платой; здесь мы сравниваем пути на своих деньгах, но
# на суммах, которые владелец назвал сам.
#
# ЧЕГО ЗДЕСЬ НЕТ. Покупок: контроль -- перевод нуля себе плюс чаевые, пула он
# не касается. Чужих адресов: счёт чаевых берётся только из реестра сервиса.
# Тишины: каждая строка говорит, ушла она или нет и почему.


def провести_контроль_сервиса(*, сервис: str, состояние, blockhash: str | None,
                               blockhash_ts: float | None = None,
                               семя: str | None = None,
                               секрет: str | None = None,
                               сейчас: float | None = None,
                               подготовленное: dict | None = None,
                               отправитель=None) -> dict:
    """Один контроль ОДНИМ сервисом: сборка, подпись, учёт расхода, отправка.

    Отдельно от провести_контроль намеренно: у сервиса своё тело запроса, свой
    ключ и свои чаевые, а главное -- это НЕ новый сигнал для суточного счёта:
    на одном сигнале уходит веер контролей, и считать их за 20 разных сигналов
    значило бы закрыть замер после четырёх сигналов.
    """
    сейчас = сейчас if сейчас is not None else time.time()
    из_ = {"stage": "control_service", "sender": сервис, "ok": False,
            "sent": False, "why_not": None, "signature": None,
            "ts_sent": None}
    if not контроль_включён():
        из_["why_not"] = "контроль доставки выключен (BLOOM_LANE_CONTROL не равен 1)"
        return из_
    if состояние is not None:
        убит, почему = состояние.kill_active()
        if not убит and hasattr(состояние, "lane_kill_active"):
            убит, почему = состояние.lane_kill_active()
        if убит:
            из_.update(why_not=f"рубильник: {почему}", kill=True)
            return из_
    try:
        import bloom_senders as SS  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"реестр отправителей не загружен: {type(exc).__name__}"
        return из_
    готово = подготовленное or {}
    сб = готово.get("сборка")
    if сб is None:
        сб = собрать_контроль(наш_кошелёк=кошелёк_полосы(), семя=семя,
                               сервис=сервис)
    if not сб.get("ok"):
        из_["why_not"] = сб.get("why_not") or "контроль не собран"
        return из_
    из_.update(tip_account=сб.get("tip_account"),
               tip_lamports=сб.get("tip_lamports"),
               cost_lamports=сб.get("cost_lamports"),
               cost_sol=(сб.get("cost_lamports") or 0) / ЛАМПОРТОВ_В_SOL,
               build_ms=сб.get("build_ms"))
    # ПРЕДЕЛ -- ДО ПОДПИСИ, дёшево: незачем подписывать то, что и так нельзя.
    предв = можно_контроль(состояние, цена_лампорты=сб.get("cost_lamports") or 0,
                            сейчас=сейчас, новый_сигнал=False)
    из_["limits"] = предв.get("state")
    if not предв.get("ok"):
        из_["why_not"] = f"предел контроля: {предв.get('why_not')}"
        return из_
    подписано = готово.get("подпись")
    if подписано is None:
        if not blockhash:
            из_["why_not"] = "тёплого blockhash нет -- контроль подписывать нечем"
            return из_
        возраст = (сейчас - float(blockhash_ts)) if blockhash_ts else None
        if возраст is not None and возраст > СРОК_BLOCKHASH_S:
            из_["why_not"] = (f"тёплый blockhash старше {СРОК_BLOCKHASH_S} с "
                               f"(возраст {round(возраст, 2)} с)")
            return из_
        подписано = подписать(сб["tx_base64"], blockhash=blockhash,
                               ожидаемый_кошелёк=кошелёк_полосы(),
                               секрет=(секрет if секрет is not None
                                       else ключ_полосы()))
    if not подписано.get("ok"):
        из_["why_not"] = подписано.get("why_not")
        return из_
    из_["signature"] = подписано.get("signature")
    # РАСХОД -- ДО ОТПРАВКИ и ПОД ЗАМКОМ: ответа может не быть, а лампорты
    # уйти; соседний поток веера не имеет права затереть эту запись.
    шаг = проверить_и_учесть_контроль(
        состояние, цена_лампорты=сб.get("cost_lamports") or 0, сейчас=сейчас,
        новый_сигнал=False)
    из_["limits"] = шаг.get("limits") or из_["limits"]
    из_["accounted"] = шаг.get("accounted")
    if not шаг.get("ok"):
        почему = шаг.get("why_not") or ""
        из_["why_not"] = (f"предел контроля: {почему}"
                           if шаг.get("accounted") is None else
                           "расход контроля не записан -- контроль не отправлен: "
                           f"{почему}")
        return из_
    из_["ts_sent"] = time.time()
    о = SS.отправить_через(сервис, подписано["tx_base64"],
                            отправитель=отправитель)
    из_.update(sent=bool(о.get("sent")), ok=bool(о.get("ok")),
               http=о.get("http"), send_ms=о.get("send_ms"),
               signature_sender=о.get("signature"), url=о.get("url"))
    if not о.get("ok"):
        из_["why_not"] = о.get("why_not")
    return из_


def подготовить_контроли_сервисов(*, семя: str | None, blockhash: str | None,
                                   секрет: str | None = None,
                                   сервисы: list | None = None) -> dict:
    """Собрать и подписать веер контролей ЗАРАНЕЕ, в своём потоке.

    Ни одна миллисекунда сборки не должна лежать на пути покупки, и ни одна --
    на пути соседнего сервиса: иначе сравнение путей превратится в сравнение
    порядка, в котором мы их подписывали.
    """
    из_: dict = {}
    if not контроль_включён():
        return из_
    try:
        import bloom_senders as SS  # noqa: PLC0415
    except Exception:  # noqa: BLE001
        return из_
    имена = сервисы if сервисы is not None else SS.подключённые()
    for имя in имена:
        сб = собрать_контроль(наш_кошелёк=кошелёк_полосы(), семя=семя,
                               сервис=имя)
        запись: dict = {"сборка": сб, "подпись": None}
        if сб.get("ok") and blockhash:
            запись["подпись"] = подписать(
                сб["tx_base64"], blockhash=blockhash,
                ожидаемый_кошелёк=кошелёк_полосы(),
                секрет=(секрет if секрет is not None else ключ_полосы()))
        из_[имя] = запись
    return из_


def провести_контроли_по_сервисам(*, состояние, blockhash: str | None,
                                   blockhash_ts: float | None = None,
                                   семя: str | None = None,
                                   секрет: str | None = None,
                                   сейчас: float | None = None,
                                   сервисы: list | None = None,
                                   подготовленное: dict | None = None,
                                   отправитель=None) -> dict:
    """Веер контролей: один и тот же пустой байт -- каждым подключённым.

    ПАРАЛЛЕЛЬНО, потому что смысл замера в том, что они уходят в одну и ту же
    миллисекунду: последовательная отправка добавила бы каждому следующему
    задержку предыдущего и сделала бы сравнение путей ложным.
    """
    сейчас = сейчас if сейчас is not None else time.time()
    из_ = {"rows": [], "sent": 0, "why_not": None}
    if not контроль_включён():
        из_["why_not"] = "контроль доставки выключен (BLOOM_LANE_CONTROL не равен 1)"
        return из_
    try:
        import bloom_senders as SS  # noqa: PLC0415
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"реестр отправителей не загружен: {type(exc).__name__}"
        return из_
    имена = сервисы if сервисы is not None else SS.подключённые()
    if not имена:
        из_["why_not"] = "подключённых отправителей нет -- веер контролей пуст"
        return из_
    # РУБИЛЬНИК ПРОВЕРЯЕТСЯ ДО ОТМЕТКИ СИГНАЛА. Иначе остановленная полоса
    # тратила бы суточный бюджет замера впустую: каждый сервис ниже честно
    # откажет по рубильнику, но один из двадцати сигналов уже списан, и к
    # моменту, когда полосу снимут с рубильника, мерить будет нечем.
    if состояние is not None:
        убит, почему_kill = состояние.kill_active()
        if not убит and hasattr(состояние, "lane_kill_active"):
            убит, почему_kill = состояние.lane_kill_active()
        if убит:
            из_["why_not"] = f"рубильник: {почему_kill}"
            из_["kill"] = True
            из_["rows"] = [{"stage": "control_service", "sender": и, "ok": False,
                             "sent": False, "kill": True,
                             "why_not": f"рубильник: {почему_kill}"}
                            for и in имена]
            return из_
    # СИГНАЛ ОТМЕЧАЕТСЯ ОДИН РАЗ И ДО ОТПРАВКИ. Предел владельца -- 20 сигналов
    # с контролем в сутки; исчерпан -- веер не уходит вовсе, а не "по чуть-чуть".
    отметка = отметить_сигнал_контроля(состояние, сейчас=сейчас)
    из_["signal"] = отметка.get("state")
    if not отметка.get("ok"):
        из_["why_not"] = f"предел сигналов с контролем: {отметка.get('why_not')}"
        return из_
    готово = подготовленное or {}
    строки: dict = {}

    def один(имя):
        try:
            строки[имя] = провести_контроль_сервиса(
                сервис=имя, состояние=состояние, blockhash=blockhash,
                blockhash_ts=blockhash_ts, семя=семя, секрет=секрет,
                сейчас=сейчас, подготовленное=готово.get(имя),
                отправитель=отправитель)
        except Exception as exc:  # noqa: BLE001
            строки[имя] = {"stage": "control_service", "sender": имя,
                            "ok": False, "sent": False,
                            "why_not": f"{type(exc).__name__}: {str(exc)[:160]}"}

    import threading as _th  # noqa: PLC0415

    потоки = [_th.Thread(target=один, args=(и,), daemon=True) for и in имена]
    for п in потоки:
        п.start()
    for п in потоки:
        п.join(timeout=ОЖИДАНИЕ_ВЕЕРА_S)
    for имя in имена:
        стр = строки.get(имя)
        if стр is None:
            стр = {"stage": "control_service", "sender": имя, "ok": False,
                    "sent": False,
                    "why_not": f"не ответил за {ОЖИДАНИЕ_ВЕЕРА_S} с"}
        из_["rows"].append(стр)
    из_["sent"] = sum(1 for с in из_["rows"] if с.get("sent"))
    из_["cost_sol"] = round(sum((с.get("cost_sol") or 0.0)
                                 for с in из_["rows"] if с.get("sent")), 9)
    return из_



# ------------------------------------------------------------------ весь путь

# СРОК ГОДНОСТИ ТЁПЛОГО BLOCKHASH. Сеть держит хеш около 150 слотов (~60 с).
# Тёплый хеш обновляет пульс детектора; просроченным подписывать нельзя --
# транзакция уйдёт, сеть её отбросит, и замер выйдет ложным: "не доехало"
# вместо "доехало медленно". Держим запас вдвое.
СРОК_BLOCKHASH_S = 30.0

# СКОЛЬКО ЖДЁМ ГОТОВЫЙ КОНТРОЛЬ после отправки покупки. Сборка и подпись
# контроля занимают единицы миллисекунд; четверть секунды -- это запас на
# случай занятой машины, а не разрешение опаздывать. Не успел -- пары не
# будет, и в строке это написано.
ОЖИДАНИЕ_КОНТРОЛЯ_S = 0.25

# СКОЛЬКО ЖДЁМ ВЕЕР по сервисам. Он уходит ПОСЛЕ покупки и её пути не
# касается; ждём ответа сервисов ровно чтобы записать подписи в позицию.
# Не ответил -- строка "не ответил", а не тишина.
ОЖИДАНИЕ_ВЕЕРА_S = 3.0


def провести(*, tx_источника: dict, источник: str, минт: str, состояние,
              blockhash: str | None = None, blockhash_ts: float | None = None,
              лампорты: int | None = None, проскальзывание: float = 0.35,
              ключ_операции: str | None = None,
              источник_подпись: str | None = None,
              источник_слот: int | None = None,
              отправитель=None, rpc_call=None, секрет: str | None = None,
              тень_сим=None, сейчас: float | None = None,
              отправитель_пула=None, отправитель_веера=None,
              группа: str | None = None, слот_сети: int | None = None,
              кэш_ног=None, налог_минта=None,
              трата_источника_sol: float | None = None) -> dict:
    """Весь путь полосы на один сигнал: сборка -> (симуляция | подпись и отправка).

    Одна точка входа нарочно. У полосы три шага, и каждый из них умеет
    отказать; если их вызывать по отдельности из детектора, порядок и
    причины отказа расползутся по вызывающим, а это деньги. Здесь же и
    стадия отказа называется словом: по ней видно, где полоса стоит.

    БЕЗ BLOOM_OWN_SEND_LIVE=1 доходит только до симуляции: ни подписи, ни
    отправки. Пределы и рубильник проверяются дважды -- дёшево здесь (чтобы
    не собирать зря) и обязательно внутри отправить() под замком, где
    делается бронь.
    """
    сейчас = сейчас if сейчас is not None else time.time()
    # ПОДШАГИ РЕШЕНИЯ -- ЗАМЕР, А НЕ ДОГАДКА (слово владельца 28.09, п.5:
    # "«решили» 37-77 мс разложить по подшагам, цель <= 5 мс"). Метки ставятся
    # монотонными часами в тех же точках, где меняется stage, и уходят в запись
    # решения полем podshagi_ms. Стоимость -- один perf_counter на шаг.
    _шаги = [("вход", time.perf_counter())]

    def _шаг(имя: str) -> None:
        _шаги.append((имя, time.perf_counter()))

    def _подшаги() -> dict:
        из_шагов = {}
        for и in range(1, len(_шаги)):
            имя = _шаги[и][0]
            мс = round((_шаги[и][1] - _шаги[и - 1][1]) * 1000.0, 3)
            из_шагов[имя] = round(из_шагов.get(имя, 0.0) + мс, 3)
        из_шагов["всего"] = round((_шаги[-1][1] - _шаги[0][1]) * 1000.0, 3)
        return из_шагов

    из_ = {"stage": "off", "ok": False, "sent": False, "dry": None,
            "why_not": None, "lane": МЕТКА, "mint": минт,
            "source_sig": источник_подпись, "cid": None, "signature": None}
    if not включена():
        из_["why_not"] = "полоса выключена (BLOOM_OWN_SEND не равен 1)"
        return из_
    из_["group"] = группа or None
    # ГРУППА НЕИЗВЕСТНА -- НЕ ТОРГУЕМ. Слово владельца 27.09: адрес, которого в
    # файле групп нет, идёт в неторгующую политику off; тем более не торгуется
    # сигнал, по которому группу вообще не удалось определить. До этой правки
    # полоса_торгует(None) отвечала "да", и такой сигнал покупался размером из
    # окружения.
    из_["stage"] = "gate"
    if not группа:
        из_["why_not"] = ("группа источника не определена -- полоса не торгует "
                           "(правило 27.09: нет строки в файле групп -- off)")
        return из_
    # НАЦЕНКА ВХОДА -- ПОЛЕ ГРУППЫ. Число из группы сильнее переданного: у
    # групп финального плана они разные (0.25 у лидера, 0.40 у batch5, 0.35 у
    # lane_s0), и это же число задаёт минимум выхода в транзакции.
    наценка_гр = проскальзывание_группы(группа)
    if наценка_гр is not None:
        проскальзывание = наценка_гр
    из_["slippage"] = проскальзывание
    # ТАЙМЕР ВЫХОДА -- С ПОПРАВКОЙ НА РАЗМЕР ПОКУПКИ ИСТОЧНИКА (слово
    # владельца 27.09, вечер). Размер приходит из решения детектора, тем же
    # числом, которым считался порог группы: отдельного запроса нет.
    из_["hold_slots"] = слотов_держать_по_размеру(группа, трата_источника_sol)
    if трата_источника_sol is not None:
        из_["source_spend_sol_eq"] = float(трата_источника_sol)

    # ПРЕДВАРИТЕЛЬНЫЙ ГЕЙТ. Не заменяет тот, что внутри отправить(): он там
    # под замком и с бронью. Здесь только чтобы не тратить сеть на сборку,
    # когда полоса всё равно закрыта.
    if состояние is None:
        из_["why_not"] = "состояние не передано -- пределы полосы проверить нечем"
        return из_
    убит, почему_kill = состояние.kill_active()
    if убит:
        из_["why_not"] = f"рубильник: {почему_kill}"
        из_["kill"] = True
        return из_
    # ПЕРЕКУПЩИК. Признак группы включает действие, метка стоит у адреса.
    if пропускать_перекупщиков(группа) and источник_перекупщик(источник):
        из_["skip_flipper"] = True
        из_["why_not"] = (f"источник помечен перекупщиком, а по группе {группа} "
                           "таких пропускаем (skip_flippers)")
        return из_
    # СКОЛЬКО СЛОТОВ ПРОШЛО ОТ s0. Считается от слота ИСТОЧНИКА, а не от нашего
    # входа (слово владельца 27.09, п.2 про lane_s0: "к моменту отправки прошло
    # больше 3 слотов от s0 -- не покупать"). Предел задан, а слота сети или
    # слота источника нет -- НЕ ПОКУПАЕМ: неясность на денежном пути читается
    # как запрет.
    предел_слотов = предел_слотов_от_источника(группа)
    if предел_слотов is not None:
        if not (isinstance(источник_слот, int) and источник_слот > 0
                and isinstance(слот_сети, int) and слот_сети > 0):
            из_["why_not"] = (f"по группе {группа} предел {предел_слотов} слотов "
                               "от источника, а слот источника или слот сети "
                               "неизвестен -- не покупаем")
            return из_
        прошло = int(слот_сети) - int(источник_слот)
        из_["slots_from_source"] = прошло
        if прошло > предел_слотов:
            из_["why_not"] = (f"от слота источника прошло {прошло} слотов при "
                               f"пределе {предел_слотов} (группа {группа})")
            return из_
    try:
        позиции_сейчас = состояние.positions()
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"позиции не прочитаны ({type(exc).__name__})"
        return из_
    # РАЗМЕР -- ПО ГРУППЕ, и первые три севшие сделки группы по 0.01 SOL
    # (слово владельца 27.09, п.2). Считается ЗДЕСЬ, потому что нужен счёт
    # севших покупок группы, а он в позициях.
    if not isinstance(лампорты, int):
        разм = размер_для_группы(группа, позиции_сейчас)
        лампорты = int(round(разм["sol"] * ЛАМПОРТОВ_В_SOL))
        из_["size_why"] = разм.get("why")
        из_["first_trades"] = разм.get("first_trades")
        из_["group_landed"] = разм.get("landed")
        # БИЛЕТ ОТ РЕЗЕРВА (точка врезки от Code-3, docs/bilet_ot_rezerva_kak_
        # vstroit.md, п.4). Доля -- вход BLOOM_BILET_DOLYA, по умолчанию 0: без
        # слова владельца НИ ОДИН билет не меняется, а числа всё равно считаются
        # и ложатся в решение. Резерв берётся из самой сделки источника и БЕЗ
        # ЕДИНОГО ЧТЕНИЯ: pool_reserve_sol появляется только ПОСЛЕ сборки, а
        # размер нужен ДО неё, и пересобирать покупку ради него на горячем пути
        # значило бы платить миллисекундами за число, которое уже есть в сделке.
        #
        # ОТКАЗ ДВЕРИ -- НЕ ОТКАЗ В ПОКУПКЕ: нет резерва, резерв виртуальный
        # (кривая pump.fun) или доля вне (0, 0.5] -- билет остаётся потолком
        # группы, причина словами в bilet_rezerv_why_not.
        # ПОДЪЁМ ИЛИ СРЕЗ -- РЕШАЕТ ПОЛЕ ГРУППЫ, И ЗОВ ОДИН (слово владельца
        # 05.10). bilet_dolya у группы задана -- билет ПОДНИМАЕТСЯ:
        # max(билет группы, min(доля x резерв, потолок 2.0)). Поля нет -- всё
        # как было: доля из окружения и срез вниз от потолка группы.
        #
        # ЗОВ РОВНО ОДИН, И ЭТО НЕ АККУРАТНОСТЬ: добыча резерва -- самая дорогая
        # часть врезки (разбор сделки источника, у CLMM ещё и ёмкость шага), и
        # второй зов удвоил бы её на горячем пути. Поэтому потолок и пол
        # выбираются ДО зова, а направление решается по числам ответа.
        _доля_гр = _число_группы(группа, "bilet_dolya")
        # РУБИЛЬНИК ПЕРВЫМ, ПОЛЕ ГРУППЫ ВТОРЫМ: при ПОДЪЁМ_ВКЛЮЧЁН = False
        # поле bilet_dolya в файле не делает ничего.
        _подъём_вкл = (ПОДЪЁМ_ВКЛЮЧЁН
                        and isinstance(_доля_гр, (int, float)) and _доля_гр > 0)
        if _подъём_вкл:
            _пот_поля = _число_группы(группа, "bilet_potolok_sol")
            _пот_вход = min(ПОТОЛОК_ПОДЪЁМА_SOL,
                             float(_пот_поля) if _пот_поля and _пот_поля > 0
                             else ПОТОЛОК_ПОДЪЁМА_SOL)
            # ПРЕДЕЛ РЕЗЕРВА: поле группы может его только ОПУСТИТЬ, как и
            # потолок. Слово владельца -- 150 SOL-экв., и опечатка в файле
            # групп не должна открыть дверь выше.
            _пред_поля = _число_группы(группа, "bilet_rezerv_max_sol")
            _пред_вход = min(ПРЕДЕЛ_РЕЗЕРВА_ПОДЪЁМА_SOL,
                              float(_пред_поля) if _пред_поля and _пред_поля > 0
                              else ПРЕДЕЛ_РЕЗЕРВА_ПОДЪЁМА_SOL)
        else:
            _пот_вход = разм["sol"]
            _пред_вход = None
        try:
            import c3_bilet_ot_rezerva as BR  # noqa: PLC0415
            бр = BR.bilet_dlya_signala(
                potolok_sol=_пот_вход, tx_istochnika=tx_источника or {},
                istochnik=источник or "", mint=минт or "",
                pol_sol=(разм["sol"] if _подъём_вкл else None),
                dolya_vhod=(float(_доля_гр) if _подъём_вкл else None))
        except Exception as exc:  # noqa: BLE001
            бр = {"bilet_sol": None, "ot_rezerva": False,
                  "rezerv_why_not": f"модуль билета не загружен: {type(exc).__name__}"}
        из_.update(bilet_sol=бр.get("bilet_sol"), bilet_dolya=бр.get("dolya"),
                    bilet_ot_rezerva=бр.get("ot_rezerva"),
                    bilet_rezerv_sol=бр.get("rezerv_sol"),
                    bilet_rezerv_otkuda=бр.get("rezerv_otkuda"),
                    bilet_rezerv_vid=бр.get("rezerv_vid"),
                    bilet_rezerv_why_not=бр.get("rezerv_why_not"),
                    bilet_podjom=False, bilet_pol_sol=(разм["sol"] if _подъём_вкл
                                                        else None),
                    bilet_potolok_podjoma_sol=(_пот_вход if _подъём_вкл else None),
                    bilet_rezerv_max_sol=(_пред_вход if _подъём_вкл else None))
        if _подъём_вкл:
            _п = подъём_билета(разм["sol"], бр, потолок_sol=_пот_вход,
                                предел_резерва_sol=_пред_вход)
            из_["bilet_podjom"] = _п["подъём"]
            из_["bilet_podjom_why"] = _п["почему"]
            if _п["лампорты"]:
                лампорты = int(_п["лампорты"])
            # БИЛЕТ В СТРОКЕ -- ТОТ, КОТОРЫМ ПОКУПАЕМ, А НЕ ОТВЕТ МОДУЛЯ.
            # ЖИВОЙ СЛУЧАЙ 05.10 11:20:08Z (cand2): резерва у пула не было
            # ("котировка пула не SOL"), подъёма не случилось и покупка ушла
            # билетом группы 0.1 -- а в строке решения стояло bilet_sol 2.0,
            # потому что модулю потолком отдан потолок ПОДЪЁМА и без резерва
            # он честно отвечает "билет равен потолку". На деньги это не
            # влияло (размер берётся из lamports), но строка показывала билет,
            # которого не было, и средний билет по журналу вышел бы вдвадцатеро
            # больше. Теперь bilet_sol -- фактический билет этой покупки, а
            # ответ модуля лежит рядом под своим именем.
            из_["bilet_sol_modul"] = бр.get("bilet_sol")
            из_["bilet_sol"] = round(лампорты / ЛАМПОРТОВ_В_SOL, 9)
        elif бр.get("ot_rezerva") and бр.get("bilet_lamporty"):
            лампорты = int(бр["bilet_lamporty"])
    из_["lamports"] = лампорты
    из_["size_sol"] = лампорты / ЛАМПОРТОВ_В_SOL
    # ЧЕСТНОЕ ИМЯ ПОДШАГА. Всё до этой метки -- разбор сигнала источника и
    # расчёт размера: ни гейта, ни веера тут ещё нет.
    _шаг("разбор и размер")
    try:
        гейт = можно_отправлять(позиции_сейчас, сейчас=сейчас,
                                 группа=группа, минт=минт,
                                 размер_лампорты=лампорты,
                                 состояние=состояние,
                                 слот=источник_слот,
                                 подпись_источника=источник_подпись)
    except Exception as exc:  # noqa: BLE001
        из_["why_not"] = f"пределы полосы не посчитаны ({type(exc).__name__})"
        return из_
    из_["lane_state"] = гейт.get("state")
    if not гейт.get("ok"):
        из_["why_not"] = f"предел полосы: {гейт.get('why_not')}"
        return из_

    # КОНТРОЛЬ ДОСТАВКИ (З2, слово владельца 25.09) готовится ПАРАЛЛЕЛЬНО.
    # Он обязан уйти в ту же миллисекунду, что и покупка, но ни одна его
    # миллисекунда не имеет права лечь на путь покупки -- поэтому сборка и
    # подпись контроля идут своим потоком, а после отправки покупки остаётся
    # только отправить готовые байты.
    веер_готов: dict = {}
    поток_контроля = None
    # ВЕЕР -- НЕ НА КАЖДОЙ ГРУППЕ. Владелец 25.09 про speed_only: "через пул
    # БЕЗ веера". Эта группа сама и есть замер скорости, и платить на ней ещё
    # и за веер незачем: 0.003 SOL на сигнал при её суточном потолке 0.2 SOL --
    # это шестая часть бюджета за один сигнал.
    _шаг("гейт полосы")
    # МЕТКА РЕШЕНИЯ -- НАСТОЯЩИМИ ЧАСАМИ (п.6 слова владельца 29.09). Подшаги
    # уже мерятся монотонными часами, но по ним не сказать, КОГДА решение
    # состоялось: монотонные часы не сравнить с метками цепи и с ts источника.
    # Здесь гейт уже пропустил, то есть решение принято, а сборка ещё впереди.
    из_["ts_decision"] = time.time()
    if контроль_включён() and живьём() and веер_нужен(группа):
        def _готовить_контроль():
            # ВЕЕР ПО СЕРВИСАМ готовится ЗАРАНЕЕ и в своём потоке: он уходит
            # после покупки, но ни одна его миллисекунда не имеет права лечь
            # на путь покупки.
            try:
                веер_готов.update(подготовить_контроли_сервисов(
                    семя=(источник_подпись or ключ_операции),
                    blockhash=blockhash,
                    секрет=(секрет if секрет is not None else ключ_полосы())))
            except Exception as exc:  # noqa: BLE001
                веер_готов["почему"] = f"{type(exc).__name__}: {str(exc)[:160]}"

        try:
            поток_контроля = threading.Thread(target=_готовить_контроль,
                                               name="lane-control-prep", daemon=True)
            поток_контроля.start()
        except Exception as exc:  # noqa: BLE001
            # ИМЯ ТОЛЬКО СУЩЕСТВУЮЩЕЕ. Здесь стояло контроль_готов -- словарь,
            # удалённый вместе с одиночным контролем, и при неудачном старте
            # потока (RuntimeError "can't start new thread" на занятой машине)
            # вместо честной причины летел NameError. Ловился он выше как
            # "полоса упала", то есть ПОКУПКА НЕ УХОДИЛА ВОВСЕ ради замера --
            # прямо против правила "терять сделку из-за замера нельзя", и
            # причина в журнале была ложной.
            поток_контроля = None
            веер_готов["почему"] = (f"поток веера контролей не запустился: "
                                     f"{type(exc).__name__}")

    _шаг("веер контролей")
    # БОЕВОЙ ПУЛ (шаг 1, слово владельца 25.09). Отдельный рубильник
    # BLOOM_POOL_SEND: чаевые всем подключённым и отправка всеми сразу -- это
    # другой расход и другая дорога, и включаться она должна осознанно.
    чаевые_всем = None
    сервисы_пула = None
    if пул_включён():
        пч = чаевые_пула(источник_подпись or ключ_операции)
        из_["pool_tips"] = пч
        if not пч.get("ok"):
            # Пул не собрался -- это НЕ повод не покупать: полоса уходит своим
            # обычным путём, а причина названа словами.
            из_["pool_why_not"] = пч.get("why_not")
        else:
            чаевые_всем = пч["tips"]
            сервисы_пула = [з["sender"] for з in пч["senders"]]

    # ВАРИАНТ ПУЛА НА ДОЛГОВЕЧНОМ NONCE (шаг 2, слово владельца 25.09: "по
    # транзакции на сервис, только его чаевые, один durable nonce"). Он
    # заменяет отправку ОДНОЙ транзакции со всеми чаевыми: пакет становится
    # маленьким (предел сети 1232 байта больше не жмёт), платим только тому, кто
    # довёз, а купить дважды нельзя -- первая исполнившаяся сдвигает nonce.
    режим_нонса = bool(пул_нонсом_включён() and живьём() and сервисы_пула)
    нонс = None
    # ДВА ВИДА ОДНОГО ЗНАЧЕНИЯ, И СБОРЩИКАМ НУЖЕН ВТОРОЙ. нонс_для_сделки отдаёт
    # СЛОВАРЬ (account, authority, blockhash) -- он нужен вариантам на nonce и
    # спасению; сборщики (двухшаговая, USDC-нога, маршрут) ждут ПАРУ
    # (аккаунт, распорядитель), ровно ту, что делает собрать_варианты_нонсом.
    # Пока словарь уходил в них как есть, нонс[0] давал KeyError: 0: 02.10 так
    # потерян единственный годный сигнал USDC-ноги за сутки (lane_s0, DAMM v2).
    # Поэтому пара делается ОДИН РАЗ и здесь, рядом с чтением значения.
    # NONCE СБОРЩИКАМ НЕ ОТДАЁМ, И ЭТО РЕШЕНИЕ, А НЕ ЗАБЫВЧИВОСТЬ.
    # Пара нужна была, чтобы сборщики не падали на нонс[0]; падать они перестали.
    # Но ОТДАВАТЬ им nonce нельзя, пока подпись этих путей идёт обычным тёплым
    # хешем (ниже: подписать(сб["tx_base64"], blockhash=blockhash, ...)), а не
    # нонс["blockhash"]: инструкция advance_nonce в транзакции с обычным хешем
    # ОТКАЗЫВАЕТ, если сохранённый nonce совпал с этим хешем, и уносит с собой
    # ВСЮ покупку. Выгоды же никакой: стойкий nonce нужен ВАРИАНТАМ, а их строит
    # прямой сборщик -- на котировке не SOL он отказывает, значит вариантов на
    # этих путях нет вовсе; и стоит nonce лишних 74 байта при пределе сети 1232.
    # None здесь воспроизводит РОВНО то поведение, что идёт на стенде сейчас: до
    # починки KeyError словарь до сборщиков не доходил, и advance_nonce в этих
    # транзакциях не было. Хотеть стойкий nonce на этих путях -- значит менять
    # подпись, и это отдельное слово владельца, а не попутная правка.
    нонс_сборщикам = None
    if режим_нонса:
        # НЕПОДТВЕРЖДЁННЫЙ СДВИГ ЗАКРЫВАЕТ ПУТЬ НА ЭТОМ NONCE (слово владельца
        # 25.09). Собрать покупку сейчас значило бы поставить её в очередь к
        # висящим вариантам прошлого сигнала: nonce один, и сесть может любая из
        # них. Обычный путь пула при этом остаётся -- он nonce не касается вовсе.
        ож = нонс_ожидает(состояние, rpc_call=rpc_call)
        if ож.get("pending"):
            из_["pool_nonce"] = {"ok": False, "pending_shift": True,
                                  "why_not": ож.get("why"),
                                  "shift_signature": ож.get("signature")}
            режим_нонса = False
    if режим_нонса:
        нонс = нонс_для_сделки(rpc_call, сейчас=сейчас)
        из_["nonce_ms"] = нонс.get("nonce_ms")
        из_["pool_nonce"] = {"account": нонс.get("account"),
                              "ok": нонс.get("ok"),
                              "why_not": нонс.get("why_not"),
                              "warm": bool(нонс.get("warm")),
                              "warm_age_s": нонс.get("warm_age_s"),
                              "warm_why_not": нонс.get("warm_why_not"),
                              "nonce_ms": нонс.get("nonce_ms")}
        if not нонс.get("ok"):
            # Нет живого аккаунта nonce -- идём обычным путём пула (шаг 1), а
            # причина названа словами. Выдумывать nonce нельзя: транзакции
            # ушли бы недействительными, потратив чаевые.
            режим_нонса = False
    if режим_нонса:
        # В ОСНОВНОЙ транзакции чаевых пула нет: у каждого варианта свои.
        чаевые_всем = None
        # Словарь остаётся там, где его и ждут: варианты на nonce и спасение.

    # СБОРКА. Дёшево и безопасно: ни ключа, ни подписи, ни отправки.
    _шаг("чаевые пула и нонс")
    из_["stage"] = "build"
    сб = собрать(tx_источника=tx_источника or {}, источник=источник or "",
                 минт=минт or "", наш_кошелёк=кошелёк_полосы(),
                 чаевые_списком=чаевые_всем,
                 лампорты=лампорты, проскальзывание=проскальзывание,
                 приоритет_лампорты=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                 чаевые_лампорты=int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)),
                 семя=источник_подпись or ключ_операции, rpc_call=rpc_call,
                 налог_минта=налог_минта)
    # ПОДГОНКА ПУЛА ПО РАЗМЕРУ. Убираем сервисы по одному с конца, пока
    # транзакция не влезет в пакет сети; каждый убранный назван в отчёте.
    if чаевые_всем and сб.get("too_big"):
        def _сборщик(список_ч):
            return собрать(tx_источника=tx_источника or {}, источник=источник or "",
                            минт=минт or "", наш_кошелёк=кошелёк_полосы(),
                            чаевые_списком=список_ч,
                            лампорты=лампорты, проскальзывание=проскальзывание,
                            приоритет_лампорты=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                            чаевые_лампорты=int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)),
                            семя=источник_подпись or ключ_операции, rpc_call=rpc_call,
                 налог_минта=налог_минта)

        подгонка = подогнать_чаевые_под_размер(
            сборщик=_сборщик, чаевые=чаевые_всем, сервисы=сервисы_пула or [])
        сб = подгонка["сб"]
        из_["pool_trimmed"] = подгонка["убраны"]
        из_["pool_why_not"] = подгонка["why_not"]
        чаевые_всем = подгонка["чаевые"] or None
        сервисы_пула = подгонка["сервисы"] or None
    # ПЕРВАЯ СДЕЛКА НА НОВОМ ТИПЕ ПУЛА -- 0.01 SOL. Проверка стоит ПОСЛЕ
    # сборки, потому что до неё программа пула неизвестна, и пересборка дёшева:
    # ни ключа, ни сети она не трогает. Предел полосы выше уже проверен по
    # ПОЛНОМУ размеру, то есть по строгому.
    if сб.get("ok") and сб.get("pool_program"):
        разм_пр = размер_первой_на_программе(позиции_сейчас,
                                              сб.get("pool_program"), лампорты)
        if разм_пр.get("first") and int(разм_пр["lamports"]) != int(лампорты):
            из_["new_pool_size_sol"] = разм_пр["lamports"] / ЛАМПОРТОВ_В_SOL
            из_["new_pool_size_why"] = разм_пр.get("why")
            из_["new_pool_landed"] = разм_пр.get("landed")
            сб2 = собрать(tx_источника=tx_источника or {}, источник=источник or "",
                           минт=минт or "", наш_кошелёк=кошелёк_полосы(),
                           чаевые_списком=чаевые_всем,
                           лампорты=разм_пр["lamports"],
                           проскальзывание=проскальзывание,
                           приоритет_лампорты=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                           чаевые_лампорты=int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)),
                           семя=источник_подпись or ключ_операции, rpc_call=rpc_call,
                 налог_минта=налог_минта)
            if сб2.get("ok"):
                сб = сб2
                лампорты = int(разм_пр["lamports"])
                из_["lamports"] = лампорты
                из_["size_sol"] = лампорты / ЛАМПОРТОВ_В_SOL
            else:
                # Пересборка не вышла -- идём ПОЛНЫМ размером и говорим почему:
                # молча купить полным на новом строителе хуже, чем сказать.
                из_["new_pool_size_why_not"] = сб2.get("why_not")

    # ДВУХШАГОВЫЙ ПУТЬ -- ПЕРВЫМ (финальный план владельца 27.09, п.3): SOL ->
    # котировочный -> токен ОДНОЙ транзакцией, нашим строителем. Он и закрывает
    # отказ "котировка пула не SOL" -- у лидера это 74 % покупок. Jupiter в
    # покупке владелец запретил вовсе, поэтому он остаётся ниже и только на
    # случай, если группа явно его просит полем lane_route.
    if (not сб.get("ok")
            and ПРИЗНАК_КОТИРОВКИ_НЕ_SOL in (сб.get("why_not") or "")
            and двухшаговый_включён(группа)):
        из_["stage"] = "two_step_build"
        из_["direct_why_not"] = сб.get("why_not")
        # РАЗМЕР ПЕРВОЙ ДВУХШАГОВОЙ -- 0.01. Считается ЗДЕСЬ, а не выше: до
        # сборки не известно, выйдет маршрут двухшаговым или нет, а предел
        # полосы выше уже проверен по ПОЛНОМУ размеру -- то есть по строгому.
        разм_дш = размер_первой_двухшаговой(позиции_сейчас, лампорты)
        лампорты_дш = разм_дш["lamports"]
        из_["two_step_size_sol"] = лампорты_дш / ЛАМПОРТОВ_В_SOL
        из_["two_step_size_why"] = разм_дш.get("why")
        из_["two_step_landed"] = разм_дш.get("landed")
        try:
            import bloom_lane_two_step as TS  # noqa: PLC0415

            дш = TS.собрать(
                tx_источника=tx_источника or {}, источник=источник or "",
                минт=минт or "", наш_кошелёк=кошелёк_полосы(), лампорты=лампорты_дш,
                # ПРЕДЕЛ CU ДВУХШАГОВОЙ -- ИЗ ОДНОЙ ТАБЛИЦЫ СО ВСЕМИ (решение
                # владельца 28.09). ВАЖНО: на этом пути умолчание модуля было
                # 800 000, а не общие 140 000, поэтому 250 000 -- это ПОНИЖЕНИЕ.
                # Сделок two_step в замере суток ноль, максимума по цепи нет.
                # Меняется одной переменной окружения BLOOM_LANE_CU_TWO_STEP,
                # без правки кода и без деплоя.
                cu_units=предел_cu("two_step"),
                проскальзывание=проскальзывание, чаевые_списком=чаевые_всем,
                приоритет_лампорты=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                чаевые_лампорты=int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)),
                чаевые_адрес=(None if чаевые_всем else выбрать_чаевые(
                    источник_подпись or ключ_операции)),
                семя=источник_подпись or ключ_операции, нонс=нонс_сборщикам,
                rpc_call=rpc_call, кэш_ног=кэш_ног, налог_минта=налог_минта,
                потолок_комиссии=ПОТОЛОК_КОМИССИИ_ПУЛА,
                # ПРАВИЛО ТОНКОГО ПУЛА -- внутрь сборки: резерв второго шага в
                # SOL-эквивалент переводит она (у неё есть цена ноги), а здесь
                # этой цены нет.
                проскальзывание_тонкого=проскальзывание_тонкого_пула(группа)[0],
                порог_тонкого_sol=проскальзывание_тонкого_пула(группа)[1])
        except Exception as exc:  # noqa: BLE001
            дш = {"ok": False,
                  "why_not": f"двухшаговая сборка не загрузилась: {type(exc).__name__}"}
        из_["two_step"] = {к: дш.get(к) for к in
                            ("ok", "why_not", "leg1_pool_program", "quote_mint",
                             "quote_fee_bps", "leg1_min_out", "leg2_amount_in",
                             "leg2_to_pool", "min_out", "expected_out", "size",
                             "build_ms", "leg1_template_age_s",
                             "pool_reserve_quote_raw", "pool_reserve_sol_eq",
                             "slippage_thin", "slippage_used", "slippage_why",
                             "min_out_floor_absent")}
        if дш.get("ok"):
            # ЧАЕВЫЕ ИЗ ДВУХШАГОВОЙ СБОРКИ -- ЕЁ СОБСТВЕННЫЕ: дальше путь общий
            # (симуляция, подпись, отправка, пределы и бронь), и второго пути
            # отправки в полосе нет.
            сб = дш
            из_["route"] = "two_step"
            # РАЗМЕР В ОТВЕТЕ -- ФАКТИЧЕСКИЙ. Иначе учёт и строка позиции
            # считали бы трату по полному размеру группы, а ушло 0.01.
            лампорты = лампорты_дш
            из_["lamports"] = лампорты
            из_["size_sol"] = лампорты / ЛАМПОРТОВ_В_SOL
        else:
            из_["two_step_why_not"] = дш.get("why_not")
    # USDC-НОГА -- ТЕНЬ (утренний пакет 01.10, п.2). Вторая нога на СТРОИТЕЛЯХ
    # ТИПОВ: сигнал с котировкой USDC в CLMM/DLMM/Whirlpool/DAMM v2 двухшаговый
    # путь не берёт (у него вторая нога только CPMM и Pump AMM), и полоса такой
    # сигнал теряет целиком. Число Code-2 за 28-29.09: 9 сигналов в сутки в
    # денежных группах.
    #
    # ЗДЕСЬ ТОЛЬКО ЧИСЛА. Флаг BLOOM_USDC_NOGA по умолчанию выключен, режим
    # "ten" решений полосы не меняет вовсе: поля идут в журнал решений (его
    # пишет детектор, запись.update(рез)) и в выгрузку позиции, если сделка
    # всё-таки состоялась другим путём.
    #
    # БОЕВОЙ РЕЖИМ -- ТРЕТЬИМ ЗНАЧЕНИЕМ ФЛАГА (п.9 вечернего пакета 01.10).
    # Тень считала min_out по ЦЕНЕ СОБЫТИЯ источника, а она наш объём не
    # учитывает и потому выход ЗАВЫШАЕТ: отправить по ней значило бы заплатить
    # чаевые и приоритет за откат. Поэтому в бою min_out второй ноги берёт
    # КОТИРОВЩИК ТИПА (c2_usdc_noga.KOTIROVSHCHIKI): CLMM, Whirlpool, AMM v4 и
    # DBC -- подготовить(минт_котировки=USDC) на НЫНЕШНИХ массивах тиков,
    # DAMM v2 -- по остаткам, DLMM -- своим счётом. Котировщик отказал -- сборка
    # отказывает САМА и называет причину: подмены ценой события в бою нет.
    #
    # ПЕРВАЯ БОЕВАЯ -- 0.01: размер даёт размер_первой_двухшаговой, тот же, что
    # у двухшагового пути, и то же число идёт в тень -- иначе тень считала бы
    # min_out для одного размера, а бой отправлял другой.
    # ОТКРЫВАТЬ ЛИ ВЕТКУ USDC-НОГИ -- ОДНИМ ПРАВИЛОМ (правка 04.10, п.2). Здесь
    # стояло условие подстрокой, и ровно такое же -- у сигнальных типов ниже;
    # оба пропускали отказ ОПРЕДЕЛЕНИЯ пула «неоднозначная котировка … (EPjFWd)»,
    # то есть сигналы с котировкой USDC до строителя ноги не доходили (18 за
    # 16.1 часа журнала). Решение -- в предлагать_усдс_ногу, и спрашивают его
    # обе ветки.
    _усдс_ветка = предлагать_усдс_ногу(сб.get("why_not"))
    из_["lane_usdc_vetka"] = _усдс_ветка
    if not сб.get("ok") and _усдс_ветка["да"]:
        разм_un = размер_первой_двухшаговой(позиции_сейчас, лампорты)
        # ПОТОЛОК БОЕВОЙ USDC-НОГИ СТОИТ ЗДЕСЬ, ДО ТЕНИ: тень обязана считать
        # min_out для ТОГО ЖЕ размера, который уйдёт в бою.
        # ПОТОЛОК СНИМАЕТСЯ ПОСЛЕ ТРЁХ ПОСАДОК USDC-НОГИ (слово владельца 02.10).
        # Решение считает потолок_usdc_ноги_sol по ЗАПИСЯМ, по полю route: метки
        # двухшагового пути у этого маршрута нет, и чужой счётчик снял бы потолок
        # на чужих посадках.
        _пот_реш = потолок_usdc_ноги_sol(позиции_сейчас)
        if _пот_реш["потолок_sol"] is None:
            лампорты_un = int(разм_un["lamports"])
        else:
            _пот_un = int(round(float(_пот_реш["потолок_sol"]) * ЛАМПОРТОВ_В_SOL))
            лампорты_un = min(int(разм_un["lamports"]), _пот_un)
        из_["lane_usdc_noga_lamports"] = лампорты_un
        из_["lane_usdc_noga_first"] = разм_un.get("first")
        из_["lane_usdc_noga_potolok_sol"] = _пот_реш["потолок_sol"]
        из_["lane_usdc_noga_posadok"] = _пот_реш["село"]
        из_["lane_usdc_noga_potolok_snjat"] = _пот_реш["снят"]
        из_["lane_usdc_noga_potolok_pochemu"] = _пот_реш["почему"]
        из_["lane_usdc_noga_potolok_srabotal"] = (
            лампорты_un < int(разм_un["lamports"]))
        из_.update(тень_usdc_ноги(
            tx_источника=tx_источника, источник=источник, минт=минт,
            лампорты=лампорты_un,
            кэш_ног=кэш_ног, проскальзывание=проскальзывание, группа=группа))
        if из_.get("lane_usdc_noga_godilos") and бой_usdc_ноги(группа):
            из_["stage"] = "usdc_noga_build"
            try:
                import c2_usdc_noga as UN  # noqa: PLC0415

                # ТАБЛИЦА АДРЕСОВ -- ДО сборки, и её отсутствие НАЗВАНО в записи.
                _альт_un = таблица_ноги(состояние)
                из_["lane_usdc_noga_alt"] = _альт_un
                ун = UN.sobrat(
                    tx_istochnika=tx_источника or {}, istochnik=источник or "",
                    mint=минт or "", nash_koshelek=кошелёк_полосы(),
                    lamporty=лампорты_un, kesh_nog=кэш_ног,
                    proskalzyvanie=проскальзывание,
                    cu_units=предел_cu("two_step"),
                    prioritet_lamporty=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                    chaevye_lamporty=int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)),
                    chaevye_spiskom=чаевые_всем,
                    chaevye_adres=(None if чаевые_всем else выбрать_чаевые(
                        источник_подпись or ключ_операции)),
                    nons=нонс_сборщикам, rpc_call=rpc_call, gruppa=группа,
                    nashi_tablicy=([_альт_un["адрес"]] if _альт_un.get("ok")
                                    else None),
                    nalog_vyhoda=налог_минта)
            except Exception as exc:  # noqa: BLE001
                # ПЕРВЫЕ СЛОВА НЕ МЕНЯЮТСЯ: по подстроке "сборка USDC-ноги не
                # загрузилась: " эту запись ищут снаружи. Меняется ХВОСТ -- вместо
                # одного имени класса repr с ключом и файл:строка кадра падения.
                ун = {"ok": False,
                      "why_not": (f"сборка USDC-ноги не загрузилась: "
                                   f"{след_сбоя(exc)}")}
            из_["lane_usdc_noga_boj"] = {к: ун.get(к) for к in
                ("ok", "why_not", "min_out", "min_out_from", "expected_out",
                 "size", "build_ms", "chtenij", "fee_share",
                 "tpl_ot_kotirovshchika")}
            if ун.get("ok"):
                # ДАЛЬШЕ ПУТЬ ОБЩИЙ -- подпись, отправка, пределы и бронь: ответ
                # sobrat() того же вида, что у прямой и двухшаговой сборки, и
                # второго пути отправки в полосе нет.
                сб = ун
                из_["route"] = UN.ROUTE
                # РАЗМЕР В ОТВЕТЕ -- ФАКТИЧЕСКИЙ, как у двухшагового: иначе учёт
                # и строка позиции считали бы трату по полному размеру группы.
                лампорты = лампорты_un
                из_["lamports"] = лампорты
                из_["size_sol"] = лампорты / ЛАМПОРТОВ_В_SOL
            else:
                из_["lane_usdc_noga_boj_why_not"] = ун.get("why_not")
    # USDC-НОГА СИГНАЛЬНЫХ ТИПОВ: CPMM, LaunchLab, Pump AMM, кривая v2
    # (слово владельца 03.10, п.3б; врезка по docs/usdc_noga_signaly_kak_vstroit.md).
    #
    # ЗАЧЕМ ВТОРАЯ ТАБЛИЦА ТИПОВ. Счёт сигналов с котировкой USDC за сутки -- 118,
    # и лежат они НЕ там, где нога закрыта: CPMM 44, LaunchLab 38, Pump AMM 25,
    # кривая v2 7, а закрытые c2_usdc_noga CLMM/DLMM/DAMM v2/Whirlpool дают 4.
    # Собственный двухшаговый путь полосы (bloom_lane_two_step) эти типы
    # СОБИРАЕТ, но не отправляет ни одной: 1453…1594 байта при пределе сети 1232,
    # потому что в нём нет НАШЕЙ таблицы адресов. С таблицей те же пакеты
    # 915…1056 байт.
    #
    # ЧЕЙ ПУТЬ ПЕРВЫЙ. Сначала c2_usdc_noga -- у неё CPMM с 03.10 тоже есть, и
    # на деньгах это не дубль: условие ниже берётся за эту врезку ТОЛЬКО когда
    # тот путь не собрался (not lane_usdc_noga_godilos). CPMM остаётся здесь
    # ради двух вещей, которых у того нет: переворота сторон (сделка источника
    # оказалась продажей) и продажи токен -> USDC -> SOL.
    #
    # ВЫКЛЮЧАТЕЛЬ ОДИН. Режим берётся тем же BLOOM_USDC_NOGA через
    # c3_usdc_noga_signaly.rezhim(группа): таблицы типов две, флаг один, и в
    # тени sobrat ничего не собирает и говорит почему.
    if (not сб.get("ok") and _усдс_ветка["да"]
            and not из_.get("lane_usdc_noga_godilos")):
        из_["stage"] = "usdc_signaly_build"
        try:
            import c3_usdc_noga_signaly as UNS  # noqa: PLC0415

            # ТАБЛИЦЫ -- И НАША, И ЕГО. Наша несёт постоянные адреса кривой
            # (п.3а), его -- счета первой ноги его замера; лишняя таблица байт
            # не добавляет, а недостающий адрес уехал бы целиком.
            _альт_с = таблица_ноги(состояние)
            из_["lane_usdc_signaly_alt"] = _альт_с
            _таблицы_с = [UNS.TABLICA_ADRESOV]
            if _альт_с.get("ok") and _альт_с.get("адрес"):
                _таблицы_с.insert(0, _альт_с["адрес"])
            сн = UNS.sobrat(
                tx_istochnika=tx_источника or {}, istochnik=источник or "",
                mint=минт or "", nash_koshelek=кошелёк_полосы(),
                lamporty=лампорты_un, kesh_nog=кэш_ног,
                proskalzyvanie=проскальзывание,
                cu_units=предел_cu("two_step"),
                prioritet_lamporty=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                chaevye_lamporty=int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)),
                chaevye_spiskom=чаевые_всем,
                chaevye_adres=(None if чаевые_всем else выбрать_чаевые(
                    источник_подпись or ключ_операции)),
                nons=нонс_сборщикам, rpc_call=rpc_call, gruppa=группа,
                nashi_tablicy=_таблицы_с)
        except Exception as exc:  # noqa: BLE001
            # ПЕРВЫЕ СЛОВА НЕ МЕНЯЮТСЯ: по ним эту запись ищут снаружи.
            сн = {"ok": False,
                  "why_not": (f"сборка USDC-ноги сигнальных типов не загрузилась: "
                               f"{след_сбоя(exc)}")}
        из_["lane_usdc_signaly_godilos"] = сн.get("ok")
        из_["lane_usdc_signaly_why_not"] = сн.get("why_not")
        из_["lane_usdc_signaly"] = {к: сн.get(к) for к in
            ("label", "kotirovshchik", "leg1_min_out", "leg2_amount_in",
             "min_out", "expected_out", "min_out_from", "razvernut", "size")}
        if сн.get("ok"):
            # ДАЛЬШЕ ПУТЬ ОБЩИЙ: ответ sobrat() того же вида, что у прямой,
            # двухшаговой и первой USDC-ноги, и второго пути отправки нет.
            сб = сн
            из_["route"] = UNS.ROUTE
            лампорты = лампорты_un
            из_["lamports"] = лампорты
            из_["size_sol"] = лампорты / ЛАМПОРТОВ_В_SOL
    # ВТОРОЙ МАРШРУТ -- ТОЛЬКО ТАМ, ГДЕ ПРЯМАЯ СБОРКА ОТКАЗАЛА ПО КОТИРОВКЕ
    # (слово владельца 27.09). Пулы с котировкой SOL идут прямой сборкой, как
    # сейчас: маршрут их не касается вовсе. Включает его ПОЛЕ ГРУППЫ, поэтому
    # ни один сигнал группы без поля здесь ничего нового не делает.
    if (not сб.get("ok")
            and ПРИЗНАК_КОТИРОВКИ_НЕ_SOL in (сб.get("why_not") or "")):
        маршрут = маршрут_полосы(группа)
        из_["lane_route_offered"] = True
        из_["direct_why_not"] = сб.get("why_not")
        if маршрут == МАРШРУТ_JUPITER:
            из_["stage"] = "route_build"
            рм = собрать_маршрутом(
                минт=минт or "", наш_кошелёк=кошелёк_полосы(), лампорты=лампорты,
                проскальзывание=проскальзывание, чаевые_списком=чаевые_всем,
                приоритет_лампорты=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                чаевые_лампорты=int(round(чаевые_sol() * ЛАМПОРТОВ_В_SOL)),
                семя=источник_подпись or ключ_операции, нонс=нонс_сборщикам,
                rpc_call=rpc_call)
            из_["lane_route"] = {
                "route": маршрут, "ok": bool(рм.get("ok")),
                "why_not": рм.get("why_not"), "quote_ms": рм.get("quote_ms"),
                "ix_ms": рм.get("ix_ms"), "lut_ms": рм.get("lut_ms"),
                "build_ms": рм.get("build_ms"), "path": рм.get("route"),
                "steps": рм.get("route_steps"), "quote_slot": рм.get("quote_slot"),
                "min_out": рм.get("min_out"), "expected_out": рм.get("expected_out"),
                "size": рм.get("size"), "in_tx": рм.get("in_tx")}
            if рм.get("ok"):
                # Дальше путь ОБЩИЙ: симуляция, подпись, отправка, пределы и
                # бронь -- те же, что у прямой сборки. Второго пути отправки в
                # полосе нет и быть не должно.
                сб = рм
            else:
                из_["route_why_not"] = рм.get("why_not")
        else:
            из_["lane_route"] = {"route": None,
                                  "why_not": ("маршрут по этой группе не включён "
                                               "(поле группы lane_route)")}
    из_.update(pool_program=сб.get("pool_program"), min_out=сб.get("min_out"),
               expected_out=сб.get("expected_out"), build_ms=сб.get("build_ms"),
               size=сб.get("size"), tip_account=сб.get("tip_account"),
               pool_reserve_sol=сб.get("pool_reserve_sol"),
               pool_reserve_kind=сб.get("pool_reserve_kind"),
               pool_senders=сервисы_пула)
    # ФАКТЫ ЗАПУСКА -- НАРУЖУ ТЕМИ ЖЕ ИМЕНАМИ. Переносятся только те, что
    # сборка действительно нашла: пусто у всех прочих групп, и ни одно поле не
    # выдумывается. Отсюда они попадают и в строку решения, и в запись позиции.
    for _зп in ("zapusk_sol_sozdatelya", "zapusk_lamportov_sozdatelya",
                 "zapusk_sozdanie", "zapusk_pokupka_sozdatelya",
                 "zapusk_mint_authority", "zapusk_why_not"):
        if сб.get(_зп) is not None:
            из_[_зп] = сб[_зп]
    # НИЖНИЙ ПРЕДЕЛ РЕЗЕРВА ПУЛА. Стоит ПОСЛЕ сборки, потому что резерв считает
    # она (по хранилищам пула после сделки источника), и ДО подписи -- ни
    # лампорта ещё не ушло. Предел задан, а резерв неизвестен -- отказ: покупать
    # в пул неизвестного размера владелец не велел.
    предел_резерва = резерв_пула_минимум_sol(группа)
    if сб.get("ok") and предел_резерва is not None:
        резерв = сб.get("pool_reserve_sol")
        if not isinstance(резерв, (int, float)):
            из_["why_not"] = (f"по группе {группа} резерв пула должен быть не ниже "
                               f"{предел_резерва} SOL-экв., а он неизвестен")
            return из_
        if float(резерв) < предел_резерва:
            из_["why_not"] = (f"резерв пула {round(float(резерв), 4)} SOL-экв. "
                               f"({сб.get('pool_reserve_kind') or 'неизвестного вида'}) "
                               f"ниже предела группы {предел_резерва}")
            return из_
    if not сб.get("ok"):
        из_["why_not"] = сб.get("why_not")
        # ПРИЧИНА ДОЛЖНА БЫТЬ ТОЙ, ЧТО И ОТКАЗАЛА ПОСЛЕДНЕЙ (слово владельца
        # 05.10 про USDC-ногу). Прежде наружу всегда уходил отказ ПРЯМОЙ
        # сборки -- "котировка пула не SOL -- полоса только одношаговая", --
        # даже когда ветка USDC-ноги открывалась и отказывала по своей,
        # совершенно другой причине. По такому счётчику три дня выходило, что
        # полоса "только одношаговая", хотя вторая нога строилась и падала на
        # опознании пула. Теперь, если ветка открывалась, наружу идёт ЕЁ
        # причина; а тип, у которого строителя второй ноги нет вовсе,
        # называется прямо.
        if (из_.get("lane_usdc_vetka") or {}).get("да"):
            _пр_ноги = (из_.get("lane_usdc_signaly_why_not")
                        or из_.get("lane_usdc_noga_why_not"))
            _тип_ноги = (из_.get("lane_usdc_signaly_godilos") is not None
                         or из_.get("lane_usdc_noga_godilos") is not None)
            if _пр_ноги:
                из_["why_not"] = f"USDC-нога: {_пр_ноги}"
            elif not _тип_ноги:
                _прог_ноги = (сб.get("pool_program") or из_.get("pool_program")
                              or "тип не назван")
                из_["why_not"] = f"тип пула вне USDC-ноги ({_прог_ноги})"
        # ЧУЖОЙ ПОЛУЧАТЕЛЬ -- ЭТО УТЕЧКА, И ТУТ РУБИЛЬНИК (владелец 25.09).
        # Сборка отказала, ни лампорта не ушло -- но список счетов Sender
        # правится руками, и адрес не из списка означает, что следующая
        # сборка могла бы отправить чаевые неизвестно кому. Останавливаемся
        # до разбора человеком.
        if "адрес чаевых не из списка" in (сб.get("why_not") or ""):
            из_["kill_set"] = остановить_полосу(
                состояние, f"чужой получатель чаевых: {сб.get('why_not')}")
            из_["kill"] = True
        return из_

    # СИМУЛЯЦИЯ -- ВНЕ ПУТИ СДЕЛКИ. Решение владельца 25.09 после первой живой
    # пары: симуляция стоила 52.95 мс, и ровно из-за неё мы пришли в блок на
    # 11.4 мс позже Bloom. Теперь она идёт СВОИМ потоком и только в журнал, а
    # защита сделки -- min_out внутри самой транзакции (проскальзывание уже
    # заложено в сборке). Путь сделки: сборка -> подпись -> отправка.
    #
    # В нежилом режиме (без BLOOM_OWN_SEND_LIVE) симуляция остаётся
    # ПОСЛЕДОВАТЕЛЬНОЙ: там торопиться некуда, а её вердикт -- единственный
    # смысл сухого прогона.
    _шаг("сборка")
    if rpc_call is not None and тень_сим is not None and живьём():
        запустить_тень_симуляции(rpc_call, сб.get("tx_base64"),
                                  журнал=тень_сим,
                                  метка={"source_sig": источник_подпись,
                                          "mint": минт, "op": ключ_операции})
        из_["sim_shadow"] = "запущена в своём потоке"
    elif not живьём():
        из_["stage"] = "sim"
        if rpc_call is None:
            из_["why_not"] = "симулировать нечем (узел не передан)"
            из_["code"] = "SKIP_SIM_FAIL"
            return из_
        t_сим = time.perf_counter()
        try:
            _, _, SB, _ = _модули()
            знач = (rpc_call("simulateTransaction",
                            [сб["tx_base64"], SB.SIM_OPTS]) or {}).get("value") or {}
            из_.update(SB.classify_sim(знач))
        except Exception as exc:  # noqa: BLE001
            из_["why_not"] = f"симуляция: {type(exc).__name__}: {str(exc)[:160]}"
            из_["code"] = "SKIP_SIM_FAIL"
            из_["sim_ms"] = round((time.perf_counter() - t_сим) * 1000, 2)
            return из_
        из_["sim_ms"] = round((time.perf_counter() - t_сим) * 1000, 2)
    if not живьём():
        # Нежилой режим: дальше подписи нет и денег нет.
        из_.update(stage="dry", dry=True, ok=True)
        return из_

    # ПОДПИСЬ. Тёплый blockhash обязан быть свежим: просроченным подписывать
    # бессмысленно, сеть такую транзакцию отбросит.
    _шаг("симуляция")
    из_["stage"] = "blockhash"
    if not blockhash:
        из_["why_not"] = "тёплого blockhash нет -- подписывать нечем"
        return из_
    возраст = (сейчас - float(blockhash_ts)) if blockhash_ts else None
    из_["blockhash_age_s"] = round(возраст, 2) if возраст is not None else None
    if возраст is not None and возраст > СРОК_BLOCKHASH_S:
        из_["why_not"] = (f"тёплый blockhash старше {СРОК_BLOCKHASH_S} с "
                          f"(возраст {из_['blockhash_age_s']} с) -- сеть отбросит")
        return из_
    _шаг("blockhash")
    из_["stage"] = "sign"
    t_подпись = time.perf_counter()
    пд = подписать(сб["tx_base64"], blockhash=blockhash,
                   ожидаемый_кошелёк=кошелёк_полосы(),
                   секрет=(секрет if секрет is not None else ключ_полосы()))
    из_["sign_ms"] = round((time.perf_counter() - t_подпись) * 1000, 2)
    if not пд.get("ok"):
        из_["why_not"] = пд.get("why_not")
        return из_
    из_["signature"] = пд.get("signature")

    # ВАРИАНТЫ НА NONCE собираются и подписываются ЗДЕСЬ, после проверки
    # обычного пути: если они не собрались, полоса уходит обычной отправкой, а
    # не остаётся без покупки.
    варианты = None
    # ВАРИАНТЫ НА NONCE СОБИРАЕТ ПРЯМОЙ СБОРЩИК -- на маршруте Jupiter их нет.
    # Молча позвать _вариант() значило бы получить от прямого сборщика тот же
    # отказ по котировке на каждый сервис и записать его как сбой вариантов.
    # Основная транзакция при этом уже подписана и уходит обычным путём пула;
    # nonce в ней тот же, если он был передан в сборку.
    if режим_нонса and сб.get("lane_route"):
        из_["pool_nonce"] = dict(из_.get("pool_nonce") or {})
        из_["pool_nonce"]["fallback"] = ("обычная отправка пула: варианты на nonce "
                                          "собирает только прямой сборщик")
        режим_нонса = False
    if режим_нонса:
        из_["stage"] = "nonce_variants"

        # ОДИН СНИМОК ПУЛА НА ВСЕ ВАРИАНТЫ (замер 01.10, см. кэш_чтений).
        # Обёртка живёт ровно эту покупку: между сигналами кэша нет.
        _rpc_вариантов = кэш_чтений(rpc_call)

        def _вариант(список_ч, пара_нонса, вперёд=False):
            return собрать(tx_источника=tx_источника or {},
                            источник=источник or "", минт=минт or "",
                            наш_кошелёк=кошелёк_полосы(),
                            чаевые_списком=список_ч, лампорты=лампорты,
                            проскальзывание=проскальзывание,
                            приоритет_лампорты=int(round(приоритет_sol()
                                                          * ЛАМПОРТОВ_В_SOL)),
                            чаевые_лампорты=int(round(чаевые_sol()
                                                       * ЛАМПОРТОВ_В_SOL)),
                            семя=источник_подпись or ключ_операции,
                            нонс=пара_нонса, чаевые_вперёд=вперёд,
                            rpc_call=_rpc_вариантов, налог_минта=налог_минта)

        т_варианты = time.perf_counter()
        в = собрать_варианты_нонсом(
            сборщик=_вариант, сервисы=сервисы_пула, нонс=нонс,
            семя=источник_подпись or ключ_операции,
            секрет=(секрет if секрет is not None else ключ_полосы()))
        из_["variants_ms"] = round((time.perf_counter() - т_варианты) * 1000, 2)
        # ЧТЕНИЯ ВАРИАНТОВ -- ЧИСЛОМ В ЗАПИСЬ. Без них "стало быстрее" осталось
        # бы словами: видно, сколько запросов было и сколько ушло в сеть.
        из_["variants_reads"] = {"запросов": _rpc_вариантов.запросов,
                                  "в_сеть": _rpc_вариантов.в_сеть,
                                  "из_кэша": _rpc_вариантов.из_кэша}
        из_["pool_nonce"].update(
            n_variants=в.get("n_variants"), why_not=в.get("why_not"),
            candidates=в.get("candidates"),
            tips_total_lamports=в.get("tips_total_lamports"),
            sizes=[с.get("size") for с in (в.get("rows") or []) if с.get("ok")])
        if в.get("ok"):
            варианты = в
        else:
            # Не собрались варианты -- обычный путь остаётся, и он уже подписан.
            из_["pool_nonce"]["fallback"] = "обычная отправка пула"

    # ОТПРАВКА. Пределы, рубильник и бронь -- внутри, под замком.
    _шаг("подпись")
    # МЕТКА ПОДПИСИ -- НАСТОЯЩИМИ ЧАСАМИ (п.6). Между ней и ts_decision лежит
    # всё наше: сборка, симуляция, blockhash, подпись; между ней и ts_sent_buy --
    # только уход в сеть. Без этих двух меток вопрос "где именно 12 мс остатка"
    # разрешался бы рассуждением, а не числом.
    из_["ts_signed"] = time.time()
    # ПОДШАГИ РЕШЕНИЯ -- В ЗАПИСЬ ДО ОТПРАВКИ: дальше идёт сеть, и её время к
    # "решили" не относится. Владелец просил сначала числа, потом правку.
    из_["podshagi_ms"] = _подшаги()
    из_["stage"] = "send"
    из_["ts_sent_buy"] = time.time()
    if режим_нонса or сб.get("nonce_account"):
        # НАША ОТПРАВКА МОГЛА СДВИНУТЬ NONCE. Помечаем тёплое значение грязным
        # ДО отправки, а не после: между отправкой и возвратом ответа другой
        # поток может зайти за nonce, и тёплое значение к тому моменту уже
        # недостоверно. Часы перечитают аккаунт и снимут метку.
        # ВТОРОЕ УСЛОВИЕ -- ПРО МАРШРУТ, И ОНО НЕ ЗАПАС. Выше режим_нонса СНЯТ,
        # когда сборка вышла маршрутом (вариантов на нём нет), а advance_nonce в
        # той транзакции УЖЕ стоит первой инструкцией -- значит уходит она со
        # сдвигом nonce. По одному режим_нонса метка бы не встала, тёплое
        # значение осталось бы прежним, и варианты следующего сигнала ушли бы
        # подписанными мёртвым хешем nonce -- то есть сигнал был бы потерян
        # целиком. Спрашиваем поэтому саму сборку: nonce_account у неё непуст
        # ровно тогда, когда advance_nonce в транзакцию попал.
        испортить_тёплый_нонс("после нашей отправки: nonce мог быть сдвинут")
    # РЕГИОНАЛЬНЫЕ ТОЧКИ (III.14). Флаг выключен -- словарь пустой, и отправка
    # идёт ровно как сейчас; включён -- вариант каждого сервиса уходит в его же
    # точку рядом с лидером слота. Целевой слот -- следующий за слотом
    # источника: в него мы и стремимся попасть.
    рег = региональные_адреса(
        rpc_call, (int(источник_слот) + 1) if источник_слот else None,
        [с.get("sender") for с in ((варианты or {}).get("rows") or []) if с.get("ok")])
    если_рег = рег if (рег.get("адреса") or рег.get("регион")) else None
    # ПРИЧИНА ПИШЕТСЯ ВСЕГДА, А НЕ ТОЛЬКО ПРИ УСПЕХЕ. Раньше поле ставилось
    # лишь когда адреса нашлись, и у сделки 30.09 в 14:06Z регион в записи не
    # оставил НИ ОДНОГО следа: по записи нельзя было отличить "регион подобрал
    # точку" от "регион отказал и почему". Замер "S+0 до и после региона" на
    # таких записях не проверяем вовсе -- он просто не опровергается.
    # Поведение отправки этим не меняется: если_рег считается как прежде.
    _адр = рег.get("адреса") or {}
    из_["region_send"] = {"регион": рег.get("регион"), "лидер": рег.get("лидер"),
                           "точек": len(_адр), "отправители": sorted(_адр),
                           "точки": (рег.get("точки") or None),
                           # ЦЕЛЕВОЙ СЛОТ -- В ЗАПИСЬ: регион лидера считается
                           # ДЛЯ НЕГО, и без слота нельзя проверить, тот ли это
                           # лидер, что у посадки.
                           "слот": ((int(источник_слот) + 1) if источник_слот
                                     else None),
                           "why_not": рег.get("why_not")}
    о = отправить(пд["tx_base64"], состояние=состояние, варианты=варианты,
                  региональные=если_рег,
                  ключ_операции=ключ_операции, минт=минт, лампорты=лампорты,
                  источник_подпись=источник_подпись, источник_слот=источник_слот,
                  # АДРЕС ИСТОЧНИКА -- в бронь позиции: по паре "источник +
                  # минт" считается предел покупок.
                  источник=источник,
                  # У пула своя подпись вызова отправителя (адрес, тело,
                  # заголовки, таймаут) -- подставлять сюда одиночного
                  # отправителя полосы нельзя, они разные.
                  отправитель=(отправитель_пула if сервисы_пула else отправитель),
                  сейчас=сейчас, сервисы=сервисы_пула, группа=группа,
                  тип_пула=сб.get("pool_program"),
                  # УДЕРЖАНИЕ ГРУППЫ -- В ЗАПИСЬ ПОЗИЦИИ, а не только в отчёт:
                  # по этому полю сторож ставит таймер продажи.
                  держать_слотов=из_.get("hold_slots"),
                  # ФАКТЫ ЗАПУСКА -- В ЗАПИСЬ ПОЗИЦИИ. У прочих групп их в
                  # отчёте сборки нет, и словарь выходит пустым.
                  запуск={к: v for к, v in из_.items()
                          if к.startswith("zapusk_")})
    if о.get("pool") is not None:
        из_["pool"] = о["pool"]
        из_["pool_winner"] = о.get("pool_winner")
    # СПАСЕНИЕ NONCE -- отдельной функцией, чтобы его можно было проверить без
    # всей сборки покупки (иначе проверялись бы только части, а связка -- на
    # слово).
    if варианты and о.get("sent"):
        из_["pool_nonce"] = dict(из_.get("pool_nonce") or {})
        из_["pool_nonce"].update(спасти_нонс_если_не_село(
            состояние=состояние, кандидаты=(о.get("pool") or {}).get("candidates"),
            rpc_call=rpc_call, нонс=нонс,
            секрет=(секрет if секрет is not None else ключ_полосы()),
            отправитель=отправитель_пула,
            строки_вариантов=(варианты.get("rows") if варианты else None)))
        # СЕВШАЯ ПОДПИСЬ -- В ПОЗИЦИЮ. В варианте на nonce подпись, которую нам
        # вернул первый ответивший сервис, и подпись, которая СЕЛА, -- разные:
        # ответ значит "принял". Сторож ищет покупку по подписи позиции, и
        # оставить там чужую значит искать то, чего в цепи нет.
        сел = (из_["pool_nonce"].get("landing") or {})
        if сел.get("landed") and сел.get("signature") and о.get("cid"):
            из_["signature_landed"] = сел["signature"]
            из_["pool_winner"] = сел.get("sender")
            try:
                состояние.update_position(
                    о["cid"], lane=МЕТКА,
                    lane_signature=сел["signature"],
                    lane_signature_accepted_first=о.get("result"),
                    lane_pool_winner=сел.get("sender"),
                    lane_pool_mode="nonce")
            except Exception as exc:  # noqa: BLE001
                из_["position_update_why_not"] = (
                    f"севшая подпись не записана: {type(exc).__name__}")
    из_.update(sent=bool(о.get("sent")), http=о.get("http"),
               send_ms=о.get("send_ms"), cid=о.get("cid"),
               duplicate=о.get("duplicate"))
    # ЗАМЕР МАРШРУТА -- В СТРОКУ ПОЗИЦИИ (владелец 27.09: "время котировки,
    # время сборки, слот посадки"). Слот посадки пишет детектор, когда находит
    # нашу покупку в цепи (lane_landed_slot), поэтому здесь -- котировка,
    # сборка и путь маршрута. Запись в позицию не имеет права ронять отправку:
    # деньги уже ушли, и потерять из-за замера нечего, кроме замера.
    # МЕТКА ДВУХШАГОВОГО МАРШРУТА -- В ПОЗИЦИЮ. По ней считается, сколько
    # двухшаговых покупок уже СЕЛО (размер_первой_двухшаговой), и по ней же
    # видно в выгрузке, чем куплена позиция. Запись не имеет права ронять
    # отправку: деньги уже ушли.
    if из_.get("route") == "two_step" and о.get("cid"):
        try:
            состояние.update_position(
                о["cid"], lane=МЕТКА, lane_two_step=True,
                lane_two_step_quote_mint=(из_.get("two_step") or {}).get("quote_mint"),
                lane_two_step_leg1_program=(из_.get("two_step") or {}).get("leg1_pool_program"),
                lane_two_step_size_sol=из_.get("two_step_size_sol"),
                lane_two_step_quote_fee_bps=(из_.get("two_step") or {}).get("quote_fee_bps"))
        except Exception as exc:  # noqa: BLE001
            из_["position_update_why_not"] = (
                f"метка двухшагового не записана: {type(exc).__name__}")
    if сб.get("lane_route") and о.get("cid"):
        лр = из_.get("lane_route") or {}
        try:
            состояние.update_position(
                о["cid"], lane=МЕТКА,
                lane_route=сб.get("lane_route"),
                lane_route_quote_ms=лр.get("quote_ms"),
                lane_route_ix_ms=лр.get("ix_ms"),
                lane_route_lut_ms=лр.get("lut_ms"),
                lane_route_build_ms=лр.get("build_ms"),
                lane_route_path=лр.get("path"),
                lane_route_steps=лр.get("steps"),
                lane_route_quote_slot=лр.get("quote_slot"),
                lane_route_min_out=лр.get("min_out"),
                lane_route_expected_out=лр.get("expected_out"))
        except Exception as exc:  # noqa: BLE001
            из_["position_update_why_not"] = (
                f"замер маршрута не записан: {type(exc).__name__}")
    if о.get("lane_state") is not None:
        из_["lane_state"] = о.get("lane_state")
    # КОНТРОЛЬ -- СРАЗУ ПОСЛЕ ПОКУПКИ и никогда до неё: покупка это деньги
    # и место в блоке, контроль -- замер. Отправляется он и при неудачной
    # покупке тоже: неудача покупки не делает замер пути ненужным, а пределы
    # у контроля свои.
    #
    # ОТДЕЛЬНОГО "ОСНОВНОГО" КОНТРОЛЯ БОЛЬШЕ НЕТ. Решение владельца 25.09:
    # "убрать отдельный основной контроль через Helius -- Helius уже есть в
    # веере, это дубль". Раньше на сигнал уходили шесть транзакций (одна
    # Helius'у отдельно плюс пятеро в веере) и Helius платился дважды.
    if поток_контроля is not None and о.get("duplicate"):
        # ПОВТОР ПО КЛЮЧУ ОПЕРАЦИИ -- НЕ СИГНАЛ. Покупка отказана потому, что
        # по этому же ключу уже отправляли: значит сигнал один, и веер по нему
        # уже уходил. Второй веер стоил бы 0.003 SOL и ещё один из двадцати
        # суточных сигналов -- за замер, которого нет: сравнивать не с чем,
        # покупки в этот раз не было вовсе.
        из_["controls_by_sender"] = {
            "rows": [], "sent": 0,
            "why_not": ("покупка отказана как повтор по ключу операции -- "
                        "веер по этому сигналу уже уходил, второй не нужен")}
    elif поток_контроля is not None:
        # ВЕЕР ПО СЕРВИСАМ: контроль через КАЖДЫЙ подключённый. Ждать готовности
        # долго нельзя -- смысл замера в том, что он уходит рядом с покупкой;
        # не успел, значит пары не будет, и это сказано словами.
        поток_контроля.join(timeout=ОЖИДАНИЕ_КОНТРОЛЯ_S)
        if поток_контроля.is_alive() or not веер_готов:
            из_["controls_by_sender"] = {
                "rows": [], "sent": 0,
                "why_not": (веер_готов.get("почему")
                             or f"веер контролей не готов за {ОЖИДАНИЕ_КОНТРОЛЯ_S} с "
                                "-- пары без контроля")}
            веер = из_["controls_by_sender"]
        else:
            веер = провести_контроли_по_сервисам(
                состояние=состояние, blockhash=blockhash, blockhash_ts=blockhash_ts,
                семя=(источник_подпись or ключ_операции), секрет=секрет,
                сейчас=сейчас, подготовленное=веер_готов,
                # В бою здесь None -- уходит настоящий запрос. Подменяется
                # только в самопроверке: без этого весь веер внутри провести()
                # проверить было нечем, кроме сети.
                отправитель=отправитель_веера)
        for стр in веер.get("rows") or []:
            if стр.get("ts_sent") and из_.get("ts_sent_buy"):
                стр["after_buy_ms"] = round(
                    (float(стр["ts_sent"]) - float(из_["ts_sent_buy"])) * 1000.0, 2)
        из_["controls_by_sender"] = веер

    if о.get("ok"):
        из_.update(stage="sent", ok=True, dry=False)
        # Подпись из ответа Sender и наша сходятся по построению: мы её сами
        # и считали. Если вдруг нет -- это не успех, а расхождение, и в
        # позиции должны лежать обе.
        из_["signature_sender"] = о.get("result")
        # ЧИСЛА ТЕНИ НУЛЯ ЧТЕНИЙ -- ОДНИМ ЧТЕНИЕМ СБОРКИ, ДО записи: шесть
        # обращений подряд внутри вызова update_position читались бы шесть раз,
        # и один отказ разобрал бы только часть полей.
        _нч_сб = тень_dlmm_нуль(сб)
        try:
            состояние.update_position(
                о.get("cid"), state="bought", lane=МЕТКА,
                lane_signature=о.get("result") or пд.get("signature"),
                lane_signature_local=пд.get("signature"),
                # ВРЕМЯ ОТПРАВКИ -- НАСТОЯЩЕЕ. Здесь стояло ts_sent=сейчас,
                # то есть метка НАЧАЛА обработки сигнала, а ts_intent полоса
                # пишет позже, в резервирующей записи. Из-за этого "собрали"
                # (ts_intent -> ts_sent) в отчёте выходило ОТРИЦАТЕЛЬНЫМ (от
                # -12 до -64 мс на 22 сделках с 18:00Z 28.09), а "всего" --
                # меньше правды. Настоящий момент отправки уже посчитан в
                # ts_sent_buy, его и пишем.
                ts_sent=(из_.get("ts_sent_buy") or сейчас),
                ts_accepted=time.time(),
                # МЕТКИ РЕШЕНИЯ И ПОДПИСИ -- В ПОЗИЦИЮ (п.6): отчёт по сделкам
                # считает "решили" и "собрали" по позиции, а не по журналу.
                ts_decision=из_.get("ts_decision"),
                ts_signed=из_.get("ts_signed"),
                pool=None, program=сб.get("pool_program"),
                # ПОКОЛЕНИЕ ПУТИ СБОРКИ -- В ЗАПИСЬ: без него правило "первая
                # сделка на новом типе пула" считало бы севшие по переписанному
                # пути вместе с нынешними.
                program_gen=поколение_сборки(сб.get("pool_program")),
                lane_min_out=сб.get("min_out"),
                lane_expected_out=сб.get("expected_out"),
                # ТОЧКА ОТПРАВКИ -- "кто довёз" для строки владельца, когда
                # пула не было: у пула на этот вопрос отвечает pool_winner.
                lane_send_point=о.get("send_point"),
                lane_send_ms=о.get("send_ms"), lane_build_ms=сб.get("build_ms"),
                # ЧТЕНИЯ УЗЛА ВНУТРИ СБОРКИ (слово владельца в ночь 29->30.09,
                # п.1). У DLMM поколения 2 сборка идёт 39-56 мс против 0.7 мс у
                # прежнего пути, и весь разрыв -- два getMultipleAccounts точной
                # котировки. Без этих полей разложить те миллисекунды нечем.
                lane_dlmm_reads=чтения_dlmm(сб)[0],
                lane_dlmm_reads_ms=чтения_dlmm(сб)[1],
                # ТЕНЬ ОДНОГО ЧТЕНИЯ -- В ЗАПИСЬ ПОЗИЦИИ. Три значения: True --
                # путь Code-3 на этом сигнале сработал бы, False -- отказал бы
                # (и почему), None -- посчитать было нечем. По ним и решается
                # "село >= прежнего" на БОЕВОМ отставании, а не на журнальном.
                lane_dlmm_odno_godilos=тень_dlmm(сб)[0],
                lane_dlmm_odno_why_not=тень_dlmm(сб)[1],
                # ТЕНЬ НУЛЯ ЧТЕНИЙ -- ШЕСТЬ ПОЛЕЙ (утренний пакет 01.10, п.1):
                # годилось, причина, ОБЕ цены и ОБА минимума. Обе цены и оба
                # минимума в записи нужны не для красоты: без них "разошлось на
                # 1 %" нечем проверить -- процент пришлось бы верить на слово.
                lane_dlmm_nol_godilos=_нч_сб["годилось"],
                lane_dlmm_nol_why_not=_нч_сб["почему_нет"],
                lane_dlmm_nol_cena_polosy=_нч_сб["цена_полосы"],
                lane_dlmm_nol_cena_teni=_нч_сб["цена_тени"],
                lane_dlmm_nol_min_out_polosy=_нч_сб["min_out_полосы"],
                lane_dlmm_nol_min_out_teni=_нч_сб["min_out_тени"],
                lane_dlmm_nol_otklonenie_pct=_нч_сб["отклонение_%"],
                # ВРЕМЕНА ПО ШАГАМ (I.7): без них "стало быстрее" -- обещание.
                lane_nonce_ms=из_.get("nonce_ms"),
                lane_sign_ms=из_.get("sign_ms"),
                lane_variants_ms=из_.get("variants_ms"),
                # ЧТЕНИЯ ВАРИАНТОВ: сколько запросов было и сколько ушло в сеть.
                # По этим двум числам видно, работает ли один снимок пула на все
                # варианты, или сборка опять читает пул шесть раз.
                lane_variants_reads_net=((из_.get("variants_reads") or {})
                                          .get("в_сеть")),
                lane_variants_reads_cached=((из_.get("variants_reads") or {})
                                             .get("из_кэша")),
                lane_nonce_warm=((из_.get("pool_nonce") or {}).get("warm")),
                lane_tip_account=сб.get("tip_account"),
                lane_priority_lamports=int(round(приоритет_sol() * ЛАМПОРТОВ_В_SOL)),
                lane_ts_sent_buy=из_.get("ts_sent_buy"),
                # БОЕВОЙ ПУЛ: кто довёз покупку (ответил первым) и сколько
                # чаевых ушло всем вместе. Без этих полей "пул работает"
                # пришлось бы принимать на слово, а строка пары не смогла бы
                # сказать владельцу, кто довёз.
                # РЕГИОНАЛЬНАЯ ОТПРАВКА -- В ЗАПИСЬ ПОЗИЦИИ. Выгрузка читает
                # ИМЕННО эти имена (lane_region*), а писать их не умел никто:
                # поэтому region_otpravki в выгрузке был пуст ВСЕГДА, с любым
                # значением флага, и печатал "региональная отправка регион не
                # писала" даже когда она работала. Адреса сюда не идут: у
                # Helius ключ стоит в пути url. Идут регион лидера, число и
                # имена отправителей с точкой, host каждой точки и причина
                # отказа, если регион ничего не поменял.
                lane_region=((из_.get("region_send") or {}).get("регион")),
                # РЕГИОН ЛИДЕРА -- РЯДОМ С lane_region (слово владельца 01.10,
                # п.5). Докладчик читает ИМЕННО lane_region_leader, и без него в
                # строке BUY стояло "EU→—": регион точки есть, региона лидера
                # нет. Это ТО ЖЕ САМОЕ число, которым выбиралась точка (лидер
                # целевого слота), второго запроса к узлу тут не появляется --
                # значит на денежный путь это не добавляет ни миллисекунды.
                lane_region_leader=((из_.get("region_send") or {}).get("регион")),
                lane_region_leader_slot=((из_.get("region_send") or {}).get("слот")),
                lane_region_point=((из_.get("region_send") or {}).get("точки")),
                lane_region_senders=((из_.get("region_send") or {}).get("отправители")),
                lane_region_why_not=((из_.get("region_send") or {}).get("why_not")),
                lane_pool_winner=из_.get("pool_winner"),
                lane_pool_senders=((из_.get("pool") or {}).get("senders")),
                lane_pool_ok_senders=((из_.get("pool") or {}).get("ok_senders")),
                # ВАРИАНТЫ НА NONCE: подписей несколько, села одна, и какая --
                # решает цепь. Без списка кандидатов в позиции детектор не
                # узнал бы нашу же транзакцию в потоке, а сторож не нашёл бы
                # покупку для продажи.
                lane_pool_mode=((из_.get("pool") or {}).get("mode")),
                lane_pool_candidates=((из_.get("pool") or {}).get("candidates")),
                lane_pool_nonce=((из_.get("pool") or {}).get("nonce_account")),
                lane_tips_total_sol=((сб.get("tips_total_lamports") or 0)
                                      / ЛАМПОРТОВ_В_SOL),
                # ВЕЕР: подпись каждого сервиса и время его отправки. Без этого
                # детектор не узнает их в потоке своего кошелька, и замер путей
                # останется без ответа "кто довёз быстрее".
                control_services=[
                    {"sender": с.get("sender"), "signature": с.get("signature"),
                      "ts_sent": с.get("ts_sent"), "sent": bool(с.get("sent")),
                      "send_ms": с.get("send_ms"),
                      "after_buy_ms": с.get("after_buy_ms"),
                      "tip_lamports": с.get("tip_lamports"),
                      "cost_sol": с.get("cost_sol"),
                      "why_not": с.get("why_not")}
                    for с in ((из_.get("controls_by_sender") or {}).get("rows") or [])
                ] or None)
        except Exception as exc:  # noqa: BLE001
            # Отправка уже состоялась: молчать нельзя, но и "не ok" ставить
            # поздно -- деньги ушли. Причина идёт в отчёт отдельным полем.
            из_["position_update_why_not"] = f"{type(exc).__name__}: {str(exc)[:160]}"
        return из_

    из_["why_not"] = о.get("why_not")
    if о.get("kill"):
        из_["kill"] = True
    # БРОНЬ ПОСЛЕ НЕУДАЧИ. Закрываем её ТОЛЬКО на определённом отказе узла:
    # он разобрал транзакцию и отверг её, в цепи её нет. Любая другая
    # неудача (сеть молчит, ответ не JSON, 200 без подписи) неопределённа --
    # транзакция могла уйти, и бронь обязана остаться открытой, иначе сторож
    # не узнает о токене, который у нас на руках.
    if о.get("cid"):
        try:
            if о.get("definite_refusal"):
                состояние.update_position(
                    о["cid"], state=ST.STATE_CLOSED, lane=МЕТКА,
                    close_reason="sender_refused", chain_ok=False,
                    why_not=str(о.get("why_not"))[:300])
                из_["reservation"] = "closed"
            else:
                состояние.update_position(
                    о["cid"], lane=МЕТКА, lane_send_ambiguous=True,
                    lane_signature_local=пд.get("signature"),
                    why_not=str(о.get("why_not"))[:300])
                из_["reservation"] = "open_ambiguous"
        except Exception as exc:  # noqa: BLE001
            из_["position_update_why_not"] = f"{type(exc).__name__}: {str(exc)[:160]}"
    return из_


# ------------------------------------------------------------------ самопроверка

def self_test() -> int:
    # СТРАЖ САМОПРОВЕРОК -- ПЕРВОЙ СТРОКОЙ. 25.09 самопроверки, запущенные на
    # хосте с боевым окружением, отправили строки с заглушками в БОЕВОЙ чат
    # владельца. Теперь тест физически не может ни написать в боевой путь, ни
    # выйти в сеть: страж падает исключением, а не предупреждает.
    import selftest_guard as _SG  # noqa: PLC0415

    _охрана = _SG.включить()
    всего = [0, 0]
    # СТОП ПО ЦЕПИ НА ВРЕМЯ ОСТАЛЬНЫХ ПРОВЕРОК СНЯТ. Пределы полосы ниже
    # проверяются по позициям, цепного числа у них нет, и с поднятым флагом
    # каждая получила бы честный отказ "стоп считается стоящим" -- то есть
    # проверяла бы не то, что написано в её имени. Сам стоп по цепи проверяется
    # своим разделом, где флаг поднимается явно.
    _было_цепь_флаг = СТОП_ПО_ЦЕПИ
    globals()["СТОП_ПО_ЦЕПИ"] = False
    # ДНЕВНОЙ СТОП ГРУПП НА ВРЕМЯ ОСТАЛЬНЫХ ПРОВЕРОК ВКЛЮЧЁН ВХОДОМ, И ЭТО НЕ
    # ЗНАЧИТ, ЧТО ОН ВКЛЮЧЁН В РАБОТЕ. По Правилу 16 (слово владельца 02.10)
    # дневных стопов у групп нет: в боевом окружении LANE_GROUP_DAILY_STOP не
    # задан, и потолок_группы отдаёт stop_loss_sol=None. Но САМ МЕХАНИЗМ (ветка
    # гейта, защёлка, чтение числа из файла групп) владелец велел оставить в
    # коде, а механизм без проверок -- это механизм, который сломается молча.
    # Поэтому прежние проверки идут со входом, поднятым здесь, а Правило 16
    # проверяется своим разделом ниже -- на ЗНАЧЕНИЯХ ПО УМОЛЧАНИЮ, без входа.
    _было_стоп_групп = os.environ.get("LANE_GROUP_DAILY_STOP")
    os.environ["LANE_GROUP_DAILY_STOP"] = "1"

    def chk(имя, условие, факт=None):
        всего[0] += 1
        if условие:
            всего[1] += 1
            print(f"  [ok  ] {имя}")
        else:
            print(f"  [ПЛОХО] {имя} -- {факт}")

    # ГРУППЫ ДЛЯ ПРОВЕРОК -- СВОИ, А НЕ БОЕВЫЕ. Проверки денежного пути не
    # должны зависеть от того, что владелец написал в файле групп сегодня:
    # 27.09 одиннадцать проверок упали ровно потому, что опирались на боевые
    # группы (speed_only, lane_only), а финальный план их упразднил. Сам боевой
    # файл проверяется своей самопроверкой -- bloom_source_groups.self_test.
    _кат_групп = tempfile.mkdtemp(prefix="own_send_groups_")
    _было_файл_групп = os.environ.get("BLOOM_SOURCE_GROUPS")

    def _группы_для_проверки(группы: dict) -> None:
        import bloom_source_groups as SG_т  # noqa: PLC0415

        путь = Path(_кат_групп) / "groups.json"
        путь.write_text(json.dumps({"groups": группы}, ensure_ascii=False),
                         encoding="utf-8")
        os.environ["BLOOM_SOURCE_GROUPS"] = str(путь)
        # Кэш снимается руками: две записи в одну наносекунду метку не изменят.
        SG_т._КЭШ = SG_т._МЕТКА = SG_т._ПОСЛЕДНИЙ_ХОРОШИЙ = None

    # --- числа из документации, а не из головы
    chk("tip-аккаунтов ровно десять, как на странице Sender Max",
        len(TIP_ACCOUNTS) == 10 and len(set(TIP_ACCOUNTS)) == 10, len(TIP_ACCOUNTS))
    алфавит = set("123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz")
    chk("все tip-адреса -- base58 нужной длины",
        all(32 <= len(a) <= 44 and set(a) <= алфавит for a in TIP_ACCOUNTS),
        [a for a in TIP_ACCOUNTS if not (32 <= len(a) <= 44)])
    chk("минимальный тип -- 0.001 SOL, как в тарифе Sender Max",
        TIP_MIN_SOL == 0.001, TIP_MIN_SOL)
    chk("адрес Амстердама -- тот, что в документации",
        SENDER_HOSTS["ams"] == "http://ams-sender.helius-rpc.com/fast",
        SENDER_HOSTS["ams"])

    # --- чаевые ниже минимума не опускаются
    было = os.environ.get("BLOOM_OWN_SEND_TIP_SOL")
    os.environ["BLOOM_OWN_SEND_TIP_SOL"] = "0.000005"
    chk("чаевые ниже документированного минимума поднимаются до него",
        чаевые_sol() == TIP_MIN_SOL, чаевые_sol())
    if было is None:
        os.environ.pop("BLOOM_OWN_SEND_TIP_SOL", None)
    else:
        os.environ["BLOOM_OWN_SEND_TIP_SOL"] = было

    # --- приоритет: заданная сумма, а не наугад взятая цена единицы
    chk("цена единицы CU даёт заданный приоритет",
        цена_единицы_cu(1_000_000, 400_000) == 2_500_000,
        цена_единицы_cu(1_000_000, 400_000))
    # ПРЕДЕЛЫ ПО СТРОИТЕЛЯМ (решение владельца 28.09, от МАКСИМУМА, не от p99).
    # ДЛИНА СЛОТА: замер из файла сильнее константы, мусор -- слабее.
    import tempfile as _tf_дс  # noqa: PLC0415

    with _tf_дс.TemporaryDirectory() as d_дс:
        зап = записать_длину_слота(0.2659, слотов=113, окно_с=30.044, state_dir=d_дс)
        chk(f"замер длины слота записан ({зап.get('ok')})", зап.get("ok") is True, зап)
        _ДЛИНА_СЛОТА_КЕШ.update(когда_читали=0.0)
        зн = длина_слота_s(state_dir=d_дс)
        chk(f"читатель берёт ЗАМЕР, а не константу ({зн})", abs(зн - 0.2659) < 1e-9, зн)
        chk("удержание 150 слотов по замеру = 39.9 с, а не 60",
            abs(round(150 * зн, 1) - 39.9) < 0.05, round(150 * зн, 1))
        подр = длина_слота_подробно(state_dir=d_дс)
        chk(f"источник числа назван: {подр.get('источник')!r}",
            подр.get("источник") == "замер", подр)
        chk("мусорный замер не пишется",
            записать_длину_слота(0.0, слотов=1, окно_с=1.0,
                                  state_dir=d_дс).get("ok") is False)
        _ДЛИНА_СЛОТА_КЕШ.update(когда_читали=0.0)
        chk("без файла берётся константа, а не ноль",
            abs(длина_слота_s(state_dir=str(Path(d_дс) / "нету")) - ДЛИНА_СЛОТА_S) < 1e-9)
    _ДЛИНА_СЛОТА_КЕШ.update(когда_читали=0.0, значение=None)
    chk(f"pump_amm {предел_cu('pump_amm')} = макс 136 100 + 25 %",
        предел_cu("pump_amm") == 170_000, предел_cu("pump_amm"))
    chk(f"bonding {предел_cu('bonding')}", предел_cu("bonding") == 140_000)
    chk(f"two_step {предел_cu('two_step')} до первых 20 сделок",
        предел_cu("two_step") == 800_000, предел_cu("two_step"))
    chk(f"новый строитель и неизвестный адрес -- {ПРЕДЕЛ_CU_НОВОГО}",
        предел_cu("launchlab") == ПРЕДЕЛ_CU_НОВОГО
        and предел_cu("dlmm") == ПРЕДЕЛ_CU_НОВОГО
        and предел_cu("АДРЕС_КОТОРОГО_НЕТ") == ПРЕДЕЛ_CU_НОВОГО
        and предел_cu(None) == ПРЕДЕЛ_CU_НОВОГО,
        (предел_cu("launchlab"), предел_cu("АДРЕС_КОТОРОГО_НЕТ")))
    chk("предел берётся и по АДРЕСУ программы, а не только по имени",
        предел_cu("pAMMBay6oceH9fJKBRHGP5D4bD4sWpmSwMn52FMfXEA") == 170_000,
        предел_cu("pAMMBay6oceH9fJKBRHGP5D4bD4sWpmSwMn52FMfXEA"))
    # ПЛАТА = ЦЕНА x ЛИМИТ (документация Solana, поправка владельца 28.09):
    # общая плата держится на 0.001 SOL при ЛЮБОМ пределе строителя, потому что
    # цена единицы считается от самого предела.
    for _предел in (140_000, 170_000, 200_000, 250_000, 800_000):
        _цена = цена_единицы_cu(int(round(ПЛАТА_ПРИОРИТЕТА_SOL * ЛАМПОРТОВ_В_SOL)),
                                 _предел)
        _плата = _цена * _предел / 1_000_000
        chk(f"при пределе {_предел} плата за приоритет {_плата / ЛАМПОРТОВ_В_SOL:.6f} "
            f"SOL (цена {_цена} мкл)",
            abs(_плата - ПЛАТА_ПРИОРИТЕТА_SOL * ЛАМПОРТОВ_В_SOL) <= _предел / 1_000_000 + 1,
            (_предел, _цена, _плата))
    chk(f"предел CU покупки {ПРЕДЕЛ_CU_ПОКУПКИ} (по факту 115 210 + 20 %), "
        f"а приоритет тот же: цена за единицу "
        f"{цена_единицы_cu(1_000_000, ПРЕДЕЛ_CU_ПОКУПКИ)} мкл x {ПРЕДЕЛ_CU_ПОКУПКИ} "
        f"= {цена_единицы_cu(1_000_000, ПРЕДЕЛ_CU_ПОКУПКИ) * ПРЕДЕЛ_CU_ПОКУПКИ / 1_000_000:.6f} "
        f"лампортов",
        ПРЕДЕЛ_CU_ПОКУПКИ == 140_000
        and abs(цена_единицы_cu(1_000_000, ПРЕДЕЛ_CU_ПОКУПКИ) * ПРЕДЕЛ_CU_ПОКУПКИ
                / 1_000_000 - 1_000_000) <= 140_000 / 1_000_000 + 1,
        цена_единицы_cu(1_000_000, ПРЕДЕЛ_CU_ПОКУПКИ))
    chk("нулевой лимит CU не делит на ноль",
        цена_единицы_cu(1_000_000, 0) == 0, цена_единицы_cu(1_000_000, 0))

    # --- адрес чаевых разный, но по одному семени повторяем
    а1 = выбрать_чаевые("ПОДПИСЬ_ОДИН")
    chk("по одному семени адрес чаевых один и тот же",
        а1 == выбрать_чаевые("ПОДПИСЬ_ОДИН") and а1 in TIP_ACCOUNTS, а1)
    разные = {выбрать_чаевые(f"С{i}") for i in range(40)}
    chk("по разным семенам адреса расходятся", len(разные) > 1, разные)

    # --- ОТПРАВКА БЕЗ РУБИЛЬНИКА НЕ УХОДИТ
    было_live = os.environ.get("BLOOM_OWN_SEND_LIVE")
    os.environ.pop("BLOOM_OWN_SEND_LIVE", None)
    ушло: list = []

    def перехват(url, данные, таймаут):
        ушло.append((url, данные))
        return 200, json.dumps({"jsonrpc": "2.0", "result": "ПОДПИСЬ"})

    р = отправить("AAA", отправитель=перехват)
    chk("без BLOOM_OWN_SEND_LIVE=1 не уходит ничего",
        р["sent"] is False and not ушло and "не равен 1" in (р["why_not"] or ""), р)

    os.environ["BLOOM_OWN_SEND_LIVE"] = "1"
    р2 = отправить("AAA", адрес="http://пример/fast", отправитель=перехват,
                    без_учёта=True)
    chk("с рубильником отправка уходит и подпись возвращается",
        р2["ok"] and р2["result"] == "ПОДПИСЬ" and len(ушло) == 1, р2)
    url, тело = ушло[0]
    chk("метод и параметры -- ровно из документации Sender",
        тело["method"] == "sendTransaction"
        and тело["params"][0] == "AAA"
        and тело["params"][1] == {"encoding": "base64", "skipPreflight": True,
                                   "maxRetries": 0}, тело)
    ушло.clear()

    # --- ПОВТОРНАЯ ОТПРАВКА ПО ТОМУ ЖЕ КЛЮЧУ ОПЕРАЦИИ. Вторая сборка даёт
    # ДРУГУЮ транзакцию с другой подписью, то есть вторую настоящую покупку.
    забыть_отправленные()
    ушло.clear()
    # ТИП ПУЛА ДОХОДИТ ДО ЗАПИСИ ПОЗИЦИИ. Без этого вечерний итог по строителям
    # показывал одну графу "поля нет" на все сделки полосы.
    with tempfile.TemporaryDirectory() as _д_тп:
        _ст_тп = ST.ExecState(base=Path(_д_тп) / "s", kill=Path(_д_тп) / "k")
        _было_живьём = os.environ.get("BLOOM_OWN_SEND_LIVE")
        _было_вкл = os.environ.get("BLOOM_OWN_SEND")
        os.environ["BLOOM_OWN_SEND_LIVE"] = "1"
        os.environ["BLOOM_OWN_SEND"] = "1"
        try:
            # СВОЙ перехватчик, не общий: общий считают проверки ниже, и
            # лишняя отправка сбила бы их числа.
            def _перехват_тп(url, данные, таймаут):
                return 200, json.dumps({"jsonrpc": "2.0", "result": "ПОДПИСЬ_ТП"})

            # СРОК ПРОДАЖИ -- ИЗ УДЕРЖАНИЯ ГРУППЫ, а не флагом на всех.
            chk(f"удержание 12 слотов -> срок {срок_продажи_s(12)} с",
                abs(срок_продажи_s(12) - 4.8) < 1e-9, срок_продажи_s(12))
            chk(f"удержание 72 слота -> срок {срок_продажи_s(72)} с",
                abs(срок_продажи_s(72) - 28.8) < 1e-9, срок_продажи_s(72))
            chk("без удержания остаётся флаг окружения",
                срок_продажи_s(None) == float(СРОК_ПРОДАЖИ_S)
                and срок_продажи_s(0) == float(СРОК_ПРОДАЖИ_S)
                and срок_продажи_s("мусор") == float(СРОК_ПРОДАЖИ_S))
            _о_тп = отправить("AAA", состояние=_ст_тп, ключ_операции="ОПТП",
                               минт="МИНТ_ТП", лампорты=10_000_000,
                               источник_подпись="СИГ", источник="ИСТ",
                               отправитель=_перехват_тп,
                               тип_пула="ПРОГРАММА_ПУЛА",
                               держать_слотов=12)
            _поз_тп = [p for p in _ст_тп.positions().values()
                       if p.get("mint") == "МИНТ_ТП"]
            chk(f"тип пула лёг в запись позиции полосы: "
                f"{[p.get('program') for p in _поз_тп]}",
                len(_поз_тп) == 1 and _поз_тп[0].get("program") == "ПРОГРАММА_ПУЛА",
                (_о_тп.get("why_not"), _поз_тп))
            chk(f"срок продажи в записи позиции -- по удержанию группы: "
                f"{[p.get('sell_after_s') for p in _поз_тп]}",
                len(_поз_тп) == 1
                and abs(float(_поз_тп[0].get("sell_after_s") or 0) - 4.8) < 1e-9,
                _поз_тп)
        finally:
            if _было_живьём is None:
                os.environ.pop("BLOOM_OWN_SEND_LIVE", None)
            else:
                os.environ["BLOOM_OWN_SEND_LIVE"] = _было_живьём
            if _было_вкл is None:
                os.environ.pop("BLOOM_OWN_SEND", None)
            else:
                os.environ["BLOOM_OWN_SEND"] = _было_вкл

    р_1 = отправить("AAA", ключ_операции="ОП1", отправитель=перехват, без_учёта=True)
    р_2 = отправить("BBB", ключ_операции="ОП1", отправитель=перехват, без_учёта=True)
    chk("первая отправка по ключу операции уходит",
        р_1["ok"] and len(ушло) == 1, (р_1, len(ушло)))
    chk("вторая по ТОМУ ЖЕ ключу в сеть не уходит вовсе",
        р_2["ok"] is False and р_2.get("duplicate") is True and len(ушло) == 1,
        (р_2, len(ушло)))
    р_3 = отправить("CCC", ключ_операции="ОП2", отправитель=перехват, без_учёта=True)
    chk("другой ключ операции не заблокирован",
        р_3["ok"] and len(ушло) == 2, (р_3, len(ушло)))

    # Неудачная отправка тоже занимает ключ: транзакция могла уйти, а ответ
    # не дойти. Повторять её вслепую нельзя.
    забыть_отправленные()
    ушло.clear()

    def падает_сеть(url, данные, таймаут):
        ушло.append((url, данные))
        raise TimeoutError("сеть молчит")

    н1 = отправить("AAA", ключ_операции="ОП3", отправитель=падает_сеть,
                    без_учёта=True)
    н2 = отправить("AAA", ключ_операции="ОП3", отправитель=падает_сеть,
                    без_учёта=True)
    chk("после сетевой неудачи повтор по тому же ключу запрещён",
        н1["ok"] is False and н2.get("duplicate") is True and len(ушло) == 1,
        (н1["why_not"], н2["why_not"], len(ушло)))
    забыть_отправленные()
    ушло.clear()

    # --- УСПЕХ ТОЛЬКО ПРИ HTTP 200 И ПОДПИСИ В ОТВЕТЕ.
    def код_500(url, данные, таймаут):
        return 500, json.dumps({"jsonrpc": "2.0", "result": "ПОДПИСЬ"})

    п500 = отправить("AAA", отправитель=код_500, без_учёта=True)
    chk("код 500 -- не успех, даже если в теле есть подпись",
        п500["ok"] is False and "кодом 500" in (п500["why_not"] or ""), п500)

    def без_подписи(url, данные, таймаут):
        return 200, json.dumps({"jsonrpc": "2.0", "id": "1"})

    пбп = отправить("AAA", отправитель=без_подписи, без_учёта=True)
    chk("200 без подписи -- не успех, искать в цепи нечего",
        пбп["ok"] is False and "не вернул подпись" in (пбп["why_not"] or ""), пбп)

    def отказ(url, данные, таймаут):
        return 200, json.dumps({"jsonrpc": "2.0",
                                 "error": {"code": -32002, "message": "нет"}})

    р3 = отправить("AAA", отправитель=отказ, без_учёта=True)
    chk("отказ Sender -- не успех и назван словами",
        р3["ok"] is False and "Sender отказал" in (р3["why_not"] or ""), р3)

    def падает(url, данные, таймаут):
        raise TimeoutError("сеть молчит")

    р4 = отправить("AAA", отправитель=падает, без_учёта=True)
    chk("падение сети -- отказ с причиной, а не исключение наружу",
        р4["ok"] is False and "TimeoutError" in (р4["why_not"] or ""), р4)
    if было_live is None:
        os.environ.pop("BLOOM_OWN_SEND_LIVE", None)
    else:
        os.environ["BLOOM_OWN_SEND_LIVE"] = было_live

    # --- ПОТОЛОК РАЗМЕРА И КОШЕЛЁК. Проверяются ДО сборки: собранную
    # транзакцию уже можно подписать.
    выше = собрать(tx_источника={"meta": {}}, источник="SRC", минт="M",
                    наш_кошелёк=кошелёк_полосы(),
                    лампорты=потолок_лампортов() + 1)
    chk("размер выше потолка полосы -- отказ, а не обрезка",
        выше["ok"] is False and "выше потолка" in (выше["why_not"] or ""), выше)
    # ПОТОЛОК ДОЛЖЕН ПРОПУСКАТЬ РАЗМЕРЫ ВЛАДЕЛЬЦА. Это деньги: при потолке
    # 0.05 полоса отказывала на каждом сигнале торгующих групп (leader 0.5,
    # batch5 и lane_s0 0.3) -- ни одной сделки при живых сигналах.
    chk("потолок не ниже самого большого размера владельца (0.5 SOL)",
        ПОТОЛОК_РАЗМЕРА_SOL >= 0.5, ПОТОЛОК_РАЗМЕРА_SOL)
    # ПОДЪЁМ ЖИВ ТОЛЬКО ПРИ ПОТОЛКЕ ПОЛОСЫ НЕ НИЖЕ ПОТОЛКА ПОДЪЁМА -- ИНАЧЕ
    # ПОДЪЁМ ОТНИМАЕТ ПОКУПКУ. Это не вкусовщина, а живой случай 05.10: при
    # потолке полосы 0.5 оба сработавших подъёма (1.872375817 и 1.971248231
    # SOL) кончились ОТКАЗОМ покупки, которая без подъёма ушла бы билетом
    # группы. Сейчас потолок снова 0.5, и держит это именно выключенный
    # подъём: включить его обратно, не подняв потолок, самопроверка не даст.
    chk("подъём выключен ИЛИ потолок полосы не ниже потолка подъёма",
        (not ПОДЪЁМ_ВКЛЮЧЁН) or ПОТОЛОК_РАЗМЕРА_SOL >= ПОТОЛОК_ПОДЪЁМА_SOL,
        (ПОДЪЁМ_ВКЛЮЧЁН, ПОТОЛОК_РАЗМЕРА_SOL, ПОТОЛОК_ПОДЪЁМА_SOL))
    chk("потолок полосы -- 0.5 SOL словом владельца 06.10 (возврат с 2.0)",
        ПОТОЛОК_РАЗМЕРА_SOL == 0.5, ПОТОЛОК_РАЗМЕРА_SOL)
    chk("подъём билета выключен в коде -- слово владельца 06.10",
        ПОДЪЁМ_ВКЛЮЧЁН is False, ПОДЪЁМ_ВКЛЮЧЁН)
    for _р in (0.3, 0.5):
        _в_потолке = собрать(tx_источника={"meta": {}}, источник="SRC", минт="M",
                              наш_кошелёк=кошелёк_полосы(),
                              лампорты=int(round(_р * ЛАМПОРТОВ_В_SOL)))
        chk(f"размер {_р} SOL потолок НЕ режет",
            "выше потолка" not in (_в_потолке["why_not"] or ""),
            _в_потолке.get("why_not"))
    чужой = собрать(tx_источника={"meta": {}}, источник="SRC", минт="M",
                     наш_кошелёк="ЧУЖОЙ_КОШЕЛЁК", лампорты=10_000_000)
    chk("сборка не на кошелёк полосы -- отказ",
        чужой["ok"] is False and "кошелёк полосы" in (чужой["why_not"] or ""),
        чужой)
    ноль = собрать(tx_источника={"meta": {}}, источник="SRC", минт="M",
                    наш_кошелёк=кошелёк_полосы(), лампорты=0)
    chk("нулевой размер -- отказ", ноль["ok"] is False, ноль)

    # --- МИНИМУМ РАВНЫЙ НУЛЮ НЕ ПРОХОДИТ. Флага ok мало: ноль -- это и есть
    # "куплю по любой цене", только под видом посчитанного числа.
    class МодулиСНулевымМинимумом:
        class B:
            PUMP_AMM = "PUMP"
            CPMM = "CPMM"

            @staticmethod
            def extract_template(*a, **kw):
                return {"ok": True, "program": "PUMP"}

            @staticmethod
            def mints_and_vaults(*a, **kw):
                return {"quote_mint": "So11111111111111111111111111111111111111112"}

            @staticmethod
            def min_out_from_reserves(*a, **kw):
                return {"ok": True, "min_out": 0, "expected_out": 0}

            @staticmethod
            def build_buy(*a, **kw):
                raise AssertionError("до сборки дойти не должно")

        class C:
            WSOL = "So11111111111111111111111111111111111111112"

            @staticmethod
            def identify_pool(*a, **kw):
                return {"ok": True, "pool_vault": "ХРАН", "quote_mint": C_WSOL}

        class PP:
            @staticmethod
            def pool_program(*a, **kw):
                return {"pool_program": "PUMP"}

        class SB:
            @staticmethod
            def _labels():
                return {}

    C_WSOL = "So11111111111111111111111111111111111111112"
    было_модули = globals()["_модули"]
    globals()["_модули"] = lambda: (МодулиСНулевымМинимумом.C,
                                     МодулиСНулевымМинимумом.PP,
                                     МодулиСНулевымМинимумом.SB,
                                     МодулиСНулевымМинимумом.B)
    try:
        м0 = собрать(tx_источника={"meta": {}}, источник="SRC", минт="M",
                      наш_кошелёк=кошелёк_полосы(), лампорты=10_000_000)
        chk("минимум ноль -- отказ, покупки по любой цене не будет",
            м0["ok"] is False and "минимум не положителен" in (м0["why_not"] or ""),
            м0)
    finally:
        globals()["_модули"] = было_модули

    # --- КРИВАЯ PUMP.FUN В ПОЛОСЕ (I.2б): только по флагу, и трата не выше
    # нашей. Проверяем на НАСТОЯЩЕЙ покупке из образцов: подменяется только
    # определение пула (у образцов сделка источника шла роутером и задела USDC,
    # поэтому котировка у неё неоднозначная), всё остальное -- настоящий
    # сборщик, настоящая транзакция, настоящая кривая.
    try:
        C_ж, PP_ж, SB_ж, B_ж = _модули()
    except Exception:  # noqa: BLE001
        C_ж = None
    # ТИПЫ ПУЛОВ ПРОВЕРЯЮТСЯ БЕЗ ГРУПП: здесь проверяются ФЛАГИ окружения, и
    # боевой файл (где у групп свой список lane_pools) в этих проверках только
    # мешал бы -- источники образцов числятся в боевых группах.
    _группы_для_проверки({})
    # ПОТОЛОК КОМИССИИ ПУЛА НА x*y=k. Сборщик минимума отдаёт fee_share только
    # у сосредоточенной ликвидности; спрашивать только его значило не проверять
    # потолок на CPMM, Pump AMM, Launchlab и кривой вовсе. Теперь для них
    # комиссия ЗАМЕРЯЕТСЯ по сделке источника.
    chk("комиссия пула: fee_share берётся как есть",
        _доля_комиссии_пула({"fee_share": 0.509}) == 0.509)
    chk("комиссия пула: без fee_share и без сделки источника -- неизвестна",
        _доля_комиссии_пула({"fee_factor": 0.9975}) is None)
    if C_ж is not None:
        обр_cpmm = [x for x in B_ж.load_samples(B_ж.CPMM) if x.get("pool_vault")]
        зам_cpmm = []
        for x_ in обр_cpmm:
            t_ = B_ж.extract_template(x_["tx"], B_ж.CPMM, x_["pool_vault"])
            if not t_.get("ok"):
                continue
            мо_ = B_ж.min_out_from_reserves(t_, x_["tx"], 10_000_000, 0.35)
            if not мо_.get("ok"):
                continue
            зам_cpmm.append((_доля_комиссии_пула(мо_, t_, x_["tx"]), мо_.get("fee_share")))
        chk(f"комиссия пула замерена на живых образцах CPMM ({len(зам_cpmm)} шт.)",
            len(зам_cpmm) >= 5, len(зам_cpmm))
        if зам_cpmm:
            chk("у CPMM сборщик fee_share не даёт -- значит раньше потолок тут "
                "не срабатывал ни разу",
                all(f is None for _, f in зам_cpmm))
            chk("замеренная комиссия -- число в [0, потолок): защита включена и "
                "честные сигналы не отказываются",
                all(isinstance(d, float) and 0.0 <= d < ПОТОЛОК_КОМИССИИ_ПУЛА
                    for d, _ in зам_cpmm),
                sorted((round(d, 6) for d, _ in зам_cpmm), reverse=True)[:3])
    обр_кр = []
    if C_ж is not None:
        файл_кр = (Path(__file__).resolve().parent.parent / "data" / "c2_pool_samples"
                   / f"{B_ж.BONDING}.json")
        if файл_кр.exists():
            обр_кр = json.loads(файл_кр.read_text(encoding="utf-8"))
    образец_кр = next((x for x in обр_кр
                       if B_ж.extract_template(x["tx"], B_ж.BONDING, x["pool_vault"]).get("ok")), None)
    if образец_кр is not None:
        ЛАМП_КР = 10_000_000
        хран_кр = образец_кр["pool_vault"]

        class МодулиКривой:
            class C:
                WSOL = C_ж.WSOL
                NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                @staticmethod
                def identify_pool(*a, **kw):
                    return {"ok": True, "pool_vault": хран_кр,
                            "quote_mint": getattr(C_ж, "NATIVE_QUOTE", "native_sol")}

        было_м = globals()["_модули"]
        было_флаг = os.environ.get("LANE_BONDING_CURVE")
        globals()["_модули"] = lambda: (МодулиКривой.C, PP_ж, SB_ж, B_ж)
        try:
            os.environ["LANE_BONDING_CURVE"] = "0"
            выкл = собрать(tx_источника=образец_кр["tx"], источник=образец_кр["source"],
                            минт=образец_кр["mint"], наш_кошелёк=кошелёк_полосы(),
                            лампорты=ЛАМП_КР)
            chk("кривая pump.fun без флага -- отказ, полоса её не берёт",
                выкл["ok"] is False and "вне полосы" in (выкл["why_not"] or ""), выкл)
            os.environ["LANE_BONDING_CURVE"] = "1"
            вкл = собрать(tx_источника=образец_кр["tx"], источник=образец_кр["source"],
                           минт=образец_кр["mint"], наш_кошелёк=кошелёк_полосы(),
                           лампорты=ЛАМП_КР)
            chk("кривая pump.fun по флагу -- собрана, минимум положителен",
                вкл["ok"] is True and isinstance(вкл.get("min_out"), int) and вкл["min_out"] > 0,
                вкл)
            предел_ок = (вкл.get("max_sol_cost_lamports") == ЛАМП_КР
                         if вкл.get("curve_exact_out") else
                         вкл.get("max_sol_cost_lamports") is None)
            chk("кривая: трата ровно наша, до кривой доходит меньше "
                "(остальное -- комиссии программы), предел по разновидности",
                вкл.get("spend_lamports") == ЛАМП_КР and предел_ок
                and 0 < int(вкл.get("sol_to_curve_lamports") or 0) < ЛАМП_КР,
                {к: вкл.get(к) for к in ("spend_lamports", "curve_exact_out",
                                          "max_sol_cost_lamports", "sol_to_curve_lamports")})
            сыр_кр = base64.b64decode(вкл["tx_base64"]) if вкл.get("tx_base64") else b""
            chk("кривая: обёртки SOL в транзакции нет, котировка нативная, размер в пределе",
                вкл.get("native_quote") is True and C_ж.WSOL.encode() not in сыр_кр
                and 0 < int(вкл.get("size") or 0) <= ПРЕДЕЛ_РАЗМЕРА_TX,
                {"size": вкл.get("size"), "quote_mint": вкл.get("quote_mint")})
            chk("кривая: минимум ниже ожидания (проскальзывание учтено)",
                int(вкл.get("min_out") or 0) < int(вкл.get("expected_out") or 0), вкл)
            # КРИВАЯ ПО ОДНОЙ ГРУППЕ (владелец 26.09, пункт 4). Источник
            # образца в группах не числится, значит его группа -- bloom_lane;
            # при списке "speed_only" кривая по нему идти НЕ должна, даже когда
            # общий флаг стоит.
            os.environ["LANE_BONDING_CURVE_GROUPS"] = "speed_only"
            чужая = собрать(tx_источника=образец_кр["tx"], источник=образец_кр["source"],
                             минт=образец_кр["mint"], наш_кошелёк=кошелёк_полосы(),
                             лампорты=ЛАМП_КР)
            chk("кривая только для одной группы: по источнику вне файла -- отказ, "
                "хотя общий флаг стоит",
                чужая["ok"] is False and "вне полосы" in (чужая["why_not"] or "")
                and чужая.get("lane_group") == "off", чужая)
            os.environ.pop("LANE_BONDING_CURVE_GROUPS", None)
        finally:
            globals()["_модули"] = было_м
            os.environ.pop("LANE_BONDING_CURVE_GROUPS", None)
            if было_флаг is None:
                os.environ.pop("LANE_BONDING_CURVE", None)
            else:
                os.environ["LANE_BONDING_CURVE"] = было_флаг

    # --- METEORA DAMM v2 В ПОЛОСЕ (ночное задание владельца 27.09, пункт 2).
    # Сборщик сверен байт в байт на 17 живых сделках, цена -- по событию свопа.
    # Здесь проверяется ДЕНЕЖНОЕ: без флага не берём, по флагу собираем с
    # положительным минимумом, по чужой группе не берём, и пул с комиссией выше
    # потолка не берём ни при каком флаге.
    обр_d2 = []
    файл_d2 = (Path(__file__).resolve().parent.parent / "data" / "c2_pool_samples"
               / f"{B_ж.DAMM2}.json")
    if файл_d2.exists():
        обр_d2 = json.loads(файл_d2.read_text(encoding="utf-8"))

    def _d2_годный(x, дорогой: bool):
        """Образец с котировкой SOL: дешёвый (комиссия в потолке) или дорогой."""
        t_ = B_ж.extract_template(x["tx"], B_ж.DAMM2, x["pool_vault"])
        if not t_.get("ok"):
            return False
        mv_ = B_ж.mints_and_vaults(t_, x["tx"])
        if not mv_ or mv_["quote_mint"] != C_ж.WSOL:
            return False
        r_ = B_ж.min_out_from_reserves(t_, x["tx"], 10_000_000, 0.35)
        if not r_.get("ok"):
            return False
        дор = float(r_["fee_share"]) > ПОТОЛОК_КОМИССИИ_ПУЛА
        return дор if дорогой else not дор

    образец_d2 = next((x for x in обр_d2 if _d2_годный(x, False)), None)
    дорогой_d2 = next((x for x in обр_d2 if _d2_годный(x, True)), None)
    if образец_d2 is not None:
        хран_d2 = образец_d2["pool_vault"]

        class МодулиD2:
            class C:
                WSOL = C_ж.WSOL
                NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                @staticmethod
                def identify_pool(*a, **kw):
                    return {"ok": True, "pool_vault": хран_d2, "quote_mint": C_ж.WSOL}

        было_м2 = globals()["_модули"]
        было_ф2 = os.environ.get("LANE_DAMM2")
        globals()["_модули"] = lambda: (МодулиD2.C, PP_ж, SB_ж, B_ж)
        try:
            os.environ.pop("LANE_DAMM2_GROUPS", None)
            os.environ["LANE_DAMM2"] = "0"
            d2_выкл = собрать(tx_источника=образец_d2["tx"], источник=образец_d2["source"],
                               минт=образец_d2["mint"], наш_кошелёк=кошелёк_полосы(),
                               лампорты=10_000_000)
            chk("DAMM v2 без флага -- отказ, полоса его не берёт",
                d2_выкл["ok"] is False and "вне полосы" in (d2_выкл["why_not"] or ""),
                d2_выкл)
            os.environ["LANE_DAMM2"] = "1"
            d2_вкл = собрать(tx_источника=образец_d2["tx"], источник=образец_d2["source"],
                              минт=образец_d2["mint"], наш_кошелёк=кошелёк_полосы(),
                              лампорты=10_000_000)
            chk("DAMM v2 по флагу -- собран, минимум положителен и ниже ожидания",
                d2_вкл["ok"] is True and isinstance(d2_вкл.get("min_out"), int)
                and 0 < d2_вкл["min_out"] < int(d2_вкл.get("expected_out") or 0),
                d2_вкл)
            chk("DAMM v2: комиссия пула названа и в потолке",
                d2_вкл.get("pool_fee_share") is not None
                and float(d2_вкл["pool_fee_share"]) <= ПОТОЛОК_КОМИССИИ_ПУЛА,
                d2_вкл.get("pool_fee_share"))
            os.environ["LANE_DAMM2_GROUPS"] = "speed_only"
            d2_чужая = собрать(tx_источника=образец_d2["tx"], источник=образец_d2["source"],
                                минт=образец_d2["mint"], наш_кошелёк=кошелёк_полосы(),
                                лампорты=10_000_000)
            chk("DAMM v2 только для speed_only: по источнику другой группы -- отказ",
                d2_чужая["ok"] is False and "вне полосы" in (d2_чужая["why_not"] or ""),
                d2_чужая)
            os.environ.pop("LANE_DAMM2_GROUPS", None)
            if дорогой_d2 is not None:
                хран_дор = дорогой_d2["pool_vault"]

                class МодулиДор:
                    class C:
                        WSOL = C_ж.WSOL
                        NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                        @staticmethod
                        def identify_pool(*a, **kw):
                            return {"ok": True, "pool_vault": хран_дор,
                                    "quote_mint": C_ж.WSOL}

                globals()["_модули"] = lambda: (МодулиДор.C, PP_ж, SB_ж, B_ж)
                d2_дорого = собрать(tx_источника=дорогой_d2["tx"],
                                     источник=дорогой_d2["source"],
                                     минт=дорогой_d2["mint"],
                                     наш_кошелёк=кошелёк_полосы(), лампорты=10_000_000)
                chk("DAMM v2: пул с комиссией выше потолка не берётся, и она названа",
                    d2_дорого["ok"] is False
                    and "комиссия пула" in (d2_дорого["why_not"] or ""),
                    d2_дорого.get("why_not"))
        finally:
            globals()["_модули"] = было_м2
            os.environ.pop("LANE_DAMM2_GROUPS", None)
            if было_ф2 is None:
                os.environ.pop("LANE_DAMM2", None)
            else:
                os.environ["LANE_DAMM2"] = было_ф2

    # --- RAYDIUM CLMM В ПОЛОСЕ (очередь строителей владельца 28.09, номер 2).
    # Сборка сверена байт в байт на 27 живых сделках из 38, цена -- по событию
    # свопа из ЛОГОВ и ставке комиссии из счёта amm_config. Здесь проверяется
    # ДЕНЕЖНОЕ: без флага не берём, по флагу собираем с положительным
    # минимумом, по чужой группе не берём, и без прочитанной ставки комиссии
    # не берём даже при поднятом флаге.
    # ОБРАЗЦЫ БЕРУТСЯ ЗАГРУЗЧИКОМ, А НЕ ФАЙЛОМ НАПРЯМУЮ: своих сделок CLMM в
    # репозитории восемь, и все восемь -- пулы xStock, где котировка НЕ SOL.
    # Сделки CLMM с котировкой SOL лежат в файлах образцов других программ
    # (CLMM встречается шагом чужих маршрутов), и load_samples их добирает.
    try:
        обр_cl = B_ж.load_samples(B_ж.CLMM)
    except Exception:  # noqa: BLE001
        обр_cl = []
    B_ж.загрузить_ставки_clmm()

    def _cl_годный(x):
        """Образец с котировкой SOL, у которого минимум выхода считается."""
        t_ = B_ж.extract_template(x["tx"], B_ж.CLMM, x["pool_vault"])
        if not t_.get("ok") or len(t_["accounts"]) < 3:
            return False
        mv_ = B_ж.mints_and_vaults(t_, x["tx"])
        if not mv_ or mv_["quote_mint"] != C_ж.WSOL:
            return False
        return bool(B_ж.min_out_from_reserves(t_, x["tx"], 10_000_000, 0.35).get("ok"))

    образец_cl = next((x for x in обр_cl if _cl_годный(x)), None)
    if образец_cl is not None:
        хран_cl = образец_cl["pool_vault"]

        class МодулиCL:
            class C:
                WSOL = C_ж.WSOL
                NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                @staticmethod
                def identify_pool(*a, **kw):
                    return {"ok": True, "pool_vault": хран_cl, "quote_mint": C_ж.WSOL}

        было_мcl = globals()["_модули"]
        было_фcl = os.environ.get("LANE_CLMM")
        globals()["_модули"] = lambda: (МодулиCL.C, PP_ж, SB_ж, B_ж)
        try:
            os.environ.pop("LANE_CLMM_GROUPS", None)
            os.environ["LANE_CLMM"] = "0"
            cl_выкл = собрать(tx_источника=образец_cl["tx"],
                               источник=образец_cl["source"],
                               минт=образец_cl["mint"], наш_кошелёк=кошелёк_полосы(),
                               лампорты=10_000_000)
            chk("Raydium CLMM без флага -- отказ, полоса его не берёт",
                cl_выкл["ok"] is False and "вне полосы" in (cl_выкл["why_not"] or ""),
                cl_выкл)
            os.environ["LANE_CLMM"] = "1"
            cl_вкл = собрать(tx_источника=образец_cl["tx"],
                              источник=образец_cl["source"],
                              минт=образец_cl["mint"], наш_кошелёк=кошелёк_полосы(),
                              лампорты=10_000_000)
            chk("Raydium CLMM по флагу -- собран, минимум положителен и ниже ожидания",
                cl_вкл["ok"] is True and isinstance(cl_вкл.get("min_out"), int)
                and 0 < cl_вкл["min_out"] < int(cl_вкл.get("expected_out") or 0),
                cl_вкл)
            os.environ["LANE_CLMM_GROUPS"] = "speed_only"
            cl_чужая = собрать(tx_источника=образец_cl["tx"],
                                источник=образец_cl["source"],
                                минт=образец_cl["mint"], наш_кошелёк=кошелёк_полосы(),
                                лампорты=10_000_000)
            chk("Raydium CLMM только для speed_only: по источнику другой группы -- отказ",
                cl_чужая["ok"] is False and "вне полосы" in (cl_чужая["why_not"] or ""),
                cl_чужая)
            os.environ.pop("LANE_CLMM_GROUPS", None)
            # СТАВКА НЕ ПРОЧИТАНА -- НЕ ПОКУПАЕМ. Это главный денежный запрет
            # строителя: без ставки комиссии минимум выхода посчитать нечем, а
            # догадка означала бы минимум ниже настоящего.
            t_cl = B_ж.extract_template(образец_cl["tx"], B_ж.CLMM, хран_cl)
            конфиг_cl = t_cl["accounts"][1]
            было_ст = B_ж.СТАВКИ_CLMM.pop(конфиг_cl, None)
            было_бс = set(B_ж.КОНФИГИ_БЕЗ_СТАВКИ)
            B_ж.КОНФИГИ_БЕЗ_СТАВКИ.clear()
            try:
                cl_без_ставки = собрать(tx_источника=образец_cl["tx"],
                                         источник=образец_cl["source"],
                                         минт=образец_cl["mint"],
                                         наш_кошелёк=кошелёк_полосы(),
                                         лампорты=10_000_000)
                chk(f"Raydium CLMM без прочитанной ставки комиссии -- отказ: "
                    f"{str(cl_без_ставки.get('why_not'))[:70]}",
                    cl_без_ставки["ok"] is False,
                    cl_без_ставки.get("why_not"))
                chk("и адрес конфига лёг заданием фоновому чтению",
                    конфиг_cl in B_ж.НУЖНЫ_КОНФИГИ_CLMM)
            finally:
                if было_ст is not None:
                    B_ж.СТАВКИ_CLMM[конфиг_cl] = было_ст
                B_ж.НУЖНЫ_КОНФИГИ_CLMM.discard(конфиг_cl)
                B_ж.КОНФИГИ_БЕЗ_СТАВКИ.clear()
                B_ж.КОНФИГИ_БЕЗ_СТАВКИ.update(было_бс)
        finally:
            globals()["_модули"] = было_мcl
            os.environ.pop("LANE_CLMM_GROUPS", None)
            if было_фcl is None:
                os.environ.pop("LANE_CLMM", None)
            else:
                os.environ["LANE_CLMM"] = было_фcl
    else:
        chk("образца Raydium CLMM с котировкой SOL и посчитанным минимумом нет -- "
            "строитель проверять нечем", False)

    # --- METEORA DLMM В ПОЛОСЕ (очередь строителей владельца 28.09, N4).
    # Цена у DLMM живёт в корзинах, и считается по событию свопа плюс шаг
    # корзины из счёта пула (см. docs/dlmm_sobytie_i_cena.md). Здесь
    # проверяется ДЕНЕЖНОЕ: без флага не берём, по флагу собираем с
    # положительным минимумом, по чужой группе не берём, и без прочитанного
    # шага корзины не берём даже при поднятом флаге.
    try:
        обр_dl = B_ж.load_samples(B_ж.DLMM)
    except Exception:  # noqa: BLE001
        обр_dl = []
    B_ж.загрузить_ступени_dlmm()

    def _dl_годный(x):
        t_ = B_ж.extract_template(x["tx"], B_ж.DLMM, x["pool_vault"])
        if not t_.get("ok") or not (t_.get("accounts") or []):
            return False
        mv_ = B_ж.mints_and_vaults(t_, x["tx"])
        if not mv_ or mv_["quote_mint"] != C_ж.WSOL:
            return False
        return bool(B_ж.min_out_from_reserves(t_, x["tx"], 10_000_000, 0.35).get("ok"))

    образец_dl = next((x for x in обр_dl if _dl_годный(x)), None)
    if образец_dl is not None:
        хран_dl = образец_dl["pool_vault"]

        class МодулиDL:
            class C:
                WSOL = C_ж.WSOL
                NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                @staticmethod
                def identify_pool(*a, **kw):
                    return {"ok": True, "pool_vault": хран_dl, "quote_mint": C_ж.WSOL}

        # ШАГ DLMM В САМОПРОВЕРКЕ -- БЕЗ СЕТИ. С 29.09 полоса для DLMM обязана
        # прочитать нынешние массивы корзин (вариант 1б), и без узла честно
        # отказывает. Здесь узла нет, поэтому шаг подменяется прозрачным: шаблон
        # как есть, минимум остаётся приближённым. Так эти три проверки проверяют
        # ровно то, что и раньше, а сам отказ без узла проверен отдельно.
        def _шаг_dlmm_прозрачный(B_, tpl_, mv_, **кв):
            return {"ok": True, "шаблон": tpl_, "мест_у_источника": None,
                     "не_влезло": [], "не_влезло_сколько": 0,
                     "путь": "самопроверка: шаг DLMM прозрачный"}

        было_мdl = globals()["_модули"]
        было_фdl = os.environ.get("LANE_DLMM")
        globals()["_модули"] = lambda: (МодулиDL.C, PP_ж, SB_ж, B_ж)
        try:
            os.environ.pop("LANE_DLMM_GROUPS", None)
            os.environ["LANE_DLMM"] = "0"
            dl_выкл = собрать(tx_источника=образец_dl["tx"],
                               источник=образец_dl["source"],
                               минт=образец_dl["mint"], наш_кошелёк=кошелёк_полосы(),
                               лампорты=10_000_000)
            chk("Meteora DLMM без флага -- отказ, полоса его не берёт",
                dl_выкл["ok"] is False and "вне полосы" in (dl_выкл["why_not"] or ""),
                dl_выкл)
            os.environ["LANE_DLMM"] = "1"
            dl_вкл = собрать(tx_источника=образец_dl["tx"],
                              источник=образец_dl["source"],
                              минт=образец_dl["mint"], наш_кошелёк=кошелёк_полосы(),
                              лампорты=10_000_000,
                              dlmm_шаг=_шаг_dlmm_прозрачный)
            chk("Meteora DLMM по флагу -- собран, минимум положителен и ниже ожидания",
                dl_вкл["ok"] is True and isinstance(dl_вкл.get("min_out"), int)
                and 0 < dl_вкл["min_out"] < int(dl_вкл.get("expected_out") or 0),
                dl_вкл)
            os.environ["LANE_DLMM_GROUPS"] = "speed_only"
            dl_чужая = собрать(tx_источника=образец_dl["tx"],
                                источник=образец_dl["source"],
                                минт=образец_dl["mint"], наш_кошелёк=кошелёк_полосы(),
                                лампорты=10_000_000)
            chk("Meteora DLMM только для speed_only: по источнику другой группы -- отказ",
                dl_чужая["ok"] is False and "вне полосы" in (dl_чужая["why_not"] or ""),
                dl_чужая)
            os.environ.pop("LANE_DLMM_GROUPS", None)
            # ПОТОЛОК КОМИССИИ ПУЛА РАБОТАЕТ И НА DLMM. В живых сделках DLMM
            # комиссия пула доходит до 8.75 % (замер 28.09 по девяти сделкам:
            # 0.2 %, 1.01 %, 1.03 %, 2.03 %, 2.69 %, 2.77 %, 3.68 % четыре
            # раза, 7.64 %, 8.75 %). Покупать с такой комиссией значит отдать
            # пулу десятую часть входа, поэтому пул выше потолка полоса не
            # берёт -- проверяем это на НАСТОЯЩЕМ таком образце.
            дорогой = None
            for x_ in обр_dl:
                t2_ = B_ж.extract_template(x_["tx"], B_ж.DLMM, x_["pool_vault"])
                if not t2_.get("ok") or not (t2_.get("accounts") or []):
                    continue
                мо_ = B_ж.min_out_from_reserves(t2_, x_["tx"], 10_000_000, 0.35)
                if (мо_.get("ok") and мо_.get("fee_share") is not None
                        and float(мо_["fee_share"]) > ПОТОЛОК_КОМИССИИ_ПУЛА):
                    дорогой = (x_, float(мо_["fee_share"]))
                    break
            if дорогой is not None:
                x_д, доля_д = дорогой
                хран_д = x_д["pool_vault"]

                class МодулиДорогой:
                    class C:
                        WSOL = C_ж.WSOL
                        NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                        @staticmethod
                        def identify_pool(*a, **kw):
                            return {"ok": True, "pool_vault": хран_д,
                                     "quote_mint": C_ж.WSOL}

                было_мд = globals()["_модули"]
                globals()["_модули"] = lambda: (МодулиДорогой.C, PP_ж, SB_ж, B_ж)
                try:
                    dl_дорогой = собрать(tx_источника=x_д["tx"],
                                          источник=x_д["source"],
                                          минт=x_д["mint"],
                                          наш_кошелёк=кошелёк_полосы(),
                                          лампорты=10_000_000,
                                          dlmm_шаг=_шаг_dlmm_прозрачный)
                    chk(f"DLMM с комиссией пула {доля_д * 100:.2f} % выше потолка "
                        f"{ПОТОЛОК_КОМИССИИ_ПУЛА * 100:.0f} % -- отказ: "
                        f"{str(dl_дорогой.get('why_not'))[:60]}",
                        dl_дорогой["ok"] is False
                        and "комисси" in (dl_дорогой.get("why_not") or ""),
                        dl_дорогой)
                finally:
                    globals()["_модули"] = было_мд
            else:
                chk("живого образца DLMM с комиссией выше потолка нет -- потолок "
                    "проверять нечем", False)
            # ШАГ КОРЗИНЫ НЕ ПРОЧИТАН -- НЕ ПОКУПАЕМ. Главный денежный запрет
            # строителя: без шага корзины цена не считается, а догадка означала
            # бы минимум ниже настоящего.
            t_dl = B_ж.extract_template(образец_dl["tx"], B_ж.DLMM, хран_dl)
            пул_dl = t_dl["accounts"][0]
            был_шаг = B_ж.СТУПЕНИ_DLMM.pop(пул_dl, None)
            было_бш = set(B_ж.ПУЛЫ_БЕЗ_СТУПЕНИ)
            B_ж.ПУЛЫ_БЕЗ_СТУПЕНИ.clear()
            try:
                dl_без_шага = собрать(tx_источника=образец_dl["tx"],
                                       источник=образец_dl["source"],
                                       минт=образец_dl["mint"],
                                       наш_кошелёк=кошелёк_полосы(),
                                       лампорты=10_000_000)
                chk(f"Meteora DLMM без прочитанного шага корзины -- отказ: "
                    f"{str(dl_без_шага.get('why_not'))[:70]}",
                    dl_без_шага["ok"] is False, dl_без_шага.get("why_not"))
                chk("и адрес пула лёг заданием фоновому чтению",
                    пул_dl in B_ж.НУЖНЫ_ПУЛЫ_DLMM)
            finally:
                if был_шаг is not None:
                    B_ж.СТУПЕНИ_DLMM[пул_dl] = был_шаг
                B_ж.НУЖНЫ_ПУЛЫ_DLMM.discard(пул_dl)
                B_ж.ПУЛЫ_БЕЗ_СТУПЕНИ.clear()
                B_ж.ПУЛЫ_БЕЗ_СТУПЕНИ.update(было_бш)
        finally:
            globals()["_модули"] = было_мdl
            os.environ.pop("LANE_DLMM_GROUPS", None)
            if было_фdl is None:
                os.environ.pop("LANE_DLMM", None)
            else:
                os.environ["LANE_DLMM"] = было_фdl
    else:
        chk("образца Meteora DLMM с котировкой SOL и посчитанным минимумом нет -- "
            "строитель проверять нечем", False)

    # --- RAYDIUM LAUNCHLAB В ПОЛОСЕ (очередь строителей владельца 28.09, N3).
    # Сборка сверена на живых сделках источников (buy_exact_in, 18 счетов),
    # цена -- по событию TradeEvent из ЛОГОВ: у кривой запуска резервы
    # виртуальные, и хранилища цену не дают. Здесь проверяется ДЕНЕЖНОЕ: без
    # флага не берём, по флагу собираем с положительным минимумом ниже
    # ожидания, по чужой группе не берём, а без события в логах -- отказ.
    try:
        обр_ll = B_ж.load_samples(B_ж.LAUNCHLAB)
    except Exception:  # noqa: BLE001
        обр_ll = []

    def _ll_годный(x):
        """Образец с котировкой SOL, у которого минимум выхода считается."""
        t_ = B_ж.extract_template(x["tx"], B_ж.LAUNCHLAB, x["pool_vault"])
        if not t_.get("ok"):
            return False
        mv_ = B_ж.mints_and_vaults(t_, x["tx"])
        if not mv_ or mv_["quote_mint"] != C_ж.WSOL:
            return False
        return bool(B_ж.min_out_from_reserves(t_, x["tx"], 10_000_000, 0.35).get("ok"))

    образец_ll = next((x for x in обр_ll if _ll_годный(x)), None)
    if образец_ll is not None:
        хран_ll = образец_ll["pool_vault"]

        class МодулиLL:
            class C:
                WSOL = C_ж.WSOL
                NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                @staticmethod
                def identify_pool(*a, **kw):
                    return {"ok": True, "pool_vault": хран_ll, "quote_mint": C_ж.WSOL}

        было_мll = globals()["_модули"]
        было_фll = os.environ.get("LANE_LAUNCHLAB")
        globals()["_модули"] = lambda: (МодулиLL.C, PP_ж, SB_ж, B_ж)
        try:
            os.environ.pop("LANE_LAUNCHLAB_GROUPS", None)
            os.environ["LANE_LAUNCHLAB"] = "0"
            ll_выкл = собрать(tx_источника=образец_ll["tx"],
                               источник=образец_ll["source"],
                               минт=образец_ll["mint"], наш_кошелёк=кошелёк_полосы(),
                               лампорты=10_000_000)
            chk("Raydium LaunchLab без флага -- отказ, полоса его не берёт",
                ll_выкл["ok"] is False and "вне полосы" in (ll_выкл["why_not"] or ""),
                ll_выкл)
            os.environ["LANE_LAUNCHLAB"] = "1"
            ll_вкл = собрать(tx_источника=образец_ll["tx"],
                              источник=образец_ll["source"],
                              минт=образец_ll["mint"], наш_кошелёк=кошелёк_полосы(),
                              лампорты=10_000_000)
            chk("Raydium LaunchLab по флагу -- собран, минимум положителен и ниже ожидания",
                ll_вкл["ok"] is True and isinstance(ll_вкл.get("min_out"), int)
                and 0 < ll_вкл["min_out"] < int(ll_вкл.get("expected_out") or 0),
                ll_вкл)
            os.environ["LANE_LAUNCHLAB_GROUPS"] = "speed_only"
            ll_чужая = собрать(tx_источника=образец_ll["tx"],
                                источник=образец_ll["source"],
                                минт=образец_ll["mint"], наш_кошелёк=кошелёк_полосы(),
                                лампорты=10_000_000)
            chk("Raydium LaunchLab только для speed_only: по источнику другой группы -- отказ",
                ll_чужая["ok"] is False and "вне полосы" in (ll_чужая["why_not"] or ""),
                ll_чужая)
            os.environ.pop("LANE_LAUNCHLAB_GROUPS", None)
            # СОБЫТИЯ НЕТ -- НЕ ПОКУПАЕМ. У кривой запуска цена живёт только в
            # событии; без него минимум выхода считать нечем, а брать
            # хранилища как у x*y=k значило бы считать по ложным резервам.
            tx_без_лога = json.loads(json.dumps(образец_ll["tx"]))
            tx_без_лога.setdefault("meta", {})["logMessages"] = []
            ll_без_события = собрать(tx_источника=tx_без_лога,
                                      источник=образец_ll["source"],
                                      минт=образец_ll["mint"],
                                      наш_кошелёк=кошелёк_полосы(),
                                      лампорты=10_000_000)
            chk(f"Raydium LaunchLab без события в логах -- отказ: "
                f"{str(ll_без_события.get('why_not'))[:70]}",
                ll_без_события["ok"] is False, ll_без_события.get("why_not"))
        finally:
            globals()["_модули"] = было_мll
            os.environ.pop("LANE_LAUNCHLAB_GROUPS", None)
            if было_фll is None:
                os.environ.pop("LANE_LAUNCHLAB", None)
            else:
                os.environ["LANE_LAUNCHLAB"] = было_фll
    else:
        chk("образца Raydium LaunchLab с котировкой SOL и посчитанным минимумом "
            "нет -- строитель проверять нечем", False)

    # --- METEORA DBC В ПОЛОСЕ (ночное задание владельца 27.09, пункт 3).
    # Берётся образец с котировкой SOL: остальные полоса и так не возьмёт.
    обр_dbc = []
    файл_dbc = (Path(__file__).resolve().parent.parent / "data" / "c2_pool_samples"
                / f"{getattr(B_ж, 'DBC', 'нет')}.json")
    if файл_dbc.exists():
        обр_dbc = json.loads(файл_dbc.read_text(encoding="utf-8"))

    def _dbc_годный(x):
        t_ = B_ж.extract_template(x["tx"], B_ж.DBC, x["pool_vault"])
        if not t_.get("ok"):
            return False
        mv_ = B_ж.mints_and_vaults(t_, x["tx"])
        if not mv_ or mv_["quote_mint"] != C_ж.WSOL:
            return False
        return B_ж.min_out_from_reserves(t_, x["tx"], 10_000_000, 0.35).get("ok") is True

    образец_dbc = next((x for x in обр_dbc if _dbc_годный(x)), None)
    if образец_dbc is not None:
        хран_dbc = образец_dbc["pool_vault"]

        class МодулиDBC:
            class C:
                WSOL = C_ж.WSOL
                NATIVE_QUOTE = getattr(C_ж, "NATIVE_QUOTE", "native_sol")

                @staticmethod
                def identify_pool(*a, **kw):
                    return {"ok": True, "pool_vault": хран_dbc, "quote_mint": C_ж.WSOL}

        было_м3 = globals()["_модули"]
        было_ф3 = os.environ.get("LANE_DBC")
        globals()["_модули"] = lambda: (МодулиDBC.C, PP_ж, SB_ж, B_ж)
        try:
            os.environ.pop("LANE_DBC_GROUPS", None)
            os.environ["LANE_DBC"] = "0"
            dbc_выкл = собрать(tx_источника=образец_dbc["tx"],
                                источник=образец_dbc["source"],
                                минт=образец_dbc["mint"], наш_кошелёк=кошелёк_полосы(),
                                лампорты=10_000_000)
            chk("DBC без флага -- отказ, полоса его не берёт",
                dbc_выкл["ok"] is False and "вне полосы" in (dbc_выкл["why_not"] or ""),
                dbc_выкл)
            os.environ["LANE_DBC"] = "1"
            dbc_вкл = собрать(tx_источника=образец_dbc["tx"],
                               источник=образец_dbc["source"],
                               минт=образец_dbc["mint"], наш_кошелёк=кошелёк_полосы(),
                               лампорты=10_000_000)
            chk("DBC по флагу -- собран, минимум положителен и ниже ожидания, "
                "комиссия кривой названа",
                dbc_вкл["ok"] is True
                and 0 < int(dbc_вкл.get("min_out") or 0) < int(dbc_вкл.get("expected_out") or 0)
                and dbc_вкл.get("pool_fee_share") is not None
                and float(dbc_вкл["pool_fee_share"]) <= ПОТОЛОК_КОМИССИИ_ПУЛА,
                {к: dbc_вкл.get(к) for к in ("why_not", "min_out", "expected_out",
                                              "pool_fee_share")})
        finally:
            globals()["_модули"] = было_м3
            os.environ.pop("LANE_DBC_GROUPS", None)
            if было_ф3 is None:
                os.environ.pop("LANE_DBC", None)
            else:
                os.environ["LANE_DBC"] = было_ф3

    # --- ФЛАГ КРИВОЙ ПО ГРУППАМ, без сборки: чистая логика решения.
    было_общий = os.environ.get("LANE_BONDING_CURVE")
    было_список = os.environ.get("LANE_BONDING_CURVE_GROUPS")
    try:
        os.environ.pop("LANE_BONDING_CURVE", None)
        os.environ.pop("LANE_BONDING_CURVE_GROUPS", None)
        chk("без флагов кривой нет ни по одной группе",
            кривая_включена("speed_only") is False and кривая_включена(None) is False, "")
        os.environ["LANE_BONDING_CURVE"] = "1"
        chk("общий флаг -- кривая по всем группам и даже без группы",
            кривая_включена("speed_only") and кривая_включена("bloom_lane")
            and кривая_включена(None), "")
        os.environ["LANE_BONDING_CURVE_GROUPS"] = "speed_only"
        chk("список сильнее общего флага: кривая только у speed_only",
            кривая_включена("speed_only") is True
            and кривая_включена("lane_only") is False
            and кривая_включена("bloom_lane") is False, "")
        chk("группа неизвестна -- кривой нет (молчаливое расширение дороже)",
            кривая_включена(None) is False, "")
        os.environ["LANE_BONDING_CURVE_GROUPS"] = "speed_only, lane_only"
        chk("в списке можно перечислить несколько групп через запятую",
            кривая_включена("speed_only") and кривая_включена("lane_only")
            and кривая_включена("bloom_lane") is False, "")
        os.environ.pop("LANE_BONDING_CURVE", None)
        os.environ["LANE_BONDING_CURVE_GROUPS"] = "speed_only"
        chk("список работает и без общего флага",
            кривая_включена("speed_only") is True
            and кривая_включена("bloom_lane") is False, "")
    finally:
        os.environ.pop("LANE_BONDING_CURVE", None)
        os.environ.pop("LANE_BONDING_CURVE_GROUPS", None)
        if было_общий is not None:
            os.environ["LANE_BONDING_CURVE"] = было_общий
        if было_список is not None:
            os.environ["LANE_BONDING_CURVE_GROUPS"] = было_список

    # --- ПУСТОЙ BLOCKHASH. Подписать можно, отправить можно, сеть не примет,
    # а чаевые и приоритет уже потрачены.
    пусто_bh = подписать("AAA", blockhash="1" * 32,
                          ожидаемый_кошелёк=ST.EXECUTOR_WALLET, секрет="не ключ")
    chk("пустой blockhash -- отказ ДО проверки ключа",
        пусто_bh["ok"] is False and "blockhash пустой" in (пусто_bh["why_not"] or ""),
        пусто_bh)
    нет_bh = подписать("AAA", blockhash="",
                        ожидаемый_кошелёк=ST.EXECUTOR_WALLET, секрет="не ключ")
    chk("отсутствующий blockhash -- тоже отказ", нет_bh["ok"] is False, нет_bh)

    # --- ТЕКСТ ИСКЛЮЧЕНИЯ РАЗБОРА КЛЮЧА НАРУЖУ НЕ ИДЁТ: в него может попасть
    # сам секрет.
    плохой = подписать("AAA", blockhash="11111111111111111111111111111112",
                        ожидаемый_кошелёк=ST.EXECUTOR_WALLET,
                        секрет="СЕКРЕТНАЯ_СТРОКА_КОТОРОЙ_ТУТ_БЫТЬ_НЕ_ДОЛЖНО")
    chk("секрет не утекает в причину отказа",
        плохой["ok"] is False
        and "СЕКРЕТНАЯ_СТРОКА" not in (плохой["why_not"] or ""), плохой["why_not"])

    # --- подпись чужим ключом запрещена
    п = подписать("AAA", blockhash="11111111111111111111111111111111",
                   ожидаемый_кошелёк="ЧУЖОЙ_КОШЕЛЁК", секрет="не ключ")
    chk("чужой или негодный ключ -- подписи нет",
        п["ok"] is False and п["why_not"], п)

    # --- пределы полосы
    def поз(cid, *, ts, состояние="closed", цепь=True, вход=0.01, назад=None,
             метка=МЕТКА):
        p = {"client_order_id": cid, "lane": метка, "ts_intent": ts,
             "state": состояние, "chain_ok": цепь, "sol_in": вход}
        if назад is not None:
            p["closed_sol_net"] = назад
        return p

    сейчас = 1_790_000_000.0
    пусто = можно_отправлять({}, сейчас=сейчас)
    chk("выключенная полоса не пропускает",
        пусто["ok"] is False and "выключена" in пусто["why_not"], пусто)
    было_вкл = os.environ.get("BLOOM_OWN_SEND")
    os.environ["BLOOM_OWN_SEND"] = "1"
    chk("включённая и пустая полоса пропускает",
        можно_отправлять({}, сейчас=сейчас)["ok"], можно_отправлять({}, сейчас=сейчас))
    chk("KILL останавливает полосу",
        можно_отправлять({}, kill=True, сейчас=сейчас)["ok"] is False,
        можно_отправлять({}, kill=True, сейчас=сейчас))
    открытая = {"a": поз("a", ts=сейчас - 10, состояние="bought")}
    chk("одна открытая позиция полосы закрывает вход второй",
        можно_отправлять(открытая, сейчас=сейчас)["ok"] is False
        and "открытых" in можно_отправлять(открытая, сейчас=сейчас)["why_not"],
        можно_отправлять(открытая, сейчас=сейчас))

    # ЗАВИСШАЯ ПОЗИЦИЯ МЕСТА НЕ ЗАНИМАЕТ (решение владельца 25.09 вечера). Это
    # денежное место в обе стороны: без правила полоса стоит всю ночь из-за
    # одной недопроданной позиции, а слишком короткий срок пустил бы вторую
    # покупку на живой, ещё не проданной первой.
    зависшая = {"a": поз("a", ts=сейчас - (СРОК_ЗАВИСАНИЯ_S + 1),
                          состояние="selling")}
    свежая = {"a": поз("a", ts=сейчас - (СРОК_ЗАВИСАНИЯ_S - 30),
                        состояние="selling")}
    chk("зависшая позиция полосы вход НЕ закрывает",
        можно_отправлять(зависшая, сейчас=сейчас)["ok"] is True,
        можно_отправлять(зависшая, сейчас=сейчас))
    chk("а та же позиция до срока зависания -- закрывает",
        можно_отправлять(свежая, сейчас=сейчас)["ok"] is False,
        можно_отправлять(свежая, сейчас=сейчас))
    chk("зависшие считаются отдельным числом, а не пропадают",
        состояние_полосы(зависшая, сейчас=сейчас)["stuck"] == 1
        and состояние_полосы(зависшая, сейчас=сейчас)["open"] == 0,
        состояние_полосы(зависшая, сейчас=сейчас))
    сутки = {str(i): поз(str(i), ts=сейчас - 100 - i, назад=0.01)
             for i in range(ЛИМИТ_В_СУТКИ)}
    chk("предел сделок за сутки соблюдается",
        можно_отправлять(сутки, сейчас=сейчас)["ok"] is False
        and "за сутки" in можно_отправлять(сутки, сейчас=сейчас)["why_not"],
        можно_отправлять(сутки, сейчас=сейчас)["why_not"])
    вчера = {str(i): поз(str(i), ts=сейчас - 90000 - i, назад=0.01)
             for i in range(ЛИМИТ_В_СУТКИ)}
    chk("вчерашние сделки в сегодняшний предел не идут",
        можно_отправлять(вчера, сейчас=сейчас)["ok"], можно_отправлять(вчера, сейчас=сейчас))
    упавшие = {str(i): поз(str(i), ts=сейчас - 300 + i, цепь=False)
               for i in range(СТОП_ПОДРЯД_УПАВШИХ)}
